FAILURES: list[str] = []

#: A real, tiny 16 kHz WAV (10 ms of silence) for the tests that hand the
#: transcriber "some audio": since 13.4 the transcriber decodes what it is
#: given through pcm.py before the model sees it, so four bytes of RIFF
#: are not audio any more.
RIFF = frames_to_wav([np.zeros(160, dtype=np.int16)], 16000)

VK_RCTRL = 0xA3
VK_LCTRL = 0xA2
VK_C = 0x43
VK_V = 0x56
VK_SHIFT = 0x10


def check(name: str, fn) -> None:
    try:
        fn()
        print(f"  PASS  {name}")
    except AssertionError as e:
        FAILURES.append(name)
        print(f"  FAIL  {name}: {e}")
    except Exception as e:  # noqa: BLE001
        FAILURES.append(name)
        print(f"  FAIL  {name}: unexpected {type(e).__name__}: {e}")


class Spy:
    def __init__(self) -> None:
        self.events: list[str] = []

    def machine(self, hotkey_vk=VK_RCTRL) -> PTTStateMachine:
        return PTTStateMachine(
            hotkey_vk,
            on_start=lambda lang: self.events.append("start"),
            on_stop=lambda lang: self.events.append("stop"),
            on_abort=lambda why: self.events.append(f"abort:{why}"))

    def lang_machine(self, hotkeys: dict) -> PTTStateMachine:
        return PTTStateMachine(
            hotkeys,
            on_start=lambda lang: self.events.append(f"start:{lang}"),
            on_stop=lambda lang: self.events.append(f"stop:{lang}"),
            on_abort=lambda why: self.events.append(f"abort:{why}"))


def test_press_release_cycle() -> None:
    spy = Spy()
    m = spy.machine()
    m.handle("down", VK_RCTRL, injected=False)
    m.handle("up", VK_RCTRL, injected=False)
    assert spy.events == ["start", "stop"], spy.events


def test_autorepeat_ignored() -> None:
    spy = Spy()
    m = spy.machine()
    for _ in range(4):  # Windows key auto-repeat while held
        m.handle("down", VK_RCTRL, injected=False)
    m.handle("up", VK_RCTRL, injected=False)
    assert spy.events == ["start", "stop"], spy.events


def test_physical_other_key_down_aborts() -> None:
    spy = Spy()
    m = spy.machine()
    m.handle("down", VK_RCTRL, injected=False)
    m.handle("down", VK_C, injected=False)   # user is doing Ctrl+C
    m.handle("up", VK_C, injected=False)
    m.handle("up", VK_RCTRL, injected=False)  # after abort: no stop
    assert spy.events == ["start", "abort:'c' pressed mid-hold"], spy.events


def test_injected_keys_never_abort() -> None:
    """Our own synthetic paste chord arrives with LLKHF_INJECTED set."""
    spy = Spy()
    m = spy.machine()
    m.handle("down", VK_RCTRL, injected=False)
    m.handle("down", VK_LCTRL, injected=True)   # synthetic ctrl+v begins
    m.handle("down", VK_V, injected=True)
    m.handle("up", VK_V, injected=True)
    m.handle("up", VK_LCTRL, injected=True)
    m.handle("up", VK_RCTRL, injected=False)
    assert spy.events == ["start", "stop"], spy.events


def test_injected_hotkey_still_works() -> None:
    """Test drivers (SendInput) must be able to run the PTT cycle."""
    spy = Spy()
    m = spy.machine()
    m.handle("down", VK_RCTRL, injected=True)
    m.handle("up", VK_RCTRL, injected=True)
    assert spy.events == ["start", "stop"], spy.events


def test_left_ctrl_is_not_the_hotkey() -> None:
    spy = Spy()
    m = spy.machine()  # hotkey = right ctrl
    m.handle("down", VK_LCTRL, injected=False)  # idle: ignored
    m.handle("up", VK_LCTRL, injected=False)
    assert spy.events == [], spy.events
    m.handle("down", VK_RCTRL, injected=False)
    m.handle("down", VK_LCTRL, injected=False)  # recording: a modifier defers
    assert spy.events == ["start"], spy.events
    m.handle("up", VK_LCTRL, injected=False)
    m.handle("up", VK_RCTRL, injected=False)
    assert spy.events == ["start", "stop"], spy.events


def test_a_modifier_alone_defers_and_the_letter_aborts() -> None:
    """The abort rule reads the COMBO, not the reach for one.

    It used to fire on the modifier's key-down, which is the one moment a
    chord can never be judged from: every chord this app binds starts with
    a modifier, so aborting there made ctrl+F10 and win+shift+s
    unpressable mid-dictation by construction. Deferring costs nothing —
    Ctrl+C still throws the recording away, one key later, on the C.
    """
    spy = Spy()
    m = spy.machine()
    m.handle("down", VK_RCTRL, injected=False)
    m.handle("down", VK_LCTRL, injected=False)   # reaching for a combo
    assert spy.events == ["start"], spy.events
    m.handle("down", VK_C, injected=False)       # ...and there it is
    assert spy.events == ["start", "abort:'c' pressed mid-hold"], spy.events


def test_other_key_up_does_not_abort() -> None:
    spy = Spy()
    m = spy.machine()
    m.handle("down", VK_RCTRL, injected=False)
    m.handle("up", VK_SHIFT, injected=False)  # lingering shift released
    m.handle("up", VK_RCTRL, injected=False)
    assert spy.events == ["start", "stop"], spy.events


def test_other_key_while_idle_ignored() -> None:
    spy = Spy()
    m = spy.machine()
    m.handle("down", VK_C, injected=False)
    m.handle("up", VK_C, injected=False)
    assert spy.events == [], spy.events


def test_vk_tables() -> None:
    assert vk_for("right ctrl") == VK_RCTRL
    assert vk_for("LEFT CTRL") == VK_LCTRL
    assert vk_for(" f9 ") == 0x78
    assert vk_name(VK_RCTRL) == "right ctrl"
    assert parse_chord("ctrl+v") == [0x11, VK_V]
    assert parse_chord("shift+insert") == [VK_SHIFT, 0x2D]
    for bad in ("ctrl+", "", "hyperkey"):
        try:
            parse_chord(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"parse_chord({bad!r}) did not raise")


def test_frames_to_wav_format() -> None:
    tone = (np.sin(np.linspace(0, 2 * np.pi * 440, 16000))
            * 8000).astype(np.int16).reshape(-1, 1)
    data = frames_to_wav([tone[:8000], tone[8000:]], 16000)
    with wave.open(io.BytesIO(data)) as w:
        assert w.getnchannels() == 1
        assert w.getsampwidth() == 2
        assert w.getframerate() == 16000
        assert w.getnframes() == 16000, w.getnframes()


def _refuse(rec, why="Invalid number of channels"):
    """What a driver saying no looks like from inside a fake stream."""
    raise rec.sd.PortAudioError(f"Error opening InputStream: {why}")


def _fake_streams(behaviour):
    """Run `behaviour(kwargs) -> samplerate` in place of sd.InputStream,
    and give back the kwargs every attempt was made with. Raising from
    `behaviour` is how a test says "this driver refuses that"."""
    import recorder as rec

    tried: list[dict] = []

    class Stream:
        device = 0

        def __init__(self, **kw):
            tried.append(kw)
            self.samplerate = behaviour(kw)

    return rec, tried, Stream


def test_a_microphone_that_moved_does_not_stop_the_app_starting() -> None:
    """2026-09-05: `[audio] device` held a bare INDEX, and indices shift
    whenever any device appears or disappears — a Bluetooth headset
    connecting is enough. Index 27 was the headset microphone at 15:14 and
    "Speakers (Realtek HD Audio output)" (0 in, 8 out) by 15:36, so every
    start died on "Invalid number of channels" and the app would not come
    up at all. A third hand does not down tools because a plug moved: a
    pinned device that cannot be opened means the system default, loudly.
    """
    rec, tried, Stream = _fake_streams(
        lambda kw: 16000 if kw.get("device") is None else _refuse(rec))

    real = rec.sd.InputStream
    rec.sd.InputStream = Stream
    try:
        r = rec.Recorder(16000, 27, 400, lambda: None)
    finally:
        rec.sd.InputStream = real

    assert r.sample_rate == 16000
    assert tried[0]["device"] == 27, "the pinned microphone comes first"
    assert tried[-1]["device"] is None, \
        "a microphone that cannot be opened must fall back to the default"


def test_the_rate_ladder_asks_wasapi_before_giving_up_on_16_khz() -> None:
    """The Arctis 7 Chat refuses 16 kHz shared-mode capture and takes it
    with WASAPI's own converter switched on — measured 2026-09-05 on the
    live endpoint: -9997 without, 16000.0 Hz with. Dropping straight to
    the device's own 48 kHz, which is what used to happen, triples every
    recording and costs the language detector its fast path, so the
    converter is tried before the rate is given up on."""
    rec, tried, Stream = _fake_streams(
        lambda kw: (kw["samplerate"] if kw.get("extra_settings")
                    else (_refuse(rec, "Invalid sample rate")
                          if kw.get("samplerate") else 48000)))
    if rec.wasapi_auto_convert() is None:
        return          # no WASAPI on this machine; there is no rung to ask

    real = rec.sd.InputStream
    rec.sd.InputStream = Stream
    try:
        r = rec.Recorder(16000, 21, 400, lambda: None)
    finally:
        rec.sd.InputStream = real

    assert [(kw.get("samplerate"), bool(kw.get("extra_settings")))
            for kw in tried] == [(16000, False), (16000, True)], tried
    assert r.sample_rate == 16000, "the recording fell to the device's rate"


