def test_the_phone_reads_and_answers_the_second_reading() -> None:
    """GET /review lists what waits, with the snippet the card paints and
    the source the phone rings on; POST /review/decide writes the verdict
    by="phone" and answers 404 once nothing is pending under that id."""
    import dataclasses
    import tempfile

    import requests

    import review as review_mod
    import server as server_mod

    cfg = config_mod.load(Path(__file__).resolve().parent / "defaults.toml")
    cfg = dataclasses.replace(
        cfg, server=config_mod.ServerConfig(enabled=True, host="127.0.0.1",
                                            port=8796))
    tmp = Path(tempfile.mkdtemp(prefix="phone-review-"))
    store = review_mod.Store(tmp / "review.json")
    store.add({"id": "20260913-140000-0031", "when": "2026-09-13 14:00:00",
               "seconds": 3.1, "text": "אוכלים מטוס בערב", "raw":
               "אוכלים מטוס בערב", "proposed": "אוכלים מנטוס בערב",
               "changes": [{"before": "מטוס", "after": "מנטוס",
                            "kind": "replace", "span": [1, 2],
                            "why": "מנטוס, לא מטוס"}],
               "agree": 0.5, "decodes": [], "llm": True,
               "status": review_mod.PENDING, "shown": False,
               "decided": None, "by": None, "learned": False, "hwnd": 0,
               "source": "phone"})
    decided: list[tuple[str, str]] = []

    def decide(sid, verdict):
        decided.append((sid, verdict))
        return store.decide(sid, verdict, by="phone")

    srv = server_mod.PhoneServer(cfg, lambda wav: ("", "fake"),
                                 lambda: "fake",
                                 review_pending=lambda: store.pending(),
                                 review_decide=decide)
    srv.start()
    base = "http://127.0.0.1:8796"
    auth = {"Authorization": f"Bearer {server_mod.load_token()}"}
    try:
        # The list quotes what was said, so it is behind the token.
        assert requests.get(f"{base}/review", timeout=10).status_code == 401
        r = requests.get(f"{base}/review", timeout=10, headers=auth)
        assert r.status_code == 200, r.text
        items = r.json()["items"]
        assert len(items) == 1 and items[0]["id"] == "20260913-140000-0031"
        assert items[0]["source"] == "phone"
        assert items[0]["proposed"] == "אוכלים מנטוס בערב"
        snip = items[0]["snippets"][0]
        assert snip["word"] == "מנטוס" and snip["was"] == "מטוס", snip
        assert snip["rtl"] is True

        bad = requests.post(f"{base}/review/decide", timeout=10,
                            headers=auth, json={"id": "x", "verdict": "maybe"})
        assert bad.status_code == 400, bad.text
        ok = requests.post(f"{base}/review/decide", timeout=10, headers=auth,
                           json={"id": "20260913-140000-0031",
                                 "verdict": "accepted"})
        assert ok.status_code == 200, ok.text
        assert ok.json()["status"] == review_mod.ACCEPTED
        assert decided == [("20260913-140000-0031", "accepted")]
        assert store.get("20260913-140000-0031")["by"] == "phone"
        # Decided once; the second verdict finds nothing pending.
        again = requests.post(f"{base}/review/decide", timeout=10,
                              headers=auth,
                              json={"id": "20260913-140000-0031",
                                    "verdict": "rejected"})
        assert again.status_code == 404, again.text
        assert not store.pending()
        r = requests.get(f"{base}/review", timeout=10, headers=auth)
        assert r.json()["items"] == []
    finally:
        srv.stop()


def test_the_phone_looks_a_word_up_without_writing_anything() -> None:
    """POST /lookup hands the selection to the F8 engine and returns its
    answer and direction; a selection with nothing to look up is a 400
    naming the reason, and a server built without the hook says 503."""
    import dataclasses

    import requests

    import server as server_mod

    cfg = config_mod.load(Path(__file__).resolve().parent / "defaults.toml")
    cfg = dataclasses.replace(
        cfg, server=config_mod.ServerConfig(enabled=True, host="127.0.0.1",
                                            port=8795))
    asked: list[str] = []

    def lookup(text):
        asked.append(text)
        if text == "empty":
            raise ValueError("nothing to look up (both-scripts)")
        return "שלום", "Hebrew", "fake", 0.2

    srv = server_mod.PhoneServer(cfg, lambda wav: ("", "fake"),
                                 lambda: "fake", lookup=lookup)
    srv.start()
    base = "http://127.0.0.1:8795"
    auth = {"Authorization": f"Bearer {server_mod.load_token()}"}
    try:
        r = requests.post(f"{base}/lookup", timeout=10, headers=auth,
                          json={"text": "hello"})
        assert r.status_code == 200, r.text
        assert r.json() == {"text": "שלום", "target": "Hebrew",
                            "backend": "fake", "seconds": 0.2}, r.json()
        no = requests.post(f"{base}/lookup", timeout=10, headers=auth,
                           json={"text": "empty"})
        assert no.status_code == 400 and "both-scripts" in no.json()["error"]
        blank = requests.post(f"{base}/lookup", timeout=10, headers=auth,
                              json={"text": "   "})
        assert blank.status_code == 400, blank.text
        assert asked == ["hello", "empty"], asked
        assert requests.post(f"{base}/lookup", timeout=10,
                             json={"text": "hello"}).status_code == 401
    finally:
        srv.stop()

    bare = server_mod.PhoneServer(cfg, lambda wav: ("", "fake"),
                                  lambda: "fake")
    bare.start()
    try:
        r = requests.post(f"{base}/lookup", timeout=10, headers=auth,
                          json={"text": "hello"})
        assert r.status_code == 503, r.text
        r = requests.get(f"{base}/review", timeout=10, headers=auth)
        assert r.status_code == 503, r.text
    finally:
        bare.stop()


def test_a_phone_dictation_is_kept_for_the_second_reading() -> None:
    """Until 2026-09-13 a phone clip was transcribed and forgotten, so the
    reading never saw it. Now it lands in recent\ stamped source=phone and
    is handed to the engine WITHOUT the desktop card — the phone asks
    GET /review for it instead."""
    import tempfile
    import types

    import main as main_mod
    import spool as spool_mod

    tmp = Path(tempfile.mkdtemp(prefix="phone-kept-"))
    recent = spool_mod.Spool(tmp / "recent", keep=5)
    submitted: list[tuple] = []
    engine = types.SimpleNamespace(
        submit=lambda item, hwnd=0, card=True: submitted.append(
            (item, hwnd, card)))
    wav = frames_to_wav([np.zeros(16000, dtype=np.int16)], 16000)

    app = types.SimpleNamespace(
        recent=recent, _review=engine, _last_words=[], _local=None,
        transcriber=types.SimpleNamespace(last_warning=None),
        _transcribe=lambda w, language=None: ("שלום מהטלפון", "fake"),
        _improve=lambda t, wait=False, receipt=None: t)
    text, backend, warning = main_mod.App._transcribe_for_phone(app, wav)
    assert text == "שלום מהטלפון" and backend == "fake" and warning is None
    assert len(submitted) == 1, submitted
    item, hwnd, card = submitted[0]
    # nobody repaired it before the reply: the reading's local repair may
    assert item.meta.get("repair") == "", item.meta
    assert card is False, "a phone clip must not raise the desktop card"
    assert item.meta["source"] == "phone", item.meta
    assert item.meta["text"] == "שלום מהטלפון"
    assert abs(item.meta["seconds"] - 1.0) < 0.05, item.meta["seconds"]
    assert item.wav_path.exists()


def test_splash_shuts_down_without_aborting_the_process() -> None:
    """Tk interpreters must be torn down on the thread that created them.
    Left to the GC, the after() callbacks keep root alive in a cycle that
    is collected on some other thread, and freeing Tcl from there aborts
    the process — a clean shutdown was exiting with code 3. Only visible
    at interpreter exit, so this has to be a subprocess."""
    import subprocess
    here = Path(__file__).resolve().parent
    script = (
        "import time, overlay as splash;"
        "s = splash.Splash(); s.start();"
        "s.status('loading…'); time.sleep(.3);"
        "s.finish('ready', linger_ms=60); time.sleep(.9);"
        "print('ok')"
    )
    out = subprocess.run([sys.executable, "-c", script], cwd=str(here),
                         capture_output=True, encoding="utf-8",
                         errors="replace", timeout=90)
    assert out.returncode == 0, (out.returncode, out.stdout, out.stderr)
    assert "Tcl_AsyncDelete" not in (out.stderr or ""), out.stderr


def test_a_closed_dashboard_buries_its_own_interpreter() -> None:
    """The dashboard had the same wrong-thread abort the ask card had,
    hidden behind an accident.

    ui._cache and ui._FONTS are module globals holding PhotoImages and
    Fonts, and each of those holds the tkapp -- so a closed window's
    interpreter was PINNED rather than garbage, and pinned is safe. But
    the NEXT Dashboard's __init__ calls ui.forget_images(), which drops
    that pin while the old window's cycle is still uncollected. From that
    instant the old interpreter is reachable only through a cycle, and
    whichever thread runs the next full collection calls
    Tcl_DeleteInterp. Tcl aborts when that is not the creating thread:
    exit code 3, no traceback, nothing in any log.

    Two windows and a collection on a third thread, which is the shape
    the suite itself has. Has to be a subprocess: the abort takes the
    whole process with it.
    """
    import subprocess
    here = Path(__file__).resolve().parent
    script = (
        "import gc, threading, ui, dashboard as dash;"
        "gc.disable();"
        "a = dash.Dashboard(); a.root.update(); a._close(); del a;"
        "b = dash.Dashboard(); b.root.update(); b._close(); del b;"
        "t = threading.Thread(target=gc.collect, name='not-the-builder');"
        "t.start(); t.join();"
        "print('ok')"
    )
    out = subprocess.run([sys.executable, "-c", script], cwd=str(here),
                         capture_output=True, encoding="utf-8",
                         errors="replace", timeout=120)
    assert out.returncode == 0, (out.returncode, out.stdout, out.stderr)
    assert "Tcl_AsyncDelete" not in (out.stderr or ""), out.stderr
    # and the burial has to be quiet: the poller and the reopen watcher
    # read self.closing to notice they should stop, so _bury leaves that
    # behind rather than killing them with an AttributeError
    assert "AttributeError" not in (out.stderr or ""), out.stderr


def test_closing_the_splash_cannot_close_the_status_dot() -> None:
    """The splash and the dot are two Tk interpreters alive at once, and
    `quitMainLoop` in _tkinter is a MODULE-LEVEL GLOBAL: quit() sets it and
    whichever mainloop reads it first returns and clears it. Measured over
    ten runs of the real startup sequence, five of them had the splash's
    quit() end the DOT's loop instead — no dot, and a splash left animating
    on screen for the rest of the session with nothing left to stop it.

    Run as a subprocess: it needs two fresh interpreters and it must not
    leave half-torn-down Tk state in the test process.
    """
    import subprocess
    here = Path(__file__).resolve().parent
    script = (
        "import os, time, overlay as ov, win32gui, win32process;"
        # The wait is derived, not typed. With the skin installed the
        # splash's close is followed by a ~2.7 s release, and the 1.6 s
        # that used to be here reported "the splash never closed" when it
        # was simply still playing.
        "import skin.boot as _b; whole = _b.moment_ms() / 1000.0;"
        "s = ov.Splash(); s.start(); s.status('loading...'); time.sleep(.4);"
        "d = ov.StatusDot(); d.start(); time.sleep(.3);"
        "s.finish('ready', linger_ms=60); time.sleep(whole + 1.6);"
        "me = os.getpid(); found = [];"
        # Two classes, because there are two ways this app draws an
        # overlay. 'TkTopLevel' is the original pair; the skin (skin\) puts
        # the same two windows on a plain CreateWindowExW popup so it can
        # use UpdateLayeredWindow, and that popup registers a class of its
        # own. What is being asserted has not changed — the splash must be
        # gone and the dot must not have gone with it — only the way the
        # two windows are found. Naming both keeps this test honest with
        # the skin installed AND with it deleted.
        "classes = ('TkTopLevel', 'DeskITSkinGlass');"
        "cb = lambda h, _: ("
        "    found.append(win32gui.GetWindowRect(h))"
        "    if win32process.GetWindowThreadProcessId(h)[1] == me"
        "    and win32gui.IsWindowVisible(h)"
        "    and win32gui.GetClassName(h) in classes else None);"
        "win32gui.EnumWindows(cb, None);"
        "sizes = [(r[2]-r[0], r[3]-r[1]) for r in found];"
        "print('SPLASH' if any(w > 200 for w, _ in sizes) else '', "
        "      'DOT' if any(w <= 40 for w, _ in sizes) else '', flush=True);"
        "os._exit(0)"
    )
    out = subprocess.run([sys.executable, "-c", script], cwd=str(here),
                         capture_output=True, encoding="utf-8",
                         errors="replace", timeout=120)
    assert out.returncode == 0, (out.returncode, out.stdout, out.stderr)
    shown = (out.stdout or "").strip()
    assert "SPLASH" not in shown, \
        f"the splash never closed — its quit() was eaten ({shown!r})"
    assert "DOT" in shown, \
        f"the dot was destroyed by the splash's quit() ({shown!r})"


def test_the_overlays_never_call_mainloop_or_quit() -> None:
    """The deterministic half of the test above. The race only shows up
    about half the time, so the rule it exists to protect is asserted
    directly: no overlay may touch the shared quit flag."""
    source = (Path(__file__).resolve().parent / "overlay.py").read_text("utf-8")
    # Comments and docstrings NAME both of these on purpose — they explain
    # why not to use them — so look at the code only.
    code = "\n".join(line.split("#", 1)[0] for line in source.splitlines())
    body = code.split('"""', 2)[-1]
    for forbidden in ("root.quit", ".mainloop("):
        assert forbidden not in body, (
            f"overlay.py calls {forbidden} — _tkinter's quit flag is shared "
            f"between interpreters, so this closes whichever overlay looks "
            f"at it first. Use _pump_until() and a per-overlay Event.")


def _glass_dot_here() -> bool:
    """The two probes of the REAL dot window below ask WM_NCHITTEST what
    the disc answers, and only skin\\dot has a window proc to answer:
    the Tk fallback (skin off, or no skia — the hosted CI runner, whose
    venv holds no Skin pack, 2026-09-18) is HTCLIENT everywhere and six
    pixels smaller. Those two tests say so and stand down rather than
    fail the fallback for not being glass; the arithmetic behind them is
    tested without a window in test_the_dot_is_a_button_only_on_its_disc."""
    skin = _skin_or_skip()
    if skin is not None and skin.on():
        return True
    print("        (no glass dot here — the Tk fallback has no hit "
          "plumbing to ask — skipping)")
    return False


def test_status_dot_takes_a_click_on_its_disc_and_nowhere_else() -> None:
    """The dot used to be click-through as a whole (WS_EX_TRANSPARENT),
    because it sat on the close button of every maximised window. Since
    2026-09-07 it sits in the bottom-right of the work area and THE DISC
    IS A BUTTON: the window carries no WS_EX_TRANSPARENT, WM_NCHITTEST
    answers HTCLIENT on the disc and HTTRANSPARENT everywhere else — the
    glow, the ring, the corners — and a click on the disc fires
    `on_click`, which main.py points at the shelf's toggle. Asked of the
    REAL window with SendMessage, so this is the probe for skin\\glass's
    hit plumbing as well. Also guards the same Tcl teardown bug as the
    splash, and the position: bottom-right of the WORK AREA, above the
    taskbar, the dot's own 8 x 4 px margins."""
    import subprocess
    import overlay as overlay_mod
    assert overlay_mod.WS_EX_TRANSPARENT == 0x20
    assert overlay_mod.DOT_CORNERS == ("bottom-right", "top-right")
    assert overlay_mod.StatusDot().corner == "bottom-right"
    assert overlay_mod.StatusDot().on_click is None, \
        "a dot nobody wired up must stay the old click-through layer"
    for name, (fill, ring, _) in overlay_mod.STATES.items():
        assert fill.startswith("#") and len(fill) == 7, (name, fill)
        assert ring.startswith("#") and len(ring) == 7, (name, ring)
    if not _glass_dot_here():
        return
    here = Path(__file__).resolve().parent
    # The window is checked, not just the exit code. Both real bugs here
    # (an AttributeError inside the thread, then a restyle applied before
    # the window was realised) left a process that exited 0 with either no
    # dot at all or a dot that ate clicks on the close button.
    script = r"""
import ctypes, ctypes.wintypes as w, time, overlay
clicks = []
d = overlay.StatusDot(); d.on_click = lambda: clicks.append(1)
d.start(); time.sleep(1.0)
u = ctypes.WinDLL('user32')
u.SendMessageW.restype = ctypes.c_longlong
u.SendMessageW.argtypes = [ctypes.c_void_p, ctypes.c_uint, ctypes.c_size_t,
                           ctypes.c_longlong]
class R(ctypes.Structure):
    _fields_ = [('l',ctypes.c_int),('t',ctypes.c_int),
                ('r',ctypes.c_int),('b',ctypes.c_int)]
hits = []
def cb(h, l):
    if u.IsWindowVisible(h):
        rc = R(); u.GetWindowRect(h, ctypes.byref(rc))
        if 10 < rc.r-rc.l < 60 and 10 < rc.b-rc.t < 60:
            hits.append((h, u.GetWindowLongW(h,-20) & 0xffffffff,
                         rc.l, rc.t, rc.r, rc.b))
    return True
u.EnumWindows(ctypes.WINFUNCTYPE(
    ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)(cb), None)
assert hits, 'no dot window'
hwnd, ex, left, top, right, bottom = hits[0]
assert not (ex & 0x20), 'click-through as a whole: the disc is a button'
assert ex & 0x08000000, 'not no-activate: it would steal focus'
work = w.RECT(); u.SystemParametersInfoW(0x0030, 0, ctypes.byref(work), 0)
assert right == work.right - 8, ('not at the right margin', right, work.right)
assert bottom == work.bottom - 4, ('not above the taskbar', bottom, work.bottom)
def lp(x, y): return (int(y) & 0xFFFF) << 16 | (int(x) & 0xFFFF)
cx, cy = (left + right) // 2, (top + bottom) // 2
def hit(x, y): return u.SendMessageW(hwnd, 0x0084, 0, lp(x, y))
assert hit(cx, cy) == 1, ('the disc is not a button', hit(cx, cy))
assert hit(cx + 14, cy) == -1, ('the glow took the click', hit(cx + 14, cy))
assert hit(left + 1, top + 1) == -1, 'the corner took the click'
assert hit(right - 1, bottom - 1) == -1, 'the corner took the click'
# WM_LBUTTONDOWN at the centre, client coordinates: the callback fires
u.SendMessageW(hwnd, 0x0201, 1, lp(cx - left, cy - top)); time.sleep(.2)
assert clicks == [1], ('a click on the disc did nothing', clicks)
u.SendMessageW(hwnd, 0x0201, 1, lp(cx - left, cy - top)); time.sleep(.2)
assert clicks == [1], ('a double-click toggled twice', clicks)
for s in ('recording','locked','busy','ready'):
    d.set_state(s); time.sleep(.1)
d.stop(); print('ok')
"""
    out = subprocess.run([sys.executable, "-c", script], cwd=str(here),
                         capture_output=True, encoding="utf-8",
                         errors="replace", timeout=90)
    assert out.returncode == 0, (out.returncode, out.stdout, out.stderr)
    assert "ok" in out.stdout, out.stdout
    assert "Tcl_AsyncDelete" not in (out.stderr or ""), out.stderr


def test_the_real_dot_window_moves_while_the_app_keeps_running() -> None:
    """The whole of bug one, asked of the REAL window.

    "The dot — I want it to be movable, and without needing to open and
    close the app" (2026-09-07). So nothing here restarts anything: one
    StatusDot is started ONCE and then, on the live window, this checks
    that a saved position is where the window actually is; that arming
    move mode turns the disc's WM_NCHITTEST answer from HTCLIENT into
    HTCAPTION while every other pixel stays HTTRANSPARENT; that a click
    on the disc cannot open the shelf while it is armed; that "back to
    the corner" walks the same window home without a restart; and that
    the dot reports its own rectangle, which is the square the shelf must
    not close for.

    In a subprocess like every other window test here: the dot owns a
    long-lived thread, and burying one from the suite's main thread is
    the Tcl_AsyncDelete abort those tests exist to avoid.
    """
    import subprocess
    if not _glass_dot_here():
        return
    here = Path(__file__).resolve().parent
    script = r"""
import ctypes, ctypes.wintypes as w, time, overlay
clicks = []
saved = []
d = overlay.StatusDot(x=520, y=340, on_change=saved.append)
d.on_click = lambda: clicks.append(1)
d.start(); time.sleep(1.0)
u = ctypes.WinDLL('user32')
u.SendMessageW.restype = ctypes.c_longlong
u.SendMessageW.argtypes = [ctypes.c_void_p, ctypes.c_uint, ctypes.c_size_t,
                           ctypes.c_longlong]
class R(ctypes.Structure):
    _fields_ = [('l',ctypes.c_int),('t',ctypes.c_int),
                ('r',ctypes.c_int),('b',ctypes.c_int)]
hits = []
def cb(h, l):
    if u.IsWindowVisible(h):
        rc = R(); u.GetWindowRect(h, ctypes.byref(rc))
        if 10 < rc.r-rc.l < 60 and 10 < rc.b-rc.t < 60:
            hits.append((h, rc.l, rc.t, rc.r, rc.b))
    return True
u.EnumWindows(ctypes.WINFUNCTYPE(
    ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)(cb), None)
assert hits, 'no dot window'
hwnd, left, top, right, bottom = hits[0]
assert (left, top) == (520, 340), ('a saved position was ignored', left, top)
assert d.rect == (left, top, right, bottom), ('the dot does not say where '
                                              'it is', d.rect)
def lp(x, y): return (int(y) & 0xFFFF) << 16 | (int(x) & 0xFFFF)
cx, cy = (left + right) // 2, (top + bottom) // 2
def hit(x, y): return u.SendMessageW(hwnd, 0x0084, 0, lp(x, y))
assert hit(cx, cy) == 1, ('the disc is not a button', hit(cx, cy))
# ARM IT — no restart, no new window, the same hwnd throughout
assert d.move(seconds=20) is True
time.sleep(0.3)
assert hit(cx, cy) == 2, ('the disc does not hand the drag to Windows',
                          hit(cx, cy))
assert hit(cx + 14, cy) == -1, 'the glow took the drag'
assert hit(left + 1, top + 1) == -1, 'the corner took the drag'
u.SendMessageW(hwnd, 0x0201, 1, lp(cx - left, cy - top)); time.sleep(.2)
assert clicks == [], ('a press mid-move opened the shelf', clicks)
# THE RELEASE. WM_NCLBUTTONUP is what Windows sends when its move loop
# lets go, and it sends it whether or not the window went anywhere: this
# is the press he thought better of, so nothing is written - and move
# mode is over either way, because he asked for ONE move and a disc left
# armed is a disc that cannot open the shelf.
#
# WHERE THE DRAG ITSELF IS TESTED, AND WHY NOT HERE. The drag is
# Windows' own modal loop and it needs real mouse input; and this window
# is a layered one whose position is re-applied by every
# UpdateLayeredWindow, so a SetWindowPos standing in for a drag is undone
# by the next frame before the message can arrive. What that would have
# covered is covered without a window instead:
# test_the_dot_can_be_dropped_anywhere_and_is_remembered has the clamp
# and test_move_mode_expires_and_a_drop_writes_one_pair_of_lines has
# placed() and the write. What is checked HERE is the wiring - that the
# message reaches the dot at all, and what it does when it does.
#
# AND THE Tk FALLBACK CANNOT STAND IN FOR IT EITHER, measured 2026-09-08.
# That path tracks the drag with its own <Button-1>/<B1-Motion> bindings
# rather than handing it to Windows, so it looks drivable by SendMessage
# - and it is not: Tk builds a mouse event's position from GetMessagePos,
# which reports the last message taken OFF THE QUEUE, and SendMessage
# never goes near the queue. Probed on the hidden desktop, every synthetic
# press arrived at the real pointer's coordinates, i.e. outside the disc,
# so `press` returned before it did anything. Both paths need a real hand.
u.SendMessageW(hwnd, 0x00A2, 2, lp(cx, cy)); time.sleep(.4)
assert saved == [], ('a press that moved nothing was saved', saved)
assert d.moving() is False, 'a release has to disarm it'
assert d.rect[:2] == (520, 340), ('the dot wandered on a release that '
                                  'moved nothing', d.rect)
u.SendMessageW(hwnd, 0x0201, 1, lp(cx - left, cy - top)); time.sleep(.2)
assert clicks == [1], ('the disc stopped being a button', clicks)
# and home again, live
d.to_corner(); time.sleep(0.4)
rc = R(); u.GetWindowRect(hwnd, ctypes.byref(rc))
work = w.RECT(); u.SystemParametersInfoW(0x0030, 0, ctypes.byref(work), 0)
assert rc.r in (work.right - 8, work.right - 10), ('not back at the right '
                                                   'margin', rc.r, work.right)
assert rc.b in (work.bottom - 4, work.bottom - 6), ('not back above the '
                                                    'taskbar', rc.b)
assert saved == [{'x': -100000, 'y': -100000}], saved
d.stop()
assert d.rect is None, 'a dot with no window still claims a square'
print('ok')
"""
    out = subprocess.run([sys.executable, "-c", script], cwd=str(here),
                         capture_output=True, encoding="utf-8",
                         errors="replace", timeout=90)
    assert out.returncode == 0, (out.returncode, out.stdout, out.stderr)
    assert "ok" in out.stdout, out.stdout
    assert "Tcl_AsyncDelete" not in (out.stderr or ""), out.stderr


def test_the_dot_still_moves_with_the_skin_folder_gone() -> None:
    """skin\\'s promise for the dot, and it is not only about pixels.

    Delete the folder and the dot comes back as a chroma-keyed Tk oval —
    which is a different window, a different size and a different way of
    taking the mouse. What must NOT change is where it sits: a position
    dropped on the glass path is honoured here too (overlay.dot_spot is
    one arithmetic with two boxes), the disc still opens the shelf, and
    while it is waiting to be dragged that same press starts a drag
    instead of opening anything.

    HD_SKIN=0 takes exactly that road, in a subprocess like every other
    window test here.
    """
    _run_window_script('''
import os, time
os.environ["HD_SKIN"] = "0"

import skin
skin.reset()
assert skin.on() is False, "HD_SKIN=0 must switch the skin off"

import overlay

clicks = []
saved = []
d = overlay.StatusDot(x=430, y=260, on_change=saved.append)
d.on_click = lambda: clicks.append(1)
d.start()
for _ in range(150):
    if d.rect is not None:
        break
    time.sleep(0.02)
assert d.rect is not None, "the flat dot never mapped"
assert d.rect[:2] == (430, 260), ("a saved position was ignored", d.rect)
box = d.rect[2] - d.rect[0]
assert 10 < box < 40, ("the fallback dot changed size", box)
# and home again, live, with no restart
d.to_corner()
for _ in range(150):
    if d.rect[:2] != (430, 260):
        break
    time.sleep(0.02)
assert d.rect[:2] != (430, 260), "Back to the corner did not move it"
assert saved == [{"x": -100000, "y": -100000}], saved
assert d.moving() is False
d.move(seconds=20)
assert d.moving() is True
d.stop()
assert d.rect is None and d.moving() is False, \\
    "a dot with no window still claims a square, or is still armed"
print("ok")
''')


def test_the_dot_is_a_button_only_on_its_disc() -> None:
    """The arithmetic behind the probe above, checked without a window:
    HTCLIENT inside the disc plus two pixels, HTTRANSPARENT at 14 px and
    at the corners; and `place` puts the 38 px box in the bottom-right of
    the WORK AREA it is given, with the same margins the top-right always
    had. BOX stays 38 — two tests identify the dot by its size."""
    skin = _skin_or_skip()
    if skin is None or not skin.on():
        return
    from skin import dot as skin_dot
    from skin.glass import HTCLIENT, HTTRANSPARENT

    assert skin_dot.BOX == 38 and skin_dot.CORE == 10.0
    assert skin_dot.HIT_R == skin_dot.CORE / 2 + 2
    assert skin_dot.CORNERS == ("bottom-right", "top-right")
    assert skin_dot.DEFAULT_CORNER == "bottom-right"
    d = skin_dot.Dot()
    c = skin_dot.BOX / 2
    assert d.corner == "bottom-right"
    assert d.hit(c, c) == HTCLIENT
    assert d.hit(c + 7, c) == HTCLIENT and d.hit(c, c - 7) == HTCLIENT
    assert d.hit(c + 8, c) == HTTRANSPARENT, "the ring is not a button"
    assert d.hit(c + 14, c) == HTTRANSPARENT, "the glow is not a button"
    for corner in ((0, 0), (0, 37), (37, 0), (37, 37)):
        assert d.hit(*corner) == HTTRANSPARENT, corner
    work = (0, 0, 2560, 1392)                 # this machine: a 48 px taskbar
    assert skin_dot.place("bottom-right", work) == (2560 - 38 - 8,
                                                    1392 - 38 - 4, 38, 38)
    assert skin_dot.place("top-right", work) == (2560 - 38 - 8, 4, 38, 38)
    # a work area that does not start at the origin is a monitor like
    # any other
    assert skin_dot.place("bottom-right", (-1920, 100, 1920, 1000)) == \
        (-1920 + 1920 - 46, 100 + 1000 - 42, 38, 38)
    assert skin_dot.Dot("sideways").corner == "bottom-right", \
        "a corner the dot cannot sit in falls back rather than raises"


def test_the_dot_glows_to_nothing_inside_its_own_window() -> None:
    """THE DOT LOOKED LIKE A SQUARE. The halo was a radial gradient of
    radius CORE * 2.6 = 26 px in a 38 px window, which left alpha 27 at
    every edge midpoint (0 at the corners) — a faint tinted square on any
    wallpaper or title bar. Measured 2026-09-07: 27/27/27/27 for every lit
    state. Every glow and sweep now reaches alpha 0 strictly inside the
    window, so this walks the WHOLE border of every state, after the
    cross-fade has settled (14 frames), and asks for zero. The halo still
    has to read: alpha > 8 at 14 px from the centre, as the paused test
    already requires."""
    skin = _skin_or_skip()
    if skin is None or not skin.on():
        return
    try:
        import skia
        from skin import dot as skin_dot
        from skin.palette import DOT_STATES
    except Exception:
        return
    B = skin_dot.BOX
    assert skin_dot.HALO_R <= B / 2 - 1, skin_dot.HALO_R
    for state in DOT_STATES:
        d = skin_dot.Dot()
        d.set(state)                          # from "ready", cross-fading
        surface = skia.Surface(B, B)
        canvas = surface.getCanvas()
        for frame in range(14):
            d.draw(canvas, frame * 22.0)      # the sweep turns, the breath breathes
        alpha = surface.makeImageSnapshot().toarray(
            colorType=skia.kRGBA_8888_ColorType)[:, :, 3]
        border = [int(alpha[0].max()), int(alpha[B - 1].max()),
                  int(alpha[:, 0].max()), int(alpha[:, B - 1].max())]
        assert border == [0, 0, 0, 0], (
            f"the {state} dot paints its window's edge {border} — that is "
            f"the square")
        mid = B // 2
        for x, y in ((0, mid), (B - 1, mid), (mid, 0), (mid, B - 1),
                     (0, 0), (0, B - 1), (B - 1, 0), (B - 1, B - 1)):
            assert alpha[y, x] == 0, (state, x, y, int(alpha[y, x]))
        if state not in skin.palette.NO_HALO:
            assert alpha[mid, mid + 14] > 8, (
                f"the {state} halo no longer reads at 14 px")


def test_status_dot_ignores_states_it_does_not_know() -> None:
    """set_state is called from the keyboard hook. A typo must not raise
    there — an exception inside the hook makes Windows drop it."""
    import overlay as overlay_mod
    dot = overlay_mod.StatusDot.off()
    dot.start(); dot.set_state("recording"); dot.set_state("nonsense")
    dot.stop()
    assert dot._thread is None
    assert overlay_mod._mix("#ffffff", "#000000", 0.5) == "#808080"
    assert overlay_mod._mix("#2d6cdf", "#0b0c0d", 1.0) == "#2d6cdf"


def test_paused_is_the_one_dot_state_with_no_halo() -> None:
    """Paused reads by the halo's ABSENCE, and that has to be in pixels.

    It is the only neutral in the set. On a grey wallpaper hue alone would
    leave paused and listening a coin toss for anyone who does not see
    blue, and a grey halo is a smudge rather than a light — so the app
    draws no halo at all for paused and one for every other state. That is
    a rule about drawing, not about a colour table, which is why the check
    is on the rendered alpha 8 px out from the disc rather than on
    DOT_STATES.
    """
    skin = _skin_or_skip()
    if skin is None or not skin.on():
        return
    try:
        import skia
        from skin import dot as skin_dot
    except Exception:
        return

    def halo_alpha(state: str) -> int:
        d = skin_dot.Dot()
        d.state = d._shown = d._from = state
        d._blend = 1.0
        surface = skia.Surface(skin_dot.BOX, skin_dot.BOX)
        canvas = surface.getCanvas()
        canvas.clear(0x00000000)
        d.draw(canvas, 0.0)      # t=0: the breath is at its brightest
        alpha = surface.makeImageSnapshot().toarray(
            colorType=skia.kRGBA_8888_ColorType)[:, :, 3]
        mid = skin_dot.BOX // 2
        # Outside the disc and its containing ring, inside the halo.
        return int(alpha[mid, mid + int(skin_dot.CORE * 1.4)])

    assert halo_alpha("paused") == 0, (
        "the paused dot is glowing — it is the one state whose meaning is "
        "carried by having no halo")
    for state in ("ready", "recording", "locked", "busy"):
        assert halo_alpha(state) > 8, (
            f"the {state} dot has no halo; every lit state glows, and the "
            f"halo is the whole reason this is a layered window")


def test_the_app_hands_gdi_its_own_fonts_before_it_asks_for_one() -> None:
    """Being installed is a promise to the next logon, not an answer here.

    Measured 2026-09-06: all four Rubik files on disk, registered under
    HKCU, installed 17 days earlier and past a reboot — and a fresh
    process asking GDI for the family "Rubik" got Arial, so
    ui.pick_face(["Rubik"]) returned "Segoe UI" and the whole app had been
    drawing in the fallback face without a word about it. fonts.load()
    hands the files to THIS process, and ui.py has to call it before it
    picks a face or the fix arrives after the question.
    """
    import fonts as fonts_mod

    first = fonts_mod.load()
    assert first == fonts_mod.load(), "load() is not idempotent"
    assert first == fonts_mod.loaded()
    assert any(name.lower().startswith("rubik") for name in first), \
        f"fonts\\ handed GDI nothing that looks like Rubik: {first}"

    source = (Path(__file__).resolve().parent / "ui.py").read_text("utf-8")
    load_at = source.find("_fonts.load()")
    pick_at = source.find("DISPLAY = pick_face")
    assert 0 < load_at < pick_at, (
        "ui.py asks GDI for a face before it has handed GDI the files — "
        "the load has to come first or it changes nothing this run")

    import ui as ui_mod
    found, hebrew = ui_mod._gdi_face("Rubik")
    assert found and hebrew, (
        "GDI does not resolve 'Rubik' even after the private load; the "
        "window is drawing in Segoe UI and every size here is tuned for "
        "the other face")


def test_splash_off_is_inert_and_nothing_ever_raises() -> None:
    """It is decoration. On a machine with no display, no Tk, or a hostile
    window manager it must degrade to nothing, not take dictation down."""
    import overlay as overlay_mod
    off = overlay_mod.Splash.off()
    off.start(); off.status("x"); off.finish("y")
    assert off._thread is None, "off() started a thread"
    never_started = overlay_mod.Splash()
    never_started.status("x"); never_started.finish()   # must not raise


def test_the_ready_cue_lands_with_the_light_and_not_before_it() -> None:
    """The sound and the picture are one event, or they are two mistakes.

    `beep("ready")` used to sit one line above `splash.finish(...)`, and
    finish() only SCHEDULES the release: 1100 ms of linger, then GATHER_MS
    of wind-up, then the reveal's own second and a bit before its light
    reaches the corner dot. Measured, the cue arrived 3.5 s ahead of the
    thing it is the sound of — you heard the app become ready, and then
    watched it happen. It is handed to finish() as `on_land` now and
    fired from the draw loop on the landing frame.

    Three assertions, because this can come back three ways: the wrong
    instant, the wrong number of times, or main() playing it again itself.
    """
    import ast
    import overlay as overlay_mod
    import skin.boot as boot_mod
    import skin.burst as burst_mod
    import skin.reveal as reveal_mod

    # WHEN. reveal.py converges on the dot and its arrival pulse is drawn
    # from T_LAND[1] - 320, which is the first frame of the arrival and
    # the one the cue is tied to. burst.py (the CPU fallback) does not
    # converge on anything, so its only honest sync point is its flash.
    reveal = reveal_mod.Reveal(1920, 1080, origin=(1600.0, 900.0), seed=7)
    assert boot_mod._land_ms(reveal) == reveal_mod.T_LAND[1] - 320
    assert boot_mod._land_ms(object()) == burst_mod.T_FLASH[0]
    # ...and it is the status dot's own centre the light arrives at, which
    # is what makes the cue land ON something. boot._landing asks
    # skin/dot.place, so the dot and the landing cannot drift apart:
    # bottom-right of the WORK AREA (above the taskbar) since 2026-09-07,
    # top-right when [dot] corner says so.
    from skin import dot as skin_dot
    box, work = (0, 0, 1920, 1080), (0, 0, 1920, 1040)
    for corner in skin_dot.CORNERS:
        x, y, w, h = skin_dot.place(corner, work)
        assert boot_mod._landing(corner, box, work) == (x + w / 2, y + h / 2)
    assert boot_mod._landing("bottom-right", box, work) == (1920 - 27.0,
                                                            1040 - 23.0)
    assert boot_mod._landing("top-right", box, work) == (1920 - 27.0, 23.0)
    aimed = reveal_mod.Reveal(1920, 1080, origin=(1600.0, 900.0), seed=7,
                              landing=boot_mod._landing("bottom-right", box,
                                                        work))
    assert aimed.landing == (1893.0, 1017.0), aimed.landing
    # built bare (preview, record, the warm-up) it assumes the default
    # corner and the whole layer
    assert reveal.landing == (1920 - 27.0, 1080 - 23.0), reveal.landing

    # ONCE, AND NEVER LOST. Three separate backstops call land() — the
    # draw loop, boot.run's finally and Splash._run's — so it has to be
    # idempotent; and a splash with no thread has no release coming, so
    # it must fire immediately rather than wait for a landing that cannot
    # happen (that is `splash = false`, and any machine without Tk).
    fired = []
    never_ran = overlay_mod.Splash()
    never_ran.finish("ready", on_land=lambda: fired.append(1))
    assert fired == [1], f"the cue was lost when there was no splash: {fired}"
    never_ran.land(); never_ran.land()
    assert fired == [1], f"the cue fired more than once: {fired}"

    # THE WINDOW THAT ACTUALLY LOST IT, and the reason the handoff is
    # decided by a flag and not by Thread.is_alive(): the splash thread
    # runs its final land() and only THEN dies, so for a moment it is
    # alive with no landing left in it. A cue armed there was handed to a
    # queue nobody would ever read again, and the boot went silent.
    import threading
    import time

    def _dying_splash() -> "overlay_mod.Splash":
        splash = overlay_mod.Splash()
        splash._thread = threading.Thread(target=lambda: time.sleep(2),
                                          daemon=True)
        splash._thread.start()
        return splash

    late = []
    stopping = _dying_splash()
    stopping._landings_over = True          # its last land() has been and gone
    stopping.finish("ready", on_land=lambda: late.append(1))
    assert stopping._thread.is_alive(), "the fixture stopped being the race"
    assert late == [1], (
        "the cue was lost to a splash thread that was still alive but had "
        "already run its last land()")

    # ...while a splash that still HAS a landing coming must not fire at
    # finish() time — that is the 3.5 s-early bug this whole test is about.
    early = []
    _dying_splash().finish("ready", on_land=lambda: early.append(1))
    assert early == [], "the cue fired at finish() instead of at the landing"

    # A cue that throws may not take the boot down with it: land() is
    # called from the splash thread, where an escape is a dead animation.
    def boom() -> None:
        raise RuntimeError("the cue blew up")

    overlay_mod.Splash().finish("ready", on_land=boom)   # must not raise

    # NOT IN MAIN ANY MORE. The regression is one line moving back up.
    # Read with ast, not line by line: a line scan saw `on_land=` and
    # `beep("ready")` on two lines of ONE call when the call was wrapped
    # (cfd3ee1, 2026-09-18) and failed the runner with the code right.
    def _ready_beep(node) -> bool:
        return (isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name) and node.func.id == "beep"
                and len(node.args) == 1
                and isinstance(node.args[0], ast.Constant)
                and node.args[0].value == "ready")

    tree = ast.parse(
        (Path(__file__).resolve().parent / "main.py").read_text("utf-8"))
    beeps = {id(n): n for n in ast.walk(tree) if _ready_beep(n)}
    assert beeps, "main.py no longer plays the ready cue at all"
    handed = {id(n) for kw in ast.walk(tree)
              if isinstance(kw, ast.keyword) and kw.arg == "on_land"
              for n in ast.walk(kw.value) if _ready_beep(n)}
    stray = [f"main.py:{n.lineno}" for i, n in beeps.items()
             if i not in handed]
    assert not stray, (
        f"main.py plays the ready cue itself again: {stray}. It belongs to "
        f"the landing frame — pass it to splash.finish(on_land=...) so the "
        f"sound and the light are the same event.")


def test_splash_log_forwards_app_messages_and_trims_long_ones() -> None:
    """The phone URL carries a token long enough to reflow the window."""
    import logging

    import main as main_mod

    seen: list[str] = []

    class Fake:
        def status(self, text): seen.append(text)

    handler = main_mod.SplashLog(Fake())
    logger = logging.getLogger("splash-test")
    logger.addHandler(handler)
    logger.setLevel(logging.INFO)
    try:
        logger.info("local model %s ready on %s", "ivrit", "cuda")
        logger.debug("noise that must not appear")
        logger.info("x" * 400)
    finally:
        logger.removeHandler(handler)
    assert seen[0] == "local model ivrit ready on cuda", seen
    assert len(seen) == 2, seen
    assert len(seen[1]) <= 110 and seen[1].endswith("…"), len(seen[1])


def test_subprocess_output_survives_a_hebrew_locale() -> None:
    """This machine's locale code page is cp1255. subprocess(text=True)
    decodes with it, so a tool emitting UTF-8 raises UnicodeDecodeError in
    the reader thread and returns stdout=None — and because that is a
    ValueError, a broad except reports the tool as absent. Exactly how the
    app came to log "tailscale is not up" while Tailscale was up."""
    import json as json_mod

    import server as server_mod

    # “ is 0x9c in cp1255's undefined range — the real byte that broke it
    payload = {"Self": {"DNSName": "yoav.example.ts.net."},
               "note": "עברית “quoted”"}
    script = ("import sys,io;"
              "sys.stdout=io.TextIOWrapper(sys.stdout.buffer,encoding='utf-8');"
              f"print({json_mod.dumps(json_mod.dumps(payload))})")
    out = server_mod.run_utf8([sys.executable, "-c", script])
    assert out is not None, "utf-8 stdout came back as None"
    assert json_mod.loads(out)["Self"]["DNSName"] == "yoav.example.ts.net."
    assert server_mod.run_utf8(["definitely-not-a-real-binary-xyz"]) is None


