def test_long_selections_reach_the_local_model_in_parts() -> None:
    """Select-all used to be refused outright at lookup.max_chars = 5000,
    which the owner read as "it didn't translate". Now the LOCAL path
    feeds gemma3 in ~3800-char pieces — inside the runner's context
    window — joined with newlines, with progress between parts. Gemini is
    never chunked: its API takes the whole selection in one request and
    always did.
    """
    import lookup as lookup_mod

    class Backend:
        name = "ollama"

        def __init__(self):
            self.asked = []

        def translate(self, text):
            self.asked.append(len(text))
            return f"[{len(self.asked)}]"

    text = "\n".join(f"paragraph {i} " + "word " * 90
                     for i in range(120))          # ~12k chars of prose
    assert len(text) > lookup_mod._LOCAL_CHUNK * 2, \
        "the sample must force several parts"

    backend = Backend()
    got = lookup_mod.translate_chunked(backend, text)
    assert len(backend.asked) >= 2, "one request for 12k chars"
    assert all(n <= lookup_mod._LOCAL_CHUNK for n in backend.asked), \
        backend.asked
    assert sum(backend.asked) <= len(text), "parts grew beyond the source"
    assert got.startswith("[1]") and got.count("[") == len(backend.asked)

    # Progress fires before each part AFTER the first, never before it.
    seen = []
    second = Backend()
    lookup_mod.translate_chunked(second, text,
                                 lambda i, n: seen.append((i, n)))
    assert seen[0] == (2, len(second.asked)), seen
    assert seen[-1] == (len(second.asked), len(second.asked)), seen

    # A Gemini-shaped backend takes the whole thing in one request.
    class Cloud(Backend):
        name = "gemini"

    cloud = Cloud()
    lookup_mod.translate_chunked(cloud, text)
    assert cloud.asked == [len(text)], cloud.asked


def test_the_local_splitter_cuts_where_prose_allows() -> None:
    """The parts must each fit the request, must never start or end in
    stray whitespace, and — unless a paragraph has no sentence end at all
    — must cut at a sentence boundary rather than mid-word."""
    import lookup as lookup_mod

    limit = 400
    sentences = ("משפט ראשון נגמר כאן. משפט שני בא אחריו. "
                 "והנה משפט שלישי ארוך יחסית במידה זו. ")
    text = sentences * 60                      # ~5k chars, one paragraph
    parts = lookup_mod._split_for_local(text, limit)
    assert len(parts) >= 2, "one part for 5k chars against a 400 limit"
    total = 0
    for part in parts:
        assert 0 < len(part) <= limit, (len(part), limit)
        assert part == part.strip(), repr(part[:20])
        assert part.rstrip().endswith((".")), repr(part[-20:])
        total += len(part)
    assert total >= int(len(text) * 0.9), (total, len(text))

    # No sentence punctuation anywhere: the hard-cut last resort still
    # bounds every piece.
    run = "אבגד" * 1500                         # 6000 chars, no breaks
    hard = lookup_mod._split_for_local(run, limit)
    assert all(len(part) <= limit for part in hard), \
        [len(p) for p in hard]
    assert "".join(hard) == run, "the hard cut lost characters"


def test_the_clipboard_comes_back_on_every_way_out() -> None:
    """Read-only has to mean read-only on the paths that go wrong too.
    Four ways out — an answer, an empty selection, a refusal before any
    request, and a backend that raised — and the clipboard is handed back
    on all four, with nothing else touched on any of them.

    The mechanism underneath is asserted rather than assumed: the restore
    lives in a finally and not after the loop, because anything raising
    between the copy and the restore leaves the user's clipboard holding
    the text that was captured (verified destroyed 3/3 without it,
    survived 2/2 with it)."""
    import ast
    import inspect
    import shutil
    import tempfile

    import main as main_mod
    import translate as translate_mod

    tmp = Path(tempfile.mkdtemp(prefix="dictation-lookup-clip-"))
    real_inj = main_mod.injector
    played, restore = _cue_spy(main_mod)
    try:
        ways_out = [
            ("an answer", "brittle", "שביר"),
            ("nothing selected", "", "never reached"),
            ("nothing to translate", "https://example.com/a",
             "never reached"),
            ("the backend refused", "brittle",
             translate_mod.TranslationError("no model")),
        ]
        for label, selection, answer in ways_out:
            fake = _FakeInjector()
            app = _lookup_app(tmp, fake, answer)
            fake.selection = selection
            fake.selection_reason = "ok" if selection else "nothing-selected"
            app._lookup(fake.focus)
            assert fake.calls.count(
                ("restore", "whatever the user had")) == 1, (label,
                                                             fake.calls)
            assert not [c for c in fake.calls
                        if c[0] not in ("read", "restore")], (label,
                                                              fake.calls)

        source = inspect.getsource(injector.read_selection)
        tree = ast.parse(source)

        def _restores(body):
            return any(isinstance(node, ast.Name)
                       and node.id == "_restore_if_touched"
                       for statement in body
                       for node in ast.walk(statement))

        assert any(isinstance(node, ast.Try) and _restores(node.finalbody)
                   for node in ast.walk(tree)), \
            ("read_selection puts the clipboard back outside a finally — "
             "anything raising between the copy and the restore then "
             "leaves the captured text sitting in the user's clipboard")
    finally:
        restore()
        main_mod.injector = real_inj
        shutil.rmtree(tmp, ignore_errors=True)


def test_a_lookup_holds_the_cursor_only_while_it_reads() -> None:
    """_translate holds _cursor_lock across the whole 1-3 s model call
    because it is going to paste at the end and the cursor has to still be
    where it found it. This key has nothing to paste: holding the lock
    that long would be a dictation waiting seconds on a clipboard nobody
    is using any more. Asserted from inside both halves, because the
    difference is invisible from outside."""
    import shutil
    import tempfile

    import main as main_mod

    tmp = Path(tempfile.mkdtemp(prefix="dictation-lookup-lock-"))
    fake = _FakeInjector()
    real_inj = main_mod.injector
    played, restore = _cue_spy(main_mod)
    try:
        app = _lookup_app(tmp, fake, "שביר")
        fake.selection = "brittle"
        seen: list[tuple[str, bool]] = []
        fake.on_read = lambda: seen.append(
            ("reading", app._cursor_lock.locked()))
        engine = app._lookup_engine
        asked = engine.look_up

        def watched(text, decision=None, on_status=None, on_chunk=None, on_progress=None):
            seen.append(("asking the model", app._cursor_lock.locked()))
            return asked(text, decision, on_status, on_chunk)

        engine.look_up = watched
        app._lookup(fake.focus)
        assert seen == [("reading", True),
                        ("asking the model", False)], seen
        assert not app._cursor_lock.locked(), "the lock was left held"
    finally:
        restore()
        main_mod.injector = real_inj
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_lookup_key_takes_turns_with_itself_and_nobody_else() -> None:
    """One clipboard, so a second press while one is in flight is dropped
    — but a press of a TEXT key is not. They queue separately on purpose:
    by the time the lookup's model answers it has long since given the
    clipboard back, so making F9 wait for it would buy nothing."""
    import shutil
    import tempfile

    import main as main_mod

    tmp = Path(tempfile.mkdtemp(prefix="dictation-lookup-turns-"))
    fake = _FakeInjector()
    real_inj = main_mod.injector
    played, restore = _cue_spy(main_mod)
    try:
        main_mod.injector = fake
        app = _worker_app(_Flaky(fail_times=0), tmp)
        app._on_tap("lookup")
        assert app.lookup_queue.qsize() == 1, app.lookup_queue.qsize()
        # A pair now: the window the selection is in, and the mouse point
        # the answer has to appear beside. Both are read on the hook
        # thread because both are only true at the moment of the press.
        hwnd, anchor = app.lookup_queue.get()
        assert hwnd == fake.focus, hwnd
        assert anchor is None or (len(anchor) == 2
                                  and all(isinstance(v, int)
                                          for v in anchor)), anchor
        app._on_tap("lookup")                  # the first is still running
        assert app.lookup_queue.qsize() == 0, app.lookup_queue.qsize()
        assert played == ["noop"], played

        app._on_tap("translate")               # a different queue entirely
        assert app.text_queue.get() == ("translate", fake.focus)

        app._looking_up.clear()                # the worker finished
        app._on_tap("lookup")
        assert app.lookup_queue.get()[0] == fake.focus
    finally:
        restore()
        main_mod.injector = real_inj
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_box_opens_where_the_key_was_pressed_and_waits_to_be_closed(
) -> None:
    """Two decisions main.py makes on every press, and nowhere else.

    The anchor, because the box used to appear in the bottom-right corner
    of the screen whatever you were reading — an answer about a word in
    the top-left of a browser window, 1500 px away from it. The mouse
    point is what makes it appear beside the word instead: a selection is
    made by dragging across it, so the cursor is left at the end of what
    was selected. WHERE the box then lands is popup.py's arithmetic and is
    proved there; that it is handed the point at all is this.

    And dwell_ms = 0, which is the owner's actual complaint. It used to be
    handed lookup.dwell_ms — 12 s — so an answer he was still reading took
    itself away, and a box that vanishes on a timer is indistinguishable
    from one that vanished because of a bug. It waits to be closed now.
    """
    import shutil
    import tempfile

    import main as main_mod

    tmp = Path(tempfile.mkdtemp(prefix="dictation-lookup-anchor-"))
    fake = _FakeInjector()
    real_inj = main_mod.injector
    played, restore = _cue_spy(main_mod)
    try:
        app = _lookup_app(tmp, fake, "שביר")
        fake.selection = "brittle"
        app._lookup(fake.focus, (1234, 567))
        assert app.popup.anchors == [(1234, 567)], app.popup.anchors
        assert app.popup.dwells == [0], app.popup.dwells

        # And it survives the answer landing on top of the ellipsis:
        # popup.update re-places from the anchor show() was given, so the
        # box grows away from the text rather than moving out from under
        # the eyes reading it. One show, one anchor, however long the
        # answer turns out to be.
        assert app.popup.last == ("שביר", True), app.popup.last
        assert len(app.popup.anchors) == 1, app.popup.anchors

        # No anchor is not a failure. The CLI probe and anything that
        # cannot say where it was pointing get the corner, which is where
        # this box appeared before any of it.
        app._lookup(fake.focus)
        assert app.popup.anchors[-1] is None, app.popup.anchors
    finally:
        restore()
        main_mod.injector = real_inj
        shutil.rmtree(tmp, ignore_errors=True)


def test_a_refusal_takes_down_the_answer_to_the_last_question() -> None:
    """A box that waits to be closed can be left telling a lie.

    Every "nothing to look up" path returns without putting anything in
    the box. That was harmless while a tap closed the box first, and
    stopped being harmless the moment a tap started asking a new question
    instead: select a URL, tap, and the answer to the PREVIOUS word would
    sit there while the cue said nothing had happened. The honest report
    is an empty screen — the key was pressed, there was nothing to look
    up, so there is nothing to see.
    """
    import shutil
    import tempfile

    import main as main_mod

    tmp = Path(tempfile.mkdtemp(prefix="dictation-lookup-refuse-"))
    fake = _FakeInjector()
    real_inj = main_mod.injector
    played, restore = _cue_spy(main_mod)
    try:
        app = _lookup_app(tmp, fake, "שביר")
        fake.selection = "brittle"
        app._lookup(fake.focus, (400, 300))
        assert app.popup.visible(), "the answer never went up"

        # Every refusal, one at a time, each starting from a box that is
        # up: a URL, nothing selected, and more than max_chars.
        for selection in ("https://example.com/a/b", "   ",
                          "word " * 4400):
            before = len(app._lookup_engine.asked)
            fake.selection = selection
            app._lookup(fake.focus, (400, 300))
            assert not app.popup.visible(), \
                f"{selection[:20]!r} left the last answer standing"
            assert len(app._lookup_engine.asked) == before, \
                f"{selection[:20]!r} was sent to the model"
            fake.selection = "brittle"
            app._lookup(fake.focus, (400, 300))
            assert app.popup.visible()
    finally:
        restore()
        main_mod.injector = real_inj
        shutil.rmtree(tmp, ignore_errors=True)


def test_pausing_takes_the_lookup_box_with_it() -> None:
    """Nothing dismisses this box on its own any more, so pausing has to.

    The pause key exists so the owner can start a game without Right Ctrl
    starting recordings, and the fullscreen watcher presses it for him. An
    always-on-top box left sitting over that game is exactly the intrusion
    pausing was asked to stop — and with no dwell to take it away, it
    would sit there for as long as the app ran.

    Driven through _on_pause rather than through the key, because that is
    the one funnel both ways in go through: the pause key reaches it via
    the state machine, and the dashboard's button reaches it via
    set_paused. Putting the take-down anywhere else would cover one of
    them and not the other.
    """
    import shutil
    import tempfile

    import main as main_mod

    tmp = Path(tempfile.mkdtemp(prefix="dictation-lookup-pause-"))
    fake = _FakeInjector()
    real_inj = main_mod.injector
    played, restore = _cue_spy(main_mod)
    try:
        app = _lookup_app(tmp, fake, "שביר")
        app._auto_paused = False
        app.dot = type("_Dot", (), {"set_state": lambda self, s: None})()
        app.hint = _FakeHint()
        fake.selection = "brittle"
        app._lookup(fake.focus, (400, 300))
        assert app.popup.visible(), "the answer never went up"

        app._on_pause(True)
        assert not app.popup.visible(), \
            "the box outlived the pause it was supposed to get out of"
        assert app.popup.hidden == 1, app.popup.hidden

        # Resuming does not bring it back: there is nothing to bring back,
        # and an answer reappearing minutes later would be a ghost.
        app._on_pause(False)
        assert not app.popup.visible(), app.popup.shown
        assert app.popup.hidden == 1, app.popup.hidden
    finally:
        restore()
        main_mod.injector = real_inj
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_answer_is_painted_by_the_line_and_never_by_the_token() -> None:
    """The box shows the answer arriving, without shaking while it does.

    lookup.py hands over every token the local model writes — one every
    24 ms, measured against real Ollama on 2026-08-19 — and each repaint
    re-lays-out and RESIZES the window. Painted per token, a two-second
    answer resizes the box forty times, which reads as jitter rather than
    as speed. Painted on a newline or after 80 ms, the same answer takes
    12-15 paints and each one is the box gaining a line.

    The last word belongs to the finished answer, not to the last partial:
    on_chunk is given the RAW stream, fences and stray quotes included,
    and the update after look_up returns is what replaces it with the
    cleaned, niqqud-stripped text.
    """
    import shutil
    import tempfile

    import main as main_mod

    tmp = Path(tempfile.mkdtemp(prefix="dictation-lookup-stream-"))
    fake = _FakeInjector()
    real_inj = main_mod.injector
    played, restore = _cue_spy(main_mod)
    try:
        app = _lookup_app(tmp, fake, "שביר")
        fake.selection = "brittle"

        class _Streaming:
            """40 tokens, 24 ms apart, four of them ending a line."""

            asked: list[str] = []

            def look_up(self, text, decision=None, on_status=None,
                        on_chunk=None, on_progress=None):
                import lookup as lookup_mod
                self.asked.append(text)
                so_far = ""
                for i in range(40):
                    so_far += "\n" if i and i % 10 == 0 else "x"
                    on_chunk(so_far)
                    time.sleep(0.024)
                return lookup_mod.Answer("שביר", decision.target,
                                         decision.mode, "fake", 1.0)

        app._lookup_engine = _Streaming()
        app._lookup(fake.focus, (400, 300))

        partials = app.popup.updates[:-1]
        assert 4 <= len(partials) <= 20, \
            f"40 tokens became {len(partials)} paints"
        assert len(partials) < 40, "the box was painted per token"
        # Every partial is a prefix of the next: the box shows the answer
        # growing, never a fragment of it out of order.
        assert partials == sorted(partials, key=len), partials
        for earlier, later in zip(partials, partials[1:]):
            assert later.startswith(earlier), (earlier, later)
        # The finished answer has the last word.
        assert app.popup.updates[-1] == "שביר", app.popup.updates[-1]
        assert app.popup.last == ("שביר", True), app.popup.last
    finally:
        restore()
        main_mod.injector = real_inj
        shutil.rmtree(tmp, ignore_errors=True)


def test_a_second_tap_asks_again_instead_of_closing_the_box() -> None:
    """A reversal, and the reason for it is the whole feature.

    A second tap used to CLOSE the open box and stop there. That was right
    while the box dismissed itself after a dwell — the key that opened it
    was the obvious key to shut it. It became wrong the moment the box
    started waiting to be closed on purpose, because it turned the
    commonest use of this key into a no-op: select a second word, tap, and
    all that happens is the first answer disappearing. The box has a
    button of its own now, and Esc; this key is for asking.

    The busy flag is the only thing that still refuses a press, and it
    means something narrower than "a box is on screen": one clipboard, one
    selection, one answer being written.
    """
    import shutil
    import tempfile

    import main as main_mod

    tmp = Path(tempfile.mkdtemp(prefix="dictation-lookup-toggle-"))
    fake = _FakeInjector()
    real_inj = main_mod.injector
    played, restore = _cue_spy(main_mod)
    try:
        main_mod.injector = fake
        app = _worker_app(_Flaky(fail_times=0), tmp)
        app.popup.show("שביר", rtl=True)
        app._on_tap("lookup")
        assert app.lookup_queue.qsize() == 1, app.lookup_queue.qsize()
        assert app._looking_up.is_set(), "a lookup was queued without the flag"
        assert app.popup.hidden == 0, \
            "the tap closed the box instead of asking a new question"
        assert played == [], played     # the cue belongs to the worker

        # ...and the busy flag, which is what a real second press hits
        # while the first answer is still being written, still refuses.
        app._on_tap("lookup")
        assert app.lookup_queue.qsize() == 1, app.lookup_queue.qsize()
        assert played == ["noop"], played
    finally:
        restore()
        main_mod.injector = real_inj
        shutil.rmtree(tmp, ignore_errors=True)


# ------------------------------------------- reading the log back out
#
# transcripts.log is the record. The history screen is a READER of it, and
# everything below is about the three places where "one line" and "one
# thing that happened" are not the same number.


def _log_with(lines: list[str], monkey=None):
    """A transcripts.log of our own, with history pointed at it."""
    import history as history_mod
    tmp = Path(tempfile.mkdtemp(prefix="dictation-history-"))
    path = tmp / "transcripts.log"
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    history_mod.LOG = path
    return tmp, path


def _restore_log(tmp) -> None:
    import shutil

    import history as history_mod
    history_mod.LOG = history_mod.APP_DIR / "transcripts.log"
    shutil.rmtree(tmp, ignore_errors=True)


def test_a_translation_is_one_entry_and_keeps_both_halves() -> None:
    """TRANSLATE-IN and TRANSLATE-OUT are one act — asking for a
    translation — written down twice because that is how a log works."""
    import history as history_mod
    tmp, _path = _log_with([
        "2026-08-20 10:00:00,000 | TRANSLATE-IN  | selection | שלום עולם",
        "2026-08-20 10:00:01,000 | TRANSLATE-OUT | 0.8s | gemini | Hello world",
    ])
    try:
        events = history_mod.load(10)
        assert len(events) == 1, events
        assert events[0].kind == "translate"
        assert events[0].text == "Hello world"
        assert events[0].source == "שלום עולם", events[0].source
        # The row is stamped when it was ASKED for, not when the answer
        # came back: sorted by the reply, a slow translation jumps ahead of
        # the dictation that came after it.
        assert events[0].when.second == 0, events[0].when
    finally:
        _restore_log(tmp)


def test_a_polished_dictation_is_one_entry_not_two() -> None:
    """OK is what Whisper heard and POLISHED is the same sentence with the
    misheard words repaired. Two rows means the sentence twice, one of
    them wrong."""
    import history as history_mod
    tmp, _path = _log_with([
        "2026-08-20 10:00:00,000 | OK | 4.0s | local | 0.5s latency | ראש הממשלה",
        "2026-08-20 10:00:02,000 | POLISHED | 1.2s | ollama | ראש הממשלה נאם",
    ])
    try:
        events = history_mod.load(10)
        assert len(events) == 1, events
        assert events[0].polished, "the row does not say it was polished"
        assert events[0].text == "ראש הממשלה נאם"
        assert events[0].source == "ראש הממשלה", "the raw text was thrown away"
        assert "polished" in events[0].meta()
    finally:
        _restore_log(tmp)


def test_a_correction_becomes_the_words_that_changed() -> None:
    """CORRECTED is two whole sentences that differ in one word. The pair
    is what the eye wants; the sentences are what the file has."""
    import history as history_mod
    tmp, _path = _log_with([
        "2026-08-20 10:00:00,000 | CORRECTED | אני רוצה היוזר || אני רוצה ה-user",
    ])
    try:
        events = history_mod.load(10)
        assert len(events) == 1
        assert events[0].pairs == [("היוזר", "ה-user")], events[0].pairs
        assert events[0].note == "1 word", events[0].note
    finally:
        _restore_log(tmp)


def test_a_rewritten_sentence_claims_no_word_pairs() -> None:
    """Different lengths mean the correction was not a word swap, and
    guessing pairs out of it would put a change on screen that nobody
    made."""
    import history as history_mod
    assert history_mod.changed_words("one two three", "one two") == []
    assert history_mod.changed_words("", "") == []


def test_a_transcript_containing_a_pipe_is_not_cut_in_half() -> None:
    """The fields are separated by pipes and the last field is a sentence
    somebody said out loud. Say "pipe" and Whisper writes one down."""
    import history as history_mod
    tmp, _path = _log_with([
        "2026-08-20 10:00:00,000 | OK | 4.0s | local | 0.5s latency | "
        "run a | b | c and see",
    ])
    try:
        events = history_mod.load(10)
        assert events[0].text == "run a | b | c and see", events[0].text
    finally:
        _restore_log(tmp)


def test_a_dictated_newline_does_not_become_its_own_entry() -> None:
    """A transcript is written raw, newlines and all. A reader that takes
    every line as a record shows half a sentence with the wrong time on
    it."""
    import history as history_mod
    tmp, _path = _log_with([
        "2026-08-20 10:00:00,000 | OK | 4.0s | local | 0.5s latency | first",
        "second line of the same thing",
    ])
    try:
        events = history_mod.load(10)
        assert len(events) == 1, events
        assert "second line" in events[0].text, events[0].text
    finally:
        _restore_log(tmp)


def test_the_newest_thing_that_happened_is_at_the_top() -> None:
    import history as history_mod
    tmp, _path = _log_with([
        "2026-08-20 10:00:00,000 | OK | 1.0s | local | 0.1s latency | older",
        "2026-08-20 11:00:00,000 | OK | 1.0s | local | 0.1s latency | newer",
    ])
    try:
        events = history_mod.load(10)
        assert [e.text for e in events] == ["newer", "older"], events
    finally:
        _restore_log(tmp)


def test_a_phone_dictation_says_where_it_came_from() -> None:
    """The phone route has no backend field, so reading it like a desktop
    dictation puts the latency where the engine goes."""
    import history as history_mod
    tmp, _path = _log_with([
        "2026-08-20 10:00:00,000 | OK | PHONE | 3.1s | 0.4s latency | from afar",
    ])
    try:
        event = history_mod.load(10)[0]
        assert event.phone and "from the phone" in event.meta()
        assert event.text == "from afar", event.text
        assert event.seconds == 3.1 and event.latency == 0.4
    finally:
        _restore_log(tmp)


def test_a_broken_line_is_skipped_rather_than_repaired() -> None:
    """Half a line is what a log looks like when the process died mid
    write. It must cost that entry and nothing else."""
    import history as history_mod
    tmp, _path = _log_with([
        "this is not a log line at all",
        "2026-08-20 99:99:99,000 | OK | 1.0s | local | 0.1s latency | bad stamp",
        "2026-08-20 10:00:00,000 | OK | 1.0s | local | 0.1s latency | good",
    ])
    try:
        events = history_mod.load(10)
        assert [e.text for e in events] == ["good"], events
    finally:
        _restore_log(tmp)


def test_the_filters_only_offer_kinds_the_reader_can_produce() -> None:
    """A chip for a kind nothing is ever tagged with is a filter that
    always comes back empty."""
    import history as history_mod
    for name, kind in history_mod.FILTERS:
        assert name, "a chip with no label"
        assert kind is None or kind in history_mod.KINDS, kind


def test_searching_looks_at_what_went_in_as_well_as_what_came_out() -> None:
    import history as history_mod
    tmp, _path = _log_with([
        "2026-08-20 10:00:00,000 | TRANSLATE-IN  | selection | ברוכים הבאים",
        "2026-08-20 10:00:01,000 | TRANSLATE-OUT | 0.8s | gemini | welcome",
    ])
    try:
        events = history_mod.load(10)
        assert history_mod.filtered(events, None, "welcome")
        assert history_mod.filtered(events, None, "ברוכים"), \
            "the text that was translated is not searchable"
        assert not history_mod.filtered(events, "dictation", "welcome")
    finally:
        _restore_log(tmp)


# ------------------------------------------------- the window's drawing kit


def _tk_or_skip():
    """A Tk root, or None with a note — the same shape as the icon test."""
    import tkinter as tk

    import ui as ui_mod
    try:
        ui_mod.forget_images()
        return tk.Tk()
    except Exception as e:
        print(f"    (skipped: no Tk window — {e})")
        return None


def test_wrapping_never_overflows_the_box_it_was_measured_for() -> None:
    """The whole point of measuring here rather than letting Tk wrap is
    that the height of a row and the text in it agree. A line wider than
    the box it was drawn for is the failure that reaches the screen."""
    import ui as ui_mod
    root = _tk_or_skip()
    if root is None:
        return
    try:
        samples = [
            "אני רוצה שתעשה משהו כזה תסתכל על האפליקציה שלי ותבצע כזה דבר "
            "כרגע היא נראית נורא ישנה",
            "a short one",
            "supercalifragilisticexpialidociousandthensome" * 3,
            "",
        ]
        for text in samples:
            for width in (120, 300, 546):
                shown, lines = ui_mod.clamp(text, ui_mod.TEXT, 11, width, 2)
                assert lines <= 2, (lines, text[:20])
                assert lines == len(shown.split("\n")) or not shown
                for line in shown.split("\n"):
                    got = ui_mod.text_width(line, ui_mod.TEXT, 11)
                    assert got <= width, (got, width, line)
    finally:
        root.destroy()


def test_a_wrapped_line_keeps_every_word_it_started_with() -> None:
    """Estimating where the break goes is only allowed to move the break."""
    import ui as ui_mod
    root = _tk_or_skip()
    if root is None:
        return
    try:
        text = "one two three four five six seven eight nine ten"
        shown, _lines = ui_mod.clamp(text, ui_mod.UI, 9, 400, 4)
        assert shown.replace("\n", " ") == text, shown
    finally:
        root.destroy()


def test_a_hundred_rows_of_the_same_size_share_one_bitmap() -> None:
    """Every rounded rectangle is a decoded image. A hundred history rows
    that each make their own is a hundred times the memory and the wait."""
    import ui as ui_mod
    root = _tk_or_skip()
    if root is None:
        return
    try:
        first = ui_mod.rounded(680, 66, 12, ui_mod.CARD, ui_mod.PANE)
        again = ui_mod.rounded(680, 66, 12, ui_mod.CARD, ui_mod.PANE)
        assert first is again, "the bitmap cache is not being hit"
        assert ui_mod.rounded(680, 67, 12, ui_mod.CARD, ui_mod.PANE) is not first
    finally:
        root.destroy()


def test_the_direction_of_a_line_comes_from_its_first_strong_letter() -> None:
    """Tk cannot be told which way a paragraph runs — the renderer decides
    from the first strong character. Aligning a box by a different rule
    than the one the text is laid out by is how a sentence ends up
    right-aligned and left-to-right at the same time."""
    import ui as ui_mod
    assert ui_mod.is_rtl("שלום עולם")
    assert ui_mod.is_rtl("  \"שלום\" said the man") is True
    assert not ui_mod.is_rtl("Chrome ואז עברית")
    assert not ui_mod.is_rtl("12.5 s")          # no strong letter at all
    assert not ui_mod.is_rtl("")


def _arrows(canvas) -> list[str]:
    """The arrow glyphs on a canvas. itemcget(_, "text") raises on the
    image items, which is most of a pill."""
    return [canvas.itemcget(i, "text") for i in canvas.find_all()
            if canvas.type(i) == "text"
            and canvas.itemcget(i, "text") in ("←", "→")]


def test_a_correction_pill_points_away_from_the_word_that_was_wrong() -> None:
    """Photographed as one "wrong -> right" string, two Hebrew words lay
    out right-to-left, U+2192 came back unmirrored, and the arrow pointed
    at the word it came from. The three runs are drawn separately so the
    direction is chosen here."""
    import tkinter as tk

    import ui as ui_mod
    root = _tk_or_skip()
    if root is None:
        return
    try:
        canvas = tk.Canvas(root, width=400, height=60)
        ui_mod.pair_pill(canvas, 380, 4, "היוזר", "ה-user", "#161b25")
        assert _arrows(canvas) == ["←"], _arrows(canvas)
        canvas.delete("all")
        ui_mod.pair_pill(canvas, 380, 4, "there", "their", "#161b25")
        assert _arrows(canvas) == ["→"], _arrows(canvas)
    finally:
        root.destroy()


# ------------------------------------------------------------- the page


def _scrolling(root, w: int = 300, h: int = 300, rows: int = 60):
    """A Scroller with more in it than fits, ready to be wheeled."""
    import tkinter as tk

    import ui as ui_mod
    scroller = ui_mod.Scroller(root, w, h, bg=ui_mod.BG)
    for i in range(rows):
        tk.Label(scroller.inner, text=f"row {i}", bg=ui_mod.BG,
                 fg=ui_mod.FG).pack(anchor="w")
    scroller.update_idletasks()
    scroller._paint_thumb()
    return scroller


def _a_page(root):
    """A root sized, placed and MAPPED — `winfo containing` answers with
    nothing at all for a window that has never been laid out, and the
    wheel is routed by what is under the pointer."""
    root.geometry("900x400+0+0")
    root.update()


def test_the_wheel_reaches_a_row_that_arrived_after_the_page_was_built(
) -> None:
    """The dead zone the owner found on 2026-09-07, in one assertion.

    "If we scroll down a bit, where it says 'the rest of the day one line
    each', I can't scroll on that. That area isn't scrollable." Those
    three rows are destroyed and rebuilt by `dashboard._paint_rest` every
    time the log changes, and `bind_wheel` had walked the tree ONCE, at
    build time — so the new rows carried no binding and the wheel landed
    on nothing. Every list in this window is rebuilt like that.
    """
    import tkinter as tk

    import ui as ui_mod
    root = _tk_or_skip()
    if root is None:
        return
    try:
        page = _scrolling(root)
        page.place(x=10, y=10)
        _a_page(root)
        # Built now, and deliberately never handed to bind_wheel.
        late = tk.Label(page.inner, text="a row that arrived later",
                        bg=ui_mod.BG, fg=ui_mod.FG)
        late.pack(anchor="w")
        root.update()
        assert not late.bind("<MouseWheel>"), \
            "the test binds nothing: the point is that nobody did"
        was = page.canvas.canvasy(0)
        late.event_generate("<MouseWheel>", delta=-120, x=5, y=5)
        root.update()
        step = ui_mod.SCROLL_STEP * ui_mod.SCROLL_UNITS
        assert page.canvas.canvasy(0) == was + step, (
            f"a notch over a row nobody bound moved the page "
            f"{page.canvas.canvasy(0) - was} px, not {step}")
        # ...and exactly one notch. A widget binding that fails to say
        # "break" hands the same event to the interpreter-wide one after
        # it, and the page moves twice per click.
        was = page.canvas.canvasy(0)
        page.inner.event_generate("<MouseWheel>", delta=-120, x=5, y=5)
        root.update()
        assert page.canvas.canvasy(0) == was + step, (
            "a bound widget scrolled twice: the widget binding and the "
            "wheel-to-the-pointer binding both ran")
    finally:
        root.destroy()


def test_two_scrollers_on_one_screen_scroll_the_one_under_the_pointer(
) -> None:
    """`bind_all` is per INTERPRETER, and this window has four Scrollers.

    So the one binding there is may not belong to any of them: it is
    routed by asking the screen which widget the pointer is over. The
    event is generated on the ROOT here on purpose — a Scroller found by
    walking up from `event.widget` would pass this test by accident.
    """
    import ui as ui_mod
    root = _tk_or_skip()
    if root is None:
        return
    try:
        left = _scrolling(root)
        left.place(x=10, y=10)
        right = _scrolling(root)
        right.place(x=450, y=10)
        _a_page(root)
        step = ui_mod.SCROLL_STEP * ui_mod.SCROLL_UNITS
        for name, x, moves, still in (("left", 60, left, right),
                                      ("right", 500, right, left)):
            was, other = moves.canvas.canvasy(0), still.canvas.canvasy(0)
            root.event_generate("<MouseWheel>", delta=-120, x=x, y=60)
            root.update()
            assert moves.canvas.canvasy(0) == was + step, (
                f"the wheel over the {name} page moved it "
                f"{moves.canvas.canvasy(0) - was} px")
            assert still.canvas.canvasy(0) == other, \
                f"the wheel over the {name} page moved the other one"
    finally:
        root.destroy()


def test_the_thumb_can_be_held_and_dragged_and_the_view_follows() -> None:
    """"The scroll button on the right side ... if I hold it, it doesn't
    help. Like, you can't use it."

    It was a picture: `_paint_thumb` drew it and nothing took a mouse
    press. A drag of D pixels has to move the content by D x (everything
    that is not on screen) / (the thumb's own travel) — the standard
    mapping, and the only one where letting go leaves the thumb under the
    finger. It lands on a multiple of SCROLL_STEP because the canvas
    carries a yscrollincrement, which is the tolerance below.

    THE THUMB'S TRAVEL IS `_rail_room()`, AND SINCE 2026-09-08 THAT IS
    THE WHOLE VIEWPORT AGAIN. The rail gave up its bottom TOP_FOOT px for
    one night, while the way home was parked at its foot; the way home is
    at the top middle of the page now and nothing else is on the rail, so
    a thumb that stopped short of the end would be stopping for a button
    that is not there. Asked of the page rather than worked out here,
    because a test that recomputes the rule is a test that agrees with
    itself.
    """
    import ui as ui_mod
    root = _tk_or_skip()
    if root is None:
        return
    try:
        page = _scrolling(root)
        page.place(x=10, y=10)
        _a_page(root)
        page.to_top()
        root.update()
        top, length = page._thumb
        assert top == 0 and length >= 36, page._thumb
        total, view = page.inner.winfo_height(), page._height
        assert total > view, (total, view)
        room = page._rail_room()
        assert room == view, (
            f"the rail keeps {view - room} px of its foot back from the "
            f"thumb, and there is nothing down there to keep it for")
        span = room - length
        drag = 50
        page.rail.event_generate("<Button-1>", x=3, y=top + 5)
        assert page._grab is not None, "the press did not take the thumb"
        page.rail.event_generate("<B1-Motion>", x=3, y=top + 5 + drag)
        page.rail.event_generate("<ButtonRelease-1>", x=3, y=top + 5 + drag)
        root.update()
        want = drag * (total - view) / span
        got = page.canvas.canvasy(0)
        assert abs(got - want) <= ui_mod.SCROLL_STEP, (
            f"a {drag} px drag moved the view {got} px, not {want:.1f} "
            f"(thumb {length} px, travel {span} px, {total - view} px "
            f"off screen)")
        assert page._grab is None, "the thumb was never let go of"
        assert abs(page._thumb[0] - drag) <= 4, (
            f"the thumb ended at {page._thumb[0]} after a {drag} px drag")

        # A press below the thumb pages down, a press above it pages back.
        page.to_top()
        root.update()
        page.rail.event_generate("<Button-1>", x=3, y=view - 5)
        root.update()
        page_px = (int(view * 0.9) // ui_mod.SCROLL_STEP) * ui_mod.SCROLL_STEP
        assert page.canvas.canvasy(0) == page_px, (
            f"a click on the empty rail moved {page.canvas.canvasy(0)} px, "
            f"not one page of {page_px}")
        page.rail.event_generate("<Button-1>", x=3, y=1)
        root.update()
        assert page.canvas.canvasy(0) == 0, "the rail pages one way only"
    finally:
        root.destroy()


def test_the_thumb_lights_under_the_pointer_without_moving_a_pixel(
) -> None:
    """The rail is RAIL_HIT px wide so it can be grabbed and the thumb is
    still painted THUMB_W px wide at x=1 on it, which is where it has
    always been: the extra width is hit area to the RIGHT of the paint,
    past the thumb, so nothing on screen moved. And the thumb is drawn
    INSIDE its rail — `first * height` has no floor and `length` does, so
    a very long page used to put its last pixels past the bottom."""
    import ui as ui_mod
    root = _tk_or_skip()
    if root is None:
        return
    try:
        page = _scrolling(root, rows=400)
        page.place(x=10, y=10)
        _a_page(root)
        assert page.rail.winfo_width() == ui_mod.RAIL_HIT
        item = page.rail.find_withtag("thumb")[0]
        assert page.rail.coords(item)[0] == 1, "the paint moved"
        image = page.rail.itemcget(item, "image")
        # Tcl answers with a STRING; "4" == 4 is a failure with no
        # message in it, which is a bad half-hour.
        assert int(root.call(image, "cget", "-width")) == ui_mod.THUMB_W

        page.rail.event_generate("<Motion>", x=3, y=page._thumb[0] + 5)
        root.update()
        assert page._hot, "the thumb does not know the pointer is on it"
        page.rail.event_generate("<Motion>", x=3, y=page._height - 2)
        root.update()
        assert not page._hot

        page.canvas.yview_moveto(1.0)
        page._paint_thumb()
        root.update()
        top, length = page._thumb
        assert top + length <= page._rail_room(), (
            f"the thumb ends {top + length - page._rail_room()} px past "
            f"the bottom of its own rail")
        # ...and at the end of a page it reaches the END of the rail,
        # which it did not while the way home was parked down there.
        assert top + length >= page._height - 1, (
            f"at the end of the page the thumb stops at y{top + length} "
            f"and the rail ends at y{page._height}")
    finally:
        root.destroy()


def test_the_way_back_to_the_top_waits_until_he_scrolls_back_up() -> None:
    """His rule, 2026-09-08, and it replaces "once the page has left the
    top".

    "And maybe let the arrow appear only if I scroll up. Okay, so I
    scroll down and I stayed on something, then only when I'm starting to
    scroll up there will appear — and it will stay there. Okay, so if I
    stop scrolling it, it will also be there."

    So four things, in the order he said them: scrolling DOWN never shows
    it however far it goes; the first notch back UP does; it is still
    there after the page has been left alone; and it goes away when the
    view arrives at the top, because there is then nowhere to jump to.
    Pressing it is one of the ways of arriving.

    Scrolling back down is deliberately NOT one of the ways it goes away
    — "and it will stay there" — and that is asserted here so that
    changing it later is a decision somebody makes on purpose.
    """
    import tkinter as tk

    import ui as ui_mod
    root = _tk_or_skip()
    if root is None:
        return
    try:
        page = _scrolling(root)
        page.place(x=10, y=10)
        _a_page(root)
        assert not page.top_showing(), "it is there before anything moved"
        for _ in range(4):
            page.inner.event_generate("<MouseWheel>", delta=-120, x=5, y=5)
        root.update()
        assert page.canvas.canvasy(0) > 0, "nothing moved: nothing to test"
        assert not page.top_showing(), \
            "scrolling DOWN put the arrow on screen, which is the one " \
            "thing he asked it not to do"

        page.inner.event_generate("<MouseWheel>", delta=120, x=5, y=5)
        root.update()
        assert page.top_showing(), "he scrolled back up and there is no arrow"
        was = page.canvas.canvasy(0)
        assert was > 0, "one notch up went the whole way home by itself"

        # "If I stop scrolling it, it will also be there." Nothing here is
        # on a timer, so the test for that is that nothing takes it away.
        for _ in range(20):
            root.update()
        assert page.top_showing(), "it went away while he sat still"

        # ...and going back down leaves it alone as well.
        page.inner.event_generate("<MouseWheel>", delta=-120, x=5, y=5)
        root.update()
        assert page.canvas.canvasy(0) > was, "the page did not go back down"
        assert page.top_showing(), \
            "it vanished when he scrolled down again, and he said it " \
            "would stay"

        page.top_button.event_generate("<Button-1>", x=5, y=5)
        root.update()
        assert page.canvas.canvasy(0) == 0, "it did not go home"
        assert not page.top_showing(), "it is still there at the top"

        # ...and the latch is properly off: a scroll DOWN from the top
        # does not bring it straight back.
        page.inner.event_generate("<MouseWheel>", delta=-120, x=5, y=5)
        root.update()
        assert not page.top_showing(), \
            "pressing it left the arrow armed, so the next notch down " \
            "showed it again"

        short = _scrolling(root, rows=2)
        short.place(x=450, y=10)
        root.update()
        short.inner.event_generate("<MouseWheel>", delta=120, x=5, y=5)
        root.update()
        assert not short.top_showing(), \
            "a page that fits on screen offers a way back to itself"
    finally:
        root.destroy()


def test_the_way_home_hears_an_upward_move_however_it_was_made() -> None:
    """The wheel is not the only way up.

    The thumb can be dragged and the empty rail pages, and "only when I'm
    starting to scroll up" is about the VIEW moving up, not about which
    control did it. All three routes end in `_paint_thumb`, which is
    where the latch lives, so this walks each one on a page of its own
    and asks the same question three times.

    It also pins the one thing that must NOT read as an upward move: the
    page growing under a still view. A press of Show more on the Said
    adds twenty-five rows, and the fraction the thumb is drawn from drops
    without the view having moved a pixel — which is why the latch is
    measured in `canvasy` and not in that fraction.
    """
    import tkinter as tk

    import ui as ui_mod
    root = _tk_or_skip()
    if root is None:
        return
    try:
        # 1. the thumb, dragged.
        page = _scrolling(root)
        page.place(x=10, y=10)
        _a_page(root)
        page.canvas.yview_moveto(0.6)
        page._paint_thumb()
        root.update()
        assert not page.top_showing(), (
            "a jump straight to the middle is not a scroll up")
        top, _length = page._thumb
        page.rail.event_generate("<Button-1>", x=3, y=top + 5)
        page.rail.event_generate("<B1-Motion>", x=3, y=top - 40)
        page.rail.event_generate("<ButtonRelease-1>", x=3, y=top - 40)
        root.update()
        assert page.top_showing(), \
            "the thumb was dragged up and the arrow did not come"
        page.destroy()

        # 2. the rail, paged.
        page = _scrolling(root)
        page.place(x=10, y=10)
        root.update()
        page.canvas.yview_moveto(0.6)
        page._paint_thumb()
        root.update()
        assert not page.top_showing()
        page.rail.event_generate("<Button-1>", x=3, y=1)
        root.update()
        assert page.top_showing(), \
            "a press on the rail above the thumb paged up and the arrow " \
            "did not come"
        page.destroy()

        # 3. a page that GROWS under a view that did not move.
        page = _scrolling(root)
        page.place(x=10, y=10)
        root.update()
        page.canvas.yview_moveto(0.6)
        page._paint_thumb()
        root.update()
        where, (first, _last) = page.canvas.canvasy(0), page.canvas.yview()
        for i in range(40):
            tk.Label(page.inner, text=f"later row {i}", bg=ui_mod.BG,
                     fg=ui_mod.FG).pack(anchor="w")
        root.update()
        page.update_idletasks()
        page._paint_thumb()
        root.update()
        assert page.canvas.canvasy(0) == where, \
            "the view moved when the rows arrived; this is measuring the " \
            "wrong thing"
        assert page.canvas.yview()[0] < first, \
            "the page did not get longer, so the fraction did not drop"
        assert not page.top_showing(), \
            "twenty-five more rows read as a scroll up and the arrow " \
            "appeared out of nowhere"
    finally:
        root.destroy()


def test_the_way_home_is_big_enough_to_press_and_leaves_no_square() -> None:
    """The size, and the halo — the two things he said about the button.

    "The arrow is very small so I don't know if I like it." (2026-09-08.)
    It was TOP_DISC = GUTTER * 2 = 20 px, and 20 was not a judgement about
    buttons: it was the width of the one column of a page with nothing
    drawn in it, which is where the button was parked. It is in the middle
    of the page now, so the rail has stopped being what decides its size
    and the window's own controls decide instead — which is what the two
    bounds below are.

    And the halo. A Tk widget is an opaque rectangle: whatever the shape
    leaves over gets painted with the tile's background, and a circle
    leaves a fifth of its tile over. Counted off the real bitmap on
    2026-09-07, at the 28 px the button was then: 84 of 784 pixels were
    still PURE ground colour, and over a card face those 84 are seven L*
    darker than what is behind them — "you can see it's a bit cut,
    because you made it like a circle but also square". This counts the
    same pixels on the shape that replaced it. No Tk: `_arrow_tile_pil`
    is split out of `_arrow_tile` exactly so this can be asked without a
    window, the way `rounded_pil` is split out of `rounded`.
    """
    import ui as ui_mod

    # Against the rest of the window, and not against the rail. The
    # floor is the 32 px square Windows' own guidance calls a comfortable
    # pointer target — and the 20 px one he called very small was well
    # under it. The ceiling is a chip, because past that a button that
    # floats over his rows stops being small and starts being in the way.
    assert ui_mod.TOP_TILE >= 32, (
        f"the way home is {ui_mod.TOP_TILE} px, under the 32 px square "
        f"that is the smallest comfortable pointer target — and he has "
        f"already said the 20 px one was too small to like")
    assert ui_mod.TOP_TILE <= ui_mod.PILL_H, (
        f"the way home is {ui_mod.TOP_TILE} px, bigger than the "
        f"{ui_mod.PILL_H} px chips it sits under and the 30 px buttons "
        f"beside them: it has stopped being a small control")

    ground = tuple(int(ui_mod.CARD[i:i + 2], 16) for i in (1, 3, 5))
    tile = ui_mod._arrow_tile_pil(ui_mod.TOP_TILE, ui_mod.TOP_ROUND,
                                  ui_mod.CARD_HI, ui_mod.CARD,
                                  ui_mod.STROKE, ui_mod.DIM)
    assert tile.size == (ui_mod.TOP_TILE, ui_mod.TOP_TILE), tile.size
    pixels = tile.load()
    left = sum(1 for y in range(ui_mod.TOP_TILE)
               for x in range(ui_mod.TOP_TILE)
               if pixels[x, y] == ground)
    whole = ui_mod.TOP_TILE ** 2
    # The circle it replaced, at the same size, for the comparison the
    # number only means anything against: a radius of half the side IS a
    # circle, so this is the old shape drawn by the new function.
    circle = ui_mod._arrow_tile_pil(ui_mod.TOP_TILE, ui_mod.TOP_TILE // 2,
                                    ui_mod.CARD_HI, ui_mod.CARD,
                                    ui_mod.STROKE, ui_mod.DIM)
    round_px = circle.load()
    was = sum(1 for y in range(ui_mod.TOP_TILE)
              for x in range(ui_mod.TOP_TILE)
              if round_px[x, y] == ground)
    assert was > 100, (
        f"a circle in a {ui_mod.TOP_TILE} px tile left only {was} pixels "
        f"of its own background over, which means this measurement stopped "
        f"measuring what it thinks it does")
    assert left * 2 <= was, (
        f"the shape leaves {left} of {whole} pixels showing its own "
        f"background, against a circle's {was} — it was supposed to leave "
        f"less than half as much, and that leftover is the square he "
        f"photographed")
    assert left <= whole // 16, (
        f"{left} of {whole} pixels of the tile are its own background, "
        f"which is over a sixteenth of it and starts being visible")


def test_the_way_home_sits_at_the_top_middle_of_the_column_of_rows(
) -> None:
    """Where the button is, on a page with nothing else going on.

    "I think put it in on the middle is good. Or maybe, I don't know, or
    on the up side, like on the up middle — up." (2026-09-08, with a
    photograph of the Said page carrying two drawn arrows, one at the top
    middle of the list and one at the bottom.) The top was chosen: the
    button moves the page UP, the bottom middle is where the Show more
    line and the button under the page already live, and — measured — the
    top middle floats over a painted card face far more of the time,
    which is what decides whether the tile's own corners lie about their
    colour.

    MIDDLE OF THE CONTENT, NOT OF THE FRAME. The canvas holds everything
    packed into it to `_width - GUTTER` and the rail is another RAIL_HIT
    px to the right of that, so centring on the frame would sit the
    button to the right of the column of rows it belongs to.
    """
    import ui as ui_mod

    import dashboard as dash
    root = _tk_or_skip()
    if root is None:
        return
    try:
        page = _scrolling(root, w=dash.CW + 10, h=400)
        page.place(x=10, y=10)
        root.geometry(f"{dash.W}x500+0+0")     # room for a real page
        root.update()
        page.canvas.yview_moveto(0.5)
        page._paint_thumb()
        root.update()
        assert not page.top_showing(), "a jump down is not a scroll up"
        page.canvas.yview_scroll(-1, "units")
        page._paint_thumb()
        root.update()
        assert page.top_showing(), "nothing to measure: no way home"

        x, y = page.top_button.winfo_x(), page.top_button.winfo_y()
        w, h = (page.top_button.winfo_width(),
                page.top_button.winfo_height())
        assert (w, h) == (ui_mod.TOP_TILE, ui_mod.TOP_TILE), (w, h)
        middle = (page.canvas.winfo_width() - ui_mod.GUTTER) / 2
        assert abs((x + w / 2) - middle) <= 1, (
            f"the button is centred on x{x + w / 2} and the column of "
            f"rows on x{middle}")
        assert y == ui_mod.TOP_INSET, (
            f"it hangs {y} px below the top of the page, not "
            f"{ui_mod.TOP_INSET}")
        assert y + h < page.winfo_height(), \
            "it hangs off the bottom of the page it belongs to"
        # The thumb is on the rail, past the right edge of the canvas,
        # and at the top of a long page it is level with the button — so
        # the rail is the one thing the button could have collided with.
        assert page._thumb[1], "no thumb: this proves nothing"
        assert x + w < page.canvas.winfo_width(), (
            f"the button reaches x{x + w} and the rail begins at "
            f"x{page.canvas.winfo_width()}")
    finally:
        root.destroy()


def test_the_way_home_lands_the_same_way_on_all_of_the_six_places(
) -> None:
    """The other half of it, on the real window rather than a stand-in.

    One screen is not the test: the button is the Scroller's and every
    place has one, so this walks all six, forces each page to have been
    scrolled back up, and asks the same questions of each — is it the
    right size, is it centred on that page's own column of rows, is it
    inside the viewport, is it clear of the thumb, and is it clear of
    everything the SHEET has put beside the page (the vocabulary panel
    that stands next to Said, Corrections and Keys, the row of filter
    chips over the Said list, the footer under it).

    Said is then taken to its very end on purpose, because the bottom of
    that list is where his first complaint came from — "the arrow covers
    the 'Show more', so please move it" — and it is the spot the button
    would have gone back to if the bottom middle had been chosen.

    Corrections and Problems are given proposals and reports of their
    own, because on this machine both are empty and an empty page has
    nothing to scroll. Home and Keys are given a long filler instead:
    neither of them scrolls with a real day's load — the Home is a
    summary that is built to fit exactly and the Keys place is a board
    with a short list under it — so on those two the button never appears
    at all, and the filler is the only way to ask where it WOULD land.
    """
    import datetime as dt
    import tkinter as tk

    import ui as ui_mod

    import dashboard as dash
    import history as history_mod
    import problems as problems_mod

    now = dt.datetime.now()
    log = [history_mod.Event(kind="dictation",
                             when=now - dt.timedelta(minutes=i),
                             text=f"שורה מספר {i} של מה שנאמר כאן היום")
           for i in range(100)]
    proposals = [{"id": f"r{i}", "when": f"2026-09-07 20:{i:02d}:00",
                  "status": "pending", "proposed": "הטקסט הזה נכון עכשיו.",
                  "text": "הטקסט הזה נכן עכשיו.",
                  "changes": [{"before": "נכן", "after": "נכון",
                               "why": "הגייה דומה"}]} for i in range(12)]
    reports = [{"id": f"p{i}", "at": "2026-09-04T13:22:01",
                "where": "recordings", "kind": "wrong",
                "text": "הכרטיס מראה את המספר של אתמול — yesterday's count",
                "status": problems_mod.OPEN, "resolved": None, "by": "",
                "dictation": {}, "shot": "", "env": {}} for i in range(12)]

    class Store:
        def __init__(self, items):
            self._items = items
            self.path = REPO / "nothing-of-his.json"

        def pending(self):
            return list(self._items)

        def items(self, status=None):
            return [i for i in self._items
                    if status is None or i.get("status") == status]

        def summary(self):
            return {"open": len(self._items), "fixed": 0, "closed": 0}

        def stamp(self):
            return (1, 1)

    with _window(log=log) as board:
        if board is None:
            return
        root = board.root
        # His problems.md is not this test's to rewrite, and neither
        # store is read off the disk.
        board._write_digest = lambda: None
        board._review_store = lambda: Store(proposals)
        board._problems_store = lambda: Store(reports)

        def pages(widget, found=None):
            found = [] if found is None else found
            if isinstance(widget, ui_mod.Scroller):
                found.append(widget)
            for child in widget.winfo_children():
                pages(child, found)
            return found

        def leaves(widget, out, x=0, y=0):
            for child in widget.winfo_children():
                if not child.winfo_ismapped():
                    continue
                cx, cy = x + child.winfo_x(), y + child.winfo_y()
                out.append((child, cx, cy, child.winfo_width(),
                            child.winfo_height()))
                leaves(child, out, cx, cy)
            return out

        def under(child, page):
            """Is `child` inside `page`? Walked, and not asked of the
            widget PATH: `.!frame2` is a prefix of `.!frame22`, which
            would quietly excuse a sibling from being measured."""
            node = child
            while node is not None:
                if node is page:
                    return True
                node = node.master
            return False

        def scrolled_back_up(page):
            """Take the page to its end and then one notch back up —
            which is the only thing that puts the button on screen."""
            page.canvas.yview_moveto(1.0)
            page._paint_thumb()
            root.update()
            first, last = page.canvas.yview()
            if last - first >= 0.999:
                tk.Frame(page.inner, bg=ui_mod.BG, width=10,
                         height=900).pack()
                root.update()
                page.canvas.yview_moveto(1.0)
                page._paint_thumb()
                root.update()
            page.canvas.yview_scroll(-1, "units")
            page._paint_thumb()
            root.update()

        seen = []
        for name in dash.SCREENS:
            board._show(name)
            # Both of these draw off a poll rather than off the build.
            board._problems_stamp = board._corr_stamp = None
            board._poll_problems()
            board._poll_corrections()
            for _ in range(60):
                root.update()
            for page in pages(board.sheet):
                scrolled_back_up(page)
                assert page.top_showing(), (
                    f"on {name} the page was taken to its end and scrolled "
                    f"back up and no way home appeared")
                seen.append(name)
                bx, by = page.top_button.winfo_x(), page.top_button.winfo_y()
                bw, bh = (page.top_button.winfo_width(),
                          page.top_button.winfo_height())
                assert (bw, bh) == (ui_mod.TOP_TILE, ui_mod.TOP_TILE), (
                    f"on {name} the way home is {bw}x{bh}")
                middle = (page.canvas.winfo_width() - ui_mod.GUTTER) / 2
                assert abs((bx + bw / 2) - middle) <= 1, (
                    f"on {name} the button is centred on x{bx + bw / 2} "
                    f"and that page's rows on x{middle}")
                assert by == ui_mod.TOP_INSET, (
                    f"on {name} it hangs {by} px below the top of the page")
                assert by + bh < page.winfo_height(), (
                    f"on {name} it reaches y{by + bh} of a "
                    f"{page.winfo_height()} px page")
                assert bx + bw < page.canvas.winfo_width(), (
                    f"on {name} it reaches x{bx + bw} and the rail begins "
                    f"at x{page.canvas.winfo_width()}")
                # Nothing the SHEET put beside the page may be under it.
                sx = page.winfo_x() + bx
                sy = page.winfo_y() + by
                for child, cx, cy, cw, ch in leaves(board.sheet, []):
                    if under(child, page):
                        continue          # the page's own insides
                    if not (cx < sx + bw and cx + cw > sx
                            and cy < sy + bh and cy + ch > sy):
                        continue
                    label = (child.cget("text")[:40]
                             if "text" in child.keys() else
                             child.__class__.__name__)
                    raise AssertionError(
                        f"on {name} the way home (sheet x{sx}..{sx + bw} "
                        f"y{sy}..{sy + bh}) sits on {label!r} at "
                        f"x{cx}..{cx + cw} y{cy}..{cy + ch}")
        for must in ("Home", "Corrections", "Problems", "Said", "Keys",
                     "Settings"):
            assert must in seen, (
                f"the {must} page had no way home to measure — only "
                f"{seen} did, so this test proved almost nothing")

        # Said, at its end, where he photographed the collision.
        board._show("Said")
        for _ in range(80):
            root.update()
        page, more = board.parts["page"], board.parts["more"]
        assert more.winfo_manager(), \
            "a hundred rows and no Show more: the list stopped paging"
        scrolled_back_up(page)
        top = page.canvas.canvasy(0)
        mx, my = more.winfo_x(), more.winfo_y() - top
        mw, mh = more.winfo_width(), more.winfo_height()
        bx, by = page.top_button.winfo_x(), page.top_button.winfo_y()
        bw, bh = page.top_button.winfo_width(), page.top_button.winfo_height()
        assert page.top_showing(), "no way home at the bottom of the Said"
        assert my + mh > 0 and my < page.winfo_height(), (
            f"Show more is at y{my}..{my + mh} and the page is "
            f"{page.winfo_height()} px: it is not on screen to be covered")
        assert not (mx < bx + bw and mx + mw > bx
                    and my < by + bh and my + mh > by), (
            f"the way home (x{bx}..{bx + bw} y{by}..{by + bh}) is on top "
            f"of Show more (x{mx}..{mx + mw} y{my}..{my + mh}) again")
        # ...and not merely missing it: it is a page above it, which is
        # the whole reason the top middle was taken over the bottom one.
        assert my - (by + bh) > 200, (
            f"Show more is only {my - (by + bh)} px below the way home; "
            f"the top of the page was chosen to be nowhere near it")


# ------------------------------------------------------- the window itself


def _texts(widget) -> list[str]:
    """Every word drawn anywhere under `widget`.

    A door on the home is a card with labels inside it now rather than a
    label on the page, so a test that wants to know what a tile SAYS has
    to look under it. A widget with no -text option (a Canvas, a rule)
    contributes nothing rather than raising.
    """
    found = []
    for child in widget.winfo_children():
        try:
            text = child.cget("text")
        except Exception:                 # noqa: BLE001 — no such option
            text = ""
        if text:
            found.append(str(text))
        found += _texts(child)
    return found


@contextlib.contextmanager
def _window(log=None):
    """A dashboard with nothing behind it.

    Three things are borrowed and given back: the pipe (an answer of None
    is what "nothing is running" looks like, and it is instant), the
    instance check, and the log reader — because the poller re-reads
    transcripts.log on its own, and a test that sets three rows and then
    counts a hundred is a test measuring this machine's real history.
    """
    import control as control_mod
    import history as history_mod
    import singleton as singleton_mod

    import dashboard as dash
    saved = (control_mod.send, singleton_mod.is_running, history_mod.load)
    control_mod.send = lambda *a, **k: None
    singleton_mod.is_running = lambda *a, **k: False
    history_mod.load = lambda *a, **k: list(log or [])
    board = None
    try:
        try:
            board = dash.Dashboard()
        except Exception as e:
            print(f"    (skipped: no Tk window — {e})")
            yield None
            return
        board.log = list(log or [])
        yield board
    finally:
        if board is not None:
            board.closing = True
            try:
                board.root.destroy()
            except Exception:
                pass
        control_mod.send, singleton_mod.is_running, history_mod.load = saved


def test_the_desks_x_quits_the_app_only_for_the_desk_a_person_opened() -> None:
    """The owner's word (2026-09-19): the X of the desk ends everything
    the app runs in the background — Quit DeskIT, the named event. Only
    for the desk a person opened (the entry point's run sets _looping):
    a window a test or a picture built must never signal the live app,
    and Restart's close must not either — its new copy is on its way."""
    import singleton as singleton_mod
    asked: list[int] = []
    saved = singleton_mod.request_quit
    singleton_mod.request_quit = lambda: asked.append(1) or True
    try:
        for looping, relaunch, expect in ((False, False, 0), (True, True, 0), (True, False, 1)):
            asked.clear()
            with _window() as board:
                if board is None:
                    return
                board._looping = looping
                board._relaunch = relaunch
                board._close()
                if looping:
                    board._looping = False       # no run() here to bury it
                    board._bury()
            assert len(asked) == expect, (looping, relaunch, asked)
    finally:
        singleton_mod.request_quit = saved


def test_every_screen_of_the_window_builds() -> None:
    """Four screens, built by four methods, and only the one you are
    looking at exists at any moment — so a mistake on the Settings screen
    is invisible until somebody clicks Settings."""
    import dashboard as dash
    with _window() as board:
        if board is None:
            return
        for name in dash.SCREENS:
            board._show(name)
            assert board.screen == name
            assert board.pane.winfo_children(), f"{name} drew nothing"


def test_the_sheet_is_off_the_window_while_a_screen_is_built() -> None:
    """The desk builds a new screen with the sheet UNMAPPED and puts it
    back with the slide (2026-09-19): built in the open, each
    update_idletasks() a builder needs also painted the half-built page
    — seven visible frames on a switch to Home, his "everything jumps on
    top of each other". Measured on the hidden desktop that night: the
    pixels of every screen identical, Home's frozen time 0.34 -> 0.22 s.
    A builder that dies puts the sheet back rather than leave a blank
    window; the slide ends with the sheet at y 0."""
    import dashboard as dash
    with _window() as board:
        if board is None:
            return
        seen: list = []
        real = board._screen_keys

        def spy() -> None:
            seen.append((dict(board.sheet.place_info()), board.sheet.winfo_ismapped()))
            real()
        board._screen_keys = spy
        board._show("Keys")
        # placed or not is the fact; mapped-ness is the runner's (CI's
        # desktop never maps the window, 35467636557)
        assert [placed for placed, _mapped in seen] == [{}], seen
        assert board.sheet.place_info(), "the slide did not put the sheet back"
        deadline = time.monotonic() + 3                # six 18 ms frames; CI's clock, not a count
        while board._slide_after is not None and time.monotonic() < deadline:
            board.root.update()
            time.sleep(0.02)
        assert board._slide_after is None, "the slide never finished"
        assert int(board.sheet.place_info()["y"]) == 0, board.sheet.place_info()

        def dies() -> None:
            raise RuntimeError("the builder is having a day")
        board._screen_network = dies
        try:
            board._show("Network")
        except RuntimeError:
            pass
        else:
            raise AssertionError("the builder's error was swallowed")
        assert board.sheet.place_info() and int(board.sheet.place_info()["y"]) == 0


def test_no_button_draws_its_label_past_its_own_face() -> None:
    """A `ui.Button` is a Canvas and a Canvas item is NOT clipped: a
    width too small for the label does not cut the text, it draws it over
    the button's own rounded edge and out onto the card behind it, with
    nothing in Tk to complain.

    Every one of these widths used to be a literal, picked when the
    window drew in Segoe. Rubik at the new sizes is wider, and fifteen
    buttons across the four places had their labels touching or past
    their own border (measured 2026-09-07 — "Send a test notification"
    was the worst, running 196 px of label through a 196 px face). They
    are measured from the label now, through `widgets.button_width`.
    """
    import settings as settings_mod
    import ui as ui_mod

    import dashboard as dash

    def every(node, out):
        for child in node.winfo_children():
            if isinstance(child, ui_mod.Button):
                out.append(child)
            every(child, out)
        return out

    def look(board, where, bad):
        board.root.update_idletasks()
        for button in every(board.root, []):
            width = int(button.cget("width"))
            box = button.bbox(button._label)
            if box is None:
                continue
            left, right = box[0], box[2]
            if button._icon_item is not None:
                icon = button.bbox(button._icon_item)
                if icon:
                    left, right = min(left, icon[0]), max(right, icon[2])
            if left < 4 or right > width - 4:
                bad.append((where, button.itemcget(button._label, "text"),
                            width, left, right))

    with _window() as board:
        if board is None:
            return
        board.closing = True
        bad: list = []
        for name in dash.SCREENS:
            board._show(name)
            look(board, name, bad)
        board._show("Settings")
        for tab in settings_mod.tab_names():
            board._settings_go(tab)
            board._finish_settings()
            look(board, tab, bad)
        assert not bad, bad


