def test_the_shipped_config_carries_the_study_section() -> None:
    cfg = config_mod.load(Path(__file__).resolve().parent / "defaults.toml")
    scfg = getattr(cfg, "study", None)
    assert scfg is not None and scfg.enabled, scfg
    assert scfg.idle_minutes > 0 and scfg.max_clip_seconds > 0
    assert 0 < scfg.llm_per_day < 500, "must stay well under Groq's ~1,000/day"


def test_the_learning_probes_read_the_app_cheaply() -> None:
    """The study engine polls these every few seconds; they must work on a
    half-built App (the suite's convention) and see both state and
    counters move."""
    import queue as queue_mod
    import threading

    import main as main_mod
    app = main_mod.App.__new__(main_mod.App)
    app._activity = "ready"
    app.queue = queue_mod.Queue()
    app._text_busy = threading.Event()
    app._correcting = threading.Event()
    app._looking_up = threading.Event()
    app._stats_lock = threading.Lock()
    app._stats = {"dictations": 0}
    assert app._learning_quiet()
    before = app._learning_fingerprint()
    app._stats["dictations"] = 1
    assert app._learning_fingerprint() != before, "a dictation must show"
    app._activity = "recording"
    assert not app._learning_quiet(), "recording is never a quiet moment"



def test_the_study_never_relearns_what_the_live_pass_already_fixed() -> None:
    """The backward-learning trap: polish fixed a word, every fresh decode
    of the same audio still hears the original garble, the vote "agrees"
    the fix back out — and the diff would teach the app to un-fix itself,
    (right word -> garble). The heard side of a learnable pair must be
    something the live decoder actually produced."""
    import study as study_mod
    item = _StudyItem(Path("rec-11.wav"),
                      {"raw": "נוזל קירוב למנוע",
                       "text": "נוזל קירור למנוע"})   # polish fixed it
    t = _StudyTranscriber(wide="נוזל קירוב למנוע",
                          general="נוזל קירוב למנוע",
                          loose="נוזל קירוב למנוע")
    result = study_mod.study_one(
        item, t, adjudicator=_StudyAdjudicator("נוזל קירוב למנוע"))
    assert result["llm"] is True, result
    assert result["pairs"] == [], result
    # and that disagreement is NOT silver corpus material either
    assert not study_mod.Engine._silver(item.meta, result), result
    # while a clip where everything agrees still is
    t2 = _StudyTranscriber(wide="נוזל קירור למנוע",
                           general="נוזל קירור למנוע",
                           loose="נוזל קירור למנוע")
    result2 = study_mod.study_one(
        _StudyItem(Path("rec-12.wav"),
                   {"raw": "נוזל קירור למנוע",
                    "text": "נוזל קירור למנוע"}), t2)
    assert study_mod.Engine._silver(
        {"text": "נוזל קירור למנוע"}, result2), result2
    # ...but a clip the vote DISPUTED is not "everything agreed", even
    # though the unendorsed verified text equals the live text
    assert result["disputed"] and not study_mod.Engine._silver(
        item.meta, result), result

def _hint_cfg(**over):
    """The shipped config, with fields replaced, for the card's rows."""
    cfg = config_mod.load(Path(__file__).resolve().parent / "defaults.toml")
    return dataclasses.replace(cfg, **over) if over else cfg


def test_hint_settings_are_present_in_the_real_config() -> None:
    """A default that lives only in code is a default nobody can find."""
    cfg = _hint_cfg()
    assert cfg.hint.corner in config_mod.HINT_CORNERS, cfg.hint.corner
    # The delay is the whole reason this is not clutter: an ordinary
    # dictation has to finish before the card would have appeared.
    assert 150 <= cfg.hint.after_ms <= 1200, cfg.hint.after_ms
    text = (Path(__file__).resolve().parent / "defaults.toml").read_text("utf-8")
    assert "[hint]" in text and "after_ms" in text


def test_a_bad_hint_corner_is_refused_at_load() -> None:
    """Refused where it can still be reported, not at the first paint."""
    import shutil

    tmp = Path(tempfile.mkdtemp(prefix="dictation-hint-"))
    try:
        path = tmp / "config.toml"
        base = (Path(__file__).resolve().parent / "defaults.toml"
                ).read_text("utf-8")
        # The shipped [hint] says `corner = "dot"` — the first such line
        # in the file; [shelf]'s is the second and much further down.
        assert base.count('corner = "dot"') == 2, "the file changed shape"
        path.write_text(base.replace('corner = "dot"',
                                     'corner = "middle"', 1), "utf-8")
        try:
            config_mod.load(path)
        except config_mod.ConfigError as e:
            assert "hint.corner" in str(e), e
        else:
            raise AssertionError("a nonsense corner loaded happily")
        path.write_text(base.replace("after_ms = 400", "after_ms = -1"),
                        "utf-8")
        try:
            config_mod.load(path)
        except config_mod.ConfigError as e:
            assert "after_ms" in str(e), e
        else:
            raise AssertionError("a negative delay loaded happily")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_card_lists_exactly_the_keys_the_state_machine_taps() -> None:
    """The one way this feature can lie without anyone noticing.

    A card naming a key you have rebound, or one this app never bound, is
    worse than no card. Both lists are built from the same Config by
    different code, so this compares them rather than trusting that they
    were written to agree.
    """
    import main as main_mod

    cfg = _hint_cfg()
    _hotkeys, taps, _latch, _pause = main_mod.App.bindings(cfg)
    from_machine = set(taps.values())
    from_card = {action for action, _binding in hint_mod.bindings(cfg)}
    assert from_card == from_machine, (from_card ^ from_machine)
    # and every one of them has a human name, not a bare action string
    for action in from_card:
        assert action in hint_mod.LABELS, action


def test_held_greys_the_text_keys_and_latched_does_not() -> None:
    """main._allowed's rule, read off the card instead of the log."""
    import main as main_mod

    cfg = _hint_cfg()
    held = hint_mod.card_for(cfg, hint_mod.HOLD, main_mod._SCREEN_ACTIONS)
    latched = hint_mod.card_for(cfg, hint_mod.LATCHED,
                                main_mod._SCREEN_ACTIONS)
    assert hint_mod.card_for(cfg, "idle", main_mod._SCREEN_ACTIONS) is None
    live = {k for k, _l, on in held["keys"] if on}
    dead = {k for k, _l, on in held["keys"] if not on}
    assert live and dead, held["keys"]
    # The four screen keys fire mid-hold; the four that read or write text
    # at the cursor do not, and say why rather than going quiet.
    for key, label, on in held["keys"]:
        if not on:
            assert hint_mod.NEEDS_A_HAND in label, label
    assert all(on for _k, _l, on in latched["keys"]), latched["keys"]
    assert live | dead == {k for k, _l, _o in latched["keys"]}
    # Held offers the release and the latch; latched offers neither.
    assert any(k == "שחרר" for k, _l, _o in held["rows"])
    assert not any(k == "שחרר" for k, _l, _o in latched["rows"])
    assert all(any(k == "Esc" for k, _l, _o in c["rows"])
               for c in (held, latched))


def test_rebinding_a_key_moves_it_on_the_card_and_a_kill_switch_removes_it(
) -> None:
    """Built from the live Config, so it cannot describe last week's keys."""
    import main as main_mod

    cfg = dataclasses.replace(_hint_cfg(), punctuate_hotkey="ctrl+f7")
    card = hint_mod.card_for(cfg, hint_mod.LATCHED, main_mod._SCREEN_ACTIONS)
    rows = dict((label, key) for key, label, _on in card["keys"])
    assert rows[hint_mod.LABELS["punctuate"]] == "Ctrl+F7", rows
    gone = dataclasses.replace(cfg, punctuate_hotkey="", lookup_hotkey="")
    card = hint_mod.card_for(gone, hint_mod.LATCHED, main_mod._SCREEN_ACTIONS)
    labels = {label for _key, label, _on in card["keys"]}
    assert hint_mod.LABELS["punctuate"] not in labels, labels
    assert hint_mod.LABELS["lookup"] not in labels, labels


def test_key_names_are_written_the_way_a_person_reads_them() -> None:
    assert hint_mod.pretty("ctrl+f10") == "Ctrl+F10"
    assert hint_mod.pretty("win+shift+s") == "Win+Shift+S"
    assert hint_mod.pretty("right ctrl") == "Right Ctrl"
    # The latch key is an arrow on the keyboard and an arrow on the card.
    assert hint_mod.pretty("left") == "←"
    assert hint_mod.pretty("") == ""


def test_the_card_goes_in_the_corner_it_was_asked_for() -> None:
    """Pure arithmetic, so all four are checked without a screen — with
    the dot in each of ITS two corners, because the card stops short of
    the dot's square only in the corner the dot is actually in."""
    screen = (1920, 1080)
    room = overlay_mod.HintCard.DOT_ROOM
    # The dot at the top-right, as it was until 2026-09-07: top-right
    # alone stops short, sideways, so the status dot keeps its own square.
    # The dot is the one thing on screen that says the app is alive, and
    # it does not move for a panel that is only up while a key is held.
    got = {}
    for corner in config_mod.HINT_CORNERS:
        card = overlay_mod.HintCard(corner=corner, margin=10,
                                    dot_corner="top-right")
        got[corner] = card.origin(300, 400, screen)
    assert got["top-left"] == (10, 10), got
    assert got["bottom-left"] == (10, 1080 - 400 - 10), got
    assert got["bottom-right"] == (1920 - 300 - 10, 1080 - 400 - 10), got
    assert got["top-right"] == (1920 - 300 - 10 - room, 10), got
    # The dot at the bottom-right, where it lives now: bottom-right alone
    # stops short, UPWARDS, and top-right is an ordinary corner again.
    got = {}
    for corner in config_mod.HINT_CORNERS:
        card = overlay_mod.HintCard(corner=corner, margin=10,
                                    dot_corner="bottom-right")
        got[corner] = card.origin(300, 400, screen)
    assert got["top-left"] == (10, 10), got
    assert got["bottom-left"] == (10, 1080 - 400 - 10), got
    assert got["top-right"] == (1920 - 300 - 10, 10), got
    assert got["bottom-right"] == (1920 - 300 - 10,
                                   1080 - 400 - 10 - room), got
    # and the default dot corner IS bottom-right, in the class as in the
    # file, so a card built with no word about the dot behaves the same
    assert overlay_mod.HintCard(corner="bottom-right", margin=10).origin(
        300, 400, screen) == got["bottom-right"]


def test_the_cards_open_above_a_bottom_right_dot_and_beside_a_top_right_one(
) -> None:
    """The shelf and the key card open BESIDE the dot, never over it, and
    "beside" depends on which corner the dot is in. With the work area
    handed in (the dot is placed against the work area, above the
    taskbar), a bottom-right card's visible bottom edge is above the
    dot's window and its right edge is at the card's own margin; a
    top-right card keeps today's placement — its right edge stops short
    of the dot by DOT_ROOM and its top is at the margin. The same
    arithmetic for both cards, because the shelf inherits it."""
    import shelf as shelf_mod
    import shelf_card as sc

    skin = _skin_or_skip()
    if skin is None or not skin.on():
        return
    from skin import dot as skin_dot

    screen, work = (2560, 1440), (0, 0, 2560, 1392)
    desktop = (-1920, 0, 4480, 1440)
    inset, m = sc.SHADOW, 14
    card = sc.card_for({"mode": "listening", "uptime_s": 5},
                       _shelf_pile(3), "", False, max_rows=5)
    w, h = sc.measure(card, 1.0)
    win_w, win_h = w + inset * 2, h + inset * 2
    for corner in ("bottom-right", "top-right"):
        dx, dy, dw, dh = skin_dot.place(corner, work)
        for kind in ("shelf", "hint"):
            if kind == "shelf":
                thing = shelf_mod.ShelfCard(corner=corner, margin=m,
                                            dot_corner=corner)
            else:
                thing = overlay_mod.HintCard(corner=corner, margin=m,
                                             dot_corner=corner)
            x, y = thing.origin(win_w, win_h, screen, inset, desktop, work)
            left, top = x + inset, y + inset
            right, bottom = left + w, top + h
            if corner == "bottom-right":
                assert right == 2560 - m, (kind, right)
                assert bottom < dy, (kind, "the card sits on the dot",
                                     bottom, dy)
                assert dy - bottom >= 12, (kind, "no daylight", dy - bottom)
                assert bottom <= work[3] - m, (kind, "under the taskbar")
            else:
                assert top == m, (kind, top)
                assert right < dx, (kind, "the card sits on the dot",
                                    right, dx)
                assert right == 2560 - m - overlay_mod.HintCard.DOT_ROOM, \
                    (kind, right)
    # Without a work area the arithmetic is the old one, on the screen:
    # every test written before the work area was passed still holds.
    plain = overlay_mod.HintCard(corner="top-left", margin=12)
    assert plain.origin(300, 400, (1920, 1080)) == (12, 12)


def test_the_panel_opens_beside_the_dot_wherever_he_dragged_it() -> None:
    """THE OTHER HALF OF MOVING THE DOT, and it was left undone on
    purpose for one night.

    The owner, 2026-09-08: "I reopened the app so I don't know about the
    tab that opens when I'm pressing the dot — I want it to be able to
    move where the dot is. Okay, so please code it like that." Until
    today `[dot] corner` decided where the shelf and the key card opened,
    so a dot dragged into the middle of the screen left the panel opening
    in the bottom-right corner, detached from the thing that opened it.
    The note in AGENTS.md that called that permanent asked for an answer
    to "beside a dot that is nowhere near an edge"; this is the answer,
    and it is `overlay.beside_dot`.

    ABOVE when there is room above, BELOW when there is not, centred on
    the dot and slid back onto the screen the dot is on, and never on the
    dot. Clamped last against the whole virtual desktop, because the
    monitor to the left of this machine's primary starts at x = -1920 and
    a panel following a dot over there must not be walked home.
    """
    import shelf as shelf_mod

    work = (0, 0, 2560, 1392)                 # the primary, above a taskbar
    desktop = (-1920, 0, 4480, 1440)          # and a screen on the left
    left_screen = (-1920, 0, 1920, 1080)
    w, h = 392, 528
    box = 38

    def dot_at(x, y):
        return (x, y, x + box, y + box)

    # ABOVE, centred on the dot, with real daylight between the two
    x, y = overlay_mod.beside_dot(dot_at(1200, 700), (w, h), work,
                                  overlay_mod.DOT_GAP, desktop)
    assert y + h == 700 - overlay_mod.DOT_GAP, (y, h)
    assert x + w / 2 == 1200 + box / 2, (x, "not centred on the dot")

    # BELOW, when the dot is too near the top for the panel to fit above
    x, y = overlay_mod.beside_dot(dot_at(1200, 60), (w, h), work,
                                  overlay_mod.DOT_GAP, desktop)
    assert y == 60 + box + overlay_mod.DOT_GAP, y
    assert y + h <= work[1] + work[3], "below the screen it is on"

    # SLID BACK ON, for a dot near an edge — and still not on the dot
    for at in ((2540, 700), (4, 700), (2540, 40), (4, 1340)):
        x, y = overlay_mod.beside_dot(dot_at(*at), (w, h), work,
                                      overlay_mod.DOT_GAP, desktop)
        assert work[0] <= x and x + w <= work[0] + work[2], (at, x)
        assert work[1] <= y and y + h <= work[1] + work[3], (at, y)
        assert not overlay_mod._overlaps((x, y, x + w, y + h),
                                         dot_at(*at)), at

    # THE MONITOR ON THE LEFT, whose coordinates are genuinely negative
    x, y = overlay_mod.beside_dot(dot_at(-1900, 700), (w, h), left_screen,
                                  overlay_mod.DOT_GAP, desktop)
    assert x == -1920, x
    assert x < 0 and x + w < 0, "the panel was walked back onto the primary"

    # A PANEL TALLER THAN THE ROOM ON EITHER SIDE goes beside the dot, on
    # the side with more room, and still never over it.
    x, y = overlay_mod.beside_dot(dot_at(1200, 700), (w, 1380), work,
                                  overlay_mod.DOT_GAP, desktop)
    assert x == 1200 + box + overlay_mod.DOT_GAP, x
    assert not overlay_mod._overlaps((x, y, x + w, y + 1380),
                                     dot_at(1200, 700))

    # ...and the same answer for the shelf and the key card, from the one
    # place that decides it. `dot_at` is a callable because the dot moves
    # while the app runs and the cards are built once, at startup.
    screen, inset, m = (2560, 1440), 26, 14
    win_w, win_h = w + inset * 2, h + inset * 2
    here = lambda: dot_at(1200, 700)                             # noqa: E731
    beside = overlay_mod.beside_dot(here(), (w, h), work,
                                    overlay_mod.DOT_GAP, desktop)
    # origin() asks Windows which monitor the dot is on; this dot is a
    # fiction at (1200, 700) on a fictional 2560 px primary, and on a
    # smaller real screen (a hosted runner's 1024 px, 2026-09-18) Windows
    # answers with the nearest real monitor and slides the panel back
    # onto it. The question is answered here, with the same work area the
    # expected value was computed from, so the test is arithmetic alone.
    real_monitor_work = overlay_mod._monitor_work
    overlay_mod._monitor_work = lambda x, y: work
    try:
        for card in (overlay_mod.HintCard(corner="bottom-right", margin=m,
                                          dot_corner="bottom-right",
                                          dot_at=here),
                     shelf_mod.ShelfCard(corner="bottom-right", margin=m,
                                         dot_corner="bottom-right",
                                         dot_at=here)):
            at = card.origin(win_w, win_h, screen, inset, desktop, work)
            assert (at[0] + inset, at[1] + inset) == beside, (type(card), at)
    finally:
        overlay_mod._monitor_work = real_monitor_work

    # AND WHAT STILL WORKS. A dot that has not been dragged is None from
    # main.App._dot_beside, and then the corner rule decides exactly as
    # it did before this existed; a card he dragged HIMSELF keeps its own
    # position, dot or no dot; and a dot that cannot say where it is
    # costs a corner rather than a card.
    plain = overlay_mod.HintCard(corner="bottom-right", margin=m,
                                 dot_corner="bottom-right")
    corner = plain.origin(win_w, win_h, screen, inset, desktop, work)
    for at in (lambda: None, lambda: 1 / 0, lambda: (0, 0, 0, 0)):
        same = overlay_mod.HintCard(corner="bottom-right", margin=m,
                                    dot_corner="bottom-right", dot_at=at)
        assert same.origin(win_w, win_h, screen, inset, desktop,
                           work) == corner, at
    his = overlay_mod.HintCard(corner="bottom-right", margin=m, x=400,
                               y=250, dot_corner="bottom-right", dot_at=here)
    assert his.origin(win_w, win_h, screen, inset, desktop, work) == (
        400 - inset, 250 - inset), "his own drag has to beat the dot"

    # main.py: only a DRAGGED dot is offered, and only to the cards that
    # follow it — the corner rule is what a dot sitting in its corner
    # gets, because it puts the panel against the screen's edge rather
    # than eighteen pixels off it.
    import main as main_mod
    app = main_mod.App.__new__(main_mod.App)
    app.dot = overlay_mod.StatusDot()
    app.dot.rect = (1200, 700, 1238, 738)
    assert app._dot_beside() is None, "an undragged dot is the corner rule"
    app.dot.x, app.dot.y = 1200, 700
    assert app._dot_beside() == (1200, 700, 1238, 738)
    app.dot = None
    assert app._dot_beside() is None, "no dot, nothing to open beside"


def test_the_shadow_margin_does_not_move_the_visible_edge() -> None:
    """The glass card leaves room around itself for its own shadow and the
    Tk one does not, so the same corner has to put the same PICTURE in the
    same place from two different window sizes."""
    screen = (1920, 1080)
    card = overlay_mod.HintCard(corner="top-left", margin=12)
    plain = card.origin(300, 400, screen)
    padded = card.origin(300 + 52, 400 + 52, screen, inset=26)
    assert plain == (12, 12), plain
    # window corner is 26 px up and left, so the card inside it lands at 12
    assert padded == (12 - 26, 12 - 26), padded


def test_where_it_was_dragged_to_beats_the_corner_and_stays_reachable(
) -> None:
    """A card dragged onto a monitor that is no longer plugged in must not
    come back somewhere nobody can see it."""
    screen = (1920, 1080)
    moved = overlay_mod.HintCard(corner="top-right", x=400, y=250)
    assert moved.moved() and moved.origin(300, 400, screen) == (400, 250)
    lost = overlay_mod.HintCard(corner="top-right", x=5000, y=4000)
    x, y = lost.origin(300, 400, screen)
    assert x < 1920 and y < 1080, (x, y)
    # and far enough on to be grabbed by the strip along its top
    assert x + 300 > 0 and y + 400 > 0, (x, y)
    # nothing saved at all still means the corner
    assert not overlay_mod.HintCard(corner="top-left").moved()


def test_a_card_left_on_the_screen_to_the_LEFT_stays_there() -> None:
    """The bug this is here for, and it shipped.

    A monitor to the left of the primary has NEGATIVE screen coordinates —
    on this machine the virtual desktop starts at x = -1920 — so a card
    dragged there saves a negative x. The sentinel for "never moved" was
    -1, `x >= 0` was the test for "has been moved", and the two collided:
    every drag onto that screen was written to config.toml correctly and
    thrown away on the next read, so the card snapped back beside the dot.
    Only drags that ended at a positive x and more than a shadow's depth
    below the top of the screen survived, which is what "it saves about one
    time in eight" looks like from the outside.
    """
    assert overlay_mod.HINT_UNSET == config_mod.HINT_UNSET
    assert overlay_mod.HINT_UNSET < -32768, (
        "the sentinel has to be past anything a virtual desktop can reach")
    primary = (2560, 1440)
    desktop = (-1920, 0, 4480, 1440)       # a second screen on the left
    for x, y in ((-369, 438), (-1900, 12), (-1, -1), (0, 0), (-26, -26)):
        card = overlay_mod.HintCard(corner="top-right", x=x, y=y)
        assert card.moved(), (x, y)
        got = card.origin(392, 528, primary, 26, desktop)
        assert got == (x - 26, y - 26), (x, y, got)


def test_what_is_saved_is_the_card_you_can_see_not_the_window() -> None:
    """The other half of the same bug. The glass window is bigger than the
    card by the room it leaves for its shadow, so saving the window's
    corner stored a y 26 px higher than anything on screen — negative for
    every drag near the top, which the sentinel then ate."""
    try:
        from skin import hint as skin_hint
    except Exception:
        return
    primary, desktop = (2560, 1440), (0, 0, 2560, 1440)
    inset = skin_hint.SHADOW
    card = overlay_mod.HintCard(corner="top-right")
    # what skin/hint.py does when a drag ends: window corner + the inset
    window_was = (700, -16)
    card.placed(window_was[0] + inset, window_was[1] + inset)
    assert (card.x, card.y) == (726, 10), (card.x, card.y)
    # and it comes back to exactly the window position it was dragged to
    assert card.origin(392, 528, primary, inset, desktop) == window_was


def test_an_unchanged_position_is_not_written_again() -> None:
    """A drag ends in more than one message and this is the line editor's
    most frequent caller."""
    saved = []
    card = overlay_mod.HintCard(on_change=saved.append)
    card.placed(300, 200)
    card.placed(300, 200)
    card.placed(300, 200)
    assert saved == [{"x": 300, "y": 200}], saved
    card.placed(301, 200)
    assert len(saved) == 2, saved


def test_moving_resizing_and_dismissing_are_written_down() -> None:
    """"I moved it" has to outlive the dictation it was moved during."""
    saved = []
    card = overlay_mod.HintCard(on_change=saved.append)
    card.placed(120, 340)
    card.resized(0.8)
    assert (card.x, card.y, card.scale) == (120, 340, 0.8)
    assert saved == [{"x": 120, "y": 340}, {"scale": 0.8}], saved
    # Ticking the box is not "hide it for now": the card stops accepting
    # anything at all, and the reason is written down.
    card.dismissed()
    assert saved[-1] == {"enabled": False}, saved
    card._thread = object()                # pretend it is running
    card.show({"a": 1})
    assert card._q.empty(), "a dismissed card still queued a picture"


def test_a_failed_save_never_reaches_the_keyboard_thread() -> None:
    """The card runs on the overlay thread; config.toml can be read-only,
    locked, or on a disconnected drive. None of that may kill the card."""
    def explode(_fields):
        raise OSError("config.toml is read-only")

    card = overlay_mod.HintCard(on_change=explode)
    card.placed(10, 20)                    # must not raise
    assert (card.x, card.y) == (10, 20)


def test_the_card_takes_the_mouse_in_four_places_and_nowhere_else() -> None:
    """Everything else answers HTTRANSPARENT, so a click aimed at the close
    button of a maximised window underneath still reaches it — the trap the
    status dot paid for once already."""
    try:
        from skin import glass as skin_glass, hint as skin_hint
    except Exception:
        return
    import main as main_mod

    card = hint_mod.card_for(_hint_cfg(), hint_mod.HOLD,
                             main_mod._SCREEN_ACTIONS)
    for scale in (0.6, 1.0, 1.4):
        boxes = skin_hint.regions(card, scale)
        width, height = skin_hint.measure(card, scale)
        pad = skin_hint.SHADOW
        for name, (x0, y0, x1, y1) in boxes.items():
            assert x1 > x0 and y1 > y0, (name, boxes[name])
            assert x0 >= pad - 8 and y0 >= pad - 8, (name, boxes[name])
            assert x1 <= pad + width + 8 and y1 <= pad + height + 8, (
                name, boxes[name], width, height)
            # every claimed rectangle answers something other than "pass
            # this through", and the middle of the card always passes
            code, what = skin_hint.hit_test(
                card, scale, (x0 + x1) / 2, (y0 + y1) / 2)
            assert what == name, (name, what)
            assert code != skin_glass.HTTRANSPARENT, (name, code)
        middle = skin_hint.hit_test(card, scale, pad + width / 2,
                                    pad + height / 2)
        assert middle == (skin_glass.HTTRANSPARENT, None), middle
        # and so does everything outside the card entirely
        assert skin_hint.hit_test(card, scale, 2, 2)[0] == \
            skin_glass.HTTRANSPARENT
    # the size buttons must not sit on top of each other
    boxes = skin_hint.regions(card, 1.0)
    assert boxes[skin_hint.SMALLER][2] <= boxes[skin_hint.BIGGER][0], boxes


def test_the_size_buttons_stop_at_the_ends_of_their_range() -> None:
    try:
        from skin import hint as skin_hint
    except Exception:
        return
    assert skin_hint.clamp_scale(99) == skin_hint.SCALE_MAX
    assert skin_hint.clamp_scale(0.01) == skin_hint.SCALE_MIN
    assert skin_hint.clamp_scale(1.0) == 1.0
    # and the range the card enforces is the range config.py will accept,
    # or a size chosen on screen would refuse to load next time
    assert skin_hint.SCALE_MIN == config_mod.HINT_SCALE_MIN
    assert skin_hint.SCALE_MAX == config_mod.HINT_SCALE_MAX


# ---------------------------------------------------------------------------
# THE SHELF — shelf_card.py (words, geometry, picture), shelf.py (the
# thread and the window), skin\shelf.py (the glass). Everything below runs
# with no window and no screen, which is the point of that split.
# ---------------------------------------------------------------------------

def _shelf_pile(n: int = 5) -> list:
    """A pile in the shapes main.App._shelf_pile builds. Invented word for
    word: nothing here comes out of anybody's store."""
    kinds = (
        ("input", [("notify.open", "Open"), ("notify.dismiss", "Dismiss")]),
        ("review", [("review.accept", "Keep"), ("review.reject", "No")]),
        ("problem", [("problem.open", "Open"), ("problem.close", "Close")]),
        ("question", [("question.answer", "Answer"),
                      ("question.later", "Later")]),
        ("done", [("notify.open", "Open"), ("notify.dismiss", "Dismiss")]),
    )
    out = []
    for i in range(n):
        kind, answers = kinds[i % len(kinds)]
        out.append({"kind": kind, "id": f"x-{i}",
                    "text": f"waiting item number {i}",
                    "at": f"2026-09-06T2{i % 4}:00:00",
                    "pill": "מילה" if kind == "review" else "",
                    "answers": answers})
    return out


class _FakeShelf:
    """A stand-in for shelf.ShelfCard: it remembers what it was shown."""

    def __init__(self, card=None):
        self.card = card
        self.rows = 5
        self.scale = 1.0
        self.shown: list = []

    def visible(self) -> bool:
        return self.card is not None

    def current(self):
        return self.card

    def show(self, card) -> None:
        self.card = card
        self.shown.append(card)

    def hide(self) -> None:
        self.card = None
        self.shown.append(None)


def test_the_shelf_takes_the_mouse_where_it_is_painted_and_nowhere_else():
    """Every named rectangle answers with its own name at its centre, no
    two of them overlap, and everything else — the shadow margin and the
    panel's own padding included — answers HTTRANSPARENT.

    That last one is not tidiness. The panel opened in the top-right
    corner until 2026-09-07, which is the close button of every maximised
    window, and a hole that swallowed a click aimed at it is the trap the
    status dot paid for once already; it opens above the dot in the
    bottom-right now and the rule is kept.
    """
    import shelf_card as sc

    for scale in (0.6, 1.0, 1.4):
        for waiting in (0, 1, 5, 12):
            card = sc.card_for({"mode": "listening", "uptime_s": 90},
                               _shelf_pile(waiting), "", False, max_rows=5)
            boxes = sc.regions(card, scale)
            width, height = sc.measure(card, scale)
            pad = sc.SHADOW
            for name, (x0, y0, x1, y1) in boxes.items():
                assert x1 > x0 and y1 > y0, (name, boxes[name])
                assert x0 >= pad - 1 and y0 >= pad - 1, (name, boxes[name])
                assert x1 <= pad + width + 1 and y1 <= pad + height + 1, \
                    (name, boxes[name], width, height)
                code, what = sc.hit_test(card, scale, (x0 + x1) / 2,
                                         (y0 + y1) / 2)
                if name == sc.DRAG:
                    continue            # the head strip is under the buttons
                assert what == name, (scale, waiting, name, what)
                assert code == sc.HTCLIENT, (name, code)
            names = [n for n in boxes if n != sc.DRAG]
            for i, one in enumerate(names):
                ax0, ay0, ax1, ay1 = boxes[one]
                for two in names[i + 1:]:
                    bx0, by0, bx1, by1 = boxes[two]
                    assert not (ax0 < bx1 and bx0 < ax1
                                and ay0 < by1 and by0 < ay1), \
                        (one, two, boxes[one], boxes[two])
            # the shadow margin, and the panel's own bottom padding
            assert sc.hit_test(card, scale, 2, 2) == (sc.HTTRANSPARENT, None)
            assert sc.hit_test(card, scale, pad + width / 2,
                               pad + height - 2) == (sc.HTTRANSPARENT, None)


def test_the_shelf_has_an_x_that_closes_it() -> None:
    """The third way out, for the hand that is already on the mouse: an X
    at the top-right of the head band, in BOTH painters (shelf_card.compose
    is what skin\\shelf.py draws over its glass and what flat() draws on
    the Tk fallback, so one region serves both). It is a named rectangle
    like every other button — a press resolves to "close", action_at
    calls it chrome, and main.App routes it to _shelf_close, the same
    door the key, Esc and a second click on the dot go through. It lights
    on hover like its neighbours, and it never opens anything: the
    owner's rule is untouched."""
    import main as main_mod
    import shelf_card as sc

    assert sc.CLOSE == "close" and sc.CLOSE in sc.CHROME
    for scale in (0.6, 1.0, 1.4):
        for waiting in (0, 4):
            card = sc.card_for({"mode": "listening", "uptime_s": 90},
                               _shelf_pile(waiting), "", False, max_rows=5)
            boxes = sc.regions(card, scale)
            width, _height = sc.measure(card, scale)
            x0, y0, x1, y1 = boxes[sc.CLOSE]
            # top-right of the head band: flush with the card's right
            # padding, inside the band, and to the RIGHT of Stop
            assert abs(x1 - (sc.SHADOW + width - sc.PAD * scale)) < 1, \
                (scale, x1)
            head_top, head_h = sc._bands(card, scale)["head"]
            assert y0 >= sc.SHADOW + head_top - 1, (scale, y0, head_top)
            assert y1 <= sc.SHADOW + head_top + head_h + 1, (scale, y1)
            assert x0 >= boxes[sc.STOP][2], "the X is not right of Stop"
            assert abs((x1 - x0) - sc.CLOSE_W * scale) < 1, (x1 - x0)
            cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
            assert sc.hit_test(card, scale, cx, cy) == (sc.HTCLIENT, sc.CLOSE)
            assert sc.action_at(card, sc.CLOSE) == ("chrome", sc.CLOSE)
            # lit on hover: the plate under the X changes when it is the
            # hovered region, and only there
            plain = sc.compose(card, scale, None)
            lit = sc.compose(card, scale, sc.CLOSE)
            other = sc.compose(card, scale, sc.STOP)
            px = (int(cx - sc.SHADOW), int(cy - sc.SHADOW))
            edge = (int(x0 - sc.SHADOW + 2), int(y0 - sc.SHADOW + 2))
            assert lit.getpixel(edge) != plain.getpixel(edge), \
                (scale, "hovering the X does not light it")
            assert other.getpixel(edge) == plain.getpixel(edge), \
                (scale, "hovering Stop lit the X")
            assert plain.getpixel(px)[3] > 0, "no glyph under the pointer"

    # main.py: the press ends in _shelf_close, and only there
    src = (Path(__file__).resolve().parent / "main.py").read_text("utf-8")
    body = src[src.index("def _shelf_chrome"):]
    body = body[:body.index("def _shelf_screens")]
    assert "shelf_card_mod.CLOSE" in body and "_shelf_close()" in body
    hushed = []
    app = main_mod.App.__new__(main_mod.App)
    app.cfg = _hint_cfg()
    app.hint = _FakeHint()
    app.notify_card = type("_Column", (), {
        "hush": lambda s: hushed.append("hushed"),
        "unhush": lambda s: hushed.append("back")})()
    app.machine = type("_M", (), {"state": hotkey_mod.IDLE,
                                  "paused": False})()
    app._activity = "ready"
    app._started_at = time.monotonic() - 300
    app._rec_at = 0.0
    app._stats_lock = threading.Lock()
    app._stats = {"dictations": 0}
    app._last_lock = threading.Lock()
    app._last = None
    app._shelf_stop_armed = True
    app._shelf_stamp = ()
    app.notify = app._review = app.problems = app.questions = None
    app.awake = None
    app.shelf = _FakeShelf()
    app._shelf_open()
    assert app.shelf.visible() and hushed == ["hushed"]
    app._shelf_pressed(("chrome", sc.CLOSE))
    assert not app.shelf.visible(), "the X did not close the panel"
    assert hushed == ["hushed", "back"], hushed
    assert app._shelf_stop_armed is False, "closing disarms Stop"
    # the hint card is offered the corner back (with nothing to say for a
    # key nobody is holding, which is None — the offer is what matters)
    assert len(app.hint.shown) == 2, app.hint.shown


def test_the_shelf_stops_growing_at_the_row_it_was_given() -> None:
    """It gets taller with the pile and then stops: everything past
    `rows` becomes one "+N more" line. A panel that can grow without a
    ceiling is the dense home the owner already said no to."""
    import shelf_card as sc

    heights = []
    for waiting in (0, 1, 3, 5, 8, 20):
        card = sc.card_for({"mode": "listening", "uptime_s": 10},
                           _shelf_pile(waiting), "", False, max_rows=5)
        assert len(card["rows"]) == min(waiting, 5), (waiting, card["rows"])
        assert card["more"] == max(0, waiting - 5), (waiting, card["more"])
        assert card["waiting"] == waiting
        heights.append(sc.measure(card, 1.0)[1])
    assert heights == sorted(heights), heights
    assert heights[-1] == heights[-2], "past the cap it must stop growing"
    # and the width never moves: this is a panel, not a tooltip
    assert {sc.measure(sc.card_for({"mode": "listening"}, _shelf_pile(n), "",
                                   False, max_rows=5), 1.0)[0]
            for n in (0, 5, 20)} == {sc.CARD_W}


def test_a_press_on_the_shelf_resolves_to_the_row_that_drew_it() -> None:
    """`action_at` is the whole of what the painter decides: it turns a
    region name back into the verb and the id the CALLER put there, and
    answers None for a row this card never drew."""
    import shelf_card as sc

    card = sc.card_for({"mode": "listening"}, _shelf_pile(3), "", False,
                       max_rows=5)
    assert sc.action_at(card, sc.row_name(0, "a")) == \
        ("row", 0, "notify.open", "x-0")
    assert sc.action_at(card, sc.row_name(1, "b")) == \
        ("row", 1, "review.reject", "x-1")
    assert sc.action_at(card, sc.row_name(9, "a")) is None
    assert sc.action_at(card, "row2.z") is None
    assert sc.action_at(card, "rowX.a") is None
    assert sc.action_at(card, "") is None
    assert sc.action_at(card, "nonsense") is None
    for name in sc.CHROME:
        assert sc.action_at(card, name) == ("chrome", name), name


def test_the_shelf_interprets_nothing_it_is_handed() -> None:
    """It draws the list it is given. A kind it has never heard of becomes
    `info` rather than a KeyError, a malformed timestamp becomes an empty
    `when` rather than an exception, and a line comes back byte-identical
    — which is what lets a test hand it a pile that could never happen and
    see exactly what would be painted."""
    import shelf_card as sc

    said = "אמרתי משהו — and then some English"
    card = sc.card_for(
        {"mode": "no such mode", "uptime_s": "not a number"},
        [{"kind": "sideways", "id": 1, "text": said, "at": "yesterday-ish",
          "answers": [("a", "A"), ("b", "B"), ("c", "C")]}],
        {"text": said, "at": ""}, False, max_rows=5)
    assert card["mode"] == "listening", card["mode"]
    assert card["rows"][0]["kind"] == "info", card["rows"][0]
    assert card["rows"][0]["text"] == said
    assert card["rows"][0]["when"] == ""
    assert len(card["rows"][0]["answers"]) == 2, "two answers, never three"
    assert card["last"] == said
    assert card["uptime"] == "", "an unreadable uptime is no line, not a crash"
    # every colour it names is in the one table, and every table entry is
    # a real (r, g, b) — a reskin that dropped a name would draw nothing
    for colour, _word in sc.KIND.values():
        assert colour in sc.INK, colour
    for name in sc.STATE_COLOUR.values():
        assert name in sc.INK, name
    for value in sc.INK.values():
        assert len(value) == 3 and all(0 <= c <= 255 for c in value), value


def test_the_shelf_will_not_quit_the_app_while_the_microphone_is_live():
    """Two guards, both in the card so a test can see them: Stop ARMS on
    the first press and quits on the second, and it is refused outright
    while a recording is running. The rectangle stays claimed either way
    — a button that disappears leaves a hole that clicks through to the
    close button underneath."""
    import main as main_mod
    import shelf_card as sc

    for mode in ("recording", "locked"):
        card = sc.card_for({"mode": mode, "uptime_s": 5}, [], "", False)
        assert card["stop_ok"] is False, mode
        assert sc.STOP in sc.regions(card, 1.0), "the rectangle stays"
    for mode in ("listening", "paused", "busy"):
        assert sc.card_for({"mode": mode, "uptime_s": 5}, [], "",
                           False)["stop_ok"] is True, mode

    app = main_mod.App.__new__(main_mod.App)
    app._cue_lock = threading.Lock()
    app._cue_last = {}
    app._note = ""
    app._shelf_stop_armed = False
    was, main_mod.beep = main_mod.beep, lambda *a, **k: None
    try:
        app.shelf = _FakeShelf({"stop_ok": False})
        app._shelf_stop(app.shelf)
        assert app._shelf_stop_armed is False, "a refusal must not arm it"
        assert app.shelf.visible(), "and must not take the panel down"
        app.shelf = _FakeShelf({"stop_ok": True})
        app._shelf_push = lambda: None          # the repaint is not the point
        app._shelf_stop(app.shelf)
        assert app._shelf_stop_armed is True, "the first press arms"
    finally:
        main_mod.beep = was


def test_the_shelf_opens_on_the_key_and_the_same_key_closes_it() -> None:
    """The owner's rule, verbatim: it opens only on the key press, the
    same press or Esc closes it, never on hover. While it is up the hint
    card steps aside and the notification column is hushed — one pile in
    one corner — and both come back when it closes."""
    import main as main_mod

    hushed = []
    app = main_mod.App.__new__(main_mod.App)
    app.cfg = _hint_cfg()
    app.hint = _FakeHint()
    app.notify_card = type("_Column", (), {
        "hush": lambda s: hushed.append("hushed"),
        "unhush": lambda s: hushed.append("back")})()
    app.machine = type("_M", (), {"state": hotkey_mod.IDLE,
                                  "paused": False})()
    app._activity = "ready"
    app._started_at = time.monotonic() - 300
    app._rec_at = 0.0
    app._stats_lock = threading.Lock()
    app._stats = {"dictations": 3}
    app._last_lock = threading.Lock()
    app._last = None
    app._shelf_stop_armed = False
    app._shelf_stamp = ()
    app.notify = app._review = app.problems = app.questions = None
    app.awake = None
    app.shelf = _FakeShelf()

    app._shelf_open()
    assert app.shelf.visible(), "the key press is the only way in"
    assert app.hint.shown[-1] is None, "the hint card steps aside"
    assert hushed == ["hushed"], hushed
    card = app.shelf.current()
    assert card["title"] == "Listening" and card["waiting"] == 0, card
    assert card["rows"] == [] and card["more"] == 0
    assert "3 today" in card["uptime"], card["uptime"]

    app._tap_shelf()                        # the same key, again
    assert not app.shelf.visible(), "the same press closes it"
    assert hushed == ["hushed", "back"], hushed
    assert app._shelf_stop_armed is False, "closing disarms Stop"


def test_esc_closes_the_shelf_wherever_the_pointer_is() -> None:
    """The one deliberate difference from the review and notify cards.
    Those arrive uninvited, so they only claim Esc with the pointer on
    them; this one was asked for half a second ago, and while it is up Esc
    means close it. Exactly one vk is ever claimed, and only while it is
    up — so a locked recording is never discarded by an Esc aimed here,
    and no letter is eaten while it is down."""
    import shelf as shelf_mod

    card = shelf_mod.ShelfCard()
    card._thread = threading.current_thread()
    assert card.on_key(0x1B) is False, "nothing is up"
    card.show({"mode": "listening", "rows": []})
    assert card.visible()
    for vk in (ord("A"), ord("V"), 0x0D, 0x20, 0x71):
        assert card.on_key(vk) is False, vk
    assert card.on_key(0x1B) is True
    assert not card.visible()
    assert card.on_key(0x1B) is False, "and it only claims Esc once"

    # It is NOT the hint card's "don't show this again": that writes
    # enabled = false into config.toml, and closing a panel you opened
    # with a key is not that.
    wrote = []
    other = shelf_mod.ShelfCard(on_change=wrote.append)
    other.dismissed()
    assert wrote == [], wrote
    assert other._enabled is True


def test_the_shelf_still_opens_with_the_skin_folder_gone() -> None:
    """skin\\'s whole promise, for this panel: delete the folder and the
    same panel comes back in a plain Tk window — square corners, no
    frost, every button where it was painted. HD_SKIN=0 takes exactly
    that road, `skin.shelf_run` declines and
    shelf.ShelfCard._build_and_loop draws `shelf_card.flat()`.

    In a subprocess, like every other card test here: the card owns a Tcl
    interpreter, and burying one from the suite's main thread after its
    own thread is gone is the Tcl_AsyncDelete abort those tests exist to
    avoid.
    """
    _run_window_script('''
import os, sys, time
os.environ["HD_SKIN"] = "0"

import skin
skin.reset()
assert skin.on() is False, "HD_SKIN=0 must switch the skin off"

import shelf as shelf_mod
import shelf_card as sc

pressed = []
card = shelf_mod.ShelfCard(on_press=pressed.append)
card.start()
assert card._thread is not None and card._thread.is_alive(), "no thread"
data = sc.card_for({"mode": "listening", "uptime_s": 61}, [], "", False)
card.show(data)
for _ in range(250):
    if card.rect is not None:
        break
    time.sleep(0.02)
assert card.rect is not None, "the flat card never mapped"
x0, y0, x1, y1 = card.rect
width, height = sc.measure(data, 1.0)
assert (x1 - x0, y1 - y0) == (width, height), (card.rect, width, height)
# the window is the CARD, not the picture-plus-shadow: the hit test
# speaks in window coordinates and the fallback adds SHADOW back itself
card.pressed(sc.DOOR)
assert pressed == [("chrome", sc.DOOR)], pressed
card.hide()
card.stop()
print("ok")
''')


def test_the_shelf_key_is_registered_where_config_main_and_hint_look():
    """A tap key has eight registration points; every one of them has the
    shelf key, and switching [shelf] off takes it out of all of them.

    Two of the eight live in dashboard.py — KEY_GROUPS and its own copy of
    NESTED_HOTKEYS — and are covered by
    test_every_registered_key_has_a_place_on_the_keys_screen and
    test_both_capture_keys_are_registered_everywhere_a_key_must_be.
    """
    import main as main_mod

    fields = dict(config_mod.HOTKEY_FIELDS)
    assert fields["shelf_hotkey"].endswith("(tap)"), fields["shelf_hotkey"]
    # Inserted BEFORE the dismiss key, which is pinned as the last entry.
    assert config_mod.HOTKEY_FIELDS[-1][0] == "dismiss_hotkey", \
        config_mod.HOTKEY_FIELDS[-1]
    assert "shelf_hotkey" in config_mod.CHORD_FIELDS
    assert main_mod.NESTED_HOTKEYS["shelf_hotkey"] == "shelf.shelf_hotkey"
    cfg = config_mod.load(Path(sys.path[0]) / "defaults.toml")
    assert cfg.shelf_hotkey == cfg.shelf.hotkey == "ctrl+alt+d"
    moved = config_mod.with_field(cfg, "shelf_hotkey", "ctrl+alt+k")
    assert moved.shelf.hotkey == "ctrl+alt+k"
    assert dataclasses.replace(moved, shelf=cfg.shelf) == cfg, \
        "with_field must change nothing else"
    clash = config_mod.with_field(cfg, "shelf_hotkey", cfg.screens_hotkey)
    try:
        config_mod.check_hotkeys(clash)
        assert False, "the same chord on two keys must be refused"
    except config_mod.ConfigError as e:
        assert "shelf_hotkey" in str(e) or "screens_hotkey" in str(e), e
    _h, taps, _l, _p = main_mod.App.bindings(cfg)
    assert taps.get(parse_binding("ctrl+alt+d")) == "shelf", taps
    off = dataclasses.replace(cfg, shelf=dataclasses.replace(
        cfg.shelf, enabled=False))
    _h, taps_off, _l, _p = main_mod.App.bindings(off)
    assert "shelf" not in taps_off.values(), taps_off
    # It asks for no cursor and no clipboard, so it works mid-dictation.
    assert "shelf" in main_mod._SCREEN_ACTIONS
    assert ("shelf", "ctrl+alt+d") in hint_mod.bindings(cfg)
    assert "shelf" not in dict(hint_mod.bindings(off))
    assert hint_mod.LABELS["shelf"], "the card needs a name for it"
    assert {a for a, _b in hint_mod.bindings(cfg)} == set(taps.values()), \
        "hint.bindings and the tap table must be the same set"


def test_the_shelf_section_parses_and_is_bounded() -> None:
    """The panel's own knobs, read from the shipped file and refused when
    they are outside what the painter can draw."""
    import shutil

    cfg = config_mod.load(Path(sys.path[0]) / "defaults.toml")
    assert cfg.shelf.enabled is True
    assert cfg.shelf.corner in config_mod.HINT_CORNERS, cfg.shelf.corner
    assert config_mod.SHELF_ROWS_MIN <= cfg.shelf.rows \
        <= config_mod.SHELF_ROWS_MAX, cfg.shelf.rows
    assert cfg.shelf.x == cfg.shelf.y == config_mod.HINT_UNSET, \
        "the shipped file must not carry somebody's dragged position"
    tmp = Path(tempfile.mkdtemp(prefix="dictation-shelf-"))
    try:
        path = tmp / "config.toml"
        for line, word in (('rows = 0', "rows"),
                           ('rows = 99', "rows"),
                           ('corner = "middle"', "corner"),
                           ('scale = 9.0', "scale")):
            path.write_text(f"[shelf]\n{line}\n", "utf-8")
            try:
                config_mod.load(path)
                assert False, f"{line} was accepted"
            except config_mod.ConfigError as e:
                assert word in str(e), (line, e)
        path.write_text('[shelf]\nrows = 3\nscale = 0.8\n', "utf-8")
        got = config_mod.load(path)
        assert got.shelf.rows == 3 and got.shelf.scale == 0.8
        # and a config with no [shelf] at all still loads and binds it,
        # because the defaults are the shipped ones
        path.write_text("", "utf-8")
        assert config_mod.load(path).shelf.hotkey == "ctrl+alt+d"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_dot_section_decides_the_corner_for_every_card_beside_it(
) -> None:
    """ONE PLACE DECIDES THE CORNER. `[dot] corner` says where the status
    dot sits — either of the two corners, whichever he last chose; the
    default is bottom-right of the work area since 2026-09-07, top-right
    is the corner it used to keep and the one he can pick again. The shelf and the key card ship with
    `corner = "dot"`, which load() resolves to the dot's corner — so a
    Config never carries the word, every card reads a real corner, and
    the three tables that name the dot's corners agree. A section may
    still say a corner of its own, and a bad dot corner is refused at
    load, named as the dot's."""
    import shutil

    import overlay as overlay_mod
    assert config_mod.DOT_CORNERS == ("bottom-right", "top-right")
    assert config_mod.DOT_CORNERS == overlay_mod.DOT_CORNERS
    skin = _skin_or_skip()
    if skin is not None and skin.on():
        from skin import dot as skin_dot
        assert skin_dot.CORNERS == config_mod.DOT_CORNERS
    assert config_mod.CARD_CORNERS == ("dot",) + config_mod.HINT_CORNERS
    assert config_mod.HintConfig.corner == config_mod.FOLLOW_DOT
    assert config_mod.ShelfConfig.corner == config_mod.FOLLOW_DOT
    assert config_mod.corner_for("dot", "top-right") == "top-right"
    assert config_mod.corner_for("bottom-left", "top-right") == "bottom-left"

    # THE LIVE FILE IS HIS, NOT THE SUITE'S. This used to demand
    # "bottom-right" of config.toml itself, and it went red the evening he
    # moved the dot to the other corner from the Settings screen — a
    # choice the file offers him in the same breath. What the test is
    # actually about is that ONE place decides, so ask that instead: the
    # corner he has chosen is a real one, and both cards followed it
    # there. The shipped default is a property of the dataclass, and that
    # is where it is now pinned.
    assert config_mod.DotConfig.corner == "bottom-right"
    shipped = config_mod.load(Path(sys.path[0]) / "defaults.toml")
    assert shipped.dot.corner in config_mod.DOT_CORNERS, shipped.dot
    assert shipped.hint.corner == shipped.dot.corner, shipped.hint.corner
    assert shipped.shelf.corner == shipped.dot.corner, shipped.shelf.corner
    text = (Path(sys.path[0]) / "defaults.toml").read_text("utf-8")
    assert "[dot]" in text and text.index("[dot]") < text.index("[hint]")

    tmp = Path(tempfile.mkdtemp(prefix="dictation-dot-"))
    try:
        path = tmp / "config.toml"
        # no [dot] at all: the defaults are the shipped ones
        path.write_text("", "utf-8")
        cfg = config_mod.load(path)
        assert (cfg.dot.corner, cfg.hint.corner, cfg.shelf.corner) == \
            ("bottom-right",) * 3
        # the dot moves and both cards follow it
        path.write_text('[dot]\ncorner = "top-right"\n', "utf-8")
        cfg = config_mod.load(path)
        assert (cfg.dot.corner, cfg.hint.corner, cfg.shelf.corner) == \
            ("top-right",) * 3
        # ...unless a section says otherwise, explicitly
        path.write_text('[dot]\ncorner = "top-right"\n'
                        '[shelf]\ncorner = "bottom-left"\n'
                        '[hint]\ncorner = "dot"\n', "utf-8")
        cfg = config_mod.load(path)
        assert cfg.shelf.corner == "bottom-left" and cfg.hint.corner == \
            "top-right", (cfg.shelf.corner, cfg.hint.corner)
        # a corner the dot cannot sit in is refused as the DOT's
        for bad in ('corner = "bottom-left"', 'corner = "middle"',
                    'corner = "dot"'):
            path.write_text(f"[dot]\n{bad}\n", "utf-8")
            try:
                config_mod.load(path)
                assert False, f"[dot] {bad} was accepted"
            except config_mod.ConfigError as e:
                assert "dot.corner" in str(e), (bad, e)
        # and a card's nonsense is still the card's
        path.write_text('[shelf]\ncorner = "middle"\n', "utf-8")
        try:
            config_mod.load(path)
            assert False, "a nonsense shelf corner was accepted"
        except config_mod.ConfigError as e:
            assert "shelf.corner" in str(e) and "dot" in str(e), e
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    # main.py hands the dot's corner to the dot and to both cards, and
    # points the dot's click at the shelf's toggle
    src = (Path(__file__).resolve().parent / "main.py").read_text("utf-8")
    assert "corner=self._dot_corner," in src
    assert "self.dot.on_click = self._tap_shelf" in src
    assert src.count("dot_corner=self._dot_corner") >= 3, \
        "a card is built without the dot's corner"
    # The corner is still the one word both cards read while the dot is
    # in a corner — and since 2026-09-08 it is no longer the WHOLE story:
    # a card whose file said "dot" follows the dot to wherever he dragged
    # it (`follows_dot`, overlay.beside_dot), and one that named a corner
    # of its own stays in that corner even when the dot started there.
    # `corner_for` cannot carry that difference, because by the time it
    # has run the two read identically.
    moved_dot = config_mod.load(Path(sys.path[0]) / "defaults.toml")
    moved_dot = dataclasses.replace(
        moved_dot, dot=dataclasses.replace(moved_dot.dot, x=40, y=40))
    assert moved_dot.hint.corner == moved_dot.dot.corner
    assert moved_dot.shelf.corner == moved_dot.dot.corner
    assert moved_dot.hint.follow_dot and moved_dot.shelf.follow_dot
    assert config_mod.follows_dot("dot") is True
    assert config_mod.follows_dot("bottom-right") is False
    tmp = Path(tempfile.mkdtemp(prefix="dictation-follow-"))
    try:
        path = tmp / "config.toml"
        # the same resolved corner from two different words, and only one
        # of them is a follower
        path.write_text('[dot]\ncorner = "top-right"\n'
                        '[hint]\ncorner = "top-right"\n'
                        '[shelf]\ncorner = "dot"\n', "utf-8")
        cfg = config_mod.load(path)
        assert cfg.hint.corner == cfg.shelf.corner == "top-right"
        assert cfg.hint.follow_dot is False, "a named corner is not a follow"
        assert cfg.shelf.follow_dot is True
        # and main.py only hands the live dot to the cards that follow it
        src = (Path(__file__).resolve().parent / "main.py").read_text("utf-8")
        assert src.count("dot_at=self._dot_beside") == 4, \
            "a card is built without the live dot"
        assert 'if getattr(cfg.hint, "follow_dot", True) else None' in src
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_dot_can_be_dropped_anywhere_and_is_remembered() -> None:
    """`[dot] x/y` beats `[dot] corner`, and it is the same arithmetic on
    both paint paths.

    The owner, 2026-09-07: "the dot — I want it to be movable, and
    without needing to open and close the app". The remembering half of
    that is here — the corner is what a dot that has never been dragged
    gets, a dropped position wins, and the whole 38 px square is kept on
    the desktop, because unlike a card there is no corner of a dot you
    can grab when the rest of it is off screen.
    """
    import shutil

    work = (0, 0, 2560, 1392)               # this machine: a 48 px taskbar
    desktop = (-1920, 0, 4480, 1440)        # a second screen on the LEFT
    box, margin = (38, 38), (8, 4)
    # never dragged: the corner, with the dot's own margins
    assert overlay_mod.dot_spot("bottom-right", work, box, margin) == \
        (2560 - 38 - 8, 1392 - 38 - 4)
    assert overlay_mod.dot_spot("top-right", work, box, margin) == \
        (2560 - 38 - 8, 4)
    # dropped: exactly there, negatives included — the monitor on the
    # left is a real place and -1 was never a safe sentinel
    for at in ((1000, 500), (-1900, 12), (-1, 0), (0, 0), (-1920, 1402)):
        assert overlay_mod.dot_spot("bottom-right", work, box, margin,
                                    at[0], at[1], desktop) == at, at
    # dropped somewhere that is no longer there, or half off an edge:
    # back where he can reach it, and the WHOLE square, not sixty pixels
    # of it — there is no corner of a 38 px dot to grab
    for at, want in (((9999, 9999), (-1920 + 4480 - 38, 1440 - 38)),
                     ((-4000, -50), (-1920, 0)),
                     ((-1, -1), (-1, 0))):
        got = overlay_mod.dot_spot("bottom-right", work, box, margin,
                                   at[0], at[1], desktop)
        assert got == want, (at, got, want)
    # half a position is no position: both have to be past the sentinel
    unset = overlay_mod.HINT_UNSET
    assert overlay_mod.dot_spot("top-right", work, box, margin, 900, unset,
                                desktop) == (2560 - 38 - 8, 4)

    skin = _skin_or_skip()
    if skin is not None and skin.on():
        from skin import dot as skin_dot
        assert skin_dot.UNSET == overlay_mod.HINT_UNSET == \
            config_mod.HINT_UNSET
        # `place` is still the corner half and is what boot.py asks for a
        # landing; `spot` is the whole rule and they agree when nothing
        # was ever dragged
        assert skin_dot.spot("bottom-right", work) == \
            skin_dot.place("bottom-right", work)
        assert skin_dot.spot("bottom-right", work, 1000, 500, desktop) == \
            (1000, 500, 38, 38)
        d = skin_dot.Dot("bottom-right", x=640, y=210)
        assert (d.x, d.y) == (640, 210) and d.moving is False
        # and the boot light lands on the dot wherever the dot is
        from skin import boot as boot_mod
        layer = (0, 0, 1920, 1080)
        assert boot_mod._landing("bottom-right", layer, work, 640, 210,
                                 desktop) == (640 + 19.0, 210 + 19.0)
        assert boot_mod._landing("bottom-right", layer, work) == \
            boot_mod._landing("bottom-right", layer, work, None, None)

    tmp = Path(tempfile.mkdtemp(prefix="dictation-dot-move-"))
    try:
        path = tmp / "config.toml"
        # THE LIVE FILE IS HIS. This asked config.toml to prove nobody had
        # ever dragged the dot, and it went red the afternoon he found
        # "Move the dot" and used it - the feature working as designed
        # failed the test written for it, the second time in two days that
        # a test read his settings as if they were a fixture (the other
        # was the corner). The shipped default belongs to the dataclass,
        # so ask it there. Of the live file, ask only what is actually
        # true of every valid file: both numbers together or neither,
        # never half a position.
        assert config_mod.DotConfig.x == config_mod.DotConfig.y ==             config_mod.HINT_UNSET
        assert config_mod.DotConfig().moved() is False
        shipped = config_mod.load(Path(sys.path[0]) / "defaults.toml")
        assert (shipped.dot.x == config_mod.HINT_UNSET) ==             (shipped.dot.y == config_mod.HINT_UNSET), shipped.dot
        assert shipped.dot.moved() is (shipped.dot.x != config_mod.HINT_UNSET)
        path.write_text("[dot]\nx = 1204\ny = 388\n", "utf-8")
        cfg = config_mod.load(path)
        assert (cfg.dot.x, cfg.dot.y) == (1204, 388) and cfg.dot.moved()
        # one of the two set is refused, and said as such
        for line in ("x = 1204\n", "y = 388\n"):
            path.write_text(f"[dot]\n{line}", "utf-8")
            try:
                config_mod.load(path)
                assert False, f"[dot] {line.strip()} alone was accepted"
            except config_mod.ConfigError as e:
                assert "dot.x" in str(e) and "dot.y" in str(e), (line, e)
        # and the drop is written with the line editor that keeps the
        # comments — this file's comments are the measurements in it
        base = (Path(__file__).resolve().parent / "defaults.toml"
                ).read_text("utf-8")
        path.write_text(base, "utf-8")
        before = base.count("#")
        config_mod.set_values(path, {"dot.x": -369, "dot.y": 438})
        assert path.read_text("utf-8").count("#") == before, "comments lost"
        assert config_mod.load(path).dot.x == -369
        config_mod.set_values(path, {"dot.x": config_mod.HINT_UNSET,
                                     "dot.y": config_mod.HINT_UNSET})
        assert config_mod.load(path).dot.moved() is False, \
            "back to the corner has to clear both lines"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_dot_is_dragged_by_its_disc_and_never_by_its_glow() -> None:
    """Move mode changes ONE pixel's answer and nothing else.

    The disc says HTCAPTION instead of HTCLIENT, which is what makes
    Windows do the drag — and, because that press arrives as
    WM_NCLBUTTONDOWN, it is also what makes it impossible for one drag to
    also open the shelf. Every other pixel answers HTTRANSPARENT in BOTH
    modes: the glow, the ring and the corners let the mouse through to
    whatever is underneath, which is the rule the top-right corner taught
    this app and which a temporary mode does not get to suspend.

    And the window still ends at alpha 0 all the way round while it is
    waiting to be dragged, because the ring that says so is drawn wider:
    a lit border IS the square the owner complained about.
    """
    skin = _skin_or_skip()
    if skin is None or not skin.on():
        return
    from skin import dot as skin_dot
    from skin.glass import HTCAPTION, HTCLIENT, HTTRANSPARENT

    d = skin_dot.Dot()
    c = skin_dot.BOX / 2
    assert d.moving is False, "a dot nobody armed is a button"
    assert d.hit(c, c) == HTCLIENT
    d.moving = True
    assert d.hit(c, c) == HTCAPTION, "the disc does not hand over the drag"
    assert d.hit(c + 7, c) == HTCAPTION and d.hit(c, c - 7) == HTCAPTION
    for x, y in ((c + 8, c), (c + 14, c), (0, 0), (0, 37), (37, 0),
                 (37, 37)):
        assert d.hit(x, y) == HTTRANSPARENT, (
            f"the glow took the drag at {x}, {y} — it is click-through in "
            f"both modes or the window underneath loses clicks")
    d.moving = False
    assert d.hit(c, c) == HTCLIENT, "and it is a button again afterwards"

    try:
        import skia
    except Exception:
        return
    B = skin_dot.BOX
    for moving in (False, True):
        shown = skin_dot.Dot()
        shown.moving = moving
        surface = skia.Surface(B, B)
        canvas = surface.getCanvas()
        for frame in range(14):
            shown.draw(canvas, frame * 22.0)
        alpha = surface.makeImageSnapshot().toarray(
            colorType=skia.kRGBA_8888_ColorType)[:, :, 3]
        border = [int(alpha[0].max()), int(alpha[B - 1].max()),
                  int(alpha[:, 0].max()), int(alpha[:, B - 1].max())]
        assert border == [0, 0, 0, 0], (
            f"waiting to be dragged, the dot paints its own edge {border}")
    # the ring that says "waiting" is at the grab radius, not out in the
    # glow: what lights up has to be what can actually be pressed
    assert skin_dot.MOVE_W > 1.0
    assert skin_dot.CORE * 0.5 + 3.0 + skin_dot.MOVE_W / 2 < skin_dot.HALO_R


def test_the_move_button_reaches_the_running_app_down_the_real_pipe() -> None:
    """THE WHOLE ROAD, end to end, with a real named pipe in the middle.

    The dashboard is a separate process, so "become draggable" has to
    travel: the button calls control.send("dot", do="move"), a listener
    thread in the app hands it to App.control_command, and that arms the
    dot. Every other test of this either fakes control.send (the Settings
    screen's) or calls control_command directly (the deadline's), so the
    pipe itself — the piece the owner is actually pressing a button on —
    was never crossed. It is crossed here.

    Four things, in the order he would meet them: the command reaches the
    app and arms the disc; the reply carries the state the window needs
    to decide whether to hide itself; the mode EXPIRES on its own if he
    walks away, and the app then says so on the very next status poll,
    which is what puts the dashboard back; and a drop writes both lines
    at once and "Back to the corner" writes the sentinel back into both.

    What is NOT here, and cannot be: the drag. Windows' move loop wants
    real mouse input, and the dot is a layered window whose position is
    re-applied by every UpdateLayeredWindow, so a SetWindowPos standing
    in for a drag is undone before the message arrives.
    test_the_real_dot_window_moves_while_the_app_keeps_running sends the
    real messages to the real window instead — HTCAPTION, the press that
    must not open the shelf, the release that disarms — and that is the
    closest anything gets without a hand on the mouse.
    """
    import control as control_mod
    import main as main_mod

    app = main_mod.App.__new__(main_mod.App)
    app.cfg = config_mod.load(Path(sys.path[0]) / "defaults.toml")
    app.config_path = Path(sys.path[0]) / "defaults.toml"
    written: list = []
    app.dot = overlay_mod.StatusDot(on_change=written.append)
    app.dot._thread = threading.current_thread()      # pretend it is up
    app._say = lambda *a, **k: None

    restore = _private_pipe(control_mod, "dotmove")
    server = control_mod.ControlServer(app.control_command)
    assert server.start(), "the control channel did not come up"
    try:
        reply = control_mod.send("dot", do="move")
        assert reply is not None, "the button never reached the app"
        assert reply["ok"] and reply["dot"]["moving"] is True, reply
        assert "drag the dot" in reply["message"], reply
        assert app.dot.moving() is True, "the disc was never armed"

        # He pressed it and walked away. The deadline is the app's, and
        # the dashboard reads it off the next status rather than keeping
        # its own clock — moved here rather than slept through, because a
        # suite does not need to wait out forty-five seconds to know what
        # a deadline is.
        app.dot._move_until = time.monotonic() - 0.01
        again = control_mod.send("dot", do="state") or {}
        assert again.get("ok") is False, "state is not an action it knows"
        assert app.dot.state()["moving"] is False, \
            "a dashboard hidden for this would never come back"

        # The drop, and then home again — both lines, both times.
        control_mod.send("dot", do="move")
        app.dot.placed(1204, 388)
        assert written == [{"x": 1204, "y": 388}], written
        home = control_mod.send("dot", do="corner")
        assert home["ok"] and home["dot"]["dragged"] is False, home
        assert written[-1] == {"x": overlay_mod.HINT_UNSET,
                               "y": overlay_mod.HINT_UNSET}, written

        # ...and with no dot to drag, it says so instead of hiding a
        # window in front of nothing.
        app.dot = overlay_mod.StatusDot.off()
        refused = control_mod.send("dot", do="move")
        assert refused["ok"] is False and "no dot" in refused["error"], \
            refused
    finally:
        server.stop()
        restore()


def test_move_mode_expires_and_a_drop_writes_one_pair_of_lines() -> None:
    """The dot's half of "the desk disappears".

    move() is a DEADLINE, not a flag, because the window that hid itself
    to let him drag is in another process: if he presses the button and
    walks away, something has to end the wait, and this is it. A drop
    writes x and y together — config.load refuses half a position — and
    "Back to the corner" writes the sentinel back into both.
    """
    saved: list = []
    d = overlay_mod.StatusDot(on_change=saved.append)
    assert d.moving() is False and d.dragged() is False
    assert d.move() is False, "there is nothing to drag before it starts"
    d._thread = threading.current_thread()          # pretend it is up
    assert d.move(seconds=30) is True and d.moving() is True
    d.rest()
    assert d.moving() is False, "rest() ends it at once"
    # It is a deadline on the monotonic clock, so it runs out by itself —
    # checked by moving the deadline rather than by sleeping through it,
    # since the floor is a whole second and a suite does not need to wait
    # one out to know what a deadline is.
    d.move(seconds=0.01)
    assert d.moving() is True
    assert d._move_until - time.monotonic() > 0.5, \
        "a deadline shorter than a second is not one anybody could use"
    d._move_until = time.monotonic() - 0.01
    assert d.moving() is False, "move mode has to expire on its own"

    d.placed(1204, 388)
    assert (d.x, d.y) == (1204, 388) and d.dragged()
    assert d._replace.is_set(), "the painter is told to go there"
    d._replace.clear()
    d.placed(1204, 388)                             # the same drop again
    assert saved == [{"x": 1204, "y": 388}], (
        "a release arrives as more than one message and this writes a file")
    assert d._replace.is_set() is False
    d.to_corner()
    assert d.dragged() is False and d.state()["dragged"] is False
    assert saved[-1] == {"x": overlay_mod.HINT_UNSET,
                         "y": overlay_mod.HINT_UNSET}, saved
    d.to_corner()                                   # already home
    assert len(saved) == 2, saved
    # a config.toml that cannot be written must never kill the painter
    boom = overlay_mod.StatusDot(
        on_change=lambda _f: (_ for _ in ()).throw(OSError("read-only")))
    boom.placed(10, 20)
    assert (boom.x, boom.y) == (10, 20)

    # main.py: the command, the save, and the state on the status poll
    import main as main_mod
    app = main_mod.App.__new__(main_mod.App)
    app.cfg = config_mod.load(Path(sys.path[0]) / "defaults.toml")
    app.config_path = Path(sys.path[0]) / "defaults.toml"
    app.dot = overlay_mod.StatusDot(on_change=app._save_dot)
    app.dot._thread = threading.current_thread()
    app._say = lambda *a, **k: None
    written: list = []
    real = config_mod.set_values
    main_mod.config_mod.set_values = lambda path, updates: written.append(
        dict(updates))
    try:
        reply = app.control_command("dot", {"do": "move"})
        assert reply["ok"] and reply["dot"]["moving"] is True, reply
        app.dot.placed(640, 210)
        assert written == [{"dot.x": 640, "dot.y": 210}], written
        assert app.cfg.dot.x == 640, "the live Config has to move too"
        reply = app.control_command("dot", {"do": "corner"})
        assert reply["ok"] and reply["dot"]["dragged"] is False, reply
        assert written[-1] == {"dot.x": config_mod.HINT_UNSET,
                               "dot.y": config_mod.HINT_UNSET}, written
        bad = app.control_command("dot", {"do": "sideways"})
        assert bad["ok"] is False and "sideways" in bad["error"], bad
    finally:
        main_mod.config_mod.set_values = real
    # a [dot] with nowhere to put x and y keeps the drag for this run
    # rather than raising on the dot's own thread
    plain = dataclasses.make_dataclass("PlainDot", [("corner", str)],
                                       frozen=True)
    app.cfg = dataclasses.replace(app.cfg, dot=plain("bottom-right"))
    app._save_dot({"x": 1, "y": 2})              # must not raise


def test_the_shelf_closes_when_he_presses_somewhere_else() -> None:
    """The fifth door, and the trap it had to be written around.

    The owner, 2026-09-07: "when I press the dot and the screen opens — I
    want that if I press outside of it, like on Google or something, the
    small tab that opens when I press the dot will disappear, so I will
    not need to press the dot again or the X."

    A press on the DOT is a press outside the panel and the dot is
    already a toggle, so seeing it as away would close the panel and let
    the dot reopen it in the same gesture. The panel's own buttons need
    no exception at all — they are inside its rect.
    """
    import shelf as shelf_mod

    panel = (100, 200, 400, 700)
    dot = (2514, 1350, 2552, 1388)
    # the panel itself, and every button on it, is not away
    for at in ((100, 200), (250, 450), (400, 700), (390, 690)):
        assert shelf_mod.away_from(at, panel, [dot]) is False, at
    # the dot is spared by name
    for at in ((2514, 1350), (2533, 1369), (2552, 1388)):
        assert shelf_mod.away_from(at, panel, [dot]) is False, at
    # and everything else is away — including the shadow margin just
    # outside the panel, which is click-through anyway
    for at in ((99, 200), (401, 700), (960, 540), (-1200, 300)):
        assert shelf_mod.away_from(at, panel, [dot]) is True, at
        assert shelf_mod.away_from(at, panel) is True, at
    # nothing on screen: nothing to close. That is also what a HUSHED
    # panel looks like — the screenshot selector is up and the press is
    # somebody dragging a selection.
    assert shelf_mod.away_from((960, 540), None, [dot]) is False
    assert shelf_mod.away_from((960, 540), panel, [None]) is True

    # the watcher is armed on start and asks about the two buttons that
    # mean "I am doing something over there"
    assert shelf_mod.AWAY_BUTTONS == (0x01, 0x02), shelf_mod.AWAY_BUTTONS
    assert 0 < shelf_mod.AWAY_S <= 0.05, shelf_mod.AWAY_S
    closed: list = []
    card = shelf_mod.ShelfCard(on_away=lambda: closed.append("away"),
                               spare=lambda: [dot])
    assert card._on_away is not None and card._spare() == [dot]

    # main.py wires it to the same door the key, Esc and the X use, and
    # spares the dot's own square
    import main as main_mod
    src = (Path(__file__).resolve().parent / "main.py").read_text("utf-8")
    assert src.count("on_away=self._shelf_close") == 2, \
        "both places that build the shelf have to arm the fifth door"
    assert src.count("spare=self._dot_squares") == 2
    app = main_mod.App.__new__(main_mod.App)
    app.dot = overlay_mod.StatusDot()
    assert app._dot_squares() == [], "no dot on screen, nothing to spare"
    app.dot.rect = dot
    assert app._dot_squares() == [dot]


def test_a_saved_card_position_keeps_every_comment_in_the_config() -> None:
    """It is written from the overlay thread on every drag, so this is the
    line-editor's most frequent caller — a round-trip here would quietly
    delete the measurements the file is made of."""
    import shutil

    tmp = Path(tempfile.mkdtemp(prefix="dictation-hint-save-"))
    try:
        path = tmp / "config.toml"
        base = (Path(__file__).resolve().parent / "defaults.toml"
                ).read_text("utf-8")
        path.write_text(base, "utf-8")
        before = base.count("#")
        config_mod.set_values(path, {"hint.x": 640, "hint.y": 210,
                                     "hint.scale": 0.8})
        after = path.read_text("utf-8")
        assert after.count("#") == before, "comments were lost"
        cfg = config_mod.load(path)
        assert (cfg.hint.x, cfg.hint.y) == (640, 210), cfg.hint
        assert cfg.hint.scale == 0.8, cfg.hint
        config_mod.set_values(path, {"hint.enabled": False})
        assert config_mod.load(path).hint.enabled is False
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


