def test_the_awake_section_is_in_the_real_config_and_bounded() -> None:
    """The file is the Settings screen's list, so the section has to be
    IN the file, not only in the dataclass defaults — and the hold is on
    by default, because the requirement is "never"."""
    import settings as settings_mod

    here = Path(__file__).resolve().parent
    cfg = config_mod.load(here / "defaults.toml")
    assert cfg.awake.hold is True, "the machine must never sleep"
    assert cfg.awake.enabled is True
    assert cfg.awake.pin_timeouts is False, "off by default, on purpose"
    assert cfg.awake.screens_off_again_s == 3
    assert cfg.awake.keep_screens_off_s == 10
    assert cfg.awake.vitals_minutes == 10
    sections = {s.name: s for s in settings_mod.read(here / "defaults.toml")}
    assert "awake" in sections, sorted(sections)
    assert "night" not in sections, "the old section is still in the file"
    keys = {s.key for s in sections["awake"].settings}
    assert keys == {"hold", "enabled", "screens_hotkey", "pin_timeouts",
                    "screens_off_again_s", "keep_screens_off_s",
                    "vitals_minutes"}, keys
    assert sections["awake"].help, "the section has no help text"
    with tempfile.TemporaryDirectory() as d:
        p = Path(d) / "config.toml"
        p.write_text('[awake]\nscreens_off_again_s = 999\n', "utf-8")
        try:
            config_mod.load(p)
        except config_mod.ConfigError as e:
            assert "screens_off_again_s" in str(e), e
        else:
            raise AssertionError("a 999 s repeat was accepted")


class _FakePowercfg:
    """powercfg as a dict: /query answers from it, /change writes it."""

    def __init__(self, standby: int = 30, hibernate: int = 0) -> None:
        self.values = {"STANDBYIDLE": standby * 60,
                       "HIBERNATEIDLE": hibernate * 60}
        self.calls: list[list[str]] = []

    def __call__(self, args, timeout=15):
        self.calls.append(list(args))
        if args[0] == "/query":
            secs = self.values[args[-1]]
            return 0, (f"    Current AC Power Setting Index: 0x{secs:08x}\n"
                       f"    Current DC Power Setting Index: 0x00000000\n")
        if args[0] == "/change":
            key = {"standby-timeout-ac": "STANDBYIDLE",
                   "hibernate-timeout-ac": "HIBERNATEIDLE"}[args[1]]
            self.values[key] = int(args[2]) * 60
            return 0, ""
        if args[0] == "/requests":
            return 1, "This command requires administrator privileges"
        if args[0] == "/a":
            return 0, ("The following sleep states are available on this "
                       "system:\n    Standby (S3)\n    Hibernate\n"
                       "The following sleep states are not available on "
                       "this system:\n    Standby (S0 Low Power Idle)\n")
        return 1, "unknown"


def _awake_until(cond, timeout: float = 2.0) -> None:
    """The engine hands its broadcasts to threads; wait for one, briefly."""
    deadline = time.monotonic() + timeout
    while not cond() and time.monotonic() < deadline:
        time.sleep(0.02)


def test_the_hold_goes_up_on_a_thread_and_comes_down_on_release() -> None:
    """The execution state is per thread and dies with it (the spec's
    warning), so the hold is a thread that makes the call and waits.
    hold() asks for CONTINUOUS|SYSTEM_REQUIRED and leaves the thread
    standing; release() lets go with CONTINUOUS alone and the thread
    ends. The marker file exists exactly while it is up — and the
    screens are not touched by either."""
    import awake as awake_mod

    calls: list[tuple[int, str]] = []
    def setter(flags: int) -> int:
        calls.append((flags, threading.current_thread().name))
        return 0x80000000            # "previously: continuous only"
    sent: list[int] = []
    with tempfile.TemporaryDirectory() as d:
        eng = awake_mod.Engine(Path(d), None,
                               hold_factory=lambda: awake_mod.Hold(setter=setter),
                               sender=lambda s: sent.append(s) or True,
                               run=_FakePowercfg())
        assert eng.hold_wanted, "the hold is on by default"
        assert not eng.holding and eng.state()["holding"] is False
        state = eng.hold(by="test")
        assert state["holding"] and state["held"], state
        assert not state["dark"], "the hold does not touch the screens"
        assert calls == [(awake_mod.ES_CONTINUOUS
                          | awake_mod.ES_SYSTEM_REQUIRED, "awake-hold")], calls
        assert awake_mod.ES_DISPLAY_REQUIRED & calls[0][0] == 0, \
            "the screens must be allowed to go off"
        assert (Path(d) / awake_mod.STATE_NAME).exists(), "no marker file"
        marker = json.loads((Path(d) / awake_mod.STATE_NAME).read_text("utf-8"))
        assert marker["by"] == "test" and marker["pid"] == os.getpid()
        assert marker["saved"] is None, "timers are not pinned by default"
        time.sleep(0.2)
        assert sent == [], "hold() must not broadcast to the screens"
        eng.hold(by="test")                       # a second hold does not stack
        assert len(calls) == 1
        eng.release()
        assert not eng.holding and eng.state()["holding"] is False
        assert calls[-1][0] == awake_mod.ES_CONTINUOUS, calls
        assert calls[-1][1] == "awake-hold", "released on the holding thread"
        assert not (Path(d) / awake_mod.STATE_NAME).exists(), "marker left"
        record = (Path(d) / awake_mod.LOG_NAME).read_text("utf-8")
        assert "| HOLD by test" in record and "| RELEASE |" in record, record
        eng.release()                             # twice is fine
        assert sent == []


def test_the_screens_go_off_and_come_back_without_touching_the_hold() -> None:
    """darken() broadcasts MONITOR_OFF, lighten() MONITOR_ON, toggle()
    alternates, a second darken() puts them out again — and none of it
    starts or stops the hold. The delayed second MONITOR_OFF (for the
    click's mouse movement) stays home if the screens were brought back
    in the meantime."""
    import awake as awake_mod

    calls: list[int] = []
    sent: list[int] = []
    with tempfile.TemporaryDirectory() as d:
        eng = awake_mod.Engine(Path(d), None,
                               hold_factory=lambda: awake_mod.Hold(
                                   setter=lambda f: calls.append(f) or 0x80000000),
                               sender=lambda s: sent.append(s) or True,
                               run=_FakePowercfg())
        eng.again_s = 0
        eng.vitals_minutes = 0
        eng.keep_off_s = 0
        eng.hold(by="start")
        state = eng.darken(by="test")
        assert state["dark"] and state["holding"] and state["by"] == "test", state
        _awake_until(lambda: len(sent) == 1)
        assert sent == [awake_mod.MONITOR_OFF], sent
        eng.darken(by="test")                     # again: out again, not back
        _awake_until(lambda: len(sent) == 2)
        assert sent == [awake_mod.MONITOR_OFF] * 2 and eng.dark
        state = eng.toggle(by="key")
        assert not state["dark"] and state["holding"], state
        _awake_until(lambda: len(sent) == 3)
        assert sent[-1] == awake_mod.MONITOR_ON, sent
        assert len(calls) == 1, "the screens must not touch the hold"
        assert eng.toggle(by="key")["dark"]
        eng.lighten(by="test")
        assert eng.lighten(by="test")["dark"] is False, "lighten twice is fine"
        record = (Path(d) / awake_mod.LOG_NAME).read_text("utf-8")
        assert "| SCREENS OFF by test" in record, record
        assert "| SCREENS ON by key" in record, record
        assert eng.holding, "still held"
        # The delayed repeat, and the race it must lose. Every broadcast
        # is a thread of its own, so the five above are waited for before
        # the list is cleared: on a hosted runner (2026-09-18) the last
        # two landed after the clear and were counted as the repeat.
        _awake_until(lambda: len(sent) == 5)
        assert (sent.count(awake_mod.MONITOR_OFF) == 3
                and sent.count(awake_mod.MONITOR_ON) == 2), sent
        sent.clear()
        eng.again_s = 1
        eng.darken(by="test")
        _awake_until(lambda: len(sent) == 1)
        eng.lighten(by="test")
        time.sleep(1.4)
        assert sent.count(awake_mod.MONITOR_OFF) == 1, \
            f"the second broadcast fired after the screens came back: {sent}"
        eng.release()
        assert not eng.holding and not eng.dark


def test_the_process_list_sees_the_processes_it_cannot_open() -> None:
    """The ntdll list, not OpenProcess. THE point of it: a service
    running as SYSTEM is refused to a non-elevated OpenProcess, and a
    leak is exactly where such a process needs naming (2026-09-03:
    nvcontainer.exe, 823,369 handles of the machine's 988,258, invisible
    to the first implementation of this).

    Cross-checked against ntdll's own machine-wide counters rather than
    a hard-coded name: the sum of the per-process handles has to land
    near GetPerformanceInfo's total, which is computed by the kernel by
    a different route. Windows itself is the fixture."""
    import awake as awake_mod

    procs = awake_mod.processes()
    assert len(procs) > 50, f"only {len(procs)} processes"
    assert all(name and ws >= 0 and commit >= 0 and handles >= 0
               for name, ws, commit, handles in procs), procs[:5]
    # The kernel counted the same handles a different way, and a moment
    # later: whatever started or exited in between moves the number. Ten
    # per cent is the room — measured 3.6 % on the owner's machine
    # (nightly.KNOWN_FLAKES, 2026-09-08) and 5.2 % on a hosted runner
    # (2026-09-18), against the 83 % the OpenProcess bug lost.
    total = sum(handles for _n, _w, _c, handles in procs)
    v = awake_mod.vitals(gpu=False)
    assert abs(total - v["handles"]) < max(4000, v["handles"] // 10), \
        f"per-process sum {total} vs machine total {v['handles']}"
    # And the biggest holder is what the line names.
    biggest = max(procs, key=lambda r: r[3])
    assert v["handles_top"][1] >= biggest[3] // 2, (v["handles_top"], biggest)
    # A process this test can definitely not open, present on every
    # Windows: the kernel itself, pid 4, which has no image name.
    assert any(name == "System" for name, _w, _c, _h in procs), \
        "the ntdll list is missing pid 4 — this is the OpenProcess bug again"


def test_the_vitals_read_this_machine_without_a_subprocess() -> None:
    """vitals() is Win32 through ctypes: RAM, commit, the non-paged pool,
    this process, the heaviest programs by image. The GPU number is the
    one subprocess and is skipped here; the line renders without it."""
    import awake as awake_mod

    t0 = time.perf_counter()
    v = awake_mod.vitals(top=3, gpu=False)
    took = time.perf_counter() - t0
    assert 0 < v["ram_free"] <= v["ram_total"], v
    assert 0 < v["commit"] <= v["commit_limit"], v
    assert v["nonpaged"] > 0 and v["processes"] > 1, v
    assert 0 < v["self_ws"] and 0 < v["self_private"], v
    assert len(v["top"]) == 3 and all(r[0] and r[1] > 0 for r in v["top"]), v
    assert v["gpu"] is None
    # The name that ends the argument: a total says the machine is full
    # of handles, not whose they are (2026-09-03: nvcontainer, 812,918).
    name, count = v["handles_top"]
    assert name and 0 < count <= v["handles"], v["handles_top"]
    assert took < 2.0, f"vitals took {took:.2f} s"
    line = awake_mod.vitals_line(v)
    assert "RAM free" in line and "commit" in line and "heaviest" in line, line
    assert f"{name} holds {count}" in line, line
    assert "GPU" not in line, line
    assert "GPU 5.8 of 15.9 GB" in awake_mod.vitals_line(
        {"gpu": (5903 << 20, 16311 << 20)}), "GiB, like nvidia-smi"
    assert "this app 0.05 GB in RAM" in awake_mod.vitals_line(
        {"self_ws": 50 << 20, "self_private": 3 << 30}), \
        "two decimals under a gigabyte, or a 50 MB process reads as 0.0"


def test_the_screens_off_write_the_vitals_on_the_way_in_and_out() -> None:
    """One line when the screens go off, one every vitals_minutes, one
    when they come back — the record of the time away. The reader is
    injected: the test is about the log, not the machine."""
    import awake as awake_mod

    reads: list[float] = []
    def fake_vitals() -> str:
        reads.append(time.monotonic())
        return f"fake vitals {len(reads)}"
    with tempfile.TemporaryDirectory() as d:
        eng = awake_mod.Engine(Path(d), None,
                               hold_factory=lambda: awake_mod.Hold(
                                   setter=lambda flags: 0x80000000),
                               sender=lambda s: True, run=_FakePowercfg(),
                               vitals_fn=fake_vitals)
        eng.again_s = 0
        eng.keep_off_s = 0
        eng.vitals_minutes = 0
        eng.hold(by="start")
        eng.darken(by="test")
        time.sleep(0.3)
        eng.lighten(by="test")
        time.sleep(0.3)
        assert not reads, "vitals_minutes = 0 must mean no reads at all"
        record = (Path(d) / awake_mod.LOG_NAME).read_text("utf-8")
        assert "vitals" not in record, record

        eng.vitals_minutes = 1
        eng.darken(by="test")
        _awake_until(lambda: len(reads) >= 1)
        eng.lighten(by="test")
        _awake_until(lambda: len(reads) >= 2)
        time.sleep(0.1)
        record = (Path(d) / awake_mod.LOG_NAME).read_text("utf-8")
        assert "|   vitals | screens off: fake vitals 1" in record, record
        assert "|   vitals | screens on: fake vitals 2" in record, record
        on_at = record.index("screens off: fake")
        off_line = record.rindex("| SCREENS ON by test")   # the second cycle's
        assert on_at < off_line < record.index("screens on: fake"), \
            "the coming-back snapshot must follow the SCREENS ON line"
        assert len(reads) == 2, \
            "inside a minute only the two edge snapshots may land"
        eng.release()


def test_the_vitals_watch_spans_the_hold_and_the_alarms_shout() -> None:
    """The watch belongs to the hold, not to the screens. It goes up with
    hold() in broad daylight — the leak measured on 2026-09-03 crawled
    this machine all afternoon with the screens ON, and the one log that
    would have named it only ran at night — and it comes down with
    release(). And a number out of range is no longer merely recorded: it
    gets an ALARM line of its own, with the cure written into it."""
    import awake as awake_mod

    gb = 1 << 30
    healthy = {"commit": 10 * gb, "commit_limit": 44 * gb,
               "nonpaged": 0.9 * gb, "handles_top": ("svchost", 39_100)}
    assert awake_mod.alarms(healthy) == [], awake_mod.alarms(healthy)

    # The real numbers off this machine, 2026-09-03, while it crawled.
    sick = {"commit": 48 * gb, "commit_limit": 50 * gb,
            "nonpaged": 2.47 * gb,
            "handles_top": ("nvcontainer.exe", 825_247)}
    said = awake_mod.alarms(sick)
    assert len(said) == 3, said
    assert "nvcontainer.exe holds 825,247 handles" in said[0], said[0]
    assert "without a reboot" in said[0], said[0]
    assert "non-paged pool 2.5 GB" in said[1], said[1]
    assert "96% of the limit" in said[2], said[2]

    # Each threshold stands alone: no single number may hide behind the
    # other two being fine, which is exactly how this one was missed.
    for key, value in (("handles_top", ("nvcontainer.exe", 825_247)),
                       ("nonpaged", 2.47 * gb),
                       ("commit", 40 * gb)):
        alone = dict(healthy)
        alone[key] = value
        assert len(awake_mod.alarms(alone)) == 1, (key,
                                                   awake_mod.alarms(alone))

    reads: list[int] = []
    def fake_vitals() -> str:
        reads.append(len(reads))
        return "fake vitals"
    with tempfile.TemporaryDirectory() as d:
        eng = awake_mod.Engine(Path(d), None,
                               hold_factory=lambda: awake_mod.Hold(
                                   setter=lambda flags: 0x80000000),
                               sender=lambda s: True, run=_FakePowercfg(),
                               vitals_fn=fake_vitals,
                               alarms_fn=lambda: ["the pool is 2.5 GB"])
        eng.again_s = 0
        eng.keep_off_s = 0
        eng.vitals_minutes = 1
        assert not eng._vitals_watching, "nothing watches before the hold"
        eng.hold(by="start")
        assert eng._vitals_watching, \
            "the watch must go up with the hold, screens lit or not"
        eng.darken(by="test")
        _awake_until(lambda: len(reads) >= 1)
        eng.lighten(by="test")
        assert eng._vitals_watching, \
            "the screens coming back must not end the watch"
        eng.release()
        assert not eng._vitals_watching, "release() is what ends it"
        record = (Path(d) / awake_mod.LOG_NAME).read_text("utf-8")
        assert "|   ALARM | the pool is 2.5 GB" in record, record


def test_the_screens_stay_off_after_input_lights_them() -> None:
    """[awake] keep_screens_off_s: anything that touches the machine
    lights the screens, and that many seconds after the LAST touch they
    are put out again — for as long as the key says, the owner at the
    keyboard included. The input clock is injected: nothing here moves
    the real mouse, and an untouched machine gets no broadcast at all."""
    import awake as awake_mod

    real = awake_mod.last_input()
    assert 0 < real <= time.monotonic(), real
    touched = [0.0]                       # monotonic time of the last input
    sent: list[tuple[int, float]] = []
    def sender(state: int) -> bool:
        sent.append((state, time.monotonic()))
        return True
    with tempfile.TemporaryDirectory() as d:
        eng = awake_mod.Engine(Path(d), None,
                               hold_factory=lambda: awake_mod.Hold(
                                   setter=lambda flags: 0x80000000),
                               sender=sender, run=_FakePowercfg(),
                               input_fn=lambda: touched[0])
        eng.again_s = 0
        eng.vitals_minutes = 0
        eng.keep_off_s = 0
        eng.hold(by="start")
        eng.darken(by="test")
        time.sleep(0.4)
        assert [s for s, _t in sent] == [awake_mod.MONITOR_OFF], \
            "0 must mean the one broadcast only"
        eng.lighten(by="test")
        _awake_until(lambda: len(sent) == 2)      # the MONITOR_ON

        sent.clear()
        eng.keep_off_s = 0.2
        touched[0] = time.monotonic()     # the key that put them out
        eng.darken(by="test")
        assert eng.state()["keep_screens_off_s"] == 0.2
        _awake_until(lambda: bool(sent))
        time.sleep(0.6)
        assert [s for s, _t in sent] == [awake_mod.MONITOR_OFF], \
            "an untouched machine gets no second broadcast"
        touched[0] = time.monotonic()     # the mouse, or a click from the phone
        _awake_until(lambda: len(sent) >= 2)
        assert [s for s, _t in sent] == [awake_mod.MONITOR_OFF] * 2, sent
        assert sent[1][1] - touched[0] >= 0.2, "put out before it was still"
        # The worker broadcasts first and writes the line after
        # (_keep_off_worker), so the broadcast is not the moment to read
        # the log: a hosted runner (2026-09-18) got here between the two
        # and found the record one line short. Wait for the line itself.
        log_path = Path(d) / awake_mod.LOG_NAME

        def _record() -> str:
            # Polled while the worker writes: a hosted runner (run
            # 35400575383) hit WinError 32 on the read mid-write. Nothing
            # yet, then, and the next poll reads the finished line.
            try:
                return log_path.read_text("utf-8")
            except (PermissionError, FileNotFoundError):
                return ""
        _awake_until(lambda: "screens lit by input, put out again" in _record())
        record = _record()
        assert "screens lit by input, put out again" in record, record
        eng.lighten(by="test")
        touched[0] = time.monotonic()     # the key that brought them back
        time.sleep(0.6)
        assert [s for s, _t in sent].count(awake_mod.MONITOR_OFF) == 2, \
            "lighten() must stop the watchdog"
        eng.release()


def test_a_hold_refused_by_windows_is_reported_not_pretended() -> None:
    import dataclasses

    import awake as awake_mod

    with tempfile.TemporaryDirectory() as d:
        eng = awake_mod.Engine(Path(d), None,
                               hold_factory=lambda: awake_mod.Hold(
                                   setter=lambda flags: 0),
                               sender=lambda s: True, run=_FakePowercfg())
        state = eng.hold(by="test")
        assert state.get("ok") is False and "refused" in state["error"], state
        assert not eng.holding
        assert not (Path(d) / awake_mod.STATE_NAME).exists()
        # The screens still work without a hold, and the log says so.
        eng.again_s = 0
        eng.vitals_minutes = 0
        eng.keep_off_s = 0
        assert eng.darken(by="test")["dark"]
        assert "NOT holding" in (Path(d) / awake_mod.LOG_NAME).read_text("utf-8")
        eng.lighten(by="test")
    quiet = awake_mod.Engine(Path(d), dataclasses.replace(
        config_mod.AwakeConfig(), hold=False))
    assert quiet.hold_wanted is False, "[awake] hold = false must be honoured"


def test_the_hold_pins_the_timers_and_puts_them_back() -> None:
    """[awake] pin_timeouts: read, save, set to never, restore — and the
    saved numbers are in the marker file, which is what recover() reads
    when the app did not live to restore them itself."""
    import dataclasses

    import awake as awake_mod

    cfg = dataclasses.replace(config_mod.AwakeConfig(), pin_timeouts=True,
                              screens_off_again_s=0)
    fake = _FakePowercfg(standby=30, hibernate=0)
    with tempfile.TemporaryDirectory() as d:
        eng = awake_mod.Engine(Path(d), cfg,
                               hold_factory=lambda: awake_mod.Hold(
                                   setter=lambda flags: 1),
                               sender=lambda s: True, run=fake)
        eng.hold(by="test")
        assert fake.values == {"STANDBYIDLE": 0, "HIBERNATEIDLE": 0}, fake.values
        marker = json.loads((Path(d) / awake_mod.STATE_NAME).read_text("utf-8"))
        assert marker["saved"] == {"standby_ac": 30, "hibernate_ac": 0}, marker
        assert eng.state()["pinned"] is True
        eng.release()
        assert fake.values == {"STANDBYIDLE": 1800, "HIBERNATEIDLE": 0}, \
            fake.values
        assert eng.state()["pinned"] is False
        assert not (Path(d) / awake_mod.STATE_NAME).exists(), "marker left"
        record = (Path(d) / awake_mod.LOG_NAME).read_text("utf-8")
        assert "pinned to never" in record and "timers restored" in record, record


def test_a_leftover_awake_marker_is_recovered_at_the_next_start() -> None:
    """A session that died holding with the timers pinned: the hold went
    with it, the pinned timers did not. recover() puts them back from
    the marker, removes it, and writes what it did."""
    import awake as awake_mod

    with tempfile.TemporaryDirectory() as d:
        assert awake_mod.recover(Path(d)) is None, "nothing to recover"
        fake = _FakePowercfg(standby=0, hibernate=0)      # as it was left
        (Path(d) / awake_mod.STATE_NAME).write_text(json.dumps(
            {"since": 1.0, "since_text": "2026-09-02 23:00:00", "pid": 1,
             "by": "start", "saved": {"standby_ac": 30, "hibernate_ac": 0}}),
            "utf-8")
        message = awake_mod.recover(Path(d), run=fake)
        assert message and "restored" in message, message
        assert fake.values == {"STANDBYIDLE": 1800, "HIBERNATEIDLE": 0}, \
            fake.values
        assert not (Path(d) / awake_mod.STATE_NAME).exists(), "marker left"
        assert "RECOVERED" in (Path(d) / awake_mod.LOG_NAME).read_text("utf-8")
        # A marker with nothing saved is cleaned up and says so.
        (Path(d) / awake_mod.STATE_NAME).write_text('{"saved": null}', "utf-8")
        fake.calls.clear()
        message = awake_mod.recover(Path(d), run=fake)
        assert "nothing to restore" in message, message
        assert fake.calls == [], fake.calls


def test_the_screens_command_goes_through_the_control_channel() -> None:
    """The dashboard's button is one pipe message; the reply carries the
    state so the button can repaint without waiting for a poll. And the
    hold is wired to the app's own start and stop, not to any command."""
    import inspect

    import main as main_mod
    import awake as awake_mod

    assert 'self.awake.hold(by="start")' in inspect.getsource(main_mod.App.start)
    assert "self.awake.release()" in inspect.getsource(main_mod.App.stop)
    with tempfile.TemporaryDirectory() as d:
        app = main_mod.App.__new__(main_mod.App)
        app._note = ""
        sent: list[int] = []
        app.awake = awake_mod.Engine(
            Path(d), None,
            hold_factory=lambda: awake_mod.Hold(setter=lambda f: 1),
            sender=lambda s: sent.append(s) or True, run=_FakePowercfg())
        app.awake.again_s = 0
        app.awake.vitals_minutes = 0
        app.awake.keep_off_s = 0
        app.awake.hold(by="start")
        reply = app.control_command("screens", {"do": "off"})
        assert reply["ok"] and reply["awake"]["dark"], reply
        assert reply["awake"]["holding"], "the command must not touch the hold"
        assert "screens off" in app._note, app._note
        reply = app.control_command("screens", {"do": "again"})
        assert reply["ok"] and "screens off again" in reply["message"], reply
        reply = app.control_command("screens", {"do": "toggle"})
        assert reply["ok"] and not reply["awake"]["dark"], reply
        assert "screens on" in app._note, app._note
        reply = app.control_command("screens", {"do": "on"})
        assert reply["ok"] and not reply["awake"]["dark"], "on when on is fine"
        reply = app.control_command("screens", {"do": "sideways"})
        assert not reply["ok"] and "sideways" in reply["error"], reply
        assert not app.awake.dark and app.awake.holding
        app.awake.release()


def test_hours_cover_night_reads_a_window_that_wraps_midnight() -> None:
    import awake as awake_mod

    assert awake_mod.hours_cover_night((9, 2)) is False       # this machine
    assert awake_mod.hours_cover_night((16, 10)) is True
    assert awake_mod.hours_cover_night((22, 8)) is True
    assert awake_mod.hours_cover_night((23, 7)) is True
    assert awake_mod.hours_cover_night((0, 0)) is False
    assert awake_mod.hours_cover_night(None) is None


def test_the_verdict_names_what_can_lose_the_machine_while_away() -> None:
    """Every row the spec lists as a way to be awake and unreachable, in
    words that say what to do, with a tone the screen can colour. The
    hold row reads the HOLD, not the screens: a machine with its screens
    on and the hold standing is fine, one with nothing holding is not."""
    import awake as awake_mod

    probe = {"system_required": True, "display_required": False,
             "requests": None, "standby": "S3",
             "timeouts": {"standby_ac": 30, "hibernate_ac": 0},
             "adapters": [{"name": "Ethernet", "up": True, "saving": True}],
             "active_hours": (9, 2), "claude": 0}
    held = {"holding": True, "held": True, "dark": False}
    rows = {label: (text, tone) for label, text, tone in
            awake_mod.verdict(held, probe)}
    assert rows["Sleep hold"][1] == "good", rows["Sleep hold"]
    assert "administrator" in rows["powercfg /requests"][0]
    assert rows["Sleep after (plugged in)"][1] == "good"
    assert "30 min" in rows["Sleep after (plugged in)"][0]
    assert rows["Standby type"][1] == "good"
    assert rows["Network adapter"][1] == "warn"
    assert "Device Manager" in rows["Network adapter"][0]
    assert rows["Update active hours"][1] == "warn"
    assert "09:00–02:00" in rows["Update active hours"][0]
    assert rows["Claude"][1] == "warn"
    # Nothing holding, and the kernel agrees: the hold row and the timer
    # row both turn amber — this machine WILL sleep.
    probe["system_required"] = False
    rows = {label: tone for label, _text, tone in
            awake_mod.verdict({"holding": False, "held": False}, probe)}
    assert rows["Sleep after (plugged in)"] == "warn", rows
    assert rows["Sleep hold"] == "warn", rows
    # Nothing holding here, but another program is: dim, not amber.
    probe["system_required"] = True
    rows = {label: (text, tone) for label, text, tone in
            awake_mod.verdict({}, probe)}
    assert rows["Sleep hold"][1] == "dim" and "another program" in \
        rows["Sleep hold"][0], rows["Sleep hold"]
    # Asked, but the hold is not standing: red, in words.
    rows = {label: (text, tone) for label, text, tone in
            awake_mod.verdict({"holding": True, "held": False}, probe)}
    assert rows["Sleep hold"][1] == "bad", rows["Sleep hold"]
    # Everything right — with the screens off or on, it makes no difference.
    probe.update(system_required=True, adapters=[{"name": "Ethernet",
                                                   "up": True,
                                                   "saving": False}],
                 active_hours=(16, 10), claude=3)
    for dark in (False, True):
        tones = {tone for _l, _t, tone in
                 awake_mod.verdict({**held, "dark": dark}, probe)}
        assert "warn" not in tones and "bad" not in tones, (dark, tones)


def test_the_screen_broadcast_returns_and_reads_the_kernel_state() -> None:
    """The real APIs, harmlessly: MONITOR_ON is a no-op on a lit screen,
    and the timeout is what stops a hung window from hanging us."""
    import awake as awake_mod

    t0 = time.perf_counter()
    ok = awake_mod.send_monitor_power(awake_mod.MONITOR_ON, timeout_ms=1500)
    took = time.perf_counter() - t0
    assert isinstance(ok, bool)
    assert took < 20, f"the broadcast took {took:.1f} s"
    flags = awake_mod.system_execution_state()
    assert flags is None or isinstance(flags, int), flags
    assert awake_mod.read_timeouts().get("standby_ac") is not None, \
        "powercfg /query could not be read on this machine"


def test_the_dashboard_has_an_awake_block_that_waits_for_the_app() -> None:
    """Awake was a rail row; it is a block on the Settings place now,
    because it is not somewhere you go — it is a thing you check and
    occasionally flip. Everything it registered is registered still.

    With nothing running the switch is disabled and the hint says why;
    the check works regardless, and its rows land on the screen. With
    the app running the hero reads the HOLD, and the switch the SCREENS."""
    import dashboard as dash
    import awake as awake_mod
    import settings as settings_mod

    saved = dash.AWAKE_AUTO_CHECK
    dash.AWAKE_AUTO_CHECK = False
    try:
        with _window() as board:
            if board is None:
                return
            board._show("Settings")
            board._settings_go(settings_mod.APP)   # the blocks live there
            board._finish_settings()
            p = board.parts
            for name in ("awake_toggle", "awake_screen", "awake_check",
                         "awake_rows", "awake_state"):
                assert name in p, name
            assert not p["awake_toggle"]._enabled, "on with nothing running"
            assert not p["awake_screen"]._enabled
            assert p["awake_check"]._enabled, "the check needs no app"
            assert "NOT RUNNING" in p["awake_state"].cget("text")
            assert "start dictation" in p["awake_hint"].cget("text")
            board._awake_checked({
                "system_required": False, "requests": None, "standby": "S3",
                "timeouts": {"standby_ac": 30}, "adapters": [],
                "active_hours": (9, 2), "claude": 2})
            rows = p["awake_rows"].winfo_children()
            assert len(rows) == len(awake_mod.verdict({}, board._awake_probe)), \
                len(rows)
            assert "checked" in p["awake_checked"].cget("text")
            # A running app, holding, screens on: AWAKE, and the switch
            # offers to put the screens off.
            board.running = True
            now = time.time()
            board.status = {"stage": "running", "awake": {
                "holding": True, "held": True, "hold_since": now - 3600,
                "hold_seconds": 3600, "dark": False, "since": None,
                "seconds": 0, "pinned": False, "keep_screens_off_s": 10}}
            board._paint_awake()
            assert p["awake_state"].cget("text") == "AWAKE"
            assert p["awake_toggle"]._enabled
            assert "held since" in p["awake_meta"].cget("text")
            # Screens off: the hero says so and the meta keeps the hold.
            board.status["awake"].update(dark=True, since=now - 65,
                                         seconds=65, by="key")
            board._paint_awake()
            assert p["awake_state"].cget("text") == "SCREENS OFF"
            meta = p["awake_meta"].cget("text")
            assert "held since" in meta and "screens off for" in meta, meta
            assert "10 s after the last touch" in p["awake_hint"].cget("text")
            # Asked and refused: red, in words.
            board.status["awake"].update(held=False, dark=False)
            board._paint_awake()
            assert p["awake_state"].cget("text") == "NOT HOLDING"
    finally:
        dash.AWAKE_AUTO_CHECK = saved


# ----------------------------------------------------------------- notify
# The notify door (notify.py, notify_card.py, notify_hook.py, the /notify
# route, the card, the dashboard screen). Written 2026-09-03 in three
# parallel packages; helpers above (_window, _skin_or_skip, _awake_until,
# _hint_cfg) are reused, these are the few that were new.
import inspect

REPO = Path(__file__).resolve().parent


class _FakeNotifyCard:
    """Records what the engine asked of it; `visible` follows a flag."""

    def __init__(self) -> None:
        self.shown: list[dict] = []
        self.hidden = 0
        self.up = False

    def start(self) -> None:
        pass

    def stop(self) -> None:
        pass

    def show(self, items) -> None:
        """Records the NEWEST of what it was given. Since 2026-09-04 the
        engine hands the whole live column (notify.Engine.live), newest
        first; a bare dict is what a card from before the stack got, and
        is still accepted so the tolerance can be exercised."""
        if isinstance(items, dict):
            items = [items]
        self.shown.append(dict(items[0]))
        self.up = True

    def hide(self) -> None:
        self.hidden += 1
        self.up = False

    def visible(self) -> bool:
        return self.up

    def hovering(self) -> bool:
        return False

    def on_key(self, vk: int) -> bool:
        return False


def _notify_cfg(**over):
    from types import SimpleNamespace
    # quiet_s = 0 and interrupt = "all" pin the door as it was before
    # 2026-09-05 — every arrival lands at once and rings — so the tests
    # written against that door keep meaning what they meant. The tests
    # of the quiet door say what they want by name.
    base = dict(enabled=True, cue=True, card_seconds=30, remind_every_s=0,
                remind_times=2, coalesce_s=5, quiet_s=0, interrupt="all")
    base.update(over)
    return SimpleNamespace(**base)


def test_a_notification_is_cleaned_truncated_and_never_interpreted() -> None:
    """Everything that arrives is coerced, stripped, cut and defaulted
    into six strings — and nothing in it is ever parsed or formatted."""
    import notify

    try:
        notify.clean([1, 2])
        assert False, "a list is not a notification"
    except ValueError as e:
        assert "JSON object" in str(e), e
    out = notify.clean({"title": "x", "evil": "y", "body": "b"})
    assert set(out) == {"source", "kind", "title", "body", "project",
                        "session", "app", "hwnd", "link"}, sorted(out)
    assert "evil" not in out
    out = notify.clean({"title": "a" * 81})
    assert len(out["title"]) == 80 and out["title"].endswith("…"), out["title"]
    out = notify.clean({"body": "b" * 401})
    assert len(out["body"]) == 400 and out["body"].endswith("…")
    assert notify.clean({"kind": "boom"})["kind"] == "info"
    assert notify.clean({"kind": "done"})["kind"] == "done"
    assert notify.clean({"title": "a\x07b"})["title"] == "ab"
    assert notify.clean({"title": 5})["title"] == "5"
    assert notify.clean({"title": None, "kind": "input"})["title"] == \
        notify.DEFAULT_TITLE["input"]
    assert notify.clean({})["title"] == "Notification"
    assert notify.clean({"source": "Claude-Code"})["source"] == "claude-code"
    assert notify.clean({})["source"] == "unknown"
    out = notify.clean({"body": "one\n\n\n\nfour   five", "title": "a   b"})
    assert out["body"] == "one\n\nfour   five", out["body"]
    assert out["title"] == "a b"
    assert notify.SOURCES["claude-code"] == "Claude Code"
    assert notify.label_for("claude-code") == "Claude Code"
    assert notify.label_for("x") == "x"


def test_a_notification_can_name_the_window_it_came_from() -> None:
    """A sender may add `hwnd` and `app` so a click on the card can go
    back to it. The title is text like every other field — truncated,
    tidied, never interpreted — and the handle is an int or nothing:
    anything that will not survive int(), and anything negative, is 0,
    which reads downstream as "no window", never as an error."""
    import notify

    out = notify.clean({"title": "t", "hwnd": 43779834, "app": "Claude"})
    assert out["hwnd"] == 43779834 and out["app"] == "Claude", out
    assert notify.clean({"hwnd": "43779834"})["hwnd"] == 43779834, \
        "a decimal string is still a handle"
    for bad in ("Claude", -5, 0, None, {"h": 1}, [1], 1.5e400):
        assert notify.clean({"hwnd": bad})["hwnd"] == 0, bad
    assert notify.clean({})["hwnd"] == 0 and notify.clean({})["app"] == ""
    assert notify.clean({"app": {"a": 1}})["app"] == ""
    long_app = notify.clean({"app": "w" * (notify.APP_MAX + 40)})["app"]
    assert len(long_app) == notify.APP_MAX and long_app.endswith("…")
    assert notify.clean({"app": "  a\x07  b  "})["app"] == "a b"

    with tempfile.TemporaryDirectory() as d:
        store = notify.Store(Path(d) / "notify.json")
        item = store.add(notify.clean({"title": "t", "hwnd": 99,
                                       "app": "Claude"}))
        assert item["hwnd"] == 99 and item["app"] == "Claude", item
        assert store.last()["hwnd"] == 99, "the handle survives the file"
        assert isinstance(store.last()["hwnd"], int), "an int, not a string"
        assert store.add({"title": "t", "hwnd": "junk"})["hwnd"] == 0, \
            "the store cleans a handle it is handed directly"


def test_opening_a_notification_raises_its_window_and_dismisses_it() -> None:
    """A click on the card away from the × is `open()`: raise the newest
    item's window, then do everything dismiss() does. A missing window, a
    closed one, or a raise Windows refuses costs the raise and nothing
    else — the card still goes down and everything is still marked seen,
    because a notification the owner clicked is a notification he read."""
    import notify

    calls: list = []
    real = notify.raise_window
    with tempfile.TemporaryDirectory() as d:
        card = _FakeNotifyCard()
        eng = notify.Engine(Path(d), _notify_cfg(remind_every_s=30,
                                                 remind_times=3),
                            cue=lambda k: None, card=card)
        try:
            notify.raise_window = lambda h: calls.append(h) or True
            eng.receive({"source": "claude-code", "title": "Claude finished",
                         "hwnd": 43779834, "app": "Claude"})
            assert eng.state()["unread"] == 1 and card.up
            assert eng.state()["reminding"] is True, "armed before the click"
            state = eng.open(by="card")
            assert calls == [43779834], calls
            assert state["unread"] == 0 and state["reminding"] is False
            assert card.hidden == 1 and card.up is False
            log_text = (Path(d) / "notify.log").read_text("utf-8")
            assert "OPENED #1 -> Claude (43779834)" in log_text, log_text
            assert "would not come forward" not in log_text
            assert "DISMISSED by card | 1 marked seen" in log_text, log_text
            assert eng.store.last()["seen"] is True

            calls.clear()
            eng.receive({"source": "claude-code", "title": "no window"})
            state = eng.open(by="dashboard")
            assert calls == [], "nothing to raise, so nothing was tried"
            assert state["unread"] == 0 and card.hidden == 2
            log_text = (Path(d) / "notify.log").read_text("utf-8")
            assert "OPENED #2 | no window to raise" in log_text, log_text

            notify.raise_window = lambda h: calls.append(h) or False
            eng.receive({"source": "claude-code", "title": "gone",
                         "hwnd": 7, "app": "Claude"})
            state = eng.open()
            assert calls == [7] and state["unread"] == 0, (calls, state)
            assert card.hidden == 3, "a window that will not come is not an error"
            log_text = (Path(d) / "notify.log").read_text("utf-8")
            assert "OPENED #3 -> Claude (7) | but it would not come forward" \
                in log_text, log_text
        finally:
            notify.raise_window = real
            eng.stop()

    # The real one, with handles that are not windows. It must answer
    # False rather than raise: a sender is allowed to have exited.
    assert notify.raise_window(0) is False
    assert notify.raise_window(-1) is False
    assert notify.raise_window("Claude") is False
    assert notify.raise_window(None) is False
    assert notify.raise_window(7) is False, "7 is not a window"
    code = "\n".join(
        l for l in inspect.getsource(notify._handles).splitlines()
        if l.strip() and not l.strip().startswith("#"))
    # The USES, not the name: this function's docstring explains the trap
    # and has to name it to do that, and a bare "the string is absent"
    # check reads the warning as the crime. Same form as the hint card's
    # version of this assertion further down the file.
    assert 'ctypes.WinDLL("user32"' in code and \
        "ctypes.windll.user32." not in code and "= ctypes.windll" not in code, \
        "private handles only: a restype on ctypes.windll leaks everywhere"
    raiser = inspect.getsource(notify.raise_window) + \
        inspect.getsource(notify._is_front)
    for needle in ("IsWindow", "IsIconic", "ShowWindow", "SetForegroundWindow",
                   "GetForegroundWindow", "AttachThreadInput"):
        assert needle in raiser, needle
    assert raiser.index("SetForegroundWindow") < \
        raiser.index("AttachThreadInput"), "the dance is the FALLBACK"
    # The handover is asynchronous — one immediate read of the foreground
    # answered 0 on a raise that worked — so the check is a bounded WAIT,
    # not a read. See SETTLE_S.
    assert notify.SETTLE_S > 0 and notify.POLL_S > 0
    assert "SETTLE_S" in raiser and "time.sleep" in raiser
    t0 = time.monotonic()
    assert notify._is_front(notify._handles()[0], 7, 0.05) is False
    assert 0.04 <= time.monotonic() - t0 < 1.0, "it waits, and it stops"


def test_opening_a_notification_goes_to_its_session_before_its_window() -> None:
    """One Claude window holds every session, so the handle alone lands
    wherever the app was last showing. A sender may also name the
    session as a `claude://…` link; open() hands that to the shell FIRST
    (it spawns a process and travels; the raise is instant) and then
    raises the window exactly as before. A link nobody sent, one the
    whitelist refuses, or a shell that will not take it costs the trip
    and nothing else — the window still comes forward, the card still
    goes down, and notify.log says which of the two happened."""
    import notify

    link = "claude://resume?session=6abc45c7-8df5-460d-a90f-cbadbbbd4cb2"
    # WHAT MAY BE HANDED TO THE SHELL. This is the only field in a
    # notification that is not drawn, so it is admitted by a whitelist
    # rather than cleaned: one scheme, one alphabet, one length.
    assert notify._link(link) == link
    assert notify._link(f"  {link}\n") == link, "the ends are trimmed"
    for bad in ("claude://a b", "claude://a\tb", "file:///c:/x", "http://x",
                "CLAUDE://x", "claude://", "claude://x%20y", "claude://x\\y",
                'claude://x"&calc', "claude:" + "/" * 3 + "a" * 200,
                5, None, ["claude://x"], {"x": 1}):
        assert notify._link(bad) == "", bad
    assert notify.clean({"link": "javascript:alert(1)"})["link"] == ""
    assert notify.clean({"link": link})["link"] == link

    calls: list = []
    real_open, real_raise = notify.open_link, notify.raise_window
    with tempfile.TemporaryDirectory() as d:
        card = _FakeNotifyCard()
        eng = notify.Engine(Path(d), _notify_cfg(remind_every_s=30,
                                                 remind_times=3),
                            cue=lambda k: None, card=card)
        try:
            notify.open_link = lambda u: calls.append(("link", u)) or True
            notify.raise_window = lambda h: calls.append(("raise", h)) or True
            eng.receive({"source": "claude-code", "title": "Claude finished",
                         "hwnd": 43779834, "app": "Claude", "link": link})
            assert eng.store.last()["link"] == link, "the store keeps it"
            state = eng.open(by="card")
            assert calls == [("link", link), ("raise", 43779834)], calls
            assert state["unread"] == 0 and card.hidden == 1
            log_text = (Path(d) / "notify.log").read_text("utf-8")
            assert "OPENED #1 -> Claude (43779834) | to the session" \
                in log_text, log_text

            calls.clear()
            notify.open_link = lambda u: calls.append(("link", u)) or False
            eng.receive({"source": "claude-code", "title": "finished",
                         "hwnd": 43779834, "app": "Claude", "link": link})
            eng.open(by="card")
            assert calls == [("link", link), ("raise", 43779834)], calls
            log_text = (Path(d) / "notify.log").read_text("utf-8")
            assert "OPENED #2 -> Claude (43779834) | but the session would " \
                "not open" in log_text, log_text

            calls.clear()
            eng.receive({"source": "claude-code", "title": "no link",
                         "hwnd": 43779834, "app": "Claude",
                         "link": "file:///c:/windows/system32/calc.exe"})
            assert eng.store.last()["link"] == "", "refused on the way in"
            eng.open(by="card")
            assert calls == [("raise", 43779834)], \
                "a link that is not one is never handed to the shell"
            log_text = (Path(d) / "notify.log").read_text("utf-8")
            assert "OPENED #3 -> Claude (43779834)\n" in log_text, log_text
        finally:
            notify.open_link, notify.raise_window = real_open, real_raise
            eng.stop()

    # The real opener, with nothing it would launch. It answers False
    # rather than raising, and it puts the link through the whitelist
    # again rather than trusting the store it came from.
    assert notify.open_link("") is False
    assert notify.open_link(None) is False
    assert notify.open_link("file:///c:/windows/system32/calc.exe") is False
    opener = inspect.getsource(notify.open_link)
    assert "_link(link)" in opener and "os.startfile" in opener, opener
    assert "subprocess" not in opener and "shell=True" not in opener


def test_the_notify_store_keeps_a_hundred_and_survives_a_broken_file() -> None:
    """notify.json holds the last KEEP items with rising ids, tells the
    dashboard when it moved without being read, and a file that will
    not parse is an empty store, not a dead one."""
    import notify

    with tempfile.TemporaryDirectory() as d:
        store = notify.Store(Path(d) / "notify.json")
        assert store.stamp() is None, "no file yet"
        assert store.items() == []
        ids = [store.add({"source": "test", "kind": "done",
                          "title": f"t{i}", "body": "", "project": "",
                          "session": ""})["id"] for i in range(105)]
        assert ids == list(range(1, 106)), ids[:5]
        items = store.items()
        assert len(items) == 100, len(items)
        assert [i["id"] for i in items] == list(range(6, 106)), \
            "the oldest five must be gone"
        assert all(not i["seen"] for i in items)
        assert store.unread() == 100
        assert store.recent(3)[0]["id"] == 105 and \
            store.recent(3)[-1]["id"] == 103
        assert store.last()["id"] == 105
        before = store.stamp()
        assert before is not None
        assert store.mark_seen() == 100
        assert store.mark_seen() == 0
        assert store.unread() == 0
        time.sleep(0.01)
        store.add({"title": "again"})
        assert store.stamp() != before, "a write must move the stamp"
        assert store.stamp() == store.stamp(), "a read must not"
        (Path(d) / "notify.json").write_text("{not json", "utf-8")
        assert store.items() == []
        item = store.add({"title": "after the break"})
        assert item["id"] == 1 and store.items()[0]["title"] == \
            "after the break"


def test_receiving_plays_the_cue_shows_the_card_and_hands_back_counts() -> None:
    """One arrival: stored, logged, cued once, shown with its label and
    the unread count; the reply and state() carry counts, never a body;
    an engine that is off refuses and stores nothing."""
    import notify

    with tempfile.TemporaryDirectory() as d:
        cue: list[str] = []
        card = _FakeNotifyCard()
        eng = notify.Engine(Path(d), _notify_cfg(), cue=cue.append,
                            card=card)
        reply = eng.receive({"source": "claude-code", "kind": "done",
                             "title": "Claude finished", "body": "b" * 50,
                             "project": "DeskIT"})
        assert reply == {"ok": True, "id": 1, "unread": 1,
                         "coalesced": False, "held": False}, reply
        assert cue == ["notify"], cue
        assert len(card.shown) == 1
        shown = card.shown[0]
        assert shown["unread"] == 1 and shown["label"] == "Claude Code", shown
        assert shown["title"] == "Claude finished"
        state = eng.state()
        assert "body" not in state and "body" not in state["last"], state
        assert state["last"]["title"] == "Claude finished"
        assert state["last"]["label"] == "Claude Code"
        assert state["unread"] == 1 and state["total"] == 1
        assert state["card_up"] is True, "the fake shows itself"
        assert state["enabled"] is True and state["reminding"] is False
        log_text = (Path(d) / "notify.log").read_text("utf-8")
        assert "RECEIVED #1 from claude-code (done)" in log_text, log_text
        assert eng.recent(5)[0]["body"] == "b" * 50, "recent carries bodies"

    with tempfile.TemporaryDirectory() as d:
        cue = []
        card = _FakeNotifyCard()
        eng = notify.Engine(Path(d), _notify_cfg(enabled=False),
                            cue=cue.append, card=card)
        reply = eng.receive({"title": "x"})
        assert reply["ok"] is False and "off" in reply["error"], reply
        assert eng.store.items() == [], "nothing stored while off"
        assert cue == [] and card.shown == []
        assert eng.state()["enabled"] is False


def test_a_burst_from_one_source_updates_the_card_without_a_second_cue() -> None:
    """Claude fires Stop and Notification a moment apart: the second
    from the same source inside coalesce_s updates the card and skips
    the cue; another source, or the window passing, plays again."""
    import notify

    with tempfile.TemporaryDirectory() as d:
        now = [0.0]
        cue: list[str] = []
        card = _FakeNotifyCard()
        eng = notify.Engine(Path(d), _notify_cfg(coalesce_s=5),
                            cue=cue.append, card=card, clock=lambda: now[0])
        first = eng.receive({"source": "claude-code", "title": "one"})
        now[0] = 1.0
        second = eng.receive({"source": "claude-code", "title": "two"})
        assert first["coalesced"] is False and second["coalesced"] is True
        assert cue == ["notify"], cue
        assert len(card.shown) == 2, "the card still updates"
        assert card.shown[1]["title"] == "two" and card.shown[1]["unread"] == 2
        third = eng.receive({"source": "phone", "title": "three"})
        assert third["coalesced"] is False and len(cue) == 2, cue
        now[0] = 6.5
        fourth = eng.receive({"source": "claude-code", "title": "four"})
        assert fourth["coalesced"] is False and len(cue) == 3, cue
        assert eng.state()["unread"] == 4


def test_reminders_repeat_while_unread_and_stop_at_dismiss() -> None:
    """While something is unread the cue replays and the card comes back
    remind_times times; a dismissal cancels them and marks all seen;
    stop() returns promptly with a reminder pending."""
    import notify

    with tempfile.TemporaryDirectory() as d:
        cue: list[str] = []
        card = _FakeNotifyCard()
        eng = notify.Engine(Path(d), _notify_cfg(remind_every_s=0.05,
                                                 remind_times=2,
                                                 coalesce_s=0),
                            cue=cue.append, card=card)
        eng.receive({"source": "claude-code", "title": "one"})
        _awake_until(lambda: len(cue) == 3, 2.0)
        assert len(cue) == 3, cue
        time.sleep(0.2)
        assert len(cue) == 3, "no fourth reminder"
        assert len(card.shown) == 3, "the card came back with each reminder"
        log_text = (Path(d) / "notify.log").read_text("utf-8")
        assert "REMINDED 1/2" in log_text and "REMINDED 2/2" in log_text
        assert eng.state()["reminding"] is False, eng.state()

        eng.receive({"source": "claude-code", "title": "two"})
        assert len(cue) == 4
        state = eng.dismiss(by="key")
        time.sleep(0.2)
        assert len(cue) == 4, "a dismissed notification is not reminded"
        assert state["unread"] == 0 and eng.state()["unread"] == 0
        assert card.hidden >= 1, "dismiss takes the card down"
        assert state["reminding"] is False
        log_text = (Path(d) / "notify.log").read_text("utf-8")
        assert "DISMISSED by key | 2 marked seen" in log_text, log_text

        eng.remind_every_s = 10.0
        eng.receive({"source": "claude-code", "title": "three"})
        assert eng.state()["reminding"] is True
        assert eng.state()["reminders_left"] == 2
        t0 = time.monotonic()
        eng.stop()
        assert time.monotonic() - t0 < 1.0, "stop() must not wait out a reminder"
        assert eng.state()["reminding"] is False


def test_notify_holds_a_finish_until_its_session_goes_quiet() -> None:
    """The quiet door (2026-09-05). Claude Code fires Stop at the end of
    EVERY turn — 87 of the last 100 stored were per-turn finishes — so
    a `done` is not shown when it lands: it waits, unread and off the
    screen, until its session has been quiet for quiet_s, and then lands
    without a sound, because a finish may not interrupt."""
    import notify

    with tempfile.TemporaryDirectory() as d:
        cue: list[str] = []
        card = _FakeNotifyCard()
        eng = notify.Engine(Path(d), _notify_cfg(quiet_s=0.05,
                                                 interrupt="input"),
                            cue=cue.append, card=card)
        reply = eng.receive({"source": "claude-code", "kind": "done",
                             "title": "Claude finished", "session": "S1"})
        assert reply["held"] is True and reply["id"] == 1, reply
        assert cue == [] and card.shown == [], (cue, card.shown)
        assert eng.live() == [], "held is off the screen"
        assert eng.store.unread() == 1, "but in the store, unread"
        assert eng.state()["held"] == 1 and eng.state()["unread"] == 1
        log_text = (Path(d) / "notify.log").read_text("utf-8")
        assert "HELD #1" in log_text, log_text
        _awake_until(lambda: card.shown, 2.0)
        assert len(card.shown) == 1, card.shown
        assert card.shown[0]["title"] == "Claude finished"
        assert cue == [], "a finish never rings under interrupt = input"
        assert eng.state()["held"] == 0, eng.state()
        log_text = (Path(d) / "notify.log").read_text("utf-8")
        assert "QUIET #1" in log_text, log_text
        eng.stop()


def test_notify_retires_a_held_finish_when_its_session_speaks_again() -> None:
    """One session, one finish, the newest: a second `done` from the
    same session inside the window marks the first seen without it ever
    having been shown, and takes the slot. Another session's finish is
    left exactly where it was, and stop() cancels every held timer."""
    import notify

    with tempfile.TemporaryDirectory() as d:
        cue: list[str] = []
        card = _FakeNotifyCard()
        eng = notify.Engine(Path(d), _notify_cfg(quiet_s=5, interrupt="input"),
                            cue=cue.append, card=card)
        eng.receive({"source": "claude-code", "kind": "done", "session": "S1"})
        eng.receive({"source": "claude-code", "kind": "done", "session": "S2"})
        third = eng.receive({"source": "claude-code", "kind": "done",
                             "session": "S1"})
        assert third["held"] is True, third
        seen = [i["seen"] for i in eng.store.items()]
        assert seen == [True, False, False], seen
        assert eng.state()["held"] == 2, eng.state()
        assert card.shown == [] and cue == [], (card.shown, cue)
        log_text = (Path(d) / "notify.log").read_text("utf-8")
        assert "SUPERSEDED #1 by #3 | same session" in log_text, log_text
        t0 = time.monotonic()
        eng.stop()
        assert time.monotonic() - t0 < 1.0, "stop() cancels, never waits"
        assert eng.state()["held"] == 0, eng.state()


def test_notify_never_holds_a_permission_and_it_retires_the_held_finish() -> None:
    """A permission, a question, an error is wanted NOW: it rings and
    lands at once, and the finish its session was holding is retired —
    the session has plainly spoken again. And quiet_s = 0 is the old
    door: a finish lands the moment it arrives, still without a sound
    under interrupt = input."""
    import notify

    with tempfile.TemporaryDirectory() as d:
        cue: list[str] = []
        card = _FakeNotifyCard()
        eng = notify.Engine(Path(d), _notify_cfg(quiet_s=5, interrupt="input",
                                                 coalesce_s=0),
                            cue=cue.append, card=card)
