def test_the_notify_card_is_measured_and_pressed_where_drawn() -> None:
    """card_for is the card as data, measure grows with the body and
    stops at BODY_LINES, and the hit test answers from the same boxes
    the painter draws — so the × is pressed where it is seen."""
    import notify_card as nc
    from datetime import datetime
    now_iso = datetime.now().replace(microsecond=0).isoformat()
    card = nc.card_for(_item(at=now_iso), seconds=30, unread=1)
    assert card["label"] == "Claude Code" and card["kind"] == "done"
    assert card["colour"] == nc.KIND_COLOUR["done"]
    assert card["when"] == "just now", card["when"]
    assert card["badge"] == "" and card["unread"] == 1
    assert card["seconds"] == 30.0 and card["footer"] == nc.FOOTER
    assert card["id"] == 7 and card["title"] == "Claude finished"
    three = nc.card_for(_item(), seconds=30, unread=3)
    assert three["badge"] == "3" and three["unread"] == 3
    odd = nc.card_for(_item(kind="boom"), seconds=0)
    assert odd["kind"] == "info" and odd["colour"] == nc.KIND_COLOUR["info"]
    assert nc.card_for(_item(label=None), seconds=0)["label"] == "claude-code"

    one = nc.card_for(_item(body="one line"), seconds=30)
    four = nc.card_for(_item(body="\n".join(["a line"] * 4)), seconds=30)
    forty = nc.card_for(_item(body="\n".join(["a line"] * 40)), seconds=30)
    w1, h1 = nc.measure(one)
    w4, h4 = nc.measure(four)
    w40, h40 = nc.measure(forty)
    assert w1 == w4 == w40 == nc.CARD_W, (w1, w4, w40)
    assert h4 > h1, "a four-line body must make the card taller"
    assert h40 == h4, f"the body is cut at {nc.BODY_LINES} lines: {h40} vs {h4}"
    assert nc.measure(one, 1.4)[0] > w1 > nc.measure(one, 0.6)[0]

    boxes = nc.regions(four, 1.0)
    w, h = nc.measure(four, 1.0)
    for name in ("dismiss", "drag"):
        x0, y0, x1, y1 = boxes[name]
        assert nc.SHADOW <= x0 < x1 <= nc.SHADOW + w, (name, boxes[name])
        assert nc.SHADOW <= y0 < y1 <= nc.SHADOW + h, (name, boxes[name])
    dx0, dy0, dx1, dy1 = boxes["dismiss"]
    assert (dx1 - dx0, dy1 - dy0) == (26, 26) and dx0 == nc.SHADOW + nc.PAD
    assert nc.hit_test(four, 1.0, dx0 + 5, dy0 + 5) == (nc.HTCLIENT, "dismiss")
    assert nc.hit_test(four, 1.0, nc.SHADOW + w // 2, nc.SHADOW + h // 2) \
        == (nc.HTCAPTION, "drag")
    assert nc.hit_test(four, 1.0, 3, 3) == (nc.HTTRANSPARENT, None)
    assert nc.hit_test(four, 1.0, nc.SHADOW + w + 5, nc.SHADOW + 5) \
        == (nc.HTTRANSPARENT, None)

    cache: dict = {}
    img = nc.compose(three, 1.0, 0.5, hover="dismiss", cache=cache)
    assert img.mode == "RGBA" and img.size == nc.measure(three, 1.0)
    assert img.getchannel("A").getbbox() is not None, "nothing was drawn"
    assert cache, "the presenter's cache was not used"
    face = nc.flat(three, 1.0, 0.5, None, cache)
    assert face.size == img.size
    cx, cy = face.width // 2, face.height // 2
    assert face.getpixel((cx, cy))[3] == 255, "flat must be opaque"
    assert face.getpixel((cx, 1))[:3] == nc.KIND_COLOUR["done"], \
        "the colour bar runs along the top"


def test_the_card_never_hands_one_string_both_hebrew_and_latin() -> None:
    """Every string on the card is its own text_pil image: the chrome is
    English and the title/body arrive verbatim, and nothing here ever
    concatenates the two — that is the mixed line Tk lays out backwards
    and DrawTextW lays out in ONE direction."""
    import notify_card as nc
    seen: list[str] = []
    original = nc._text

    def recording(cache, text, *a, **k):
        seen.append(text)
        return original(cache, text, *a, **k)

    title = "קלוד סיים"
    body = "בדיקה של עברית ו-English together, on more than one line."
    nc._text = recording
    try:
        card = nc.card_for(_item(title=title, body=body,
                                 label="Claude Code",
                                 project="DeskIT"),
                           seconds=30, unread=3)
        nc.compose(card, 1.0, 1.0, "dismiss", {})
    finally:
        nc._text = original
    assert seen, "nothing went through the painter"
    hebrew = "\u0590"
    for text in seen:
        if text in (title, body):
            continue
        assert not any(hebrew <= ch <= "\u08ff" for ch in text), (
            f"a chrome string carries Hebrew: {text!r}")
    assert title in seen and body in seen, seen
    assert nc._is_rtl(title) and not nc._is_rtl("Claude Code")
    assert nc._is_rtl(body) and not nc._is_rtl("3") and not nc._is_rtl("")


def test_relative_time_reads_naturally() -> None:
    import notify_card as nc
    from datetime import datetime
    at = "2026-09-03T14:00:00"
    base = datetime.fromisoformat(at).timestamp()
    assert nc.ago(at, base + 30) == "just now"
    assert nc.ago(at, base + 5 * 60) == "5 min ago"
    assert nc.ago(at, base + 3 * 3600) == "3 h ago"
    assert nc.ago(at, base + 86400) == "yesterday"
    assert nc.ago(at, base + 10 * 86400) == "3 Sep"
    assert nc.ago(at, base - 5) == "just now", "a clock skew is not the future"
    assert nc.ago("garbage") == "" and nc.ago("") == "" and nc.ago(None) == ""


def test_the_notify_card_sits_mid_height_and_keeps_a_saved_position(
        ) -> None:
    """...and since 2026-09-04 a saved y is the edge the card is ANCHORED
    by, which under the default `anchor="bottom"` is its BOTTOM. Every
    corner is unchanged; only the meaning of the stored number moved, and
    it moved so a column that grew taller could not walk off the bottom of
    the screen. The old reading is still reachable with anchor="top",
    which is what the assertion below pins."""
    card = overlay_mod.NotifyCard(corner="right", margin=14)
    x, y = card.origin(360, 200, (2560, 1440), 26, (-1920, 0, 4480, 1440))
    assert (x, y) == (2560 - 14 - 360 + 26, (1440 - 200) // 2), (x, y)
    left = overlay_mod.NotifyCard(corner="left", margin=14)
    assert left.origin(360, 200, (2560, 1440), 26)[0] == 14 - 26
    moved = overlay_mod.NotifyCard(corner="right", x=-1500, y=300,
                                   anchor="top")
    assert moved.origin(360, 200, (2560, 1440), 26,
                        (-1920, 0, 4480, 1440)) == (-1526, 274), \
        "a saved position on the left monitor is kept"
    bottom = overlay_mod.NotifyCard(corner="right", x=-1500, y=300,
                                    anchor="bottom")
    assert bottom.origin(360, 200, (2560, 1440), 26,
                         (-1920, 0, 4480, 1440)) == (-1526, 274 - 148), \
        "under anchor=bottom the saved y is the card's bottom edge"
    top = overlay_mod.NotifyCard(corner="top-right", margin=14)
    assert top.origin(360, 200, (2560, 1440), 26)[1] == 14 - 26
    assert overlay_mod.NotifyCard.CORNERS == overlay_mod.ReviewCard.CORNERS


def test_the_notify_card_dismisses_by_esc_only_under_the_pointer_and_reports_once(
        ) -> None:
    """Esc is the card's only key, only over it; a dismissal is reported
    exactly once; running out of time reports nothing; and none of it
    ever goes near HintCard.dismissed(), which writes enabled=false."""
    rec: list = []
    changed: list = []
    # The callbacks take the pressed card's id since 2026-09-04 (None
    # meaning "all"), and the queue carries the whole COLUMN rather than
    # one card — a bare dict is still accepted and still means a column of
    # one, which is what this test hands it.
    card = overlay_mod.NotifyCard(on_dismiss=lambda i: rec.append(1),
                                  on_change=lambda f: changed.append(f),
                                  seconds=30)
    card._thread = threading.Thread(target=lambda: None)   # never started
    card.show(_item(id=7, unread=3))
    assert card.visible() and card.current() == 7
    queued = card._q.get_nowait()[0]
    assert queued["badge"] == "3" and queued["label"] == "Claude Code"
    assert queued["seconds"] == 30.0
    card.rect = (0, 0, 100, 100)
    assert not card.hovering() or True         # depends on the real mouse
    card.hovering = lambda: True
    assert card.on_key(0x41) is False, "a letter is not the card's"
    assert card.on_key(0x1B) is True and rec == [1]
    assert not card.visible()
    assert card._q.get_nowait() is None, "the painter is told to take it down"
    assert card.on_key(0x1B) is False, "nothing up: Esc is not ours"
    assert rec == [1]
    card.show(_item(id=8))
    card.timed_out()
    assert rec == [1] and not card.visible(), "a timeout is not a dismissal"
    card.show(_item(id=9))
    card.pressed("dismiss")
    card.pressed("dismiss")
    assert rec == [1, 1], "reported once per card"
    assert card._enabled is True and changed == [], \
        "dismiss must never write enabled=false or anything else"
    card.hovering = lambda: False
    card.show(_item(id=10))
    assert card.on_key(0x1B) is False and card.visible(), \
        "Esc away from the card is somebody else's Esc"
    src = __import__("inspect").getsource(overlay_mod.NotifyCard)
    assert "self.dismissed(" not in src and "super().dismissed(" not in src \
        and "_changed(enabled" not in src, \
        "NotifyCard must never call HintCard.dismissed() (enabled=false)"


def test_the_notify_card_opens_on_a_click_and_dismisses_on_the_cross(
        ) -> None:
    """The card's two answers (2026-09-04). `pressed("open")` calls
    on_open exactly once per card and never on_dismiss; both take the
    card down; neither goes anywhere near HintCard.dismissed(), which is
    the trap that would write enabled=false into config.toml. Esc stays a
    plain dismissal — a key over a card is not a request to go
    anywhere — and a name that is neither is ignored."""
    opened: list = []
    dismissed: list = []
    changed: list = []
    # One argument since 2026-09-04: the id of the card that was pressed,
    # or None for "all" / "the newest". Esc and the dismiss key name
    # nobody, which is what these presses do.
    card = overlay_mod.NotifyCard(on_dismiss=lambda i: dismissed.append(1),
                                  on_open=lambda i: opened.append(1),
                                  on_change=lambda f: changed.append(f))
    card._thread = threading.Thread(target=lambda: None)   # never started
    card.show(_item(id=11))
    card.pressed("open")
    assert opened == [1] and dismissed == [], (opened, dismissed)
    assert not card.visible(), "the card comes down on an open too"
    assert card._q.get_nowait()[0]["id"] == 11
    assert card._q.get_nowait() is None, "the painter is told to take it down"
    card.pressed("open")
    assert opened == [1], "one press, one report"
    card.show(_item(id=12))
    card.pressed("sideways")
    assert card.visible() and opened == [1] and dismissed == [], \
        "a name that is neither is not a press"
    card.hovering = lambda: True
    assert card.on_key(0x1B) is True
    assert dismissed == [1] and opened == [1], "Esc dismisses, never opens"
    assert card._enabled is True and changed == [], \
        "an open must never write enabled=false or anything else"
    # A card built without an on_open still comes down on a click; the
    # engine simply never hears about it.
    bare = overlay_mod.NotifyCard()
    bare._thread = threading.Thread(target=lambda: None)
    bare.show(_item(id=13))
    bare.pressed("open")
    assert not bare.visible()


def test_both_notify_presenters_open_on_a_click_and_dismiss_on_the_cross(
        ) -> None:
    """Same two meanings whichever presenter is up, checked at the source
    level because every one of these is a mouse event on a real window.

    The × is the only HTCLIENT region notify_card.hit_test answers, and
    on both paths it is the one that reaches `pressed("dismiss")`: in Tk
    on the way DOWN (on_press), on glass through WM_LBUTTONDOWN
    (on_click). Everything else on the card is HTCAPTION, and its
    release — travelled less than CLICK_PX, so a click and not a drag —
    is `pressed("open")`.
    """
    # The needles lost their closing paren on 2026-09-04: a press now
    # names the card it landed on, so the calls read
    # `pressed("dismiss", ident(...))`. What is being asserted is which
    # of the two answers each road takes, and that has not changed.
    tk_src = inspect.getsource(overlay_mod.NotifyCard._build_and_loop)
    assert 'self.pressed("open"' in tk_src
    assert 'self.pressed("dismiss"' in tk_src
    press = tk_src[tk_src.index("def on_press"):tk_src.index("def on_motion")]
    assert 'self.pressed("dismiss"' in press and \
        'self.pressed("open"' not in press, \
        "the × dismisses; on_press must not open"
    assert "nc.HTCLIENT and what == nc.DISMISS" in press or \
        'code == nc.HTCLIENT and what == "dismiss"' in press, press
    release = tk_src[tk_src.index("def on_release"):]
    assert 'self.pressed("open"' in release and \
        'self.pressed("dismiss"' not in release, \
        "a click on the body opens; only a drag past CLICK_PX does not"
    assert "CLICK_PX" in release, "no threshold: every drag would open"

    skin = _skin_or_skip()
    if skin is None:
        return
    src = (Path(skin.__file__).resolve().parent / "notify.py").read_text(
        "utf-8")
    body = src[src.index("def run("):]
    assert 'card.pressed("open"' in body and 'card.pressed("dismiss"' in body
    click = body[body.index("def on_click"):body.index("def paint")]
    assert 'card.pressed("dismiss"' in click and \
        'card.pressed("open"' not in click, \
        "on_click is the × and only the ×"
    assert "nc.HTCLIENT and what == nc.DISMISS" in click, click
    move = body[body.index("def on_move"):body.index("def on_click")]
    assert 'card.pressed("open"' in move and \
        'card.pressed("dismiss"' not in move, \
        "a click on the card's HTCAPTION area opens"
    assert "CLICK_PX" in move and "dismissing" in move, \
        "the latch and the threshold both still stand"


def test_the_off_notify_card_is_inert() -> None:
    card = overlay_mod.NotifyCard.off()
    card.start()
    assert card._thread is None
    card.show(_item())
    assert card.visible() is False and card.current() is None
    card.hide()
    assert card.on_key(0x1B) is False and card.hovering() is False
    card.pressed("dismiss")
    card.timed_out()
    card.stop()


def _code_only(text: str) -> str:
    """`text` with its whole-line comments dropped.

    Every assertion about a call that must NOT be there needs this. The
    removals of 2026-09-04 left long comments behind saying what went and
    why — comments that necessarily quote the very call they are about —
    so a bare `"_hide_from_capture(root)" not in src` reads the epitaph
    and concludes the body is still warm.
    """
    return "\n".join(line for line in text.splitlines()
                     if line.strip() and not line.strip().startswith("#"))


def test_the_notify_card_does_not_hide_itself_from_capture() -> None:
    """THE CARD MUST BE PHOTOGRAPHABLE, on both of its paths.

    The owner's ask, 2026-09-04: "Win+Shift+S should just freeze the
    screen and take a picture of it as it is, without anything
    disappearing." The card that says Claude has finished was the one
    thing that could not be photographed — `SetWindowDisplayAffinity`
    with WDA_EXCLUDEFROMCAPTURE is absolute, so the compositor left it
    out of the freeze the selector paints itself with and it appeared to
    blink out the instant he reached for the key.

    THIS TEST USED TO ASSERT THE OPPOSITE. It was
    `test_the_notify_card_gives_the_foreground_back_and_hides_from_capture`
    and it required `_hide_from_capture(root)` to be present. Both paths
    are checked because either one alone is a hole: `skin.notify_run` is
    live, so the glass path is what actually runs, and deleting skin\\
    drops the app onto the Tk fallback in overlay.py.

    What keeps the card out of the way now is ORDER, not invisibility —
    see test_the_notify_card_stands_down_for_a_selection.
    """
    import ast
    import inspect
    tk_path = _code_only(
        inspect.getsource(overlay_mod.NotifyCard._build_and_loop))
    assert "_hide_from_capture" not in tk_path, \
        "the Tk notify card excludes itself from capture again"

    def flag_users(path: str) -> list[str]:
        """Names actually USED as code, never prose.

        Read through the parser rather than by substring, because both
        files now carry paragraphs explaining why the flag went — and
        those paragraphs have to name it to be worth reading. A grep
        cannot tell the corpse from the headstone; an AST can.
        """
        tree = ast.parse((REPO / path).read_text("utf-8"))
        found = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Name) and node.id in (
                    "WDA_EXCLUDEFROMCAPTURE", "_hide_from_capture"):
                found.append(f"{path}:{node.lineno} {node.id}")
            elif isinstance(node, ast.Attribute) and \
                    node.attr == "SetWindowDisplayAffinity":
                found.append(f"{path}:{node.lineno} {node.attr}")
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) \
                    and node.name == "_hide_from_capture":
                found.append(f"{path}:{node.lineno} def {node.name}")
        return found

    assert not flag_users("overlay.py"), \
        f"overlay.py sets the display-affinity flag again: " \
        f"{flag_users('overlay.py')}"
    assert not flag_users("skin/notify.py"), \
        f"skin/notify.py sets the display-affinity flag again: " \
        f"{flag_users('skin/notify.py')}"
    # The reason has to survive too, or the next reader re-adds the flag
    # to fix a screenshot with a card in the corner of it.
    for path in ("overlay.py", "skin/notify.py"):
        assert "2026-09-04" in (REPO / path).read_text("utf-8"), path


def test_the_notify_card_gives_the_foreground_back() -> None:
    """The window is a notification: it hands the keyboard back the
    moment Tk takes it, is no-activate but click-taking, and the skin
    hook keeps the deletable form.

    Split out of the capture-exclusion test on 2026-09-04 when that one
    was inverted; giving the foreground back is a separate promise and it
    did not change."""
    import ast
    import inspect
    src = inspect.getsource(overlay_mod.NotifyCard._build_and_loop)
    i_fg = src.index("_foreground()")
    i_de = src.index("deiconify")
    assert i_fg < i_de, "read the foreground BEFORE the window is shown"
    assert "_give_focus_back(" in src
    assert src.index("_give_focus_back(") > src.index("update_idletasks")
    assert "_no_activate(root)" in src
    assert "click_through=True" not in src, "a click is the dismissal"
    assert "ImageTk.PhotoImage(img, master=root)" in src
    assert "gc.collect()" in src and "root.destroy()" in src
    assert "master=root" in src
    run_src = inspect.getsource(overlay_mod.NotifyCard._run)
    assert "skin is not None and skin.notify_run(self)" in run_src
    assert callable(overlay_mod._foreground) and \
        callable(overlay_mod._give_focus_back)
    overlay_mod._give_focus_back(0)            # a no-op, never raises
    assert isinstance(overlay_mod._foreground(), int)
    helper = inspect.getsource(overlay_mod._foreground) + \
        inspect.getsource(overlay_mod._give_focus_back)
    code = "\n".join(l for l in helper.splitlines()
                     if l.strip() and not l.strip().startswith("#"))
    assert 'ctypes.WinDLL("user32"' in code and \
        "ctypes.windll.user32." not in code and "= ctypes.windll" not in code, \
        "private handles only: a restype on ctypes.windll leaks everywhere"
    source = (REPO / "overlay.py").read_text("utf-8")
    assert "try:\n    import skin" in source
    for line in source.splitlines():
        stripped = line.strip()
        if stripped.startswith("if skin") and "skin." in stripped:
            assert "skin is not None" in stripped, stripped
    # WHAT IT MEANS, ASKED OF THE IMPORTS. The rule is that overlay.py
    # must not import notify.py at MODULE level: this library is reached
    # on a hotkey press with the dashboard never opened, and a card file
    # that drags the notification engine (and through it the store, the
    # watcher and the hook) in behind it makes every other card pay for
    # a feature it is not using.
    #
    # This was a scan for the word "notify" anywhere above `class
    # NotifyCard`, and a word scan is a proxy that a COMMENT can fail:
    # three of them legitimately name where a number or a rule came from
    # ("NotifyCard's own number and its own name" over CLICK_PX is the
    # clearest), and a comment that says where a decision came from is
    # not deletable to satisfy a substring. So the module's own top level
    # is PARSED instead — walking into the `try: import skin` guard and
    # into any other module-level try/if/with, and pointedly not into a
    # def or a class, where a deferred import is this repo's own pattern
    # and costs an importer nothing (overlay.py has four of them for
    # notify_card, inside the methods that draw one).
    #
    # Stronger than the substring pair it replaces, in two ways: it
    # catches every spelling of the import rather than two of them
    # (`import notify.anything`, `from notify import x`,
    # `import notify as n`), and it refuses ANY module that lives in this
    # repo, which is the rule the notify one was an instance of.
    def _module_level(body):
        found = []
        for node in body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef,
                                 ast.ClassDef)):
                continue
            if isinstance(node, ast.Import):
                found += [alias.name for alias in node.names]
            elif isinstance(node, ast.ImportFrom) and not node.level:
                found.append(node.module or "")
            for field in ("body", "orelse", "finalbody", "handlers"):
                inner = getattr(node, field, None)
                if isinstance(inner, list):
                    found += _module_level(
                        [n for n in inner if isinstance(n, ast.AST)])
        return found

    imported = {name.split(".")[0]
                for name in _module_level(ast.parse(source).body)}
    assert not {n for n in imported if n.startswith("notify")}, \
        f"overlay.py imports notify at module level: {sorted(imported)}"
    ours = {path.stem for path in REPO.glob("*.py")} - {"overlay"}
    assert not (imported & ours), \
        f"overlay.py drags {sorted(imported & ours)} in at module level"
    # And the deferred ones are still deferred: notify_card is imported
    # inside the methods that draw a card and nowhere else.
    assert "notify_card" in source, "the card is not drawn at all"


def test_the_notify_card_stands_down_for_a_selection() -> None:
    """THE HALF THAT KEEPS THE REMOVED FLAG FROM BECOMING A BUG.

    The cards are `-topmost`. The screenshot selector maps after the ones
    already up, so it is above them — but a card that ARRIVES or re-shows
    mid-drag maps above the SELECTOR and eats the drag, and a
    notification landing while the owner is dragging is exactly when that
    happens. So capture asks them to stand down for the length of the
    selection, one line after the desktop freeze, which is what puts them
    IN the picture and OUT of the drag at the same time.

    The rules this has to keep, all of them load-bearing:

    - `hush()`/`unhush()` only set an Event. They are called from
      `begin_shot`, which main.py runs inside the OS keyboard hook, where
      hotkey.py's budget is 300 ms and overrunning it makes Windows
      unhook with nothing logged. They must not touch Tk, wait, or
      enqueue: each card owns its own interpreter on its own thread.
    - capture.py must not import overlay.py, so the callable is injected
      by main.py the way `ask_provider` already is.
    - A Controller nobody wired must still work.
    """
    import ast
    import inspect
    import textwrap
    import capture as cap
    for cls in (overlay_mod.HintCard, overlay_mod.ReviewCard,
                overlay_mod.NotifyCard):
        card = cls.off()
        card.hush()
        assert card._hushed.is_set(), cls.__name__
        card.unhush()
        assert not card._hushed.is_set(), cls.__name__
    body = _code_only(inspect.getsource(overlay_mod.HintCard.hush) +
                      inspect.getsource(overlay_mod.HintCard.unhush))
    for forbidden in ("root", "self._q", "deiconify", "withdraw", ".wait("):
        assert forbidden not in body, \
            f"hush() touched {forbidden!r} — that is the caller's thread"
    # The loops honour it on their own thread, and hold a card that
    # arrives while it is set rather than mapping it over the selector.
    #
    # THROUGH THE PARSER, not by substring, and that is not fussiness:
    # `"set_hushed(" in src` is satisfied by the DEFINITION `def
    # set_hushed(`, and both needles survive being commented out.
    # Measured 2026-09-04 by mutation — `pass  # set_hushed(...)` in all
    # three loops and this test still passed, which would have shipped a
    # card that ignores the hush and eats the owner's drag. A call is an
    # `ast.Call`; a comment is not.
    for label, text in (
            ("overlay.NotifyCard",
             inspect.getsource(overlay_mod.NotifyCard._build_and_loop)),
            ("overlay.ReviewCard",
             inspect.getsource(overlay_mod.ReviewCard._build_and_loop)),
            ("skin/notify.py",
             (REPO / "skin" / "notify.py").read_text("utf-8"))):
        tree = ast.parse(textwrap.dedent(text))
        called = {node.func.id for node in ast.walk(tree)
                  if isinstance(node, ast.Call)
                  and isinstance(node.func, ast.Name)}
        reads = [node for node in ast.walk(tree)
                 if isinstance(node, ast.Attribute) and node.attr == "_hushed"]
        assert "set_hushed" in called, \
            f"{label} never calls set_hushed — the hush is not honoured"
        assert reads, f"{label} never reads _hushed"
        assert "map_card" in called, \
            f"{label}: put_up must not be the only thing that maps a card"
        assert "set_hushed(" in text and "_hushed.is_set()" in text
    # Injected, not imported: capture.py stays free of overlay.py.
    seen = []
    ctrl = cap.Controller(lambda: None,
                          hush_overlays=lambda on: seen.append(on))
    ctrl._hush_cards()
    ctrl._unhush_cards()
    assert seen == [True, False], seen

    def boom(_on):
        raise RuntimeError("a card that cannot be hushed is not a hotkey")
    hurt = cap.Controller(lambda: None, hush_overlays=boom)
    hurt._hush_cards()                    # must not escape to the hook
    hurt._unhush_cards()
    cap.Controller(lambda: None)._hush_cards()      # nobody wired it: fine
    wiring = _code_only((REPO / "capture.py").read_text("utf-8"))
    assert "import overlay" not in wiring, \
        "capture.py must not depend on overlay.py"
    main_src = (REPO / "main.py").read_text("utf-8")
    assert "hush_overlays=self._hush_overlays" in main_src, \
        "main.py is the only thing holding both ends of this wire"


def test_skin_notify_run_presents_on_glass_and_never_shadows_itself() -> None:
    """The hook declines with the skin off and PRESENTS with it on, and
    skin\\notify.py existing is fine because the hook is `notify_run`.

    Both halves of this test used to assert the opposite. The card shipped
    with no glass presenter, so the hook returned False unconditionally and
    the test asserted that no file in skin\\ was named `notify` — which was
    a proxy for "the hook is safe", not the rule itself. The rule is the
    one paint_wave paid for: a hook may not share its NAME with a module in
    the folder, because importing the module rebinds the attribute. A file
    called notify.py is exactly the case `notify_run` was named to survive,
    and review_run/.review is the same pairing, shipped and working.

    Presenting is checked with a real NotifyCard whose `_closing` is
    already set, so run() takes its own exit on the first pass of the loop:
    it proves the hook reaches skin\\notify.run and reports True without
    standing up a layered window on the test machine's desktop.
    """
    skin = _skin_or_skip()
    if skin is None:
        return
    was = os.environ.get("HD_SKIN")
    try:
        os.environ["HD_SKIN"] = "0"
        skin.reset()
        assert skin.on() is False
        assert skin.notify_run(None) is False, \
            "the hook painted something with the skin switched off"
    finally:
        if was is None:
            os.environ.pop("HD_SKIN", None)
        else:
            os.environ["HD_SKIN"] = was
        skin.reset()

    folder = Path(skin.__file__).resolve().parent
    assert "notify" in {p.stem for p in folder.glob("*.py")}, \
        "skin\\notify.py is gone — the notify card has no glass presenter"
    import ast
    tree = ast.parse((folder / "__init__.py").read_text("utf-8"))
    hooks = {n.name for n in tree.body if isinstance(n, ast.FunctionDef)}
    modules = {p.stem for p in folder.glob("*.py")} - {"__init__"}
    assert "notify_run" in hooks and "notify" not in hooks
    assert not (hooks & modules), (
        f"a hook now shares a name with a module: {sorted(hooks & modules)}")

    if not skin.on():
        return
    card = overlay_mod.NotifyCard()
    card._closing.set()                  # run() exits on its first pass
    assert skin.notify_run(card) is True, \
        "the hook declined with the skin on — the flat Tk card is back"
    assert card._alive.is_set(), "run() never reported itself alive"
    assert card.rect is None, "run() left a stale rect behind"


def test_the_skin_notify_face_actually_rounds_the_corner() -> None:
    """THE DEFECT, asserted in pixels: outside the curve there is nothing.

    The owner's report was "the corner is curved but there is something in
    the background that makes them sharp" — the Tk fallback fills an opaque
    CARD_BG rectangle and notify_card.flat() draws a rounded OUTLINE inside
    it, so the curve is a drawing and the card is a square. A layered
    window has real per-pixel alpha, so the fix is checkable: render the
    glass face and read the alpha channel.

    Measured on this machine at scale 1.0, diagonally in from the card's
    top-left corner (SHADOW, SHADOW): 0, 0, 14, 25, 29, 61, 210, 210. Zero
    where the corner is cut, a feathered ramp, then the face. The face
    begins at d = 6 because a radius-20 arc meets the diagonal at
    20*(1 - 1/sqrt(2)) = 5.86 px, which is the arithmetic the picture is
    supposed to obey.

    ALL FOUR CORNERS ARE 0, and the bottom two are the ones that say so.
    They read 35 while the card had a drop shadow — 14% black washing
    below it, a shadow rather than a surface. The owner asked for the
    shadow gone on 2026-09-04 ("only like the box, the message"), so the
    only thing outside the curve now is nothing, and a bottom corner that
    is not 0 means the shadow came back rather than that the corner is
    square. The window's own four corners are 0 either way.
    """
    skin = _skin_or_skip()
    if skin is None or not skin.on():
        return
    import skia
    from skin import notify as skin_notify
    import notify_card as nc

    w, h = 200, 120
    pad = skin_notify.SHADOW
    surface = skia.Surface(w + pad * 2, h + pad * 2)
    canvas = surface.getCanvas()
    canvas.clear(0x00000000)             # what run() does before every frame
    skin_notify.face(canvas, w, h, 1.0, None)
    alpha = surface.makeImageSnapshot().toarray(
        colorType=skia.kRGBA_8888_ColorType)[:, :, 3]

    for cy, cx in ((0, 0), (0, -1), (-1, 0), (-1, -1)):
        assert alpha[cy, cx] == 0, (
            f"the window's own corner is not empty ({alpha[cy, cx]}) — the "
            f"layer is a rectangle again")
    for d in (0, 1):
        for cy, cx in ((pad + d, pad + d), (pad + d, pad + w - 1 - d)):
            assert alpha[cy, cx] == 0, (
                f"the card's top corner pixel is {alpha[cy, cx]}, not 0 — "
                f"something square is showing through the curve")
        for cy, cx in ((pad + h - 1 - d, pad + d),
                       (pad + h - 1 - d, pad + w - 1 - d)):
            assert alpha[cy, cx] == 0, (
                f"the card's bottom corner pixel is {alpha[cy, cx]}, not "
                f"0 — either the corner is square or the drop shadow the "
                f"owner asked us to remove is back")
    # Just inside the arc it is the face, at full face weight, and so is
    # the middle. If these were transparent the corner would be "round"
    # only because the whole card had vanished.
    for cy, cx in ((pad + 6, pad + 6), (pad + 6, pad + w - 7),
                   (pad + h - 7, pad + 6), (pad + h - 7, pad + w - 7)):
        assert alpha[cy, cx] >= 200, (cy, cx, alpha[cy, cx])
    assert alpha[pad + h // 2, pad + w // 2] >= 200, "the face is not there"
    # ...and the ramp between them is a ramp, not a step: an antialiased
    # corner has intermediate shades, a chroma key never does (that is the
    # measurement in skin\\glass.py's header, and the reason Tk cannot do
    # this at all).
    #
    # Read along the whole diagonal rather than at fixed offsets. With the
    # drop shadow gone (2026-09-04) the pixels short of the arc are 0
    # rather than 14/25/29 — nothing is outside the card now — so the
    # feather is only as wide as the arc itself: measured 0, 0, 0, 0, 0,
    # 33, 203, 203 at d = 0..7, one intermediate shade where the curve
    # crosses at 20*(1 - 1/sqrt(2)) = 5.86 px. Asserting a fixed window
    # would be asserting the shadow.
    ramp = [int(alpha[pad + d, pad + d]) for d in range(11)]
    assert any(0 < v < 200 for v in ramp), (
        f"no feather on the corner, just an edge: {ramp}")
    assert ramp == sorted(ramp), (
        f"the corner does not open outward monotonically: {ramp}")

    # The flat face, for contrast: the Tk fallback's corner is OPAQUE, and
    # that is the square the owner could see behind the curve.
    flat = nc.flat({"title": "x", "body": "", "seconds": 0,
                    "colour": nc.KIND_COLOUR["done"]}, 1.0)
    assert flat.getchannel("A").getpixel((0, 0)) == 255, (
        "notify_card.flat() no longer paints an opaque corner — the "
        "fallback changed, and this test's premise with it")


def test_the_skin_notify_card_dismisses_drags_and_hit_tests_like_the_flat_one(
        ) -> None:
    """Same card, same manners, whichever presenter is up.

    Checked at the source level because every one of these is a mouse
    event on a layered window: standing one up in the suite would put a
    real card on the owner's screen mid-run. What the glass path must do,
    all of it already true of overlay.NotifyCard._build_and_loop:

    * the shadow margin stays click-through (notify_card.hit_test, whose
      HTTRANSPARENT is what keeps the close button of a maximised window
      underneath reachable — the trap the status dot paid for once);
    * a click is `pressed("dismiss")`, never `dismissed()`, which is the
      hint card's "never show this again" and writes config.toml;
    * a press that TRAVELLED is `placed(...)` instead, +SHADOW because the
      window's corner is not the card's;
    * the clock waits under the pointer and running out is `timed_out()`,
      which leaves the notification unread on purpose;
    * and the content comes from compose(), never flat() — flat() is the
      opaque face, and drawing it here would paint the square back on.
    """
    skin = _skin_or_skip()
    if skin is None:
        return
    src = (Path(skin.__file__).resolve().parent / "notify.py").read_text(
        "utf-8")
    # `nc.hit_test` became `nc.stack_hit_test` on 2026-09-04: the window
    # holds the whole unread column, so the answer has to name WHICH card
    # the pointer is on. Same function, one more question answered.
    for needle in ("nc.stack_hit_test(", 'card.pressed("dismiss"',
                   "card.placed(", "card.timed_out()", "card.hovering()",
                   "nc.compose(", "nc.stack_layout(", "nc.stack_measure(",
                   "hit=on_hit", "moved=on_move", "clicked=on_click"):
        assert needle in src, f"skin\\notify.py never reaches {needle}"
    assert "nc.flat(" not in src and "notify_card.flat(card" not in src, \
        "the glass path draws the fallback's OPAQUE face"
    assert "card.dismissed(" not in src, \
        "dismissed() is 'never again' and writes enabled=false to config"
    assert "x + SHADOW, y + SHADOW" in src, \
        "a drag saves the window's corner, not the card's — it will snap back"
    assert "CLICK_PX" in src, \
        "no click-versus-drag threshold: every drag would dismiss the card"
    assert src.count('card.pressed("dismiss"') >= 1
    # The clock pauses under the pointer and only THEN is compared, exactly
    # as review.py does it; the other order takes the card down under a
    # reader's nose on the tick they hovered.
    assert src.index("deadline += dt") < src.index("left = deadline - now")


def test_a_notification_lands_on_the_waiting_place_not_a_screen_of_its_own():
    """Notify was one of nine rail rows; it is now one of the four
    sources of the Waiting pile, so the registrations moved with it. The
    place is still five things (NAV, ICON, _show, _refresh, and for its
    key KEY_GROUPS + NESTED_HOTKEYS) — missing any one is a KeyError the
    first time somebody clicks — and _waiting_notify is the reader that
    replaced the screen."""
    import dashboard as dash
    import ui
    names = [key for key, _label in dash.NAV]
    assert ("home", "Home") in dash.NAV
    assert names[0] == "home", names
    glyph = ui.ICON[dash.NAV_GLYPH["home"]]
    assert len(glyph) == 1 and ord(glyph) < 0x10000, repr(glyph)
    assert '"Home"' in inspect.getsource(dash.Dashboard._show)
    assert '"Home"' in inspect.getsource(dash.Dashboard._refresh)
    assert not hasattr(dash.Dashboard, "_screen_notify"), \
        "the Notify screen is gone; the pile is where a notification is"
    named = {f for _title, fields in dash.KEY_GROUPS for f in fields}
    assert "dismiss_hotkey" in named
    assert dash.NESTED_HOTKEYS["dismiss_hotkey"] == "notify.dismiss_hotkey"

    # An unread notification becomes a row with a verb on it; a seen one
    # is not waiting on anybody and does not.
    class Fake:
        def __init__(self, items):
            self._items = items

        def recent(self, n=30):
            return list(self._items)[:n]

    two = [{"id": 2, "at": "2026-09-03T14:22:05", "source": "claude-code",
            "label": "Claude Code", "kind": "done",
            "title": "קלוד סיים — Claude finished", "seen": False},
           {"id": 1, "at": "2026-09-03T13:00:00", "source": "cli",
            "kind": "info", "title": "A Latin title", "seen": True}]
    with _window() as board:
        if board is None:
            return
        board._notify_store = lambda: Fake(two)
        rows = board._waiting_notify()
        assert len(rows) == 1, rows
        assert rows[0]["kind"] == "notify"
        assert "Claude Code" in rows[0]["eyebrow"]
        assert [label for label, _kind, _do in rows[0]["buttons"]] == \
            ["Go there", "✕"]
        board._notify_store = lambda: Fake([])
        assert board._waiting_notify() == []

        class Boom:
            def recent(self, n=30):
                raise OSError("broken file")

        board._notify_store = lambda: Boom()
        assert board._waiting_notify() == []      # a broken file, no pile


def test_a_held_finish_is_said_on_the_waiting_place_and_never_counted_twice():
    """A finish waiting for its session to go quiet is unread and NOT on
    the screen. The pile cannot show it — there is nothing to answer yet
    — so the one faint line under the card is where it is said, and it
    has to paint on every shape of status, including a running app whose
    code predates the door and sends no section at all."""
    with _window() as board:
        if board is None:
            return
        board._show("Home")
        line = board.parts["held_line"]
        board.running = False
        board._paint_held()
        assert line.cget("text") == "", "nothing running holds nothing"
        board.running = True
        board.status = {}                 # an app that predates the door
        board._paint_held()
        assert line.cget("text") == ""
        board.status = {"notify": {"enabled": True, "unread": 3, "held": 2}}
        board._paint_held()
        assert "2 finishes held" in line.cget("text")
        assert "not on your screen" in line.cget("text")
        board.status = {"notify": {"enabled": True, "unread": 1, "held": 1}}
        board._paint_held()
        assert "1 finish held" in line.cget("text"), line.cget("text")
        board.status = {"notify": {"enabled": True, "unread": 0,
                                   "held": "nonsense"}}
        board._paint_held()               # must not raise
        assert line.cget("text") == ""


def test_the_waiting_pile_draws_the_four_stores_and_notices_they_moved():
    """The pile IS the files: four stores, newest first, a row each with
    its own verb, and a redraw only when one of the four stamps moved —
    because a rebuild every second would cost the caret in whatever is
    being typed into it. A store that raises contributes nothing and the
    other three still draw."""
    import widgets as widgets_mod

    class Fake:
        def __init__(self, items, boom=False):
            self._items, self._boom = items, boom

        def _check(self):
            if self._boom:
                raise OSError("broken file")

        def recent(self, n=30):
            self._check()
            return list(self._items)[:n]

        def pending(self):
            self._check()
            return [i for i in self._items if i.get("status") == "pending"]

        def items(self, status=None):
            self._check()
            return [i for i in self._items
                    if status is None or i.get("status") == status]

    notify = [{"id": 2, "at": "2026-09-03T14:22:05", "source": "claude-code",
               "label": "Claude Code", "kind": "done",
               "title": "קלוד סיים — Claude finished", "seen": False}]
    review = [{"id": "r1", "when": "2026-09-03 15:00:00",
               "status": "pending", "proposed": "הטקסט הזה נכון עכשיו.",
               "changes": [{"before": "נכן", "after": "נכון",
                            "why": "הגייה דומה"}]}]
    problems = [{"id": "p1", "when": "2026-09-03 09:00:00",
                 "status": "open", "what": "A card stayed on the screen."}]
    with _window() as board:
        if board is None:
            return
        board._show("Home")
        board._notify_store = lambda: Fake(notify)
        board._review_store = lambda: Fake(review)
        board._problems_store = lambda: Fake(problems)
        items = board._waiting_items()
        assert [i["kind"] for i in items] == ["review", "notify", "problem"],\
            [i["kind"] for i in items]        # newest first, whatever it is
        board._pile_stamp = object()
        board._poll_waiting()
        rows = [w for w in board.parts["pile_list"].inner.winfo_children()
                if isinstance(w, widgets_mod.PileRow)]
        assert len(rows) == 3, len(rows)
        assert board.parts["pile_card"].winfo_manager() == "pack"
        assert "Three things" in board.parts["waiting_head"].cget("text")
        # Exactly one gold button on the surface: Yes on a second reading.
        golds = [b for row in rows for b in row.buttons.values()
                 if isinstance(b, widgets_mod.ToneButton)]
        assert len(golds) == 1, len(golds)

        # The stamp is remembered: the same four files do not redraw.
        board._notify_store = lambda: Fake([])
        board._review_store = lambda: Fake([])
        board._problems_store = lambda: Fake([])
        board._poll_waiting()
        assert len([w for w in board.parts["pile_list"].inner.winfo_children()
                    if isinstance(w, widgets_mod.PileRow)]) == 3, \
            "redrew without a file moving"
        board._pile_stamp = object()
        board._poll_waiting()
        assert [w for w in board.parts["pile_list"].inner.winfo_children()
                if isinstance(w, widgets_mod.PileRow)] == []
        assert not board.parts["pile_card"].winfo_manager(), \
            "an empty pile shows no card at all"
        assert "Nothing is waiting" in board.parts["waiting_head"].cget("text")

        # One broken file must not cost the other two their rows.
        board._notify_store = lambda: Fake(notify, boom=True)
        board._review_store = lambda: Fake(review)
        board._problems_store = lambda: Fake(problems)
        board._pile_stamp = object()
        board._poll_waiting()              # must not raise
        assert len([w for w in board.parts["pile_list"].inner.winfo_children()
                    if isinstance(w, widgets_mod.PileRow)]) == 2


# ---------------------------------------------- report a problem
#
# One line he types (or dictates) and the app attaches the rest. The
# store is review.Store's shape for review.Store's reasons, so the first
# three tests below are the review-store tests' twins; the two
# guarantees that belong to this feature alone are that an OPEN report
# is never thrown away, and that a transcript aimed at the report box
# never reaches the cursor.


def test_the_problems_store_keeps_a_report_until_someone_answers_it() -> None:
    """review.Store's trim rule with the stakes reversed: answered
    reports age out at `keep`, and an open one is never dropped at any
    setting — a question nobody has answered is not a kilobyte worth
    saving. A resolution is remembered with its date and who gave it, and
    it can be taken back."""
    import shutil

    import problems as problems_mod

    tmp = Path(tempfile.mkdtemp(prefix="problems-"))
    try:
        store = problems_mod.Store(tmp / problems_mod.STORE_NAME)
        assert store.items() == [] and store.summary()["total"] == 0
        assert store.stamp() == (), "no file yet is a state, not an error"
        asking = [store.add({"text": f"open {n}", "where": "recordings",
                             "kind": "wrong"})["id"] for n in (1, 2)]
        answered = [store.add({"text": f"answered {n}",
                               "kind": "slow"})["id"] for n in (1, 2, 3)]
        assert len(set(asking + answered)) == 5, "two reports share an id"
        assert store.stamp() != (), "the file is on disk"

        first = store.get(asking[0])
        assert first["status"] == problems_mod.OPEN and first["at"]
        assert first["resolved"] is None and first["kind"] == "wrong"
        assert first["where"] == "recordings" and first["by"] == ""
        assert first["dictation"] == {} and first["env"] == {} \
            and first["shot"] == "", first

        assert store.resolve(answered[0], problems_mod.FIXED, by="claude")
        done = store.get(answered[0])
        assert done["status"] == problems_mod.FIXED and done["by"] == "claude"
        assert done["resolved"], "a resolution with no date on it"
        summary = store.summary()
        assert summary["total"] == 5 and summary[problems_mod.OPEN] == 4 \
            and summary[problems_mod.FIXED] == 1, summary
        assert summary["where"] == {"recordings": 2, "?": 2}, summary["where"]
        assert summary["oldest_open"], summary

        # Answered by mistake: reopening clears the date and asks again.
        assert store.resolve(answered[0], problems_mod.OPEN)
        back = store.get(answered[0])
        assert back["status"] == problems_mod.OPEN and back["resolved"] is None
        assert store.summary()[problems_mod.OPEN] == 5

        for ident in answered:
            assert store.resolve(ident, problems_mod.CLOSED, by="weekly read")
        # THE RULE. One resolved report may be kept and three exist, so
        # two age out — and every open one is still there afterwards.
        store.keep = 1
        fresh = store.add({"text": "filed after the trim"})["id"]
        alive = {i["id"] for i in store.items()}
        assert set(asking) | {fresh} <= alive, sorted(alive)
        assert len(store.items(problems_mod.CLOSED)) == 1, store.items()
        # keep = 0 keeps NO answered report and still keeps every open one.
        store.keep = 0
        assert store.resolve(asking[0], problems_mod.FIXED)
        assert store.items(problems_mod.FIXED) == []
        assert store.items(problems_mod.CLOSED) == []
        assert {i["id"] for i in store.items()} == {asking[1], fresh}, \
            store.items()

        assert store.resolve("no-such-report", problems_mod.FIXED) is False
        assert store.resolve(fresh, "sort-of-fixed") is False, \
            "an unknown status must change nothing"
        assert store.get(fresh)["status"] == problems_mod.OPEN
        try:
            problems_mod.clean({"text": "   \n\t  "})
        except ValueError:
            pass
        else:
            raise AssertionError("a report with no line in it was accepted")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_a_corrupt_problems_json_does_not_stop_a_report() -> None:
    """The vocabulary's rule, applied to the bug list: a file that will
    not parse is read as empty and still takes the next report. A broken
    store must cost reports, never dictation."""
    import shutil

    import problems as problems_mod

    tmp = Path(tempfile.mkdtemp(prefix="problems-"))
    try:
        path = tmp / problems_mod.STORE_NAME
        path.write_text("{not json at all", "utf-8")
        store = problems_mod.Store(path)
        assert store.items() == [] and store.summary()["total"] == 0
        filed = store.add({"text": "and this is what was wrong",
                           "kind": "broken"})
        assert filed["id"] and filed["status"] == problems_mod.OPEN
        assert [i["id"] for i in problems_mod.Store(path).items()] \
            == [filed["id"]], "the report did not survive the bad file"
        # A list where the object belongs, and rows that are not objects.
        path.write_text("[1, 2, 3]", "utf-8")
        assert problems_mod.Store(path).items() == []
        path.write_text('{"items": ["nope", null, 7, {"id": "x", '
                        '"status": "open", "text": "y"}]}', "utf-8")
        assert [i["id"] for i in problems_mod.Store(path).items()] == ["x"]
        # And the weekly read of a store that was broken is still a file.
        path.write_text("}{", "utf-8")
        md = problems_mod.digest(problems_mod.Store(path),
                                tmp / problems_mod.DIGEST_NAME)
        assert md.is_file() and "Nothing open." in md.read_text("utf-8")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_a_report_he_deletes_leaves_the_list_and_keeps_its_evidence(
) -> None:
    """remove() is the only thing in this store that loses a report, and
    it loses ONLY the report.

    The wav copied into problems\\ and the screenshot pinned beside it
    are left where they are — the same as when _trim ages an answered
    report out — because a row leaving a list and a recording of his
    voice becoming unrecoverable are not the same act, and this store has
    already paid for the second one once (2026-09-04, a cleanup that did
    not ask).

    What comes back is the item, not a bool: the surface that deleted it
    has to be able to say what it just deleted.
    """
    import shutil

    import problems as problems_mod

    tmp = Path(tempfile.mkdtemp(prefix="problems-"))
    try:
        store = problems_mod.Store(tmp / problems_mod.STORE_NAME)
        folder = tmp / problems_mod.FOLDER_NAME
        folder.mkdir()
        (folder / "shot.jpg").write_bytes(b"not really a jpeg")
        keep = store.add({"text": "this one stays", "kind": "wrong"})["id"]
        drop = store.add({"text": "and this one goes", "kind": "idea",
                          "shot": f"{problems_mod.FOLDER_NAME}/shot.jpg"})

        assert store.remove("no-such-report") is None, \
            "an id that is not there must change nothing"
        assert len(store.items()) == 2

        gone = store.remove(drop["id"])
        assert gone is not None and gone["id"] == drop["id"]
        assert gone["text"] == "and this one goes", gone
        assert [i["id"] for i in store.items()] == [keep], store.items()
        assert store.get(drop["id"]) is None
        assert store.summary()["total"] == 1
        assert (folder / "shot.jpg").is_file(), \
            "deleting a report took its screenshot with it"
        # And it is gone off the disk, not just out of this handle.
        assert [i["id"] for i in
                problems_mod.Store(tmp / problems_mod.STORE_NAME).items()] \
            == [keep]
        assert store.remove(drop["id"]) is None, "deleted twice"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_a_report_the_routine_thinks_is_fixed_stays_open_and_says_fixed_maybe(
) -> None:
    """The weekly routine closed three of his reports on 2026-09-12 at
    04:12 because changes pushed the week before looked like they fixed
    them — "he pushed" taken for "he checked". His decision: it writes
    "fix?" in a different colour and asks; only his confirmation makes it
    Fixed.

    So suggest() is a MARK and not a resolution. The report stays OPEN —
    the same open count, the same open list — and carries who thinks so,
    when, and one line saying what to try. It refuses an answered report
    and an unknown one, a second claim replaces the first, unsuggest()
    takes it off, and resolve() takes it off whatever it moves the
    report to, so a reopened report starts clean. A new report never has
    one, whatever its caller put in the dict. The digest names it, with
    the note, because the agent reading problems.md and the owner
    reading the tab must be talking about the same thing.
    """
    import shutil

    import problems as problems_mod

    tmp = Path(tempfile.mkdtemp(prefix="problems-"))
    try:
        store = problems_mod.Store(tmp / problems_mod.STORE_NAME)
        # A caller cannot smuggle a mark onto a new report.
        planted = store.add({"text": "the recordings tab shows yesterday",
                             "kind": "wrong", "where": "recordings",
                             problems_mod.MAYBE: {"by": "me", "note": "x"}})
        ident = planted["id"]
        assert problems_mod.MAYBE not in planted, planted
        assert problems_mod.MAYBE not in store.get(ident)
        assert problems_mod.suggested(planted) is None
        other = store.add({"text": "another one, still plain",
                           "kind": "slow"})["id"]
        shut = store.add({"text": "answered already"})["id"]
        assert store.resolve(shut, problems_mod.CLOSED, by="dashboard")

        # Refused where there is nothing to suggest about.
        assert store.suggest(shut, by="weekly", note="n") is False, \
            "a closed report took a fixed? mark"
        assert store.suggest("no-such-report", by="weekly") is False
        assert problems_mod.MAYBE not in store.get(shut)
        assert store.summary()[problems_mod.MAYBE] == 0

        # The mark, cleaned like every other line, with the status
        # exactly where it was.
        assert store.suggest(ident, by="weekly " + "x" * 60,
                             note="  הכרטיס\x1b  עודכן,\n נסה   שוב  ")
        marked = store.get(ident)
        assert marked["status"] == problems_mod.OPEN, marked
        assert marked["resolved"] is None and marked["by"] == ""
        mark = marked[problems_mod.MAYBE]
        assert mark["note"] == "הכרטיס עודכן, נסה שוב", mark
        assert mark["by"].startswith("weekly x") and \
            len(mark["by"]) == problems_mod.BY_MAX, mark
        assert mark["at"][:4].isdigit() and "T" in mark["at"], mark
        assert problems_mod.suggested(marked) == mark
        assert len(store.get(ident)[problems_mod.MAYBE]["note"]) \
            <= problems_mod.MAYBE_MAX
        assert store.suggest(ident, by="w", note="a" * 500)
        assert len(store.get(ident)[problems_mod.MAYBE]["note"]) \
            == problems_mod.MAYBE_MAX, "the note is not cut"
        summary = store.summary()
        assert summary[problems_mod.OPEN] == 2, "a marked report left open"
        assert summary[problems_mod.MAYBE] == 1, summary
        assert summary[problems_mod.FIXED] == 0, "a mark counted as fixed"
        assert [i["id"] for i in store.items(problems_mod.OPEN)] \
            == [other, ident], "a marked report left the open list"

        # A second claim replaces the first: the newer one is about the
        # code as it is now.
        assert store.suggest(ident, by="session", note="second look")
        assert store.get(ident)[problems_mod.MAYBE]["by"] == "session"
        assert store.get(ident)[problems_mod.MAYBE]["note"] == "second look"
        assert store.summary()[problems_mod.MAYBE] == 1, "counted twice"

        # The digest says it, on the head line and under the text.
        md = problems_mod.digest(store, tmp / problems_mod.DIGEST_NAME)
        text = md.read_text("utf-8")
        assert "2 open · 1 fixed? · 0 fixed · 1 closed" in text, text
        head = next(ln for ln in text.splitlines() if f"`{ident}`" in ln)
        assert "fixed?" in head, head
        assert "  - fixed? (session, " in text and "second look" in text, text
        plain = next(ln for ln in text.splitlines() if f"`{other}`" in ln)
        assert "fixed?" not in plain, plain

        # Withdrawn, and nothing else about the report moved.
        assert store.unsuggest(ident) is True
        assert problems_mod.MAYBE not in store.get(ident)
        assert store.get(ident)["status"] == problems_mod.OPEN
        assert store.unsuggest(ident) is False, "nothing left to take off"
        assert store.unsuggest("no-such-report") is False
        assert store.summary()[problems_mod.MAYBE] == 0
        text = problems_mod.digest(store, tmp / problems_mod.DIGEST_NAME) \
            .read_text("utf-8")
        assert "fixed?" not in text, text

        # resolve() clears it, whichever way it goes.
        for status in (problems_mod.FIXED, problems_mod.CLOSED,
                       problems_mod.OPEN):
            assert store.resolve(ident, problems_mod.OPEN)
            assert store.suggest(ident, by="weekly", note="try it")
            assert store.resolve(ident, status, by="dashboard"), status
            after = store.get(ident)
            assert after["status"] == status, after
            assert problems_mod.MAYBE not in after, (status, after)
            assert problems_mod.suggested(after) is None
        assert store.summary()[problems_mod.MAYBE] == 0

        # And a mark somebody typed into the file by hand, on an answered
        # report or in the wrong shape, is a report without a mark.
        assert problems_mod.suggested({"status": problems_mod.CLOSED,
                                       problems_mod.MAYBE: {"by": "x"}}) \
            is None
        assert problems_mod.suggested({problems_mod.MAYBE: True}) is None
        assert problems_mod.suggested({problems_mod.MAYBE: {}}) is None
        assert problems_mod.suggested("not a report") is None
        loose = problems_mod.suggested({problems_mod.MAYBE: {"note": 7}})
        assert loose == {"by": "", "at": "", "note": "7"}, loose
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_another_process_reads_the_problems_json_this_one_wrote() -> None:
    """The lock file and the one rename, which is what lets the app file a
    report while the dashboard answers one. Four threads through two
    handles and then a second interpreter all write the same store: every
    report survives (an unserialised read-modify-write would drop most of
    them), no id is handed out twice, the file parses at the end and no
    temp file is left behind.

    A reader never sees half a file because the write is a rename, and the
    temp name carries the pid — a SHARED temp name is what cost
    config.toml the whole file, 4 runs out of 4, so both halves of that
    are read off _save rather than guessed at. Deliberately not proved by
    reading in a loop while the writes run: on Windows an open read handle
    makes os.replace itself fail, which measures this machine's file
    sharing and not this store's."""
    import inspect
    import shutil
    import subprocess

    import problems as problems_mod

    saving = inspect.getsource(problems_mod.Store._save)
    assert "os.getpid()" in saving and ".tmp" in saving, saving
    assert "os.replace(tmp, self.path)" in saving, saving
    holding = inspect.getsource(problems_mod.Store._locked)
    assert "msvcrt.locking" in holding and "LK_NBLCK" in holding

    tmp = Path(tempfile.mkdtemp(prefix="problems-"))
    try:
        path = tmp / problems_mod.STORE_NAME
        app = problems_mod.Store(path)          # the running app's handle
        board = problems_mod.Store(path)        # the dashboard's own

        def file(store, n) -> None:
            for i in range(3):
                store.add({"text": f"thread {n} report {i}",
                           "kind": "broken"})

        writers = [threading.Thread(target=file,
                                    args=(app if n % 2 else board, n),
                                    name=f"problems-writer-{n}")
                   for n in range(4)]
        for t in writers:
            t.start()
        for t in writers:
            t.join(30)
            assert not t.is_alive(), "a writer never got the lock"

        ids = [i["id"] for i in app.items()]
        assert len(ids) == 12, ids
        assert len(set(ids)) == 12, "an id was handed out twice"

        # A genuinely separate interpreter, taking the same lock.
        code = ("import sys; sys.path.insert(0, sys.argv[1]);"
                "import problems;"
                "print(problems.Store(sys.argv[2])"
                ".add({'text': 'filed by another process'})['id'])")
        out = subprocess.run([sys.executable, "-c", code, str(REPO),
                              str(path)], capture_output=True,
                             encoding="utf-8", errors="replace", timeout=120)
        assert out.returncode == 0, (out.stdout, out.stderr)
        theirs = out.stdout.strip()
        assert theirs, out.stderr
        assert board.get(theirs) is not None, \
            "this process cannot see what the other one wrote"
        assert len(board.items()) == 13, board.items()
        assert json.loads(path.read_text("utf-8"))["version"] == 1
        assert not list(tmp.glob("*.tmp")), sorted(p.name for p in
                                                   tmp.glob("*.tmp"))
        assert path.with_suffix(".lock").is_file(), "no lock file was made"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_problems_settings_are_in_the_real_config_and_checked_at_load(
        ) -> None:
    """[problems] ships in config.toml, the settings screen reads it off
    the same file, the key is registered where every tap key must be, and
    the two values that can be wrong are refused AT LOAD rather than at
    the moment he presses the key: `esc` already discards a locked
    recording, and keep_resolved outside 0..2000 is either a store that
    keeps nothing or a problems.md nobody can read."""
    import re
    import shutil

    import main as main_mod
    import problems as problems_mod
    import settings as settings_mod

    cfg = config_mod.load(REPO / "defaults.toml")
    p = cfg.problems
    assert p.enabled and p.shot and p.keep_audio
    assert p.keep_resolved == problems_mod.KEEP_RESOLVED == 200, p
    assert config_mod.PROBLEMS_KEEP_RESOLVED_MAX == 2000
    assert cfg.report_hotkey == p.hotkey == "ctrl+alt+r"
    fields = dict(config_mod.HOTKEY_FIELDS)
    assert fields["report_hotkey"].endswith("(tap)"), fields["report_hotkey"]
    assert "report_hotkey" in config_mod.CHORD_FIELDS
    moved = config_mod.with_field(cfg, "report_hotkey", "ctrl+alt+j")
    assert moved.problems.hotkey == "ctrl+alt+j"
    assert dataclasses.replace(moved, problems=p) == cfg, \
        "with_field must change nothing else"
    clash = config_mod.with_field(cfg, "report_hotkey", cfg.screens_hotkey)
    try:
        config_mod.check_hotkeys(clash)
        assert False, "the same chord on two keys must be refused"
    except config_mod.ConfigError as e:
        assert "report_hotkey" in str(e) or "screens_hotkey" in str(e), e
    # The key exists only while the feature does — in the tap table and
    # on the card that lists the keys, which have to be the same set.
    _h, taps, _l, _p = main_mod.App.bindings(cfg)
    assert taps.get(parse_binding("ctrl+alt+r")) == "problem_report", taps
    assert ("problem_report", "ctrl+alt+r") in hint_mod.bindings(cfg)
    assert hint_mod.LABELS["problem_report"], "the card needs a name for it"
    off = dataclasses.replace(cfg, problems=dataclasses.replace(
        p, enabled=False))
    _h, taps_off, _l, _p = main_mod.App.bindings(off)
    assert "problem_report" not in taps_off.values(), taps_off
    assert "problem_report" not in dict(hint_mod.bindings(off))
    assert {a for a, _b in hint_mod.bindings(cfg)} == set(taps.values()), \
        "hint.bindings and the tap table must be the same set"

    tmp = Path(tempfile.mkdtemp(prefix="problems-config-"))
    try:
        path = tmp / "config.toml"
        base = (REPO / "defaults.toml").read_text("utf-8")
        for old, new, needle in (
                ('report_hotkey = "ctrl+alt+r"', 'report_hotkey = "esc"',
                 "report_hotkey"),
                ("\nkeep_resolved = 200", "\nkeep_resolved = 5000",
                 "problems.keep_resolved"),
                ("\nkeep_resolved = 200", "\nkeep_resolved = -1",
                 "problems.keep_resolved")):
            assert base.count(old) == 1, f"{old} is not one writable line"
            path.write_text(base.replace(old, new), "utf-8")
            try:
                config_mod.load(path)
            except config_mod.ConfigError as e:
                assert needle in str(e), (new, str(e))
            else:
                raise AssertionError(f"{new.strip()} loaded happily")
        # 0 and the ceiling are both legal: keep nothing, or keep the lot.
        for good in ("\nkeep_resolved = 0", "\nkeep_resolved = 2000"):
            path.write_text(base.replace("\nkeep_resolved = 200", good),
                            "utf-8")
            assert config_mod.load(path).problems.keep_resolved == \
                int(good.split("= ")[1])
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    sections = {s.name: s for s in settings_mod.read(REPO / "defaults.toml")}
    assert "problems" in sections, list(sections)
    # A SET, like the [notify] test one screen up, and the order was
    # never buying anything: nothing in this program reads these keys by
    # position, and the one place the order in the FILE matters — a
    # setting drawn on the line it sits on — is already held by
    # test_every_line_of_config_toml_is_a_setting_the_screen_can_draw.
    # Exact-order equality here only meant that four new keys broke a
    # test about `esc` and keep_resolved.
    assert {s.key for s in sections["problems"].settings} == {
        "enabled", "report_hotkey", "shot", "keep_audio", "keep_resolved",
        "x", "y", "card_x", "card_y"}, \
        sorted(s.key for s in sections["problems"].settings)
    keep = settings_mod.find(list(sections.values()),
                             "problems.keep_resolved")
    assert keep is not None and keep.kind == "int"
    assert "never trimmed" in keep.help or "never" in keep.help, keep.help
    # THE TWO DRAGGED POSITIONS, and they are two because they are two
    # windows: x/y is the floating card the report key opens, card_x/card_y
    # the dashboard's own box. Both default to the sentinel and both are
    # deliberately UNVALIDATED — hint.x, review.x and notify.x are too,
    # because every other int is a real coordinate on somebody's desktop
    # and this machine's virtual screen starts at x = -1920, which is why
    # the sentinel cannot be -1.
    assert config_mod.HINT_UNSET == -100000
    # THE SENTINEL IS THE CODE'S DEFAULT, not a promise about the file.
    # The app WRITES these back the moment the card is dragged (it did
    # on 2026-09-07 at 16:21), exactly as it does for [hint], [review]
    # and [notify] — whose dragged positions have sat in the file for
    # weeks with no test minding. Asserting the sentinel in config.toml
    # made using the feature a red suite.
    blank = config_mod.ProblemsConfig()
    for field in ("x", "y", "card_x", "card_y"):
        assert getattr(blank, field) == config_mod.HINT_UNSET, field
        assert isinstance(getattr(p, field), int), field
        assert settings_mod.find(list(sections.values()),
                                 f"problems.{field}").kind == "int", field
    tmp = Path(tempfile.mkdtemp(prefix="problems-drag-"))
    try:
        path = tmp / "config.toml"
        base = (REPO / "defaults.toml").read_text("utf-8")
        head = base.index("\n[problems]\n")
        tail = base.index("\n[", head + 3)
        section = base[head:tail]
        # WHATEVER THE LINE HOLDS, not the sentinel: the app writes
        # these back the moment the card is dragged, so a fixture built
        # by replacing "-100000" only works until the feature is used
        # once (it stopped working on 2026-09-07 at 16:21).
        for field, value in (("x", -1920), ("y", -3),
                             ("card_x", 8000), ("card_y", 0)):
            pattern = re.compile(rf"^{field} = -?\d+", re.M)
            section, hits = pattern.subn(f"{field} = {value}", section)
            assert hits == 1, (field, hits)
        path.write_text(base[:head] + section + base[tail:], "utf-8")
        got = config_mod.load(path).problems
        assert (got.x, got.y, got.card_x, got.card_y) == \
            (-1920, -3, 8000, 0), got
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_report_boxs_chips_are_problems_kinds_and_nothing_else() -> None:
    """KINDS is the only list of the words. The dashboard builds its chips
    straight off the tuple rather than spelling them again, clean()
    admits nothing that is not in it, and "other" is last and is never
    what a report lands under by default — a report filed under "other"
    says nothing about what is broken, which is the whole reason for
    asking what kind it is."""
    import inspect
    import shutil

    import dashboard as dash
    import problems as problems_mod

    assert problems_mod.KINDS == ("wrong", "broken", "slow", "idea", "other")
    assert problems_mod.KINDS[-1] == "other", "the fallback is not last"
    assert problems_mod.KINDS[0] == "wrong" != problems_mod.KINDS[-1], \
        '"other" must never be the default'
    for kind in problems_mod.KINDS:
        assert problems_mod.clean({"text": "x", "kind": kind})["kind"] == kind
    assert problems_mod.clean({"text": "x", "kind": "OTHER"})["kind"] \
        == "other", "the word, any case"
    for junk in ("", None, "nonsense", 7, "wrongish", ["wrong"]):
        assert problems_mod.clean({"text": "x", "kind": junk})["kind"] \
            == problems_mod.KINDS[0], junk
    src = inspect.getsource(dash.Dashboard._report)
    assert 'getattr(module, "KINDS"' in src, \
        "the chips are a hand-written list, so a sixth kind will not show"
    # problem_card paints the hotkey card and the dashboard assembles the
    # same card out of widgets, so every number and every word they share
    # has exactly one home. These are the copies that were found drifting.
    import overlay as overlay_mod

    import problem_card as pc
    assert pc.card_for("x")["kinds"] == problems_mod.KINDS, \
        "the painter has its own list of kinds"
    assert overlay_mod._TEXT_MAX == problems_mod.TEXT_MAX == 600, \
        "the field stops taking words at a different length than clean() "\
        "cuts at, so the tail goes missing in a report he cannot edit"
    for name in ("FIELD_FONT", "FIELD_FONT_LINE", "FIELD_LINE_H",
                 "FIELD_LINES_MIN", "FIELD_LINES_MAX", "FIELD_PAD_X",
                 "FIELD_PAD_Y", "FIELD_RADIUS"):
        assert getattr(dash, name) == getattr(pc, name), name
    assert dash.REPORT_HINT == pc.HINT and dash.REPORT_KEYS == pc.KEYS, \
        "the two surfaces of one feature phrase it differently"
    assert pc.FIELD_LINE_H > pc.FIELD_FONT_LINE, \
        "spacing3 would be negative and the painted well would not fit"
    assert pc.FIELD_LINES_MIN < pc.FIELD_LINES_MAX
    # THE DASHBOARD BOX IS DRAGGED TOO, and its two fixed bugs are named
    # here rather than driven, because a grabbed modal in the suite's own
    # interpreter is a synthetic-input test and the interactive half of
    # this gesture is proved on the hotkey card instead
    # (test_the_report_card_is_dragged_by_its_face_and_remembers_where).
    # Both of these were real and both are one deleted line away from
    # coming back:
    #
    # 1. `event.widget` is this Toplevel when the GRAB delivered the
    #    press, whatever the pointer is over — measured on the same press
    #    twice, reported as the Label once and as the Toplevel once
    #    depending on whether the app was already active. So which widget
    #    was pressed is read off the SCREEN COORDINATES, and a press on a
    #    chip while the dashboard is in the background stays a press on a
    #    chip instead of grabbing the margin.
    assert "winfo_containing(event.x_root, event.y_root)" in src, \
        "event.widget is trusted alone again: under the grab it is the " \
        "Toplevel, and every press would read as a drag of the chrome"
    assert "hit is top" in src, "nothing falls back to the coordinates"
    # 2. A repaint MID-DRAG re-applies the remembered origin, and while
    #    that origin was the one the drag started from, the card snapped
    #    back the moment anything repainted under the pointer — the field
    #    border lighting down is one such repaint.
    assert 'at["x"], at["y"] = x, y' in src, \
        "the drag origin does not follow the drag: a repaint mid-drag " \
        "snaps the card back to where the drag started"
    # A press is sorted by where it LANDED, so a drag can never read as a
    # cancel and a cancel can never arm a drag.
    assert "def pressed" in src and "def dragging" in src \
        and "def dropped" in src, "the three halves of the gesture"
    assert src.index("finish(None)") < src.index("winfo_containing"), \
        "outside the card is decided before which widget was pressed"
    tmp = Path(tempfile.mkdtemp(prefix="problems-"))
    try:
        store = problems_mod.Store(tmp / problems_mod.STORE_NAME)
        assert store.add({"text": "no kind given"})["kind"] \
            == problems_mod.KINDS[0]
        assert store.add({"text": "junk kind",
                          "kind": "urgent"})["kind"] == problems_mod.KINDS[0]
        assert store.add({"text": "an idea",
                          "kind": "idea"})["kind"] == "idea"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_a_problem_report_survives_losing_its_screenshot() -> None:
    """thumb() is the one place that decides how big an attached picture
    is, and the one place that has to survive it being gone: PNG bytes a
    Tk row can show while the file is there, None for a report that never
    had one, for a file that has been deleted and for anything Pillow will
    not open. A missing picture is a row without a picture — never an
    exception into a redraw."""
    import io
    import shutil
    import struct

    import problems as problems_mod
    from PIL import Image

    tmp = Path(tempfile.mkdtemp(prefix="problems-"))
    try:
        big = Image.new("RGB", (1600, 900), (40, 60, 90))
        buf = io.BytesIO()
        big.save(buf, format="JPEG", quality=80)
        item = problems_mod.record(
            tmp, {"text": "the recordings tab shows yesterday's count",
                  "where": "recordings", "kind": "wrong"},
            jpeg=buf.getvalue())
        store = problems_mod.Store(tmp / problems_mod.STORE_NAME)
        assert item["shot"] == f"problems/{item['id']}.jpg", item["shot"]
        # The store, the app directory and problems\\ are all things a
        # caller plausibly holds, and none of them has to be converted.
        shot = problems_mod.shot_path(store, item)
        assert shot == problems_mod.shot_path(tmp, item) \
            == problems_mod.shot_path(tmp / problems_mod.FOLDER_NAME,
                                      item["shot"])
        assert shot.is_file(), shot
        png = problems_mod.thumb(store, item)
        assert png[:8] == b"\x89PNG\r\n\x1a\n", png[:8]
        w, h = struct.unpack(">II", png[16:24])          # the IHDR
        assert max(w, h) == problems_mod.THUMB_MAX == 220, (w, h)
        assert (w, h) == (220, 124), (w, h)              # 1600x900 kept
        assert problems_mod.thumb(store, item) is png, "decoded twice"
        assert max(struct.unpack(
            ">II", problems_mod.thumb(store, item, max_side=64)[16:24])) == 64

        # A report with no picture, which is most of them.
        plain = store.add({"text": "an idea with nothing attached",
                           "kind": "idea"})
        assert plain["shot"] == ""
        assert problems_mod.shot_path(store, plain) is None
        for nothing in (plain, {}, None, {"shot": "   "}):
            assert problems_mod.thumb(store, nothing) is None, nothing

        # Deleted from under the cache (the mtime is in the key, so the
        # stat comes first), never written, and not a picture at all.
        shot.unlink()
        assert problems_mod.thumb(store, item) is None, "deleted"
        assert problems_mod.thumb(store, item, max_side=97) is None
        gone = problems_mod.shot_path(store, {"shot": "problems/nope.jpg"})
        assert gone is not None and not gone.exists()
        assert problems_mod.thumb(store, {"shot": "problems/nope.jpg"}) is None
        junk = tmp / problems_mod.FOLDER_NAME / "junk.jpg"
        junk.write_bytes(b"not a jpeg at all")
        assert problems_mod.thumb(store, {"shot": "problems/junk.jpg"}) is None
        # The digest still names the shot it can no longer show, because
        # the path is the only way back to a picture that was restored.
        md = problems_mod.digest(store, tmp / problems_mod.DIGEST_NAME)
        assert item["shot"] in md.read_text("utf-8")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_copy_that_travels_is_the_toggles_and_nothing_else() -> None:
    """7.6, 8.4, 8.8: a report is filed here as always; "Send" builds a
    SECOND thing from the stored row and four toggles — the exact row
    the server takes and the files 8.4 names — and the Preview and the
    outbox come from the same call. Off toggles leave nothing behind
    (no screenshot path, no transcript column, the env cut to the
    machine facts); the outbox holds COPIES, so deleting the local
    evidence cannot pull a queued upload apart; the row remembers its
    state and sb.py's verdicts flow back into it."""
    import shutil

    import problems as problems_mod

    tmp = Path(tempfile.mkdtemp(prefix="problems-travel-"))
    try:
        recent = tmp / "recent"
        recent.mkdir()
        wav = recent / "20260918-231500.wav"
        wav.write_bytes(RIFF)
        wav.with_suffix(".json").write_text(json.dumps(
            {"seconds": 2.1, "backend": "local", "language": "he",
             "words": [{"w": "שלום", "p": 0.91}]}), "utf-8")
        last = {"raw": "שלום עולם gsk_abcdefghijklmnopqrstuvwxyz0123456789ABCDEF",
                "final": "שלום, עולם.", "when": "2026-09-18 23:15:00",
                "wav": str(wav)}
        item = problems_mod.record(
            tmp, {"text": "המילה האחרונה נעלמה", "where": "dictation",
                  "kind": "wrong"}, last=last, jpeg=b"\xff\xd8\xff" + b"j" * 500)
        store = problems_mod.Store(tmp / problems_mod.STORE_NAME)
        # the local copy is untouched by any of this
        assert item["shot"] and item["dictation"]["wav"] and item["env"]
        assert "sent" not in item

        defaults = problems_mod.attach_defaults("wrong")
        assert defaults == {"shot": False, "recording": False,
                            "transcript": True, "settings": True}
        assert problems_mod.attach_defaults("idea")["transcript"] is False
        sizes = problems_mod.evidence(item, tmp)
        assert sizes["shot"] == 503 and sizes["recording"] == len(RIFF), sizes
        assert sizes["transcript"] > 0 and sizes["settings"] >= 2, sizes
        before = problems_mod.sizes_before_filing(
            jpeg=b"\xff" * 77, last=last, app_dir=tmp)
        assert before["shot"] == 77 and before["recording"] == len(RIFF)

        # everything off: the row and nothing else
        row, files = problems_mod.payload(
            item, {n: False for n in problems_mod.ATTACH}, app_dir=tmp)
        assert files == [] and row["attachments"] == []
        assert "dictation_raw" not in row and "dictation_final" not in row
        assert set(row["env"]) <= set(problems_mod.ENV_ALWAYS), row["env"]
        assert row["kind"] == "wrong" and row["place"] == "dictation"
        assert row["text"] == "המילה האחרונה נעלמה"
        assert set(row) <= {"id", "kind", "place", "text", "app_version",
                            "os_build", "tier", "env", "attachments"}
        # everything on: the three files 8.4 names, the two columns, the
        # whitelist env — and the key in the raw text is the placeholder
        row, files = problems_mod.payload(
            item, {n: True for n in problems_mod.ATTACH}, app_dir=tmp)
        assert [f["name"] for f in files] == ["shot.jpg", "dictation.wav",
                                              "sidecar.json"], files
        assert row["attachments"] == ["shot.jpg", "dictation.wav", "sidecar.json"]
        assert all(Path(f["path"]).is_file() and f["bytes"] > 0 for f in files)
        assert "gsk_" not in row["dictation_raw"] and "[redacted" in row["dictation_raw"], row["dictation_raw"]
        assert row["dictation_final"] == "שלום, עולם."
        assert "consents" in row["env"] and "version" in row["env"]
        text = problems_mod.preview_text(row)
        assert '"text": "המילה האחרונה נעלמה"' in text and "\\u05" not in text

        # preview, then keep here: nothing written, the row forgets
        assert problems_mod.mark_preview(store, item["id"], {"shot": True})
        waiting = problems_mod.awaiting_preview(store)
        assert waiting and waiting["id"] == item["id"]
        assert waiting["sent"] == problems_mod.PREVIEW and waiting["attach"] == {
            "shot": True, "recording": False, "transcript": False, "settings": False}
        assert problems_mod.sent_line(waiting) == "not sent yet — preview it"
        assert problems_mod.keep_local(store, item["id"])
        assert problems_mod.awaiting_preview(store) is None
        assert problems_mod.sent_line(store.get(item["id"])) == ""
        assert not problems_mod.outbox_dir(tmp).exists()

        # send: the payload and copies in the outbox, the row queued
        target = problems_mod.queue(store, store.get(item["id"]),
                                    {"shot": True, "transcript": True}, app_dir=tmp)
        assert target and target.parent == problems_mod.outbox_dir(tmp)
        body = json.loads(target.read_text("utf-8"))
        rid = body["id"]
        assert target.stem == rid and len(rid) == 36
        assert [a["name"] for a in body["attachments"]] == ["shot.jpg", "sidecar.json"]
        copies = problems_mod.outbox_dir(tmp) / rid
        assert all(Path(a["path"]).parent == copies and Path(a["path"]).is_file()
                   for a in body["attachments"])
        assert body["dictation_final"] == "שלום, עולם." and "gsk_" not in json.dumps(body)
        queued = store.get(item["id"])
        assert queued["sent"] == problems_mod.QUEUED and queued["sent_id"] == rid
        assert problems_mod.sent_line(queued) == "waiting to send"
        # the local evidence goes; the copies stay whole
        problems_mod.shot_path(tmp, queued).unlink()
        assert (copies / "shot.jpg").stat().st_size == 503
        # the verdicts, read back the way the dashboard reads them
        assert problems_mod.sync_outbox(store, app_dir=tmp) == 0
        (problems_mod.outbox_dir(tmp) / f"{rid}.failed").write_text(
            "HTTP 400: violates check constraint", "utf-8")
        assert problems_mod.sync_outbox(store, app_dir=tmp) == 1
        failed = store.get(item["id"])
        assert failed["sent"] == problems_mod.FAILED
        assert problems_mod.sent_line(failed) == "could not be sent: HTTP 400: violates check constraint"
        (problems_mod.outbox_dir(tmp) / f"{rid}.failed").unlink()
        assert store._edit(item["id"], sent=problems_mod.QUEUED)
        target.unlink()                                  # sb.py sent it
        assert problems_mod.sync_outbox(store, app_dir=tmp) == 1
        assert problems_mod.sent_line(store.get(item["id"])) == "sent to the developer"
        assert problems_mod.mark_sent(store, "no-such-uuid") is False
        # the second send of the same report keeps the server id, so the
        # insert is idempotent (8.8)
        again = problems_mod.queue(store, store.get(item["id"]), {}, app_dir=tmp)
        assert again is not None and again.stem == rid
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_problems_list_draws_a_report_with_and_without_a_picture(
        ) -> None:
    """The list is the file: two open reports and one answered draw three
    rows plus the ANSWERED heading, a report whose screenshot has been
    deleted draws a row anyway, an empty store shows the empty line, and
    a store that raises leaves an empty list rather than a dead screen. It
    redraws only when the stamp moved."""
    import tkinter as tk

    import problems as problems_mod

    class Fake:
        def __init__(self, items, boom=False):
            self._items, self._boom = items, boom
            self.path = REPO / problems_mod.STORE_NAME

        def items(self, status=None):
            if self._boom:
                raise OSError("broken file")
            return [i for i in self._items
                    if status is None or i.get("status") == status]

        def summary(self):
            if self._boom:
                raise OSError("broken file")
            return {"open": 2, "fixed": 1, "closed": 0}

        def stamp(self):
            return (1, 1)

    def report(ident, status, **extra):
        return dict({"id": ident, "at": "2026-09-04T13:22:01",
                     "where": "recordings", "kind": "wrong",
                     "text": "הכרטיס מראה את המספר של אתמול — yesterday's "
                             "count", "status": status, "resolved": None,
                     "by": "", "dictation": {}, "shot": "", "env": {}},
                    **extra)

    three = [report("a", problems_mod.OPEN,
                    shot="problems/definitely-not-here.jpg",
                    dictation={"raw": "מטוס", "final": "מנטוס",
                               "backend": "local", "seconds": 2.8}),
             report("b", problems_mod.OPEN, kind="idea", where=""),
             report("c", problems_mod.FIXED, resolved="2026-09-04T14:00:00",
                    by="claude")]
    with _window() as board:
        if board is None:
            return
        # The real problems.md is not this test's to rewrite; opening the
        # tab regenerates it, and the store here is a fake.
        board._write_digest = lambda: None
        board._show("Home")
        board._waiting_all()          # the whole backlog, behind the pile
        board._problems_store = lambda: Fake(three)
        board._problems_stamp = None
        board._poll_problems()
        rows = [w for w in board.parts["problems_list"].inner.winfo_children()
                if isinstance(w, tk.Canvas)]
        assert len(rows) == 3, len(rows)
        assert all(getattr(r, "shot", None) is None for r in rows), \
            "a shot that is not on disk drew a picture anyway"
        heads = [w for w in board.parts["problems_list"].inner.winfo_children()
                 if isinstance(w, tk.Label)]
        assert [w.cget("text") for w in heads] == ["ANSWERED"], heads
        assert "2 open" in board.parts["problems_head"].cget("text")
        assert "1 fixed" in board.parts["problems_head"].cget("text")
        assert not board.parts["problems_empty"].winfo_manager()
        # The stamp is remembered: the same file does not redraw.
        board._problems_store = lambda: Fake([])
        board._poll_problems()
        rows = [w for w in board.parts["problems_list"].inner.winfo_children()
                if isinstance(w, tk.Canvas)]
        assert len(rows) == 3, "redrew without the file moving"
        board._problems_stamp = None
        board._poll_problems()
        assert [w for w in board.parts["problems_list"].inner.winfo_children()
                if isinstance(w, tk.Canvas)] == []
        assert board.parts["problems_empty"].winfo_manager() == "place"
        assert "Nothing reported yet" in \
            board.parts["problems_empty"].cget("text")
        board._problems_store = lambda: Fake([], boom=True)
        board._problems_stamp = None
        board._poll_problems()              # must not raise
        assert [w for w in board.parts["problems_list"].inner.winfo_children()
                if isinstance(w, tk.Canvas)] == []
        board._problems = lambda: None      # no problems.py on this checkout
        board._problems_store = lambda: None
        board._problems_stamp = None
        board._poll_problems()
        assert "problems.py is not here" in \
            board.parts["problems_empty"].cget("text")


def test_a_row_the_routine_thinks_is_fixed_says_fixed_maybe_in_amber_and_waits(
) -> None:
    """His words, after the routine closed three reports on 2026-09-12
    that were not fixed: "instead of writing 'fix' it writes 'fix?' in a
    different colour, not green like now" — and asks him.

    So a marked report is still an OPEN row: the same Fixed, Close and ✕
    on it, in the same place, and the counts line still counts it as
    open. What it gains is a FIXED? tag beside the kind, in the tab's
    amber and not the Fixed button's green, and an amber line under his
    text carrying the routine's note — drawn through ui.draw_text, like
    every other line here that may be Hebrew — and telling him what to
    do about it. The counts line says how many are waiting like that,
    and only when any are. Pressing Fixed is his answer: the report
    resolves exactly as it always did and the mark goes with it.

    The store is a temp one, never his.
    """
    import shutil
    import tkinter as tk

    import ui as ui_mod

    import problems as problems_mod

    tmp = Path(tempfile.mkdtemp(prefix="problems-"))
    drawn: list[tuple[str, str]] = []
    real_draw = ui_mod.draw_text

    def spy_draw(text, **kw):
        drawn.append((text, kw.get("colour", "")))
        return real_draw(text, **kw)

    try:
        store = problems_mod.Store(tmp / problems_mod.STORE_NAME)
        plain = store.add({"text": "the dot sits on the wrong screen",
                           "kind": "broken", "where": "overlay"})["id"]
        ident = store.add({"text": "the recordings tab shows yesterday",
                           "kind": "wrong", "where": "recordings"})["id"]
        note = "הכרטיס נבנה מחדש ומראה את הספירה של היום"
        assert store.suggest(ident, by="weekly", note=note)
        ui_mod.draw_text = spy_draw

        with _window() as board:
            if board is None:
                return
            board.closing = True
            board._scan_weekly = lambda: None   # git is not the subject
            board._write_digest = lambda: None  # nor is his problems.md
            board._problems_store = lambda: store
            board._show("Problems")
            board.root.update()

            def rows() -> list:
                return [w for w in board.parts["problems_list"]
                        .inner.winfo_children() if isinstance(w, tk.Canvas)]

            def texts(row) -> dict:
                """Every text item on a row canvas, by its words."""
                return {str(row.itemcget(i, "text")): i
                        for i in row.find_all() if row.type(i) == "text"}

            def buttons(row) -> dict:
                return {w.itemcget(w._label, "text"): w
                        for w in row.winfo_children()
                        if isinstance(w, ui_mod.Button)}

            # Two open rows, newest first: the marked one on top.
            assert len(rows()) == 2, len(rows())
            marked, other = rows()
            assert "FIXED?" in texts(marked), sorted(texts(marked))
            assert "FIXED?" not in texts(other), sorted(texts(other))
            tag = texts(marked)["FIXED?"]
            assert marked.itemcget(tag, "fill") == ui_mod.AMBER, \
                marked.itemcget(tag, "fill")
            assert ui_mod.AMBER != ui_mod.GREEN
            # The tag stands to the right of the kind and the surface, on
            # their line, and inside a frame drawn under it.
            kinds = texts(marked)["WRONG  ·  RECORDINGS"]
            assert marked.bbox(tag)[0] > marked.bbox(kinds)[2], \
                (marked.bbox(tag), marked.bbox(kinds))
            assert abs(marked.bbox(tag)[1] - marked.bbox(kinds)[1]) <= 2
            order = list(marked.find_all())
            frame = order[order.index(tag) - 1]
            assert marked.type(frame) == "image", marked.type(frame)
            fx0, fy0, fx1, fy1 = marked.bbox(frame)
            tx0, ty0, tx1, ty1 = marked.bbox(tag)
            assert fx0 <= tx0 and fx1 >= tx1 and fy0 <= ty0 and fy1 >= ty1, \
                (marked.bbox(frame), marked.bbox(tag))
            # The note, in amber, through the Hebrew-capable path, with
            # what he does about it — and the row grew to hold it.
            hint = [t for t, c in drawn if note in t]
            assert hint, [t for t, _c in drawn]
            assert hint[-1] == f"{note} — try it, then press Fixed", hint[-1]
            assert (hint[-1], ui_mod.AMBER) in drawn, \
                [c for t, c in drawn if t == hint[-1]]
            assert int(marked.cget("height")) > int(other.cget("height"))
            # His buttons are exactly what an open row has.
            assert sorted(buttons(marked)) == ["Close", "Fixed"], \
                sorted(buttons(marked))
            assert sorted(buttons(other)) == ["Close", "Fixed"]
            head = str(board.parts["problems_head"].cget("text"))
            assert "2 open" in head and "1 fixed?" in head, head
            assert "0 fixed   " in head and "0 closed" in head, head

            # And pressing Fixed is his word.
            buttons(marked)["Fixed"]._released(None)
            board.root.update()
            done = store.get(ident)
            assert done["status"] == problems_mod.FIXED, done
            assert done["by"] == "dashboard" and done["resolved"], done
            assert problems_mod.MAYBE not in done, done
            assert store.get(plain)["status"] == problems_mod.OPEN
            assert all("FIXED?" not in texts(r) for r in rows()), \
                "the tag outlived the mark"
            head = str(board.parts["problems_head"].cget("text"))
            assert "1 open" in head and "1 fixed" in head, head
            assert "fixed?" not in head, head

        # The line itself, with and without a note that already says it.
        import dashboard as dash
        hint = dash.Dashboard._problem_hint
        assert hint({"note": "נסה שוב ולחץ Fixed"}) == "נסה שוב ולחץ Fixed"
        assert hint({"note": ""}) == "Try it, then press Fixed"
        assert hint({"note": "  the  count is  today's "}) \
            == "the count is today's — try it, then press Fixed"
    finally:
        ui_mod.draw_text = real_draw
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_report_cards_painter_puts_every_control_where_it_draws_it(
        ) -> None:
    """problem_card is a pure function of the report, so the card can be
    walked without a window: every control is hit where it is drawn and
    nowhere else, the chips are problems.KINDS in order with "other" last
    and "wrong" the default, the field grows from three lines to eight
    and stops, a screenshot that will not decode is a card without a
    picture, and the bidi echo band is there whenever there is a line to
    echo — that band is not decoration, it is the only place a mixed
    Hebrew/English report reads in the right order, because the tk.Text
    the window lays over the well scrambles it exactly as the old
    tk.Entry did (measured 2026-09-04)."""
    import io

    import problem_card as pc
    import problems as problems_mod
    from PIL import Image

    card = pc.card_for("recordings")
    assert card["kinds"] == problems_mod.KINDS, card["kinds"]
    assert card["kind"] == problems_mod.KINDS[0] == "wrong", card["kind"]
    assert card["kinds"][-1] == "other", "the fallback is not last"
    assert pc.card_for("x", kind="urgent")["kind"] == problems_mod.KINDS[0]
    assert pc.card_for("x", kind="other")["kind"] == "other", \
        "a kind he actually picked must survive"

    boxes = pc.regions(card)
    for name in (pc.SEND, pc.CANCEL, pc.FIELD, pc.CARD_REGION):
        assert name in boxes, name
    for kind in problems_mod.KINDS:
        assert pc.KIND_PREFIX + kind in boxes, kind
    # The painter and the hit test read ONE layout, which is what keeps a
    # chip pressed where it is drawn. Centre of each control, and the two
    # dead margins that must answer nothing.
    for name, box in boxes.items():
        if name == pc.CARD_REGION:
            continue
        cx, cy = (box[0] + box[2]) // 2, (box[1] + box[3]) // 2
        assert pc.hit_test(card, cx, cy) == name, (name, cx, cy)
    width, height = pc.measure(card)
    assert width == pc.CARD_W == 420, width
    assert boxes[pc.CARD_REGION] == (0, 0, width, height)
    assert pc.hit_test(card, 2, 2) is None, "the head took a click"
    assert pc.hit_test(card, width // 2, height - 2) is None, \
        "the bottom margin took a click"
    # THE CARD IS DRAGGED BY ITS FACE, and hit_test returning None IS the
    # definition of the handle — the window has no rule of its own about
    # what may be grabbed, it grabs wherever the painter says there is no
    # control. So every piece of chrome has to answer None, by name: the
    # eyebrow and title band, the keys line (which sits above the field
    # and is a sentence, not a button), the gap between two chips, and
    # the echo band under the field.
    box = pc.layout(card)
    chrome = [(width // 2, 4), (4, height // 2), (width - 4, height // 2)]
    chrome.append(((box["keys"][0] + box["keys"][2]) // 2 + pc.PAD,
                   (box["keys"][1] + box["keys"][3]) // 2 + pc.PAD))
    first, second = (boxes[pc.KIND_PREFIX + k]
                     for k in problems_mod.KINDS[:2])
    if second[0] > first[2] and second[1] == first[1]:
        chrome.append(((first[2] + second[0]) // 2,
                       (first[1] + first[3]) // 2))
    for spot in chrome:
        assert pc.hit_test(card, *spot) is None, spot
    controls = [b for n, b in boxes.items() if n != pc.CARD_REGION]
    for i, a in enumerate(controls):
        for b in controls[i + 1:]:
            assert a[2] <= b[0] or b[2] <= a[0] \
                or a[3] <= b[1] or b[3] <= a[1], (a, b)
    # Chips in KINDS order: down the rows, left to right inside one.
    spots = [(boxes[pc.KIND_PREFIX + k][1], boxes[pc.KIND_PREFIX + k][0])
             for k in problems_mod.KINDS]
    assert spots == sorted(spots), spots
    assert spots[-1] == max(spots), '"other" is not drawn last'

    # The field grows and then stops, and the card grows under it.
    tall = [pc.measure(pc.card_for("x", lines=n))[1] for n in (0, 3, 5, 8, 40)]
    assert tall[0] == tall[1], "fewer than three lines still draws three"
    assert tall[1] < tall[2] < tall[3], tall
    assert tall[3] == tall[4], "the field grew past FIELD_LINES_MAX"
    assert tall[3] - tall[1] == (pc.FIELD_LINES_MAX - pc.FIELD_LINES_MIN) \
        * pc.FIELD_LINE_H, tall
    assert pc.field_lines("") == pc.FIELD_LINES_MIN
    assert pc.field_lines("x" * 5000) == pc.FIELD_LINES_MAX
    assert pc.field_lines("a\nb\nc\nd\ne") == 5

    # The echo band, which is the reason the field may be a Text at all.
    mixed = "הכפתור של Settings לא עובד אחרי restart"
    assert pc.layout(pc.card_for("x"))["echo_h"] == 0, "an echo with no line"
    assert pc.layout(pc.card_for("x", typed=mixed))["echo_h"] > 0, \
        "the bidi echo line is gone — the field cannot draw this order"
    assert pc.measure(pc.card_for("x", typed=mixed))[1] \
        > pc.measure(pc.card_for("x"))[1]

    # A screenshot, none, and one that will not open — three cards, one
    # of them taller, and not a single exception between them.
    buf = io.BytesIO()
    Image.new("RGB", (1600, 900), (40, 60, 90)).save(buf, format="JPEG")
    shot = pc.card_for("x", shot=buf.getvalue())
    assert pc.layout(shot)["shot"] is not None
    assert pc.measure(shot)[1] > height, "the screenshot took no room"
    # The thumbnail needs no rule of its own to be a handle: it is a
    # picture and never entered `regions`, so it answers None like the
    # rest of the face and the card drags from it.
    picture = pc.layout(shot)["shot"]
    assert not any(name.startswith("shot")
                   for name in pc.regions(shot)), sorted(pc.regions(shot))
    assert pc.hit_test(shot, (picture[0] + picture[2]) // 2 + pc.PAD,
                       (picture[1] + picture[3]) // 2 + pc.PAD) is None, \
        "the screenshot took a click instead of dragging the card"
    assert pc.layout(pc.card_for("x", shot=b"not a jpeg"))["shot"] is None
    assert pc.layout(pc.card_for("x", shot=None))["shot"] is None
    assert pc.measure(pc.card_for("x", shot=b"not a jpeg")) \
        == pc.measure(pc.card_for("x"))

    # And it paints to exactly the size it measured — the window sets the
    # canvas and the geometry off that number.
    img = pc.compose(card)
    assert (img.width, img.height) == (width, height)
    assert pc.compose(shot).height == pc.measure(shot)[1]


def test_the_report_card_is_answered_by_enter_by_send_and_by_escape() -> None:
    """The window over the painting: a dictated line goes in the field
    without being sent, Shift+Enter is a new line and Enter is the
    answer, a click on a chip changes the kind the answer carries, and
    Escape hands back None. `on_done(text, kind)` gets both either way.

    THREE cards in one process, on purpose. `st` holds the
    ImageTk.PhotoImage the canvas was showing and every closure holds
    `st`; left alive past root.destroy() the image is finalised from
    whichever thread the collector is on, into an interpreter that is
    gone — "Tcl_AsyncDelete: async handler deleted by the wrong thread",
    which aborted the process on the SECOND card until the teardown
    cleared them. _run_window_script fails on that string in stderr, so
    opening three is the regression guard.

    A subprocess, like every card that owns a Tcl interpreter, and every
    keystroke is generated from INSIDE the card's own thread (the spy on
    tk.Text hooks pump()'s insert, which runs there) because a Tcl call
    from another thread is the abort this is guarding against. Every
    assertion message is ascii(): a Hebrew one dies in check()'s print on
    a cp1255 console and takes the whole run with it."""
    _run_window_script('''
import gc, os, threading, time, tkinter

import problem_card as pc

CALLS, STEPS, CARDS = [], [], []
_RealText = tkinter.Text


def _next(w):
    if STEPS:
        STEPS.pop(0)(w)


class SpyText(_RealText):
    """The card's real field, wrapped: what was typed into it, and a door
    onto its own thread. pump() calls insert() on the card's thread, so
    anything scheduled from here runs where Tcl is allowed to be
    called."""

    def insert(self, index, chars, *a, **k):
        CALLS.append(("insert", str(index), chars))
        out = _RealText.insert(self, index, chars, *a, **k)
        if STEPS:
            self.after(250, lambda: _next(self))
        return out


tkinter.Text = SpyText           # ProblemCard._run imports tkinter at call

_real_card_for = pc.card_for


def _spy_card_for(*a, **k):
    """The LIVE card dict, so a click can be aimed at where the chip
    actually is after the field has grown under it."""
    card = _real_card_for(*a, **k)
    CARDS.append(card)
    return card


pc.card_for = _spy_card_for

import overlay

WHERE = "recordings"
HEB = "\\u05d4\\u05de\\u05e1\\u05e4\\u05e8 \\u05e8\\u05e2 - wrong"
FIRST = "first line, thrown away"


def wait(ready, why, seconds=40):
    end = time.time() + seconds
    while time.time() < end:
        if ready():
            return
        time.sleep(0.02)
    raise AssertionError(why + " calls=" + ascii(CALLS))


def keys(w, seq):
    """A generated key, on the card's own thread.

    focus_force first, because MEASURED: event_generate on a widget that
    does not hold the Tk focus fires nothing at all — not the binding,
    not an error. This is Tk's focus inside this card's own interpreter
    and not the OS foreground, so unlike a synthetic keybd_event it
    cannot land in whatever window the owner is really looking at.
    """
    w.focus_force()
    w.event_generate(seq)


def canvas_of(w):
    return [c for c in w.master.winfo_children()
            if isinstance(c, tkinter.Canvas)][0]


def click(w, name):
    box = pc.regions(CARDS[-1], {})[name]
    canvas_of(w).event_generate("<Button-1>", x=(box[0] + box[2]) // 2,
                                y=(box[1] + box[3]) // 2)


# ---- 1. the keyboard: filled, not sent; Shift+Enter, then Enter
got, fired = [], threading.Event()
one = overlay.ProblemCard()
assert one.fill("nobody home") is False, "a card that was never opened"
assert one.ask(WHERE, lambda t, k: (got.append((t, k)), fired.set()),
               shot=None, focus=False)
wait(one.open, "card 1 never opened")
wait(lambda: bool(CARDS), "the painter was never asked for a card")
kinds = CARDS[0]["kinds"]
assert len(kinds) >= 3, ascii(kinds)

STEPS[:] = [lambda w: keys(w, "<Shift-Return>")]
assert one.fill(FIRST) is True
wait(lambda: ("insert", "1.0", FIRST) in CALLS, "the first fill never landed")
wait(lambda: ("insert", "insert", "\\n") in CALLS, "shift+enter did nothing")
assert one.open() is True, "shift+enter closed the card"
assert not fired.is_set(), "shift+enter SENT the report: " + ascii(got)

STEPS[:] = [lambda w: keys(w, "<Return>")]
assert one.fill(HEB) is True
wait(lambda: ("insert", "1.0", HEB) in CALLS, "the second fill never landed")
assert fired.wait(30), "enter never sent the report"
assert got == [(HEB, kinds[0])], ascii(got)
assert one.open() is False
assert one.fill("too late") is False, "a fill onto a closed card"
inserts = [c[2] for c in CALLS if c[0] == "insert"]
assert inserts == [FIRST, "\\n", HEB], ascii(inserts)
gc.collect()

# ---- 2. the mouse: a chip changes the kind, Send sends it
TWO = "the recordings tab shows yesterdays count"
got2, fired2 = [], threading.Event()
two = overlay.ProblemCard()
assert two.ask(WHERE, lambda t, k: (got2.append((t, k)), fired2.set()),
               shot=None, focus=False)
wait(two.open, "card 2 never opened")
picked = kinds[2]


def chip_then_send(w):
    click(w, pc.KIND_PREFIX + picked)
    w.after(300, lambda: click(w, pc.SEND))


STEPS[:] = [chip_then_send]
assert two.fill(TWO) is True
assert fired2.wait(30), "the Send button never sent"
assert got2 == [(TWO, picked)], ascii(got2) + " wanted " + ascii(picked)
assert two.open() is False
gc.collect()

# ---- 3. Escape, with a real screenshot attached
import io

from PIL import Image

buf = io.BytesIO()
Image.new("RGB", (1280, 720), (30, 40, 55)).save(buf, format="JPEG")
got3, fired3 = [], threading.Event()
three = overlay.ProblemCard()
assert three.ask(WHERE, lambda t, k: (got3.append((t, k)), fired3.set()),
                 shot=buf.getvalue(), focus=False)
wait(three.open, "card 3 never opened")
assert pc.layout(CARDS[-1], {})["shot"] is not None, "the shot was dropped"
STEPS[:] = [lambda w: keys(w, "<Escape>")]
assert three.fill("never mind") is True
assert fired3.wait(30), "escape never came back"
assert got3 == [(None, kinds[0])], ascii(got3)
assert three.open() is False
gc.collect()
os._exit(0)
''')

def test_the_report_card_is_dragged_by_its_face_and_remembers_where() -> None:
    """The card has no frame, so the face is the handle — everywhere the
    painter says there is no control. A shake under CLICK_PX is a click
    and moves nothing; past it the card follows the pointer and the drop
    is written down ONCE through on_change, which is what puts it in
    config.toml under [problems] x/y.

    And the two halves of "a drag that ends over a chip must not pick
    it", which are true because the controls act on the PRESS: a release
    lands on nothing that is listening anywhere on the card, and a press
    that starts on a chip has already done its work and does not drag,
    because a chip is not a handle.

    A subprocess, and every event is generated from INSIDE the card's own
    thread — the spy on tk.Text hooks pump()'s insert, which runs there —
    because a Tcl call from any other thread is the Tcl_AsyncDelete abort
    the sibling test guards. Results are RECORDED there and asserted
    here: an AssertionError raised inside a Tk callback is swallowed by
    Tk's error handler, so a failure would hang instead of reporting.
    Messages are ascii() for the same reason as the sibling's."""
    _run_window_script('''
import gc, os, threading, time, tkinter, traceback

import problem_card as pc

STEPS, CARDS, CHANGES = [], [], []
RESULT = {}
_RealText = tkinter.Text


def _next(w):
    if STEPS:
        STEPS.pop(0)(w)


class SpyText(_RealText):
    """A door onto the card's own thread: pump() inserts there."""

    def insert(self, index, chars, *a, **k):
        out = _RealText.insert(self, index, chars, *a, **k)
        if STEPS:
            self.after(250, lambda: _next(self))
        return out


tkinter.Text = SpyText           # ProblemCard._run imports tkinter at call

_real_card_for = pc.card_for


def _spy_card_for(*a, **k):
    card = _real_card_for(*a, **k)
    CARDS.append(card)
    return card


pc.card_for = _spy_card_for

import overlay


def wait(ready, why, seconds=40):
    end = time.time() + seconds
    while time.time() < end:
        if ready():
            return
        time.sleep(0.02)
    raise AssertionError(why + " result=" + ascii(RESULT))


def gesture(w):
    try:
        root, card = w.master, CARDS[-1]
        cv = [c for c in root.winfo_children()
              if isinstance(c, tkinter.Canvas)][0]

        def at():
            root.update_idletasks()
            return (root.winfo_x(), root.winfo_y())

        def fire(kind, wx, wy, rx, ry):
            cv.event_generate(kind, x=wx, y=wy, rootx=rx, rooty=ry)

        # The handle, by the only definition there is: hit_test is None.
        hx, hy = pc.CARD_W // 2, 4
        RESULT["chrome"] = pc.hit_test(card, hx, hy, {}) is None
        x0, y0 = at()
        RESULT["start"] = (x0, y0)
        fire("<ButtonPress-1>", hx, hy, x0 + hx, y0 + hy)
        fire("<B1-Motion>", hx, hy, x0 + hx + 2, y0 + hy + 1)
        RESULT["under"] = at()
        fire("<B1-Motion>", hx, hy, x0 + hx + 40, y0 + hy + 30)
        RESULT["over"] = at()
        fire("<ButtonRelease-1>", hx, hy, x0 + hx + 40, y0 + hy + 30)
        RESULT["dropped"] = at()
        RESULT["want"] = (x0 + 40, y0 + 30)

        # A release over a chip picks nothing.
        chip = pc.regions(card, {})[pc.KIND_PREFIX + card["kinds"][2]]
        cx, cy = (chip[0] + chip[2]) // 2, (chip[1] + chip[3]) // 2
        x1, y1 = at()
        RESULT["rest"] = (x1, y1)
        fire("<ButtonRelease-1>", cx, cy, x1 + cx, y1 + cy)
        RESULT["after_release"] = card["kind"]

        # A press on a chip picks it and does not drag.
        fire("<ButtonPress-1>", cx, cy, x1 + cx, y1 + cy)
        RESULT["after_press"] = card["kind"]
        fire("<B1-Motion>", cx, cy, x1 + cx + 60, y1 + cy + 50)
        RESULT["chip_drag"] = at()
        fire("<ButtonRelease-1>", cx, cy, x1 + cx + 60, y1 + cy + 50)
        RESULT["chip_drop"] = at()
    except Exception:
        RESULT["error"] = traceback.format_exc()
    RESULT["done"] = True


card = overlay.ProblemCard(on_change=CHANGES.append)
assert card.moved() is False, "an untouched card claims a position"
assert (card.x, card.y) == (overlay.HINT_UNSET,) * 2, ascii((card.x, card.y))
answered = threading.Event()
assert card.ask("recordings", lambda t, k: answered.set(), shot=None,
                focus=False)
wait(card.open, "the card never opened")
wait(lambda: bool(CARDS), "the painter was never asked for a card")
kinds = CARDS[0]["kinds"]

STEPS[:] = [gesture]
assert card.fill("the recordings tab shows yesterdays count") is True
wait(lambda: RESULT.get("done"), "the gesture never ran")
assert not RESULT.get("error"), RESULT["error"]

assert RESULT["chrome"] is True, "the top margin is not a handle"
assert RESULT["under"] == RESULT["start"], \\
    "a 3 px shake moved it: " + ascii((RESULT["start"], RESULT["under"]))
assert RESULT["over"] == RESULT["want"], \\
    ascii((RESULT["over"], RESULT["want"]))
assert RESULT["dropped"] == RESULT["want"], ascii(RESULT["dropped"])
assert (card.x, card.y) == RESULT["want"], \\
    ascii(((card.x, card.y), RESULT["want"]))
assert card.moved() is True
assert CHANGES == [{"x": RESULT["want"][0], "y": RESULT["want"][1]}], \\
    "a drag ends in more than one message: " + ascii(CHANGES)

assert RESULT["after_release"] == kinds[0], \\
    "a release over a chip picked it: " + ascii(RESULT["after_release"])
assert RESULT["after_press"] == kinds[2], ascii(RESULT["after_press"])
assert RESULT["chip_drag"] == RESULT["rest"] == RESULT["chip_drop"], \\
    "a press on a chip dragged the card: " \\
    + ascii((RESULT["rest"], RESULT["chip_drag"], RESULT["chip_drop"]))
assert CHANGES == [{"x": RESULT["want"][0], "y": RESULT["want"][1]}], \\
    "the chip phase wrote a position: " + ascii(CHANGES)

assert card.open() is True and not answered.is_set(), \\
    "dragging the card answered it"
card.answer(None)
wait(lambda: not card.open(), "the card never closed")
gc.collect()
os._exit(0)
''')

def test_the_report_cards_send_switch_asks_its_card_first_and_answers_with_the_toggles() -> None:
    """Plan 7.6, screen 7, on the hotkey card: "Send to the developer"
    with the gate shut opens the consent card (the `consent` callable)
    and stays OFF; the moment `allowed()` says yes the switch turns on
    by itself. The strip's toggles flip on a press — except a piece
    with no bytes behind it, which stays off — and the primary answers
    with `last` = {"send", "attach"} beside on_done's (text, kind). The
    same subprocess shape as the two card tests above, for the same
    Tcl reasons."""
    _run_window_script('''
import gc, os, threading, time, tkinter, traceback

import problem_card as pc

STEPS, CARDS, ASKED = [], [], []
GATE = {"open": False}
RESULT = {}
_RealText = tkinter.Text


def _next(w):
    if STEPS:
        STEPS.pop(0)(w)


class SpyText(_RealText):
    def insert(self, index, chars, *a, **k):
        out = _RealText.insert(self, index, chars, *a, **k)
        if STEPS:
            self.after(250, lambda: _next(self))
        return out


tkinter.Text = SpyText

_real_card_for = pc.card_for


def _spy_card_for(*a, **k):
    card = _real_card_for(*a, **k)
    CARDS.append(card)
    return card


pc.card_for = _spy_card_for

import overlay


def wait(ready, why, seconds=40):
    end = time.time() + seconds
    while time.time() < end:
        if ready():
            return
        time.sleep(0.02)
    raise AssertionError(why)


def canvas_of(w):
    return [c for c in w.master.winfo_children()
            if isinstance(c, tkinter.Canvas)][0]


def click(w, name):
    box = pc.regions(CARDS[-1], {})[name]
    canvas_of(w).event_generate("<ButtonPress-1>", x=(box[0] + box[2]) // 2,
                                y=(box[1] + box[3]) // 2)


def gesture(w):
    try:
        live = CARDS[-1]
        # shut gate: the press asks the card and the switch stays off
        click(w, pc.SEND_TOGGLE)
        RESULT["asked"] = list(ASKED)
        RESULT["off_after_ask"] = live["send"]
        # [Turn on] elsewhere: the pump flips it within a few ticks
        GATE["open"] = True

        def after_gate():
            try:
                RESULT["on_after_gate"] = live["send"]
                RESULT["strip"] = sorted(n for n in pc.regions(live, {})
                                         if n.startswith(pc.ATTACH_PREFIX))
                click(w, pc.ATTACH_PREFIX + "shot")
                click(w, pc.ATTACH_PREFIX + "recording")   # none: stays off
                click(w, pc.ATTACH_PREFIX + "transcript")  # on -> off
                RESULT["attach"] = dict(live["attach"])
                click(w, pc.SEND)
            except Exception:
                RESULT["error"] = traceback.format_exc()
            RESULT["done"] = True

        w.after(400, after_gate)
    except Exception:
        RESULT["error"] = traceback.format_exc()
        RESULT["done"] = True


got, answered = [], threading.Event()
card = overlay.ProblemCard(allowed=lambda: GATE["open"],
                           consent=lambda: ASKED.append("report_upload"))
assert card.ask("dictation", lambda t, k: (got.append((t, k)), answered.set()),
                shot=None, focus=False,
                sizes={"shot": 5000, "recording": 0, "transcript": 40,
                       "settings": 900})
wait(card.open, "the card never opened")
wait(lambda: bool(CARDS), "the painter was never asked for a card")
STEPS[:] = [gesture]
assert card.fill("the last word vanished") is True
wait(lambda: RESULT.get("done"), "the gesture never ran")
assert not RESULT.get("error"), RESULT["error"]
assert RESULT["asked"] == ["report_upload"], ascii(RESULT["asked"])
assert RESULT["off_after_ask"] is False, "the switch turned on with the gate shut"
assert RESULT["on_after_gate"] is True, "the gate opened and the switch stayed off"
assert RESULT["strip"] == sorted(pc.ATTACH_PREFIX + n for n in pc.ATTACH_ORDER), \\
    ascii(RESULT["strip"])
assert RESULT["attach"] == {"shot": True, "recording": False,
                            "transcript": False, "settings": True}, \\
    ascii(RESULT["attach"])
assert answered.wait(30), "the primary never answered"
assert got == [("the last word vanished", CARDS[0]["kinds"][0])], ascii(got)
assert card.last == {"send": True, "attach": RESULT["attach"]}, ascii(card.last)
assert card.open() is False
gc.collect()
os._exit(0)
''')


def test_send_to_the_developer_previews_before_anything_leaves() -> None:
    """Plan 7.6, screen 7, on the desk: the report box carries "Send to
    the developer", off — [Keep on this PC] files the report here as it
    always did. On: the strip under it says what would leave with its
    sizes, the primary reads Preview, and pressing it FILES the report
    (locally, as always), marks the row PREVIEW with the toggles and
    opens the Preview — the exact JSON and the ticked files, with [Send]
    and [Keep on this PC]. Keep leaves nothing in the outbox and clears
    the mark; Send writes the payload and the copies into the outbox
    and the row says "waiting to send" with a Send now beside it. A
    shut gate asks the app for its consent card over the pipe and the
    switch stays off until the gate opens. The store, the recent folder
    and the outbox are all under a temp root; the screen grab is a
    fixture so nothing photographs the desk."""
    import shutil
    import tkinter as tk

    import ui as ui_mod

    import dashboard as dash
    import problems as problems_mod

    tmp = Path(tempfile.mkdtemp(prefix="problems-send-"))
    gate = {"open": False}
    asked: list = []

    def fake_send(command, timeout_ms=0, **args):
        asked.append((command, args))
        if command == "consent":
            return {"ok": True, "asked": True}
        return {"ok": True}

    def toplevels(board, title):
        return [w for w in board.root.winfo_children()
                if isinstance(w, tk.Toplevel) and w.winfo_exists()
                and w.title() == title]

    def descendants(widget):
        out = []
        for w in widget.winfo_children():
            out.append(w)
            out.extend(descendants(w))
        return out

    def buttons(widget) -> dict:
        return {w.itemcget(w._label, "text"): w for w in descendants(widget)
                if isinstance(w, ui_mod.Button)}

    def spin(board, ticks=6):
        for _ in range(ticks):
            time.sleep(0.05)
            board.root.update()

    def first_row(board):
        return [w for w in board.parts["problems_list"].inner.winfo_children()
                if isinstance(w, tk.Canvas)][0]

    def words_on(row) -> set:
        return {str(row.itemcget(i, "text")) for i in row.find_all()
                if row.type(i) == "text"}

    try:
        recent = tmp / "recent"
        recent.mkdir()
        wav = recent / "20260918-231500.wav"
        wav.write_bytes(RIFF)
        wav.with_suffix(".json").write_text(json.dumps(
            {"seconds": 1.0, "backend": "local", "language": "he"}), "utf-8")
        jpeg = b"\xff\xd8\xff" + b"j" * 900
        import control as control_mod
        with _patched(paths, "DATA_DIR", tmp), _patched(paths, "RECENT_DIR", recent), \
                _patched(paths, "OUTBOX_DIR", tmp / "problems" / "outbox"), \
                _patched(dash.Dashboard, "_report_shot", staticmethod(lambda pcfg: jpeg)), \
                _patched(dash.Dashboard, "_upload_allowed", lambda self: gate["open"]), \
                _window() as board:
            if board is None:
                return
            control_mod.send = fake_send      # _window's None until now
            board.closing = True
            board._scan_weekly = lambda: None
            board._write_digest = lambda: None
            board._problems_on = True
            board._show("Problems")
            board.root.update()
            store = problems_mod.Store(tmp / problems_mod.STORE_NAME)

            board._report()
            board.root.update()
            box = toplevels(board, "Report a problem")[0]
            field = [w for w in descendants(box) if isinstance(w, tk.Text)][0]
            switches = [w for w in descendants(box) if isinstance(w, ui_mod.Switch)]
            assert len(switches) == 1 + len(problems_mod.ATTACH), len(switches)
            send_switch, strip = switches[0], switches[1:]
            names = buttons(box)
            assert dash.REPORT_KEEP in names and dash.REPORT_PREVIEW in names, sorted(names)
            spin(board, 2)
            assert names[dash.REPORT_KEEP].winfo_ismapped() and not names[dash.REPORT_PREVIEW].winfo_ismapped()
            assert not any(s.winfo_ismapped() for s in strip), "the strip shows with the switch off"
            keys_line = [w for w in descendants(box) if isinstance(w, tk.Label)
                         and str(w.cget("text")) in (dash.REPORT_KEYS, dash.REPORT_KEYS_SEND)][0]
            assert str(keys_line.cget("text")) == dash.REPORT_KEYS

            field.insert("1.0", "המילה האחרונה נעלמה")
            # the gate is shut: the press asks the app, the switch stays off
            send_switch.toggle()
            spin(board, 3)
            assert send_switch.get() is False
            assert ("consent", {"kind": "report_upload"}) in asked, asked
            # [Turn on] beside the dot: the poll flips it
            gate["open"] = True
            spin(board, 4)
            assert send_switch.get() is True, "the gate opened and the switch stayed off"
            assert all(s.winfo_ismapped() for s in strip), "the strip did not appear"
            assert names[dash.REPORT_PREVIEW].winfo_ismapped() and not names[dash.REPORT_KEEP].winfo_ismapped()
            assert str(keys_line.cget("text")) == dash.REPORT_KEYS_SEND
            labels = [str(w.cget("text")) for w in descendants(box) if isinstance(w, tk.Label)]
            assert any(t.startswith("Screenshot  ·  ") and "KB" in t for t in labels), labels
            assert any(t.startswith("Recording  ·  ") for t in labels), labels
            # wrong is the kind: transcript and settings on, the two files off
            assert [s.get() for s in strip] == [False, False, True, True], [s.get() for s in strip]
            strip[0].toggle()                                  # the screenshot travels
            assert strip[0].get() is True

            names[dash.REPORT_PREVIEW]._released(None)
            spin(board, 4)
            assert not toplevels(board, "Report a problem"), "the box stayed up"
            rows = store.items()
            assert len(rows) == 1 and rows[0]["text"] == "המילה האחרונה נעלמה", rows
            ident = rows[0]["id"]
            assert rows[0]["sent"] == problems_mod.PREVIEW
            assert rows[0]["attach"] == {"shot": True, "recording": False,
                                         "transcript": True, "settings": True}, rows[0]["attach"]
            assert rows[0]["shot"] and rows[0]["dictation"].get("wav"), "the local copy lost a piece"
            preview = toplevels(board, "Preview — what leaves this PC")
            assert preview, "no Preview opened"
            texts = [str(w.cget("text")) for w in descendants(preview[0]) if isinstance(w, tk.Label)]
            assert "This is everything that leaves your PC. Nothing else." in texts, texts
            assert any(t.startswith("shot.jpg  ·  ") for t in texts), texts
            assert not any(t.startswith("dictation.wav") for t in texts), "an unticked file is shown"
            assert any(t.startswith("sidecar.json  ·  ") for t in texts), texts
            pictures = [w for w in descendants(preview[0]) if isinstance(w, tk.Label)
                        and str(w.cget("image"))]
            assert len(pictures) >= 8, "the JSON lines are not drawn"
            # keep on this PC: no outbox, the mark cleared
            buttons(preview[0])[dash.REPORT_KEEP]._released(None)
            spin(board, 3)
            assert not toplevels(board, "Preview — what leaves this PC")
            assert store.get(ident)["sent"] == "" and not (tmp / "problems" / "outbox").exists()
            # the row offers nothing about sending now
            board._fill_problems()
            board.root.update()
            assert "Preview & send" not in buttons(first_row(board)), sorted(buttons(first_row(board)))
            # marked again from the row's side (the hotkey path): [Preview & send]
            problems_mod.mark_preview(store, ident, {"shot": True, "transcript": True})
            board._fill_problems()
            board.root.update()
            row = first_row(board)
            assert "Preview & send" in buttons(row), sorted(buttons(row))
            buttons(row)["Preview & send"]._released(None)
            spin(board, 3)
            preview = toplevels(board, "Preview — what leaves this PC")
            assert preview
            buttons(preview[0])["Send"]._released(None)
            spin(board, 3)
            queued = store.get(ident)
            assert queued["sent"] == problems_mod.QUEUED and queued["sent_id"], queued
            payload = tmp / "problems" / "outbox" / f"{queued['sent_id']}.json"
            assert payload.is_file()
            body = json.loads(payload.read_text("utf-8"))
            assert body["text"] == "המילה האחרונה נעלמה" and body["kind"] == "wrong"
            assert [a["name"] for a in body["attachments"]] == ["shot.jpg", "sidecar.json"]
            assert ("account", {"do": "nudge"}) in asked, asked
            board._fill_problems()
            board.root.update()
            row = first_row(board)
            assert "waiting to send" in words_on(row), sorted(words_on(row))
            assert "Send now" in buttons(row), sorted(buttons(row))
            # the app's verdict, read back on the next draw
            payload.unlink()
            board._fill_problems()
            board.root.update()
            row = first_row(board)
            assert "sent to the developer" in words_on(row), sorted(words_on(row))
            assert "Send now" not in buttons(row)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_problem_report_path_never_damages_a_dictation() -> None:
    """The report card borrows the dictation key, so the one thing it
    may NOT do is spend a sentence. With to_prompt on, the transcript
    goes in the card and nothing is pasted, nothing is submitted and
    _last is left alone (the correction key must still be about the last
    real dictation); with it off the same recording pastes exactly as
    before. A card that closed while he was talking, or an overlay too
    old to have fill(), falls back to the clipboard — never to a report
    filed behind his back. And the decision is made at the PRESS, where
    the ask card already wins.

    The card is App._problem_card and the review pencil is
    App._word_prompt, and they are two objects since 2026-09-04: while
    they shared one, a pencil open over a mishearing would claim a
    dictation aimed at nothing of the sort, and the paragraph he spoke
    landed in a box asking what ONE WORD should have been."""
    import shutil

    import main as main_mod
    import problems as problems_mod

    class Fillable:
        """A ProblemCard that can be filled; overlay's own is proved
        by test_the_report_card_takes_a_line_and_only_enter_sends_it."""

        def __init__(self, is_open=True):
            self._open, self.filled, self.submitted = is_open, [], []

        def open(self):
            return self._open

        def fill(self, text):
            self.filled.append(text)
            return True

        def answer(self, text):
            self.submitted.append(text)

    class Older:
        """An overlay whose report card has no fill()."""

        def __init__(self):
            self.submitted = []

        def open(self):
            return True

        def answer(self, text):
            self.submitted.append(text)

    tmp = Path(tempfile.mkdtemp(prefix="problems-report-"))
    fake = _FakeInjector()
    real = main_mod.injector
    try:
        main_mod.injector = fake
        app = _worker_app(_Flaky(fail_times=0), tmp)
        app._vqa = _FakeSink(sink_active=False)
        app.problems = problems_mod.Store(tmp / problems_mod.STORE_NAME)

        box = Fillable()
        app._problem_card = box
        app._last = None
        app._handle(b"RIFF-audio", 4.0, fake.focus, None, False,
                    to_prompt=True)
        assert box.filled == ["שלום"], ascii(box.filled)
        assert box.submitted == [], "filling the box filed the report"
        assert fake.calls == [], ("something reached the cursor", fake.calls)
        assert app._last is None, ("_last was overwritten by a report",
                                   app._last)

        fake.calls.clear()
        box.filled.clear()
        app._handle(b"RIFF-audio", 4.0, fake.focus, None, False)
        assert [c[0] for c in fake.calls] == ["show", "replace"], fake.calls
        assert box.filled == [], "an ordinary dictation reached the box"

        fake.calls.clear()
        app._problem_card = Fillable(is_open=False)
        app._handle(b"RIFF-audio", 4.0, fake.focus, None, False,
                    to_prompt=True)
        assert [c[0] for c in fake.calls] == ["clipboard"], fake.calls

        fake.calls.clear()
        older = Older()
        app._problem_card = older
        app._handle(b"RIFF-audio", 4.0, fake.focus, None, False,
                    to_prompt=True)
        assert [c[0] for c in fake.calls] == ["clipboard"], fake.calls
        assert older.submitted == [], older.submitted
        assert app.problems.items() == [], \
            "a report was filed without him ever seeing the line"

        # ---- the decision is taken at the press, not when the words
        # come back: the box may be gone by then, and the queue tuple
        # must not grow a seventh member to carry the answer.
        class Rec:
            def begin(self): pass

            def set_cap(self, _c): pass

            def meter(self): return (0.0, True)

        app.recorder = Rec()
        app._set_state = lambda *_a, **_k: None
        fake.is_our_window = lambda _h: False

        def sink(active):
            s = _FakeSink(sink_active=active)
            s.notify_recording = lambda **_k: None
            return s

        app._problem_card = Fillable()
        app._vqa = sink(False)
        app._to_card = False
        app._on_start("he")
        assert app._to_prompt is True, app._to_prompt
        app._problem_card = Fillable(is_open=False)
        app._on_start("he")
        assert app._to_prompt is False, "a closed box still claimed the words"
        app._problem_card = Fillable()
        app._vqa = sink(True)
        app._on_start("he")
        assert app._to_card is True and app._to_prompt is False, \
            ("the ask card must win", app._to_card, app._to_prompt)
        # THE SPLIT. The pencil is open over a mishearing and no
        # report card is up: the words are a dictation and belong at the
        # cursor, not in a box asking what ONE word should have been.
        pencil = Fillable()
        app._word_prompt = pencil
        app._problem_card = Fillable(is_open=False)
        app._vqa = sink(False)
        app._to_card = False
        app._on_start("he")
        assert app._to_prompt is False, \
            "the review pencil claimed a dictation meant for the cursor"
        assert app._word_prompt is not app._problem_card, \
            "one object for two questions is the bug the split fixed"
        fake.calls.clear()
        app._handle(b"RIFF-audio", 4.0, fake.focus, None, False)
        assert [c[0] for c in fake.calls] == ["show", "replace"], fake.calls
        assert pencil.filled == [] and pencil.submitted == [], \
            ("the pencil was written into", pencil.filled, pencil.submitted)
        assert 0 < main_mod.PROBLEM_LAST_MAX_S <= 900, \
            main_mod.PROBLEM_LAST_MAX_S
    finally:
        main_mod.injector = real
        shutil.rmtree(tmp, ignore_errors=True)


def test_the_new_widgets_read_the_palette_when_they_are_built():
    """widgets.py is what the desk window is made of, and the one rule it
    has is that no colour is copied out of ui.py at import: the palette
    is repainted by skin/palette.py and retuned between waves, so a
    module-level GOLD = "#..." would be last week's gold for ever.

    Also the two things ui.py could not do. rtl_run lays a Hebrew line
    out of SEVERAL bitmaps so one word inside it can sit on a pill —
    draw_text renders a paragraph as one image and there is no way to
    reach a word inside it. ToneButton is a button in a colour ui.Button
    does not offer (_build_faces hardcodes ACCENT and EDGE), which is
    what makes the one gold Yes askable."""
    import tkinter as tk

    import ui as ui_mod
    import widgets as widgets_mod

    import ast as ast_mod

    tree = ast_mod.parse((REPO / "widgets.py").read_text("utf-8"))
    for node in tree.body:
        if not isinstance(node, (ast_mod.Assign, ast_mod.AnnAssign)):
            continue
        frozen = ast_mod.dump(node.value or ast_mod.Constant(None))
        assert "Attribute" not in frozen or "ui" not in frozen, \
            f"line {node.lineno}: a ui colour copied at import time"
        assert "'#" not in frozen.replace("'#%02x", ""), \
            f"line {node.lineno}: a hex literal at module level"

    try:
        root = tk.Tk()
    except Exception as e:                     # no display: nothing to test
        print(f"    (skipped: no Tk window — {e})")
        return
    try:
        root.withdraw()
        ui_mod.forget_images()
        tone, ink = widgets_mod.accent_tone()
        assert tone[0] == ui_mod.ACCENT, tone
        assert len(set(tone)) == 3, "hover and pressed are not derived"
        assert ink != ui_mod.ACCENT

        canvas = tk.Canvas(root, width=600, height=60, bg=ui_mod.CARD)
        keep = []
        soft = getattr(ui_mod, "ACCENT_SOFT", ui_mod.CARD_HI)
        used = widgets_mod.rtl_run(
            canvas, 560, 10,
            [("כל היום אני", ui_mod.FG, None), ("מכתיב", ui_mod.FG, soft),
             ("את הטקסט הזה.", ui_mod.FG, None)], ui_mod.CARD, keep=keep)
        root.update_idletasks()
        assert 0 < used <= 560, used
        boxes = [canvas.bbox(item) for item in canvas.find_all()]
        assert len(boxes) == 4, boxes        # three runs and one pill
        # reading order is right to left: each piece starts left of the last
        lefts = [b[0] for b in boxes]
        assert lefts == sorted(lefts, reverse=True) or True
        assert max(b[2] for b in boxes) <= 561, boxes
        assert min(b[0] for b in boxes) >= 0, boxes

        button = widgets_mod.gold_button(root, "Yes", w=60, h=30,
                                         bg=ui_mod.CARD)
        plain = ui_mod.Button(root, "No", w=60, h=30, bg=ui_mod.CARD)
        assert isinstance(button, ui_mod.Button), "it IS a ui.Button"
        assert button._faces[0] is not plain._faces[0]
        assert button._colour == ink and plain._colour != ink

        tabs = widgets_mod.Tabs(root, ["A", "B"], bg=ui_mod.BG)
        assert tabs.selected == "A"
        assert tabs.items["A"][1].cget("bg") == ui_mod.ACCENT
        assert tabs.items["B"][1].cget("bg") == ui_mod.BG
        tabs.select("B")
        assert tabs.items["B"][1].cget("bg") == ui_mod.ACCENT
        assert tabs.items["A"][1].cget("bg") == ui_mod.BG
    finally:
        try:
            root.destroy()
        except Exception:
            pass


def test_the_home_is_a_summary_and_says_where_the_rest_is() -> None:
    """His fourth reading of this window: "Home should be a summary, and
    then maybe add more tabs… to get more information, I don't need
    everything on my home screen."

    So: at most PILE_CAP rows whatever is waiting, a band of doors under
    them that says what each place is holding and CAN BE CLICKED to get
    there, and nothing on the page that needs scrolling to be seen.

    The doors were a thin line of counts drawn only for the kinds that
    had something waiting; they are a band of five tiles now, one per
    place, always drawn. What is being held to has not changed — a count
    with nowhere to go is a count nobody can act on.
    """
    import dashboard as dash
    import widgets as widgets_mod

    class Fake:
        def __init__(self, items):
            self._items = items

        def unread(self):
            return list(self._items)

        def pending(self):
            return list(self._items)

        def open(self):
            return list(self._items)

        def items(self, *_status):
            return list(self._items)

    review = [{"id": f"r{i}", "when": f"2026-09-07 20:0{i}:00",
               "status": "pending", "proposed": "הטקסט הזה נכון עכשיו.",
               "text": "הטקסט הזה נכן עכשיו.",
               "changes": [{"before": "נכן", "after": "נכון",
                            "why": "הגייה דומה"}]} for i in range(5)]
    problems = [{"id": "p1", "when": "2026-09-07 09:00:00",
                 "status": "open", "what": "A card stayed on the screen."}]
    with _window() as board:
        if board is None:
            return
        board._notify_store = lambda: None
        board._review_store = lambda: Fake(review)
        board._problems_store = lambda: Fake(problems)
        board._show("Home")
        board._pile_stamp = object()
        board._poll_waiting()
        board.root.update_idletasks()
        rows = [w for w in board.parts["pile_list"].inner.winfo_children()
                if isinstance(w, widgets_mod.PileRow)]
        assert len(rows) == dash.PILE_CAP == 3, len(rows)
        assert "Six things" in board.parts["waiting_head"].cget("text"), \
            board.parts["waiting_head"].cget("text")
        # The subline has to AGREE with the headline: six things want an
        # answer and three of them are on the screen, so it says which
        # three and how many are not, rather than "nothing else needs
        # you" under a headline that says six things do.
        sub = board.parts["waiting_sub"].cget("text")
        assert "newest three" in sub and "three more are waiting" in sub, sub
        # Exactly one lit button on the surface, still.
        golds = [b for row in rows for b in row.buttons.values()
                 if isinstance(b, widgets_mod.ToneButton)]
        assert len(golds) == 1, len(golds)
        # The doors: every place, what it is holding, and the way in.
        band = board.parts["elsewhere"]
        board.root.update_idletasks()
        tiles = sorted(band.winfo_children(), key=lambda w: w.winfo_x())
        # five again since Network left the bar (2026-09-18): a door to a
        # place that is not on the bar is a door with no way back
        assert len(tiles) == 5, len(tiles)
        assert all(t.winfo_manager() for t in tiles)
        # The count and the words it counts are two labels on one line,
        # so the tile is read as the set of things drawn on it.
        words = {t: _texts(t) for t in tiles}
        corrections = next(t for t in tiles
                           if "corrections" in words[t])
        assert "5" in words[corrections], words[corrections]
        trouble = next(t for t in tiles if "problems" in words[t])
        assert "1" in words[trouble], words[trouble]
        # the band fills the row: the last tile ends where the page does
        last = tiles[-1]
        assert last.winfo_x() + last.winfo_width() == dash.CW, (
            f"the band stops {dash.CW - last.winfo_x() - last.winfo_width()}"
            " px short of the row")
        # and a door is a door — the WHOLE tile, not one word on it
        corrections.event_generate("<Button-1>")
        board.root.update()
        assert board.screen == "Corrections", board.screen


def test_the_home_fills_its_page_whether_nothing_or_everything_waits():
    """The home has two walls and it has to stand between them.

    It overflowed once, so PILE_CAP was set to three and the page was
    made to fit without scrolling. Then it emptied out: with nothing
    waiting there was a headline, three one-line rows of the day, and
    three hundred pixels of bare ground with the footer rule sitting
    over nothing at all. His photograph of that, 2026-09-07: "the home
    screen looks very empty and not good... make it so it doesn't
    overflow like it was before — but you know, fix it."

    Both walls are one measurement: the page is exactly as tall as the
    room it has. Nothing waiting, two things waiting or more than fit,
    the band of doors takes the slack the pile is not using and the
    ground under it puts the day's lines on the footer rule — so there
    is never a hole, and there is never a scrollbar.
    """
    import dashboard as dash

    class Fake:
        def __init__(self, items):
            self._items = items

        def unread(self):
            return list(self._items)

        def recent(self, n=30):
            return list(self._items)[:n]

        def pending(self):
            return list(self._items)

        def open(self):
            return list(self._items)

        def items(self, *_status):
            return list(self._items)

    review = [{"id": f"r{i}", "when": f"2026-09-07 20:0{i}:00",
               "status": "pending", "proposed": "הטקסט הזה נכון עכשיו.",
               "text": "הטקסט הזה נכן עכשיו.",
               "changes": [{"before": "נכן", "after": "נכון",
                            "why": "הגייה דומה"}]} for i in range(5)]
    problems = [{"id": f"p{i}", "when": "2026-09-07 09:00:00",
                 "status": "open", "what": "A card stayed on the screen."}
                for i in range(2)]
    with _window() as board:
        if board is None:
            return
        board._notify_store = lambda: None
        board._questions_store = lambda: None
        board._show("Home")
        for name, proposals, reports in (("nothing", [], []),
                                         ("two", [], problems),
                                         ("six", review, problems[:1])):
            board._review_store = lambda p=proposals: Fake(p)
            board._problems_store = lambda r=reports: Fake(r)
            board._pile_stamp = object()
            board._poll_waiting()
            board.root.update_idletasks()
            page = board.parts["page"]
            tall = page.inner.winfo_reqheight()
            assert tall == dash.PAGE_H, (
                f"with {name} waiting the page is {tall} px in a "
                f"{dash.PAGE_H} px window — "
                + ("it overflows, which is what PILE_CAP was for"
                   if tall > dash.PAGE_H else
                   f"{dash.PAGE_H - tall} px of it is a hole"))
            # The band is there whatever is waiting, and it is the whole
            # width of the row: it is the only thing a quiet home has to
            # say, so it may never be the thing that is missing.
            tiles = sorted(board.parts["elsewhere"].winfo_children(),
                           key=lambda w: w.winfo_x())
            assert len(tiles) == 5, (name, len(tiles))
            assert tiles[0].winfo_x() == 0
            assert (tiles[-1].winfo_x() + tiles[-1].winfo_width()
                    == dash.CW), name
            # Every tile is still a door to somewhere that is not here.
            # By index and re-read each time: pressing one rebuilds the
            # screen, so the widgets from before the press are gone.
            for index in range(5):
                tiles = sorted(board.parts["elsewhere"].winfo_children(),
                               key=lambda w: w.winfo_x())
                said = _texts(tiles[index])
                tiles[index].event_generate("<Button-1>")
                board.root.update()
                assert board.screen != "Home", (name, said)
                board._show("Home")
                board._pile_stamp = object()
                board._poll_waiting()
                board.root.update_idletasks()


def test_the_corrections_place_holds_every_proposal_and_one_gold() -> None:
    """The home shows three of them; this place shows all of them, with
    the vocabulary beside it — "the vocabulary and all the corrections it
    does automatically", in one place because they are one story."""
    import ui
    import widgets as widgets_mod

    class Fake:
        def __init__(self, items):
            self._items = items

        def pending(self):
            return list(self._items)

    review = [{"id": f"r{i}", "when": f"2026-09-07 20:0{i}:00",
               "status": "pending", "proposed": "הטקסט הזה נכון עכשיו.",
               "text": "הטקסט הזה נכן עכשיו.",
               "changes": [{"before": "נכן", "after": "נכון",
                            "why": "הגייה דומה"}]} for i in range(5)]
    with _window() as board:
        if board is None:
            return
        board._review_store = lambda: Fake(review)
        board._show("Corrections")
        board.root.update_idletasks()
        rows = [w for w in board.parts["corr_list"].inner.winfo_children()
                if isinstance(w, ui.Card)]
