def test_migrate_config_diff_splits_settings_from_state():
    """An old single config.toml differing in three settings and two
    positions becomes exactly three overrides and two state keys, with the
    retired keys dropped."""
    import migrate as migrate_mod
    d = Path(tempfile.mkdtemp(prefix="deskit-migrate-"))
    try:
        old = d / "config.toml"
        text = paths.DEFAULTS_FILE.read_text("utf-8")
        text = text.replace('device = ""', 'device = "Old Mic"', 1)
        old.write_text(text, encoding="utf-8")
        config_mod.set_values(old, {"vocab.max_terms": 41, "polish.when": "known",
                                    "server.enabled": True, "notify.x": 10, "notify.y": 20,
                                    "lookup.dwell_ms": 5})
        settings, state, dropped = migrate_mod.config_diff(old)
        assert settings == {"vocab.max_terms": 41, "polish.when": "known",
                            "server.enabled": True}, settings
        assert state == {"audio.device": "Old Mic", "notify.x": 10, "notify.y": 20}, state
        assert "lookup.dwell_ms" in dropped
    finally:
        shutil.rmtree(d, ignore_errors=True)


def test_migrate_writes_the_two_files_and_retires_the_old_one():
    """End to end in a scratch DATA_DIR (fresh interpreter, DESKIT_HOME):
    --migrate <old config.toml> writes settings.toml + state.json, a
    second run finds nothing new, and --reset-data --yes removes the
    stores and keeps the two files, plus the routine's journal under
    problems\weekly (the owner's, not the app's)."""
    d = Path(tempfile.mkdtemp(prefix="deskit-migrate-e2e-"))
    try:
        old = d / "old" / "config.toml"
        old.parent.mkdir()
        old.write_text(paths.DEFAULTS_FILE.read_text("utf-8"), encoding="utf-8")
        config_mod.set_values(old, {"vocab.max_terms": 41, "hint.x": 5, "hint.y": 6})
        (old.parent / "vocab.json").write_text('{"version": 1, "corrections": []}', encoding="utf-8")
        (old.parent / "recent").mkdir()
        (old.parent / "recent" / "clip.wav").write_bytes(b"RIFF")
        home = d / "home"
        env = {**os.environ, "DESKIT_HOME": str(home)}
        env.pop("DESKIT_PORTABLE", None)
        run = lambda *args: subprocess.run(
            [sys.executable, "main.py", *args], cwd=str(REPO), env=env,
            capture_output=True, encoding="utf-8", errors="replace", timeout=120)
        out = run("--migrate", str(old.parent))
        assert out.returncode == 0, (out.stdout, out.stderr)
        assert config_mod.read_settings(home / "settings.toml") == {"vocab.max_terms": 41}
        import version as version_mod
        assert config_mod.read_state(home / "state.json") == {
            "hint.x": 5, "hint.y": 6, "config_version": version_mod.CONFIG_VERSION}
        assert (home / "vocab.json").exists() and (home / "audio" / "recent" / "clip.wav").exists()
        assert old.exists(), "a file given by folder is left where it was"
        again = run("--migrate", str(old.parent))
        assert again.returncode == 0, (again.stdout, again.stderr)
        assert any(l.startswith("stores copied") and l.endswith(": 0")
                   for l in again.stdout.splitlines()), again.stdout
        (home / "problems" / "weekly").mkdir(parents=True)
        (home / "problems" / "weekly" / "run.log").write_text("routine", encoding="utf-8")
        (home / "problems" / "outbox").mkdir()
        (home / "problems" / "20260904-224345-0332.json").write_text("{}", encoding="utf-8")
        (home / "vocab.json.bak-20260828").write_text("{}", encoding="utf-8")
        dry = run("--reset-data")
        assert dry.returncode == 1 and "Add --yes" in dry.stdout, dry.stdout
        assert (home / "vocab.json").exists()
        assert "weekly" not in dry.stdout and "outbox" in dry.stdout, dry.stdout
        wipe = run("--reset-data", "--yes")
        assert wipe.returncode == 0, (wipe.stdout, wipe.stderr)
        assert not (home / "vocab.json").exists()
        assert not (home / "vocab.json.bak-20260828").exists()
        assert not (home / "audio" / "recent").exists()
        assert not (home / "problems" / "outbox").exists()
        assert not (home / "problems" / "20260904-224345-0332.json").exists()
        assert (home / "problems" / "weekly" / "run.log").exists(), "the routine's journal stays"
        assert (home / "settings.toml").exists() and (home / "state.json").exists()
    finally:
        shutil.rmtree(d, ignore_errors=True)


def test_reset_data_everything_is_the_uninstallers_delete():
    """--reset-data --yes --everything (D9, the uninstaller's Delete since
    2026-09-20): the secrets through secretstore.delete_all, the Run value
    through autostart.apply(False), the hook lines through
    notify_hook.uninstall_hook, then the whole data folder — settings,
    keys, models and all, which the plain reset keeps (his uninstall of
    the test build kept 4.6 GB of models under a question that promised
    to take them). Without --yes it only says what it would do; on a
    portable or developer copy it refuses, because there the data folder
    is the app folder."""
    import autostart
    import migrate
    import notify_hook
    import secretstore

    d = Path(tempfile.mkdtemp(prefix="deskit-everything-"))
    calls: list = []
    try:
        home = d / "home"
        for rel in ("settings.toml", "state.json", "models/x/model.bin", "packs/gpu/site/a.py",
                    "secrets/hook_token.bin", "logs/app.log"):
            (home / rel).parent.mkdir(parents=True, exist_ok=True)
            (home / rel).write_text("x", "utf-8")
        said: list[str] = []
        with _patched(paths, "DATA_DIR", home), _patched(paths, "PORTABLE", False), \
                _patched(migrate, "_running", lambda: False), \
                _patched(secretstore, "present", lambda: {"groq": "Credential Manager"}), \
                _patched(secretstore, "delete_all", lambda: calls.append("secrets") or ["groq"]), \
                _patched(autostart, "apply", lambda on: calls.append(("run", on)) or True), \
                _patched(notify_hook, "uninstall_hook", lambda *a, **k: calls.append("hooks") or True):
            assert migrate.reset_data(yes=False, out=said.append, everything=True) == 1
            assert calls == [] and (home / "models" / "x" / "model.bin").exists()
            text = "\n".join(said)
            assert "EVERYTHING" in text and str(home) in text and "Add --yes" in text, text
            said.clear()
            assert migrate.reset_data(yes=True, out=said.append, everything=True) == 0
            assert calls == ["secrets", ("run", False), "hooks"], calls
            assert not home.exists(), "the folder stayed"
            assert any(l.startswith("secrets removed: groq") for l in said), said
        with _patched(paths, "DATA_DIR", home), _patched(paths, "PORTABLE", True), \
                _patched(migrate, "_running", lambda: False):
            calls.clear(); said.clear()
            home.mkdir()
            assert migrate.reset_data(yes=True, out=said.append, everything=True) == 2
            assert calls == [] and home.exists() and "beside the app" in said[0], said
        src = (REPO / "main.py").read_text("utf-8")
        assert 'parser.add_argument("--everything"' in src
        assert "everything=args.everything" in src
    finally:
        shutil.rmtree(d, ignore_errors=True)


def test_notify_hook_reads_the_port_through_the_layers():
    """The hook's port comes from state.json first, then settings.toml,
    then defaults.toml."""
