# ------------------------------------------------------- the secret store

class _consented:
    """Open the named [privacy] gates for the block, the way the person's
    [Turn on] would — a row in the tests' scratch consent.json and the
    mirrored key in the scratch settings.toml — and shut them again on
    the way out. Nothing here can reach the owner's files: paths.CONSENT_FILE
    and paths.SETTINGS_FILE were repointed at import."""

    def __init__(self, *kinds):
        self.kinds = kinds

    def __enter__(self):
        import privacy
        assert str(_SCRATCH_HOME) in str(paths.CONSENT_FILE), paths.CONSENT_FILE
        self._mod = privacy
        for kind in self.kinds:
            privacy.grant(kind)
        return privacy

    def __exit__(self, *exc):
        for kind in self.kinds:
            self._mod.withdraw(kind)
        return False


class _test_cred_prefix:
    """Point secretstore's Credential Manager entries at ``DeskIT.test/``
    for the block, and leave none of them behind. The real ``DeskIT/``
    entries are the owner's keys and no test may touch them."""

    def __enter__(self):
        import secretstore
        self._mod = secretstore
        self._old = secretstore.TARGET_PREFIX
        secretstore.TARGET_PREFIX = "DeskIT.test"
        for name in secretstore.CRED_NAMES:
            secretstore.delete(name)
        return secretstore

    def __exit__(self, *exc):
        for name in self._mod.CRED_NAMES:
            self._mod.delete(name)
        self._mod.TARGET_PREFIX = self._old
        return False


def test_secrets_backend_by_name():
    """groq/gemini live in Windows Credential Manager (round trip, then
    gone), phone_token in a DPAPI blob under secrets\ that never holds
    the plaintext; an unknown name is refused, an empty set() deletes."""
    import secretstore
    with _test_cred_prefix() as store:
        assert store.get("groq") is None
        store.set("groq", "gsk_fixture_0123456789")
        assert store.get("groq") == "gsk_fixture_0123456789"
        assert store.present()["groq"] == "Windows Credential Manager (DeskIT.test/groq)"
        assert store.delete("groq") is True and store.delete("groq") is False
        assert store.get("groq") is None
    # DPAPI, under the tests' scratch home
    blob = secretstore.blob_path("phone_token")
    assert str(blob).startswith(str(_SCRATCH_HOME)), blob
    secretstore.delete("phone_token")
    try:
        secretstore.set("phone_token", "tok-fixture-abcdef")
        assert blob.is_file()
        assert b"tok-fixture-abcdef" not in blob.read_bytes(), "plaintext on disk"
        assert secretstore.get("phone_token") == "tok-fixture-abcdef"
        secretstore.set("phone_token", "")
        assert not blob.exists() and secretstore.get("phone_token") is None
    finally:
        secretstore.delete("phone_token")
    try:
        secretstore.get("cerebras")
    except KeyError:
        pass
    else:
        raise AssertionError("an unknown secret name was accepted")


def test_secrets_lookup_order():
    """Credential Manager beats DESKIT_* in the environment, which beats
    the developer's bare GROQ_API_KEY / .env; the bare name and the .env
    are read only in a portable copy; the old GOOGLE_API_KEY and
    CEREBRAS_API_KEY names are never read anywhere."""
    import secretstore
    env_file = secretstore.ENV_FILE.parent / ".env.lookup-test"
    env_file.write_text('GROQ_API_KEY="from-dot-env"\n'
                        "GOOGLE_API_KEY=borrowed-gcloud\n"
                        "CEREBRAS_API_KEY=dead-tier\n", encoding="utf-8")
    saved_env = {k: os.environ.get(k) for k in
                 ("DESKIT_GROQ_API_KEY", "GROQ_API_KEY", "GOOGLE_API_KEY",
                  "CEREBRAS_API_KEY", "GEMINI_API_KEY", "DESKIT_GEMINI_API_KEY")}
    old_file, old_portable = secretstore.ENV_FILE, paths.PORTABLE
    try:
        for k in saved_env:
            os.environ.pop(k, None)
        secretstore.ENV_FILE = env_file
        paths.PORTABLE = True
        with _test_cred_prefix() as store:
            assert store.find_key("groq") == ("from-dot-env", ".env.lookup-test file (developer copy)")
            os.environ["GROQ_API_KEY"] = "from-bare-env-var"
            assert store.find_key("groq") == ("from-bare-env-var", "environment variable GROQ_API_KEY")
            os.environ["DESKIT_GROQ_API_KEY"] = "from-env-var"
            assert store.find_key("groq") == ("from-env-var", "environment variable DESKIT_GROQ_API_KEY")
            store.set("groq", "from-credential-manager")
            assert store.find_key("groq") == ("from-credential-manager",
                                              "Windows Credential Manager (DeskIT.test/groq)")
            store.delete("groq")
            os.environ.pop("DESKIT_GROQ_API_KEY")
            paths.PORTABLE = False
            assert store.find_key("groq") == (None, "not found"), \
                "an installed copy read the bare variable or .env"
            os.environ.pop("GROQ_API_KEY")
            paths.PORTABLE = True
            # the retired names: set in the environment AND in .env, still unread
            os.environ["GOOGLE_API_KEY"] = "borrowed-gcloud"
            os.environ["CEREBRAS_API_KEY"] = "dead-tier"
            assert store.find_key("gemini") == (None, "not found")
            assert apikey.find_key(("GOOGLE_API_KEY",)) == (None, "not found")
            assert apikey.find_key(("CEREBRAS_API_KEY",)) == (None, "not found")
            assert apikey.find_cerebras_key() == (None, "not found")
            # the shim maps the old env names to the store's names
            os.environ["DESKIT_GEMINI_API_KEY"] = "gem-from-env"
            assert apikey.find_api_key()[0] == "gem-from-env"
            assert apikey.find_key(("GEMINI_API_KEY", "GOOGLE_API_KEY"))[0] == "gem-from-env"
            assert "CEREBRAS_API_KEY" in apikey.CEREBRAS_MISSING_KEY_MESSAGE
            assert "--set-key groq" in apikey.GROQ_MISSING_KEY_MESSAGE
    finally:
        secretstore.ENV_FILE = old_file
        paths.PORTABLE = old_portable
        for k, v in saved_env.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        env_file.unlink(missing_ok=True)


def test_secrets_never_on_disk_in_data_dir():
    """Fresh interpreter, DESKIT_HOME: --set-key stores a fixture key,
    --keys names where it is and never the value, and no file under the
    data folder holds the key; --delete-key takes it back out. The
    hatch selects the DeskIT.test/ prefix, so the owner's entries are
    never in play; the stranger hatch beside it makes the copy an
    installed one, so the owner's .env (gemini on his PC) is not read
    either."""
    d = Path(tempfile.mkdtemp(prefix="deskit-secrets-e2e-"))
    fixture = "gsk_fixture_e2e_" + "x" * 24
    env = {**os.environ, "DESKIT_HOME": str(d), "DESKIT_STRANGER": "1"}
    for var in ("DESKIT_PORTABLE", "GROQ_API_KEY", "GEMINI_API_KEY",
                "DESKIT_GROQ_API_KEY", "DESKIT_GEMINI_API_KEY"):
        env.pop(var, None)          # the owner's shell must not answer
    run = lambda *args, **kw: subprocess.run(
        [sys.executable, "main.py", *args], cwd=str(REPO), env=env,
        capture_output=True, encoding="utf-8", errors="replace", timeout=120, **kw)
    try:
        out = run("--set-key", "groq", input=fixture + "\n")
        assert out.returncode == 0, (out.stdout, out.stderr)
        assert "DeskIT.test/groq" in out.stdout and fixture not in out.stdout, out.stdout
        keys = run("--keys")
        assert keys.returncode == 0 and "DeskIT.test/groq" in keys.stdout, keys.stdout
        assert fixture not in keys.stdout
        assert "gemini" in keys.stdout and "not set" in keys.stdout, keys.stdout
        for p in d.rglob("*"):
            if p.is_file():
                assert fixture.encode() not in p.read_bytes(), p
        gone = run("--delete-key", "groq")
        assert gone.returncode == 0 and "Removed" in gone.stdout, gone.stdout
        after = run("--keys").stdout
        assert "DeskIT.test/groq" not in after and "groq" in after, after
    finally:
        subprocess.run([sys.executable, "main.py", "--delete-key", "groq"],
                       cwd=str(REPO), env=env, capture_output=True, timeout=60)
        shutil.rmtree(d, ignore_errors=True)


def test_phone_token_moves_from_the_text_file_into_dpapi():
    """A server_token.txt from an older version is read once, kept as the
    SAME token in the DPAPI blob (the phone bookmarked it), and deleted;
    a copy with neither gets a fresh token that then stays put."""
    import secretstore
    import server as server_mod
    legacy = _SCRATCH_HOME / "phone-legacy" / "server_token.txt"
    legacy.parent.mkdir(parents=True, exist_ok=True)
    legacy.write_text("legacy-token-0123456789abcdef\n", encoding="utf-8")
    old_file = server_mod.TOKEN_FILE
    secretstore.delete("phone_token")
    try:
        server_mod.TOKEN_FILE = legacy
        assert server_mod.load_token() == "legacy-token-0123456789abcdef"
        assert not legacy.exists(), "the plaintext copy stayed behind"
        assert secretstore.get("phone_token") == "legacy-token-0123456789abcdef"
        assert server_mod.load_token() == "legacy-token-0123456789abcdef"
        secretstore.delete("phone_token")
        fresh = server_mod.load_token()
        assert len(fresh) >= 20 and fresh != "legacy-token-0123456789abcdef"
        assert server_mod.load_token() == fresh
        assert not legacy.exists(), "a new token was written as plaintext"
        import notify_hook as hook
        assert hook.read_token() == fresh, "the hook reads the same store"
    finally:
        server_mod.TOKEN_FILE = old_file
        secretstore.delete("phone_token")
        shutil.rmtree(legacy.parent, ignore_errors=True)


def test_migrate_imports_env_keys_into_credential_manager():
    """--migrate's key step: the two keys of an old .env go into Credential
    Manager unless one is already there; the retired names are reported,
    the file is left alone, and no value is ever printed."""
    import migrate as migrate_mod
    d = Path(tempfile.mkdtemp(prefix="deskit-envkeys-"))
    env_file = d / ".env"
    env_file.write_text("GEMINI_API_KEY=gem-fixture-value\n"
                        "GROQ_API_KEY = 'gsk-fixture-value'\n"
                        "CEREBRAS_API_KEY=dead\n", encoding="utf-8")
    lines: list[str] = []
    try:
        with _test_cred_prefix() as store:
            store.set("gemini", "gem-already-there")
            assert migrate_mod.import_env_keys(env_file, lines.append) == 1
            assert store.get("groq") == "gsk-fixture-value"
            assert store.get("gemini") == "gem-already-there", "an existing key was overwritten"
            text = "\n".join(lines)
            assert "groq key: copied" in text and "gemini key: already" in text, text
            assert "CEREBRAS_API_KEY: no longer read" in text, text
            for value in ("gem-fixture-value", "gsk-fixture-value", "gem-already-there", "dead"):
                assert value not in text, text
            assert env_file.exists(), ".env was deleted"
            assert migrate_mod.import_env_keys(d / "missing.env", lines.append) == 0
    finally:
        shutil.rmtree(d, ignore_errors=True)


def test_only_secretstore_touches_the_key_backends():
    """Static: Credential Manager, DPAPI, the .env file and the raw key
    variable names appear in secretstore.py and nowhere else in the
    product tree (D3, D12 lock 1). apikey.py is a shim that asks it."""
    backends = re.compile(r"win32cred|CryptProtectData|CryptUnprotectData|"
                          r"\bENV_FILE\b|/\s*\"\.env\"|"
                          r"environ(?:\.get)?\(?\[?\s*[\"'](?:GROQ|GEMINI|GOOGLE|CEREBRAS)_API_KEY")
    bad = []
    for py in sorted(REPO.glob("*.py")) + sorted((REPO / "transcribers").glob("*.py")):
        if py.name in ("secretstore.py",) or py.name.startswith("tests"):
            continue
        for i, line in enumerate(py.read_text(encoding="utf-8").splitlines(), 1):
            if backends.search(line):
                bad.append(f"{py.name}:{i}: {line.strip()}")
    assert not bad, "\n".join(bad)


# ---------------------------------------------- net.py, the one door out
#
# DISTRIBUTION_PLAN.md 5.4-5.8, D12 lock 2. Every test here stands in for
# the wire at net._connect — the one seam — so nothing leaves this PC, and
# every row a test provokes lands in the scratch network.log (see the
# guard at the top of this file), never in the owner's.

_TRANSPORT_IMPORT = re.compile(
    r"^\s*(?:import|from)\s+(?:urllib\.(?:request|error)\b|urllib\s*(?:$|,|;)"
    r"|http\.client\b|httpx\b|requests\b|socket\b|ssl\b)")


#: The one allowance beside net.py: server.py is the INBOUND phone
#: listener, not an egress path, and it touches the `socket` module only
#: for the listener's own option — SO_EXCLUSIVEADDRUSE, which stops another
#: local user squatting its 127.0.0.1 port and reading the token off the
#: wire. That is the whole allowance; every other module and every other
#: transport (urllib.request, http.client, httpx, requests, ssl) stays
#: banned outside net.py, and no other module may import socket.
_TRANSPORT_ALLOW: dict[str, tuple[str, ...]] = {"server.py": ("socket",)}


def test_only_net_imports_transport():
    """Static: urllib.request, http.client, httpx, requests, socket and
    ssl are imported by net.py and by nothing else in the product tree.
    server.py's http.server is the INBOUND listener, not a transport, and
    urllib.parse is string work; server.py's one `import socket` is for
    the listener's exclusive-bind option (see _TRANSPORT_ALLOW). The same
    grep a sceptic runs (5.10)."""
    bad = []
    for py in sorted(REPO.glob("*.py")) + sorted((REPO / "transcribers").glob("*.py")):
        if py.name == "net.py" or py.name.startswith("tests"):
            continue
        allowed = _TRANSPORT_ALLOW.get(py.name, ())
        for i, line in enumerate(py.read_text(encoding="utf-8").splitlines(), 1):
            if not _TRANSPORT_IMPORT.match(line):
                continue
            if any(re.match(rf"^\s*import\s+{mod}\b", line) for mod in allowed):
                continue
            bad.append(f"{py.name}:{i}: {line.strip()}")
    assert not bad, "\n".join(bad)
    # And the allowlist is what the plan froze: Cerebras is out (D6),
    # Anthropic was never in, loopback is the one host offline mode keeps.
    import net as net_mod
    assert isinstance(net_mod.ALLOWED_HOSTS, frozenset)
    assert "api.cerebras.ai" not in net_mod.ALLOWED_HOSTS
    assert not any("anthropic" in h for h in net_mod.ALLOWED_HOSTS)
    assert {"127.0.0.1", "api.groq.com", "generativelanguage.googleapis.com"} <= net_mod.ALLOWED_HOSTS


def test_net_refuses_unlisted_host():
    """A request to a host outside ALLOWED_HOSTS raises EgressRefused
    before any socket is opened — the fake transport counts zero
    connects — and the refusal is itself a row. Plain http to a remote
    host is refused too; loopback over http passes; offline mode refuses
    every remote host and still lets loopback through; an unknown
    purpose is a programming error, not a policy answer."""
    import net as net_mod

    connects: list[str] = []

    def fake_connect(method, url, headers, body, timeout_s):
        connects.append(url)
        return _FakeRaw(b"{}")

    with _patched(net_mod, "_connect", fake_connect):
        before = len(net_mod.rows())
        try:
            net_mod.request("GET", "https://example.com/x", "polish")
        except net_mod.EgressRefused as e:
            assert e.host == "example.com" and e.purpose == "polish", e
        else:
            raise AssertionError("an unlisted host was admitted")
        assert connects == [], connects
        row = net_mod.rows()[-1]
        assert (row.host, row.purpose, row.status) == ("example.com", "polish", "refused"), row
        try:
            net_mod.request("GET", "http://api.groq.com/openai/v1/models", "key-test")
        except net_mod.EgressRefused as e:
            assert "https" in e.reason, e
        else:
            raise AssertionError("plain http left for a remote host")
        status, _headers, body = net_mod.request(
            "GET", "http://127.0.0.1:11434/api/ps", "ollama")
        assert status == 200 and body == b"{}"
        assert connects == ["http://127.0.0.1:11434/api/ps"], connects
        with _patched(net_mod, "offline", True):
            try:
                net_mod.request("GET", "https://api.groq.com/openai/v1/models", "key-test")
            except net_mod.EgressRefused as e:
                assert "offline" in e.reason, e
            else:
                raise AssertionError("offline mode let a remote host through")
            net_mod.request("GET", "http://127.0.0.1:11434/api/ps", "ollama")
        assert len(connects) == 2, connects
        try:
            net_mod.request("GET", "https://api.groq.com/openai/v1/models", "bogus")
        except ValueError:
            pass
        else:
            raise AssertionError("an unknown purpose was accepted")
        assert len(net_mod.rows()) - before == 5, net_mod.rows()[before:]
    text = paths.NETWORK_LOG.read_text(encoding="utf-8")
    assert "example.com | polish | 0 | 0 | refused | - | -" in text, text
    assert "/x" not in text and "/openai" not in text and "/api/ps" not in text, \
        "a URL path reached the log"


def test_net_refuses_a_non_http_scheme_even_on_loopback():
    """Only http(s) may ever leave through the one door. The loopback
    exemption that lets Ollama speak plain http used to skip the scheme
    check entirely for 127.0.0.1, so `file://127.0.0.1/C:/...` passed
    admission and urllib's own FileHandler read a local file through the
    chokepoint. Now file:, ftp:, data: and anything but http(s) is refused
    on every host — loopback included — before a socket (or a file) opens,
    and the refusal is a row. http stays allowed to loopback; https stays
    allowed anywhere."""
    import net as net_mod

    connects: list[str] = []

    def fake_connect(method, url, headers, body, timeout_s):
        connects.append(url)
        return _FakeRaw(b"{}")

    with _patched(net_mod, "_connect", fake_connect):
        for bad_url in ("file://127.0.0.1/C:/Windows/win.ini",
                        "file:///C:/Windows/win.ini",
                        "ftp://127.0.0.1/x",
                        "data:text/plain,hi"):
            try:
                net_mod.request("GET", bad_url, "ollama")
            except net_mod.EgressRefused as e:
                assert "scheme" in e.reason or "host" in e.reason, (bad_url, e)
            else:
                raise AssertionError(f"a non-http scheme was admitted: {bad_url}")
        assert connects == [], connects
        # the legitimate loopback http and remote https still pass
        net_mod.request("GET", "http://127.0.0.1:11434/api/ps", "ollama")
        assert connects == ["http://127.0.0.1:11434/api/ps"], connects


def test_net_never_puts_key_in_url():
    """A Google URL carrying key= is refused. The fixture keys travel only
    in the header net.py attaches for that secret's own host —
    Authorization: Bearer for groq, x-goog-api-key for gemini — so a groq
    key can never go to Google, a gemini key never to Groq, and a caller's
    own bearer never to a remote host. The log names the secret, never
    the value; a secret nothing holds is SecretMissing, which the
    fall-through `except Exception` of every feature already catches."""
    import net as net_mod
    import secretstore

    groq_fixture = "gsk_fixture_url_" + "q" * 24
    gem_fixture = "AIza_fixture_url_" + "g" * 20
    captured: list[tuple[str, dict]] = []

    def fake_connect(method, url, headers, body, timeout_s):
        captured.append((url, dict(headers)))
        return _FakeRaw(b"{}")

    google = "https://generativelanguage.googleapis.com/v1beta/models"
    groq = "https://api.groq.com/openai/v1/chat/completions"
    with _test_cred_prefix() as store, _consented("cloud_text"), \
            _patched(net_mod, "_connect", fake_connect):
        store.set("groq", groq_fixture)
        store.set("gemini", gem_fixture)
        for url, purpose, secret, why in (
                (google + "?key=" + gem_fixture, "catalog", "gemini", "key in the query"),
                (google, "catalog", "groq", "groq key to Google"),
                (groq, "polish", "gemini", "gemini key to Groq"),
                (groq, "polish", "phone_token", "the phone token off this PC")):
            try:
                net_mod.request("GET", url, purpose, secret=secret)
            except net_mod.EgressRefused:
                pass
            else:
                raise AssertionError(f"admitted: {why}")
        try:
            net_mod.request("GET", groq, "polish",
                            headers={"Authorization": "Bearer " + groq_fixture})
        except net_mod.EgressRefused as e:
            assert "Authorization" in e.reason, e
        else:
            raise AssertionError("a caller's own bearer left for a remote host")
        assert captured == [], captured
        net_mod.request("GET", google, "catalog", secret="gemini")
        net_mod.post_json(groq, "polish", {"x": 1}, secret="groq")
        (u1, h1), (u2, h2) = captured
        assert u1 == google and h1["x-goog-api-key"] == gem_fixture and "Authorization" not in h1, h1
        assert u2 == groq and h2["Authorization"] == "Bearer " + groq_fixture \
            and "x-goog-api-key" not in h2, h2
        assert h2["User-Agent"] == "deskit/1.0" and h2["Content-Type"] == "application/json"
        # The one bearer a caller may hand over itself: to our own listener.
        net_mod.request("POST", "http://127.0.0.1:8756/notify", "notify",
                        headers={"Authorization": "Bearer phone-fixture"}, body=b"{}")
        assert captured[-1][1]["Authorization"] == "Bearer phone-fixture"
        with _patched(secretstore, "find_key", lambda name: (None, "not found")):
            try:
                net_mod.request("GET", groq, "polish", secret="groq")
            except net_mod.SecretMissing as e:
                assert e.name == "groq" and isinstance(e, net_mod.NetError)
            else:
                raise AssertionError("a request went out with no key to attach")
    text = paths.NETWORK_LOG.read_text(encoding="utf-8")
    for value in (groq_fixture, gem_fixture, "phone-fixture"):
        assert value not in text, "a secret value reached network.log"
    tail = text.splitlines()[-4:]
    assert any("| catalog | 0 | 2 | 200 | gemini | -" in line for line in tail), tail
    import privacy as privacy_mod
    assert any("| polish | 8 | 2 | 200 | groq | cloud_text@" + privacy_mod.TEXT_VERSIONS["cloud_text"]
               in line for line in tail), tail


def test_network_log_row_shape():
    """Each row has exactly the eight fields of 5.4 — time, host,
    purpose, bytes up, bytes down, HTTP status or error class, secret
    NAME, consent — and no row carries a body fragment, a header value or
    a query string. Bytes are counted on a whole read and on a streamed
    one alike; a dead server's row names the error class; the in-memory
    table and the file say the same thing."""
    import net as net_mod

    reply = b'{"message":{"content":"body-secret-text"}}\n' * 3

    def fake_connect(method, url, headers, body, timeout_s):
        if "dead" in url:
            raise net_mod.NetError("refused") from ConnectionRefusedError(10061, "refused")
        return _FakeRaw(reply, headers={"X-Fixture": "header-secret-value"})

    with _patched(net_mod, "_connect", fake_connect):
        before = len(net_mod.rows())
        up = b'{"prompt":"up-secret-text"}'
        status, headers, body = net_mod.request(
            "POST", "http://127.0.0.1:11434/api/chat?verbose=1&q=query-secret",
            "ollama", body=up)
        assert status == 200 and body == reply and headers["X-Fixture"] == "header-secret-value"
        with net_mod.open("POST", "http://127.0.0.1:11434/api/chat", "lookup", body=up) as r:
            assert r.status == 200
            lines = list(r)
            assert len(lines) == 3, lines
            r.close()                      # a watchdog closing early ...
        try:
            net_mod.request("GET", "http://127.0.0.1:11434/dead", "ollama")
        except net_mod.NetError:
            pass
        else:
            raise AssertionError("a dead server answered")
    rows = net_mod.rows()[before:]
    assert [r.purpose for r in rows] == ["ollama", "lookup", "ollama"], rows
    assert (rows[0].up, rows[0].down, rows[0].status) == (len(up), len(reply), 200), rows[0]
    assert (rows[1].up, rows[1].down, rows[1].status) == (len(up), len(reply), 200), rows[1]
    assert (rows[2].up, rows[2].down, rows[2].status) == (0, 0, "ConnectionRefusedError"), rows[2]
    assert all(r.host == "127.0.0.1" and r.secret == "-" and r.consent == "-" for r in rows)
    text = paths.NETWORK_LOG.read_text(encoding="utf-8")
    tail = text.splitlines()[-3:]
    assert tail == [net_mod.format_row(r) for r in rows], (tail, rows)
    for line in tail:
        fields = line.split(" | ")
        assert len(fields) == 8, fields
        assert re.fullmatch(r"\d{4}-\d\d-\d\d \d\d:\d\d:\d\d", fields[0]), fields[0]
        int(fields[3]), int(fields[4])
    for leak in ("body-secret-text", "header-secret-value", "up-secret-text",
                 "query-secret", "verbose", "/api/chat", "X-Fixture"):
        assert leak not in text, f"{leak!r} reached network.log"


def test_plain_dictation_touches_only_loopback():
    """D27's phase-1 acceptance, as a test: a local-backend dictation on a
    copy with NO key stored — the shipped defaults, repair on and Groq
    preferred — tries no host but 127.0.0.1. The fake wire refuses every
    connection the way a PC without Ollama does; what is asserted is the
    set of hosts that were TRIED, from the table and from the file, and
    that the text still landed (raw, unrepaired). The owner's own keys
    are taken out of play the way an installed copy never sees them:
    the test prefix in Credential Manager, no DESKIT_* variables, and
    PORTABLE off so neither the bare names nor .env are read."""
    import main as main_mod
    import net as net_mod
    from urllib.parse import urlsplit

    tried: list[str] = []

    def fake_connect(method, url, headers, body, timeout_s):
        tried.append(url)
        raise net_mod.NetError("refused") from ConnectionRefusedError(10061, "refused")

    tmp = Path(tempfile.mkdtemp(prefix="dictation-loopback-"))
    fake = _FakeInjector()
    hidden = {k: os.environ.pop(k) for k in ("DESKIT_GROQ_API_KEY", "DESKIT_GEMINI_API_KEY")
              if k in os.environ}
    try:
        with _test_cred_prefix(), _patched(paths, "PORTABLE", False), \
                _patched(net_mod, "_connect", fake_connect), \
                _patched(main_mod, "injector", fake):
            app = _worker_app(_Flaky(0, text="שלום עולם"), tmp)
            app.cfg = dataclasses.replace(app.cfg, polish=config_mod.PolishConfig(
                when="always", min_chars=1, max_wait_s=5))
            assert app.cfg.polish.prefer == "groq", "the shipped default is cloud-first"
            before = len(net_mod.rows())
            app._handle(b"RIFF-audio", 4.0, fake.focus)
        rows = net_mod.rows()[before:]
        hosts = {r.host for r in rows}
        assert tried, "the repair never reached the wire — nothing was proved"
        assert hosts == {"127.0.0.1"}, (hosts, tried)
        assert all(urlsplit(u).hostname == "127.0.0.1" for u in tried), tried
        assert all(r.secret == "-" for r in rows), rows
        landed = [c[-1] for c in fake.calls if c[0] in ("replace", "inject")]
        assert landed == ["שלום עולם"], fake.calls
        text = paths.NETWORK_LOG.read_text(encoding="utf-8").splitlines()[-len(rows):]
        assert all(line.split(" | ")[1] == "127.0.0.1" for line in text), text
    finally:
        os.environ.update(hidden)
        shutil.rmtree(tmp, ignore_errors=True)


# ------------------------------------------------ privacy.py: the gates
#
# DISTRIBUTION_PLAN.md 5.1-5.3, D7. Every test grants in the scratch
# consent.json (_consented) and shuts the gate again on the way out.

def test_privacy_gate_refuses_every_cloud_constructor():
    """With every gate shut each cloud constructor raises ConsentRequired
    BEFORE it looks for a key — and the exception is also the module's
    own error class, so every chain that skips a keyless backend skips
    it the same way. With the gate open and a fixture key it builds;
    with a stale text_version on file it refuses again."""
    import json as json_mod

    import privacy
    import translate as translate_mod
    import transcribers.gemini as tg
    import visual_qa as vq

    import secretstore

    looked = []

    def spy_find_key(name):
        looked.append(name)
        return "gsk_fixture_gate_" + "k" * 20, "test"

    with _patched(secretstore, "find_key", spy_find_key):
        for build, error, kind in (
                (lambda: translate_mod.GroqTranslator("m", 5), translate_mod.TranslationError, "cloud_text"),
                (lambda: translate_mod.GeminiTranslator(["m"], 5), translate_mod.TranslationError, "cloud_text"),
                (lambda: vq.GroqVision("m", 5, 10), vq.QAError, "cloud_screenshots"),
                (lambda: vq.GeminiVision(["m"], 5), vq.QAError, "cloud_screenshots"),
                (lambda: tg.GeminiTranscriber(["m"], 5), tg.TranscriptionError, "cloud_audio")):
            try:
                build()
            except error as e:
                assert isinstance(e, privacy.ConsentRequired), type(e)
                assert e.kind == kind, (e.kind, kind)
            else:
                raise AssertionError(f"{kind}: built with the gate shut")
        assert looked == [], "a key was looked up before the gate was asked"
        with _consented("cloud_text", "cloud_screenshots", "cloud_audio"):
            assert translate_mod.GroqTranslator("m", 5).key_source == "test"
            assert vq.GroqVision("m", 5, 10).key_source == "test"
            assert tg.GeminiTranscriber(["m"], 5).key_source == "test"
        assert looked, "the open gate never reached the key"
        # A row whose words are older than the card: shut, and says so.
        stale = {"consents": [{"kind": "cloud_text", "text_version": "groq-2020-01-01",
                               "when": "2026-01-01T00:00:00", "app_version": "dev"}]}
        paths.CONSENT_FILE.write_text(json_mod.dumps(stale), "utf-8")
        privacy._gates["cloud_text"] = True
        try:
            try:
                translate_mod.GroqTranslator("m", 5)
            except translate_mod.TranslationError as e:
                assert "words changed" in str(e), e
            else:
                raise AssertionError("a stale consent opened the gate")
        finally:
            privacy.withdraw("cloud_text")


def test_consent_round_trip_and_withdraw_teardown():
    """grant writes one atomic row (kind, text_version, when, app_version)
    and mirrors the key into settings.toml; withdraw removes the row,
    clears the key and runs every registered reset once (grant runs
    them too — a leg cached as unavailable must not outlive the card);
    a second withdraw is a no-op; a row removed BEHIND this process's
    back — the dashboard, another process — runs the same resets on the
    next look, and net.py refuses the next request."""
    import json as json_mod

    import net as net_mod
    import privacy

    torn: list[str] = []
    privacy.on_change("cloud_text", lambda: torn.append("polisher"))
    privacy.on_change("cloud_text", lambda: torn.append("punctuator"))
    assert privacy.allowed("cloud_text") is False
    row = privacy.grant("cloud_text")
    assert torn == ["polisher", "punctuator"], "a grant must reset the cached legs too"
    torn.clear()
    assert set(row) == {"kind", "text_version", "when", "app_version"}, row
    on_disk = json_mod.loads(paths.CONSENT_FILE.read_text("utf-8"))["consents"]
    assert on_disk == [row], on_disk
    assert "privacy.cloud_text = true" in paths.SETTINGS_FILE.read_text("utf-8")
    assert privacy.allowed("cloud_text") is True
    assert privacy.tag("cloud_text") == "cloud_text@" + privacy.TEXT_VERSIONS["cloud_text"]
    assert privacy.withdraw("cloud_text") is True
    assert torn == ["polisher", "punctuator"], torn
    assert privacy.allowed("cloud_text") is False
    assert "privacy.cloud_text" not in paths.SETTINGS_FILE.read_text("utf-8"), \
        "false is the default and must not linger as an override"
    assert privacy.withdraw("cloud_text") is False and torn == ["polisher", "punctuator"]
    # Behind our back: another process empties the file.
    privacy.grant("cloud_text")
    torn.clear()
    time.sleep(0.02)
    paths.CONSENT_FILE.write_text(json_mod.dumps({"consents": []}), "utf-8")
    assert privacy.allowed("cloud_text") is False
    assert torn == ["polisher", "punctuator"], torn
    seen: list[str] = []

    def fake_connect(method, url, headers, body, timeout_s):
        seen.append(url)
        return _FakeRaw(b"{}")

    with _patched(net_mod, "_connect", fake_connect), _test_cred_prefix() as store:
        store.set("groq", "gsk_fixture_rt_" + "r" * 24)
        try:
            net_mod.request("GET", "https://api.groq.com/openai/v1/x", "polish", secret="groq")
        except net_mod.EgressRefused as e:
            assert "no consent" in e.reason, e
        else:
            raise AssertionError("a withdrawn consent still let a request out")
        assert seen == []
    privacy._resets.pop("cloud_text", None)


def test_settings_page_cannot_write_privacy_keys():
    """config.save and config.set_values refuse the seven gates (a config
    write can never open one — only privacy.grant may, D7); the two
    switches are ordinary; the generated Settings page lists the gates
    as rows that are not editable and the switches as editable."""
    import settings as settings_mod

    for key in ("privacy.cloud_text", "privacy.account"):
        try:
            config_mod.save({key: True})
        except config_mod.ConfigError as e:
            assert "consent card" in str(e), e
        else:
            raise AssertionError(f"{key} was written by config.save")
    written = paths.SETTINGS_FILE.read_text("utf-8") if paths.SETTINGS_FILE.exists() else ""
    assert "privacy.cloud_text" not in written
    config_mod.save({"privacy.offline": True})
    assert "privacy.offline = true" in paths.SETTINGS_FILE.read_text("utf-8")
    config_mod.save({"privacy.offline": False})
    with tempfile.TemporaryDirectory() as d:
        one = Path(d) / "config.toml"
        one.write_text('hotkey = "right ctrl"\n[privacy]\ncloud_audio = false\n', "utf-8")
        try:
            config_mod.set_values(one, {"privacy.cloud_audio": True})
        except config_mod.ConfigError:
            pass
        else:
            raise AssertionError("set_values wrote a gate")
        assert "cloud_audio = false" in one.read_text("utf-8")
    sections = settings_mod.read(Path(__file__).resolve().parent / "defaults.toml")
    rows = {st.path: st for st in settings_mod.flatten(sections) if st.section == "privacy"}
    assert set(rows) == {f"privacy.{k}" for k in
                         ("cloud_text", "cloud_audio", "cloud_screenshots", "account",
                          "report_upload", "settings_sync", "history_sync", "update_check",
                          "offline")}, rows
    for path, st in rows.items():
        if st.key in settings_mod.CONSENT_GATES:
            assert st.consent and not st.editable, path
        else:
            assert not st.consent and st.editable, path
    assert "Privacy" in settings_mod.tab_names()


def test_warmups_never_open_a_card():
    """Start-up warm-ups with every gate shut make zero remote requests
    and raise nothing: a shut gate is one INFO line, like a missing key.
    (The card is the controller's to open on a key press, never the
    constructor's — plan 5.2.)"""
    import dataclasses

    import net as net_mod
    import polish as polish_mod
    import visual_qa as vq

    tried: list[str] = []

    def fake_connect(method, url, headers, body, timeout_s):
        tried.append(url)
        raise net_mod.NetError("refused") from ConnectionRefusedError(10061, "refused")

    import privacy

    asked: list[str] = []
    cfg = config_mod.load(Path(__file__).resolve().parent / "defaults.toml")
    cfg = dataclasses.replace(cfg, polish=dataclasses.replace(cfg.polish, max_wait_s=0.5))
    with _patched(apikey, "find_key", lambda names: ("gsk_fixture_warm", "test")), \
            _patched(net_mod, "_connect", fake_connect), \
            _patched(privacy, "_asker", asked.append):
        polish_mod.Polisher(cfg, _tmp_vocab()).warm()
        for name, build in vq.Chain(cfg)._builders():
            assert name == "ollama", name
            try:
                build().warm()
            except Exception:
                pass
        assert asked == [], f"a warm-up opened a card: {asked}"
        # The same refusal inside a press the person made opens nothing
        # either (2026-09-19 evening: the card met him mid-dictation);
        # the kind is written down once, and the card waits for a button.
        with privacy.pressed():
            for _ in range(3):
                for _b in polish_mod.Polisher(cfg, _tmp_vocab())._backends("שלום"):
                    pass
        assert asked == [], f"a press opened a card: {asked}"
        assert "cloud_text" in privacy._asked
        privacy._asked.discard("cloud_text")
        assert privacy.request("cloud_text") is True and asked == ["cloud_text"], "a button still asks"
        privacy._asked.discard("cloud_text")
    from urllib.parse import urlsplit
    remote = [u for u in tried if urlsplit(u).hostname != "127.0.0.1"]
    assert tried and not remote, (tried, remote)


def test_net_offline_refuses_all_but_loopback():
    """privacy.offline (5.9): every allowlisted host is refused with a
    row that says so, even with a key stored and the gate open, and
    127.0.0.1 still passes; the switch reaches net.py through
    privacy.configure, the way main and the live option path call it."""
    import dataclasses

    import net as net_mod
    import privacy

    seen: list[str] = []

    def fake_connect(method, url, headers, body, timeout_s):
        seen.append(url)
        return _FakeRaw(b"{}")

    cfg = config_mod.load(Path(__file__).resolve().parent / "defaults.toml")
    on = dataclasses.replace(cfg, privacy=dataclasses.replace(cfg.privacy, offline=True))
    try:
        with _test_cred_prefix() as store, _consented("cloud_text"), \
                _patched(net_mod, "_connect", fake_connect):
            store.set("groq", "gsk_fixture_off_" + "o" * 22)
            privacy.configure(on)
            assert net_mod.offline is True and privacy.allowed("cloud_text") is False
            for url, purpose, secret in (
                    ("https://api.groq.com/openai/v1/chat/completions", "polish", "groq"),
                    ("https://api.groq.com/openai/v1/models", "key-test", None),
                    ("https://api.github.com/repos/x/releases/latest", "update-check", None)):
                try:
                    net_mod.request("GET", url, purpose, secret=secret)
                except net_mod.EgressRefused as e:
                    assert "offline" in e.reason, e
                else:
                    raise AssertionError(f"offline let {purpose} out")
            status, _h, _b = net_mod.request("GET", "http://127.0.0.1:11434/api/ps", "ollama")
            assert status == 200 and seen == ["http://127.0.0.1:11434/api/ps"], seen
            privacy.configure(config_mod.load_layered())   # the mirrored key
            assert net_mod.offline is False and privacy.allowed("cloud_text") is True
            net_mod.request("GET", "https://api.groq.com/openai/v1/models", "key-test")
            assert len(seen) == 2
    finally:
        privacy.configure(cfg)
    rows = [net_mod.format_row(r) for r in net_mod.rows()[-5:]]
    assert sum("| refused |" in r for r in rows) == 3, rows


def test_consent_card_words_and_layout():
    """Every kind has a card whose text_version is the one privacy.py
    writes; each card has a title, the five blocks of plan 5.3 in order,
    the one footer, and two buttons drawn where they are pressed — the
    hit test and regions() agree, the shadow margin belongs to nobody,
    and the card grows with its words rather than clipping them."""
    import consent_card as cc
    import privacy

    for kind in privacy.KINDS:
        words = cc.TEXTS[kind]
        assert words["version"] == privacy.TEXT_VERSIONS[kind], kind
        card = cc.card_for(kind)
        assert card["title"] and card["footer"] == cc.FOOTER
        labels = [label for label, _text in card["blocks"]]
        assert labels == [cc.WHAT, cc.WHOM, cc.ACCOUNT, cc.TERMS, cc.OFF], (kind, labels)
        assert all(text.strip() for _l, text in card["blocks"]), kind
        cache: dict = {}
        w, h = cc.measure(card, 1.0, cache)
        assert w == cc.CARD_W and 200 < h < 900, (kind, w, h)
        boxes = cc.regions(card, 1.0, cache)
        for name, _w in cc.BUTTONS:
            x0, y0, x1, y1 = boxes[name]
            assert cc.hit_test(card, 1.0, (x0 + x1) / 2, (y0 + y1) / 2, cache) == (cc.HTCLIENT, name)
            assert cc.SHADOW <= x0 < x1 <= cc.SHADOW + w and y1 <= cc.SHADOW + h, (name, boxes[name])
        assert cc.hit_test(card, 1.0, cc.SHADOW + 10, cc.SHADOW + 10, cache) == (cc.HTCAPTION, cc.DRAG)
        assert cc.hit_test(card, 1.0, 3, 3, cache) == (cc.HTTRANSPARENT, None)
        img = cc.flat(card, 1.0, cc.TURN_ON, cache)
        assert (img.width, img.height) == (w, h)
        small_w, small_h = cc.measure(card, 0.6, cache)
        assert small_w < w and small_h < h
    # The cloud cards quote the providers' own words, in their words —
    # cut short since 2026-09-19 evening (the owner: "English and much
    # shorter"), the whole quotes in the guide's cloud chapter.
    for kind in ("cloud_text", "cloud_audio", "cloud_screenshots"):
        terms = dict(cc.TEXTS[kind]["blocks"])[cc.TERMS]
        assert "not permitted to use Inputs or Outputs for training" in terms, kind
        assert "to provide, improve, and develop Google products" in terms, kind
        assert not any("א" <= ch <= "ת" for ch in terms), "the card is English now"
    assert cc.RTL is False and cc.LABELS[cc.TURN_ON] == "Turn on"


def test_the_card_answers_reach_privacy():
    """[Turn on] on the overlay card grants the kind (a row, the mirrored
    key, the resets) and [Not now] records a refusal that keeps the card
    down until the next start; a kind asked while one is up waits its
    turn; the same kind is never queued twice. Driven through the card
    object with its thread stubbed out — the painter is the flat image
    the layout test already checks."""
    import consent_card as cc
    import overlay as overlay_mod
    import privacy

    answers: list[tuple] = []
    card = overlay_mod.ConsentCard(on_answer=lambda k, a: answers.append((k, a)))
    card._thread = object()           # "started": show() enqueues
    card.show("cloud_text")
    card.show("cloud_text")
    card.show("cloud_screenshots")
    assert card.current() == "cloud_text" and card._waiting == ["cloud_screenshots"]
    queued = card._q.get_nowait()
    assert queued["kind"] == "cloud_text" and card._q.empty()
    card.pressed(cc.TURN_ON)
    assert answers == [("cloud_text", cc.TURN_ON)]
    assert card.current() == "cloud_screenshots", "the waiting kind did not come up"
    assert card._q.get_nowait()["kind"] == "cloud_screenshots"
    card.pressed(cc.NOT_NOW)
    assert answers[-1] == ("cloud_screenshots", cc.NOT_NOW)
    assert card.current() is None and card._q.get_nowait() is None
    card.pressed("bogus")
    assert len(answers) == 2
    # main's answer handler, on a bare App
    import main as main_mod
    app = main_mod.App.__new__(main_mod.App)
    said: list[str] = []
    app._say = said.append
    try:
        app._consent_answered("cloud_text", cc.TURN_ON)
        assert privacy.allowed("cloud_text") is True and said, said
        app._consent_answered("cloud_screenshots", cc.NOT_NOW)
        assert "cloud_screenshots" in privacy._asked
        assert privacy.allowed("cloud_screenshots") is False
    finally:
        privacy.withdraw("cloud_text")
        privacy._asked.discard("cloud_screenshots")


def test_the_consent_card_stands_up_on_the_hidden_desktop():
    """The overlay thread builds its Tk window, maps a card at the right
    edge, takes it down, and buries its own interpreter — the contract
    every card here keeps. Skipped where Tk cannot open a window."""
    import overlay as overlay_mod

    card = overlay_mod.ConsentCard(on_answer=lambda k, a: None)
    card.start()
    if card._thread is None or not card._alive.is_set():
        return
    try:
        card.show("cloud_audio")
        deadline = time.monotonic() + 3
        while card.rect is None and time.monotonic() < deadline:
            time.sleep(0.05)
        assert card.rect is not None, "the card never mapped"
        x0, y0, x1, y1 = card.rect
        assert x1 - x0 > 300 and y1 - y0 > 200, card.rect
        card.hide()
        deadline = time.monotonic() + 3
        while card.rect is not None and time.monotonic() < deadline:
            time.sleep(0.05)
        assert card.rect is None, "the card stayed up after hide()"
    finally:
        card.stop()
        card._thread.join(timeout=3)


# ------------------------------------------------------------ the tour (D36)
#
# The owner, 2026-09-18: the guide is "a square with an arrow" on the
# first start, with a skip — not a text. tour_card.py holds the words and
# the picture, overlay.TourCard the thread and the placement beside the
# dot, main.py shows it once after the wizard and again on request.

def test_tour_card_words_and_layout():
    """Four stops, English, one sentence each; the last has one button and
    the others two; the beak's frame adds room on the side it is on and
    nowhere else; the buttons are hit where they are drawn on every
    side; the beak stays off the rounded corners; the picture is the
    frame's size with the chroma colour in the corner the card does
    not reach; the key stop grows with a long key name."""
    import tour_card as tc

    assert len(tc.STOPS) == 4
    assert [s["kind"] for s in tc.STOPS] == ["dot", "key", "shelf", "done"]
    assert [s["tail"] for s in tc.STOPS] == [True, False, True, False]
    for stop in tc.STOPS:
        assert stop["title"] and stop["body"]
        assert not any("א" <= ch <= "ת" for ch in stop["body"]), \
            ("the tour is in the wizard's language, English (2026-09-19)", stop)
    for label in tc.LABELS.values():
        assert label and not any("א" <= ch <= "ת" for ch in label), label
    assert tc.RTL is False, "English lays out from the left"
    cache: dict = {}
    for i in range(len(tc.STOPS)):
        card = tc.card_for(i, key="Right Ctrl")
        assert card["index"] == i and card["count"] == 4
        assert card["buttons"] == ((tc.DONE,) if i == 3 else (tc.NEXT, tc.SKIP))
        w, h = tc.measure(card, 1.0, cache)
        assert w == tc.CARD_W and 90 < h < 260, (i, w, h)
        assert tc.frame(card, 1.0, None, cache) == (w, h, 0, 0)
        for side in (None,) + tc.SIDES:
            fw, fh, cx, cy = tc.frame(card, 1.0, side, cache)
            if side is None or not card["tail"]:
                assert (fw, fh, cx, cy) == (w, h, 0, 0), (i, side)
            elif side in ("top", "bottom"):
                assert (fw, fh) == (w, h + tc.TAIL) and cx == 0, (i, side)
                assert cy == (tc.TAIL if side == "top" else 0)
            else:
                assert (fw, fh) == (w + tc.TAIL, h) and cy == 0, (i, side)
                assert cx == (tc.TAIL if side == "left" else 0)
            boxes = tc.regions(card, 1.0, cache, side)
            for name in card["buttons"]:
                x0, y0, x1, y1 = boxes[name]
                assert tc.hit_test(card, 1.0, (x0 + x1) / 2, (y0 + y1) / 2,
                                   cache, side) == (tc.HTCLIENT, name), (i, side, name)
                assert cx <= x0 < x1 <= cx + w and y1 <= cy + h, (i, side, name)
            assert tc.hit_test(card, 1.0, cx + 8, cy + 8, cache, side) == (tc.HTCAPTION, tc.DRAG)
            assert tc.hit_test(card, 1.0, fw - 1, fh - 1, cache, side)[0] in (tc.HTTRANSPARENT, tc.HTCAPTION)
            at = tc.clamp_tail(card, 1.0, side or "bottom", -50, cache)
            assert at >= tc.RADIUS + tc.TAIL_W / 2, at
            span = h if side in ("left", "right") else w
            far = tc.clamp_tail(card, 1.0, side or "bottom", span + 50, cache)
            assert far <= span - tc.RADIUS - tc.TAIL_W / 2, far
            img = tc.flat(card, 1.0, tc.NEXT, cache, side=side, at=at,
                          chroma=(1, 2, 3))
            assert img.size == (fw, fh) and img.mode == "RGB", (i, side)
            assert img.getpixel((0, 0)) == (1, 2, 3), "the corner is not keyed out"
            # and the card's own face is where the frame says it is
            assert img.getpixel((cx + w // 2, cy + h // 2)) != (1, 2, 3)
    short = tc.measure(tc.card_for(1, key="F9"), 1.0, cache)
    long = tc.measure(tc.card_for(1, key="Ctrl+Shift+Space"), 1.0, cache)
    assert long[0] == short[0], "the card is one width"
    small = tc.measure(tc.card_for(0, key="F9"), 0.7, cache)
    assert small[0] < tc.CARD_W


def test_the_tour_walks_its_stops_and_ends_once():
    """[הבא] walks the four stops in order and the last [הבא] or [סיימתי]
    ends it as "done"; [דלג] ends it as "skip" from anywhere; the end
    takes the card down; a press with nothing up is nothing. And the
    placement: beside the dot with the beak on the edge that faces it —
    below a dot at the top of the screen, above one at the bottom — no
    beak on the stops that do not point, and the corner rule with no
    dot at all. Driven through the card object with its thread stubbed
    out; the painter is the flat image the layout test checks."""
    import tour_card as tc

    ends: list[str] = []
    card = overlay_mod.TourCard(dot_at=lambda: (2500, 1380, 2538, 1418),
                                key="Right Ctrl", on_end=ends.append)
    card._thread = object()           # "started": show() enqueues
    card.pressed(tc.NEXT)
    assert ends == [] and card._q.empty(), "a press with nothing up did something"
    card.show(0)
    assert card.visible() and card.current() == 0
    assert card._q.get_nowait()["index"] == 0
    for expect in (1, 2, 3):
        card.pressed(tc.NEXT)
        assert card.current() == expect
        queued = card._q.get_nowait()
        assert queued["index"] == expect and queued["key"] == "Right Ctrl"
    card.pressed(tc.NEXT)
    assert ends == ["done"] and card.current() is None
    assert card._q.get_nowait() is None and card._q.empty()
    card.show(1)
    card._q.get_nowait()
    card.pressed(tc.SKIP)
    assert ends == ["done", "skip"] and not card.visible()
    assert card._q.get_nowait() is None
    card.show(3)
    card._q.get_nowait()
    card.pressed(tc.DONE)
    assert ends == ["done", "skip", "done"]
    assert card._q.get_nowait() is None
    card.show(9)
    assert card._q.empty(), "a stop that does not exist"

    # placement
    screen, field, desk = (2560, 1440), (0, 0, 2560, 1392), (0, 0, 2560, 1440)
    size = (340, 130)
    dot = (2514, 1350, 2552, 1388)                       # bottom-right
    x, y, side, at = card.place(tc.card_for(0), size, screen, dot, field, desk)
    assert side == "bottom" and y + size[1] + overlay_mod.DOT_GAP == dot[1], (x, y)
    assert x + size[0] <= field[2] and at == tc.clamp_tail(tc.card_for(0), 1.0, "bottom", (dot[0] + dot[2]) // 2 - x)
    dot_top = (1200, 8, 1238, 46)
    x, y, side, at = card.place(tc.card_for(2), size, screen, dot_top, field, desk)
    assert side == "top" and y == dot_top[3] + overlay_mod.DOT_GAP, (x, y)
    assert x == 1219 - size[0] // 2, x
    assert card.place(tc.card_for(1), size, screen, dot, field, desk)[2:] == (None, None), "the key stop does not point"
    assert card.place(tc.card_for(3), size, screen, dot, field, desk)[2:] == (None, None)
    x, y, side, at = card.place(tc.card_for(0), size, screen, None, None, desk)
    assert (side, at) == (None, None)
    assert (x, y) == overlay_mod.HintCard.origin(card, size[0], size[1], screen, 0, desk)


