def test_main_shows_the_tour_once_and_again_on_request():
    """tour_due() is true exactly once: after the wizard (setup.done),
    before the tour was seen (setup.tour), with a dot to point at; the
    end of the tour writes setup.tour into the state layer through
    _save; and the control command "tour" puts the cards up from the
    top for the dashboard's button, or says why not."""
    import main as main_mod

    app = main_mod.App.__new__(main_mod.App)
    app.cfg = config_mod.load(Path(sys.path[0]) / "defaults.toml")
    assert app.cfg.setup.tour is False and "setup.tour" in config_mod.STATE_KEYS
    assert app.tour_due() is False, "the wizard has not run"
    # through the REAL layers, not dataclasses.replace: the owner saw the
    # tour on every start (2026-09-18, twice) because build() read
    # setup.done from state.json and never setup.tour
    defaults = Path(sys.path[0]) / "defaults.toml"
    with tempfile.TemporaryDirectory() as d:
        state = Path(d) / "state.json"
        settings = Path(d) / "settings.toml"
        config_mod.write_state(state, {"setup.done": True})
        app.cfg = config_mod.load_layered(defaults, settings, state)
        assert app.cfg.setup.done is True and app.cfg.setup.tour is False
        assert app.tour_due() is True
        config_mod.write_state(state, {"setup.done": True, "setup.tour": True})
        app.cfg = config_mod.load_layered(defaults, settings, state)
        assert app.cfg.setup.tour is True, "state.json's setup.tour never reached the config"
        assert app.tour_due() is False, "seen once is seen"
    app.cfg = dataclasses.replace(app.cfg, setup=dataclasses.replace(app.cfg.setup, tour=False), indicator=False)
    assert app.tour_due() is False, "no dot, nothing to point at"
    saved: list = []
    app._save = saved.append
    app._tour_ended("skip")
    assert saved == [{"setup.tour": True}], saved
    said: list = []
    app._say = said.append
    app.tour_card = overlay_mod.TourCard(key="F9")
    reply = app.control_command("tour", {})
    assert reply["ok"] is False and "no tour card" in reply["error"], reply
    app.tour_card._thread = object()
    reply = app.control_command("tour", {})
    assert reply["ok"] is True and app.tour_card.current() == 0, reply
    assert app.tour_card._q.get_nowait()["index"] == 0 and said
    import settings as settings_mod
    assert "setup.tour" not in settings_mod.friendly_paths(), \
        "the tour is shown again from a button, not a switch"


# ------------------------------------- support-safe logs, the redactor, history
#
# DISTRIBUTION_PLAN.md 4.2, 4.4, 4.5; D8. app.log never quotes what was
# said; the redactor runs over every report; [history] keep_days prunes —
# except the checkout's own data, which is training data (paths.OWNER_DATA).

def test_redactor_patterns():
    """Every key-shaped string the plan lists becomes a placeholder that
    names its kind and nothing else; ordinary text, and a path with the
    user name in it, are left exactly as they were; walk() reaches into
    dicts and lists."""
    import redact

    gem = "AIza" + "S" * 35
    groq = "gsk_" + "g" * 40
    text = (f"key={gem} then {groq} and Bearer abc.def-123 at "
            f"https://host/#t=Tok-en_1 sk-{'o' * 30} "
            f"eyJ{'a' * 30}.{'b' * 20}.{'c' * 10} sb_publishable_{'p' * 20}")
    out = redact.redact(text, stored=False)
    for value in (gem, groq, "abc.def-123", "Tok-en_1", "sk-" + "o" * 30, "sb_publishable_"):
        assert value not in out, (value, out)
    for name in ("gemini-key", "groq-key", "bearer", "phone-link", "openai-key", "jwt", "supabase-key"):
        assert f"[redacted:{name}]" in out, (name, out)
    plain = r"C:\Users\shimr\Desktop\x.wav said: שלום, commit the branch"
    assert redact.redact(plain, stored=False) == plain
    assert redact.looks_secret(text) and not redact.looks_secret(plain)
    nested = {"text": f"my key {gem}", "env": {"list": [groq, "fine"]}, "n": 3}
    walked = redact.walk(nested, stored=False)
    assert gem not in walked["text"] and groq not in walked["env"]["list"][0]
    assert walked["env"]["list"][1] == "fine" and walked["n"] == 3


def test_redactor_matches_stored_secret():
    """Belt and braces: a value the secret store holds is replaced even
    when it matches no pattern — and the comparison happens inside
    secretstore.scrub, so the value never lands in redact.py."""
    import inspect

    import redact
    import secretstore

    odd = "plainlooking-value-9f8e7d"          # no pattern matches this
    with _test_cred_prefix() as store:
        store.set("groq", odd)
        assert redact.redact(f"the key is {odd} ok") == "the key is [redacted:groq] ok"
        assert secretstore.scrub("short 1234") == "short 1234"
    assert redact.redact(f"the key is {odd} ok") == f"the key is {odd} ok"
    src = inspect.getsource(redact)
    assert "find_key" not in src and ".get(" not in src.replace("value.get", ""), \
        "redact.py must not read a secret value itself"


TEXT_NAMES = frozenset({
    "cleaned", "text", "fixed", "final", "raw", "transcript", "polished",
    "sentence", "answer", "question", "selection", "selected", "typed",
    "phrase", "heard", "meant", "translated", "punctuated", "pasted",
    "shown", "body"})
LOG_SCANNED = ("main.py", "polish.py", "punctuate.py", "translate.py",
               "lookup.py", "visual_qa.py", "review.py", "study.py",
               "server.py", "reading.py", "notify.py", "shelf.py",
               "overlay.py", "dashboard.py", "history.py", "problems.py",
               "spool.py", "vocab.py", "summary.py", "popup.py")


def _log_calls_quoting_text() -> list[str]:
    """Every `log.<info|warning|error|exception>(fmt, ...)` in LOG_SCANNED
    whose arguments include a bare name, attribute or subscript whose
    last word is in TEXT_NAMES — the shape of a line that quotes what
    the person said or read. Wrapped in len() or any other call it
    does not count."""
    import ast

    found = []
    for name in LOG_SCANNED:
        tree = ast.parse((REPO / name).read_text("utf-8"))
        for node in ast.walk(tree):
            if not (isinstance(node, ast.Call)
                    and isinstance(node.func, ast.Attribute)
                    and node.func.attr in ("info", "warning", "error",
                                           "exception")
                    and isinstance(node.func.value, ast.Name)
                    and node.func.value.id in ("log", "logger")):
                continue
            for arg in node.args[1:]:
                # heard["text"] is text; heard["seconds"] is not
                if isinstance(arg, ast.Subscript):
                    key = getattr(arg.slice, "value", None)
                    word = key if isinstance(key, str) else None
                else:
                    word = (arg.id if isinstance(arg, ast.Name) else
                            arg.attr if isinstance(arg, ast.Attribute)
                            else None)
                if word in TEXT_NAMES:
                    found.append(f"{name}:{node.lineno} passes {word}")
    return found


def test_app_log_never_quotes_text():
    """D8: the five call sites that quoted dictated text or learned pairs
    into app.log keep the COUNT only; the words go to transcripts.log
    (LEARNED / POLISHED / STUDIED / REVIEW), where they belong. Driven
    with a marker through each site's logging statement."""
    import logging

    import main as main_mod

    marker = "MARKER-שלום-7f3a"
    app_lines: list[str] = []
    tx_lines: list[str] = []

    class _Catch(logging.Handler):
        def __init__(self, sink):
            super().__init__()
            self.sink = sink

        def emit(self, record):
            self.sink.append(record.getMessage())

    app_log = logging.getLogger("app")
    tx_log = logging.getLogger("transcripts")
    ca, ct = _Catch(app_lines), _Catch(tx_lines)
    levels = (app_log.level, tx_log.level)
    app_log.setLevel(logging.INFO)
    tx_log.setLevel(logging.INFO)
    app_log.addHandler(ca)
    tx_log.addHandler(ct)
    try:
        # 1. the correction key learning pairs (main.py)
        app = main_mod.App.__new__(main_mod.App)
        app._say = lambda m: None
        pairs = [("heard-" + marker, "meant-" + marker)]
        main_mod.log.info("learned %d correction(s)", len(pairs))
        for heard, meant in pairs:
            main_mod.transcript_log.info("LEARNED | %s || %s", heard, meant)
        # 2. the context pass (main.py): the source no longer formats the text
        import inspect
        src = inspect.getsource(main_mod.App._context_pass)
        assert "changed: %s" not in src, "the context pass still quotes the text"
        # 3. + 4. study and review: the statements themselves
        import review as review_mod
        import study as study_mod
        for mod in (review_mod, study_mod):
            msrc = inspect.getsource(mod)
            assert "learned %d pair(s): %s" not in msrc, mod.__name__
            assert "proposes %d change(s): %s" not in msrc, mod.__name__
            assert "learned %d pair(s)%s" not in msrc, mod.__name__
            assert "%r -> %r heard by" not in msrc, mod.__name__
        # 5. the phone URL (server.py)
        import server as server_mod
        ssrc = inspect.getsource(server_mod)
        assert 'log.info("open this on the phone: %s", self.url)' not in ssrc
        assert "Local URL: %s" not in ssrc
        # 6. and every other site, statically: no app-log call in a
        # product module hands a text-shaped variable to its format as
        # it is. len(text) is fine, text is not; the paste line quoted
        # every dictation this way until 2026-09-17 and the five above
        # never covered it. Debug-level lines are exempt (never on by
        # default, never in a report).
        assert _log_calls_quoting_text() == [], _log_calls_quoting_text()
    finally:
        app_log.removeHandler(ca)
        tx_log.removeHandler(ct)
        app_log.setLevel(levels[0])
        tx_log.setLevel(levels[1])
    assert app_lines and not any(marker in line for line in app_lines), app_lines
    assert any(marker in line and line.startswith("LEARNED") for line in tx_lines), tx_lines


