def test_history_keep_days_prunes():
    """prune() drops lines older than keep_days from the log and its
    rotated siblings, keeps the rest byte for byte, deletes a sibling
    that is left with no dated line, and apply() reports it — except
    for the checkout's own data (paths.OWNER_DATA), which is never
    pruned, and keep_days = 0, which detaches the handler and marks
    history off."""
    import dataclasses
    import logging
    from datetime import datetime, timedelta

    import history as history_mod

    now = datetime(2026, 9, 17, 12, 0, 0)
    old = (now - timedelta(days=40)).strftime("%Y-%m-%d %H:%M:%S")
    new = (now - timedelta(days=2)).strftime("%Y-%m-%d %H:%M:%S")
    tmp, _path = _log_with([
        f"{old},000 | OK | 4.0s | local | 0.5s latency | ישן",
        f"{new},000 | OK | 4.0s | local | 0.5s latency | חדש",
    ])
    try:
        log = history_mod.LOG
        sibling = log.with_name(log.name + ".1")
        sibling.write_text(f"{old},000 | OK | 4.0s | local | 0.5s latency | ישן מאוד\n", "utf-8")
        dropped, removed = history_mod.prune(30, now=now)
        assert (dropped, removed) == (2, 1), (dropped, removed)
        kept = log.read_text("utf-8")
        assert "חדש" in kept and "ישן" not in kept, kept
        assert not sibling.exists()
        events = history_mod.load(10)
        assert [e.text for e in events] == ["חדש"], events
        cfg = config_mod.load(Path(__file__).resolve().parent / "defaults.toml")
        assert cfg.history.keep_days == 30
        with _patched(paths, "OWNER_DATA", True):
            line = history_mod.apply(cfg)
            assert "not applied" in line and history_mod.enabled, line
        with _patched(paths, "OWNER_DATA", False):
            line = history_mod.apply(cfg)
            assert line.startswith("history: kept 30 days") and history_mod.enabled, line
            logger = logging.getLogger("tests-transcripts-fixture")
            logger.addHandler(logging.NullHandler())
            off = dataclasses.replace(cfg, history=config_mod.HistoryConfig(keep_days=0))
            line = history_mod.apply(off, logger)
            assert "history is off" in line and not history_mod.enabled, line
            assert logger.handlers == [], "the handler stayed attached"
    finally:
        history_mod.enabled = True
        _restore_log(tmp)


def test_reset_spares_the_owners_training_data():
    """--reset-data on the checkout's own data leaves transcripts.log,
    recent\ and corpus\ alone (the 72 read-aloud clips of 2026-09-13
    were lost to the first version of this command); an installed copy
    still removes them, because a stranger's data is theirs to delete."""
    import migrate as migrate_mod

    assert set(migrate_mod.TRAINING_DATA) == {"TRANSCRIPTS_LOG", "RECENT_DIR", "CORPUS_DIR"}
    assert all(name in migrate_mod.STORES for name in migrate_mod.TRAINING_DATA)
    with tempfile.TemporaryDirectory() as d:
        home = Path(d)
        saved = {name: getattr(paths, name) for name in ("TRANSCRIPTS_LOG", "RECENT_DIR", "CORPUS_DIR", "VOCAB_FILE")}
        try:
            paths.TRANSCRIPTS_LOG = home / "transcripts.log"
            paths.RECENT_DIR = home / "recent"
            paths.CORPUS_DIR = home / "corpus"
            paths.VOCAB_FILE = home / "vocab.json"
            paths.TRANSCRIPTS_LOG.write_text("x", "utf-8")
            paths.RECENT_DIR.mkdir()
            paths.CORPUS_DIR.mkdir()
            (paths.CORPUS_DIR / "gold.wav").write_bytes(b"RIFF")
            paths.VOCAB_FILE.write_text("{}", "utf-8")
            with _patched(paths, "OWNER_DATA", True):
                names = {t.name for t in migrate_mod.reset_targets()}
                assert "vocab.json" in names, names
                assert not ({"transcripts.log", "recent", "corpus"} & names), names
            with _patched(paths, "OWNER_DATA", False):
                names = {t.name for t in migrate_mod.reset_targets()}
                assert {"transcripts.log", "recent", "corpus", "vocab.json"} <= names, names
        finally:
            for name, value in saved.items():
                setattr(paths, name, value)


# ------------------------------------------- the owner's surface, hidden
#
# DISTRIBUTION_PLAN.md D15, PR 7: what only the checkout has — the git
# block, the Saturday routine's questions and problems.md, the nightly
# tests, the read-aloud corpus tool, the developer rows on Settings, the
# three owner commands — is behind paths.DEVELOPER. On this checkout it
# is all there; the test flips the flag and looks at a stranger's copy.

def test_a_strangers_copy_shows_no_owner_surface():
    import inspect

    import dashboard as dash
    import main as main_mod
    import settings as settings_mod

    defaults = Path(__file__).resolve().parent / "defaults.toml"
    everyone = {s.path for s in settings_mod.flatten(settings_mod.read(defaults))}
    drawn = set(settings_mod.friendly_paths())
    # the owner's machinery is in the file and on nobody's screen — his
    # own included, since 2026-09-18 ("I am the user; you are the
    # developer"); there is no developer flag on the Settings place
    owners = {"awake.vitals_minutes", "notify.watch", "tests.nightly",
              "tests.wait_seconds", "study.read_sentences",
              "study.read_goal_hours"}
    assert owners <= everyone, owners - everyone
    assert not owners & drawn, owners & drawn
    assert not hasattr(settings_mod, "developer_only")
    assert "Privacy" in settings_mod.tab_names()

    with _patched(paths, "DEVELOPER", False):
        assert [k for k, _n in dash.corr_tabs()] == ["waiting"]

        class _Board:
            _questions = staticmethod(lambda: object())
            _questions_store = staticmethod(lambda: object())
        assert dash.Dashboard._pending_questions(_Board()) == []
        assert dash.Dashboard._nightly_running(_Board()) is False
    assert [k for k, _n in dash.corr_tabs()] == ["waiting", "read"]
    src = inspect.getsource(main_mod.main)
    assert "for the developer's checkout only" in src
    assert src.index("not paths.DEVELOPER") < src.index("return benchmark(cfg)")


# ------------------------------------------------- one number (PR 9, D21)
#
# DISTRIBUTION_PLAN.md 7.8 and 11.2: VERSION beside main.py is the single
# source; version.py reads it once and asks git for the branch only in
# the checkout; problems.env() carries the version, the Windows build and
# the open consents — never the branch outside the checkout, never the
# Python version, never a key; the Android build derives its numbers from
# the same file.

def test_version_file_is_single_source():
    import version as version_mod

    text = paths.VERSION_FILE.read_text("utf-8")
    assert text.endswith("\n") and text.count("\n") == 1, repr(text)
    line = text.strip()
    assert version_mod.SEMVER.match(line), line
    assert version_mod.VERSION == line
    assert version_mod.PARTS == version_mod.parse(line)
    assert version_mod.IS_BETA == (version_mod.PARTS[3] is not None)
    # precedence: numbers, and a beta before its release
    assert version_mod.key("1.2.0-beta.3") < version_mod.key("1.2.0")
    assert version_mod.key("1.2.0") < version_mod.key("1.10.0")
    assert version_mod.key("1.2.0-beta.2") < version_mod.key("1.2.0-beta.10")
    for bad in ("v1.2.0", "1.2", "1.2.0-rc.1", "", "1.2.0.1"):
        try:
            version_mod.parse(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"{bad!r} parsed")
    # the phone reads the same file and types no number of its own
    gradle = (REPO / "android" / "app" / "build.gradle.kts").read_text("utf-8")
    assert 'file("../VERSION")' in gradle, "the Android build has its own number"
    assert not re.search(r"versionCode\s*=\s*\d", gradle), "a hand-typed versionCode"
    assert not re.search(r'versionName\s*=\s*"', gradle), "a hand-typed versionName"
    assert "* 10000 +" in gradle and "* 100 +" in gradle, "not D21's formula"
    # and nothing in the product still asks the retired module
    assert not (REPO / "versions.py").exists()
    for name in product_modules():
        src = (REPO / (name.replace(".", "/") + ".py")).read_text("utf-8") \
            if name not in ("transcribers", "skin") else ""
        assert "import versions" not in src, name
    assert "versions" in DEV_MODULES


def test_version_no_git_on_user_machine():
    """An installed copy has no .git and no git on PATH: version.py must
    not start a process to find that out. With DEVELOPER off, _branch()
    answers "" without calling subprocess.run; with it on, the checkout's
    branch is the one git reports."""
    import subprocess as sp

    import version as version_mod

    calls: list = []
    real = sp.run

    def spy(*a, **k):
        calls.append(a)
        return real(*a, **k)

    with _patched(sp, "run", spy):
        with _patched(paths, "DEVELOPER", False):
            assert version_mod._branch() == ""
        assert calls == [], "git was spawned on a stranger's copy"
        with _patched(paths, "DEVELOPER", True):
            here = version_mod._branch()
    assert calls and calls[0][0][:2] == ["git", "rev-parse"], calls
    assert here == version_mod.BRANCH
    assert version_mod.BRANCH, "this checkout has a branch"
    assert version_mod.label() == f"DeskIT {version_mod.VERSION} \u00b7 {version_mod.BRANCH}"
    with _patched(version_mod, "BRANCH", ""):
        assert version_mod.label() == f"DeskIT {version_mod.VERSION}"


