def test_models_env_is_set_on_an_installed_copy():
    """HF_HOME under the data folder, offline, no implicit token, no
    telemetry — the values huggingface_hub reads once at import, which is
    why main calls env() before anything imports it; and no product
    module imports faster_whisper or huggingface_hub at module level."""
    import models

    before = dict(os.environ)
    try:
        with _patched(paths, "PORTABLE", False), _patched(paths, "CACHE_DIR", Path("C:/x/cache")):
            values = models.env()
        assert values["HF_HUB_OFFLINE"] == "1" and values["HF_HUB_DISABLE_IMPLICIT_TOKEN"] == "1"
        assert values["HF_HUB_DISABLE_TELEMETRY"] == "1"
        assert values["HF_HOME"] == str(Path("C:/x/cache") / "hf")
        for k, v in values.items():
            assert os.environ[k] == v, k
    finally:
        os.environ.clear()
        os.environ.update(before)
    hub_import = re.compile(r"^(?:import|from)\s+(?:faster_whisper|huggingface_hub)\b")
    bad = []
    for name in product_modules():
        py = REPO / (name.replace(".", "/") + ".py")
        if not py.exists():
            py = REPO / name.replace(".", "/") / "__init__.py"
        for i, line in enumerate(py.read_text("utf-8").splitlines(), 1):
            if hub_import.match(line):
                bad.append(f"{py.name}:{i}: {line.strip()}")
    assert not bad, "the hub imported before models.env() could run:\n" + "\n".join(bad)


def test_models_download_resumes_verifies_and_marks_complete():
    """The download through net.py: the Hub's redirect followed by hand
    (absolute to a CDN host under hf.co, relative for a small file), a
    pause that keeps the part, a second attempt that asks for the rest
    with a Range and gets a 206, the hash of every file against the
    lock, then .complete with the revision — and every hop a row under
    model-download, with no token in any header."""
    import models
    import net as net_mod

    tmp = Path(tempfile.mkdtemp(prefix="deskit-models-"))
    try:
        big = bytes(range(256)) * 1200                      # 300 kB
        bodies = {"config.json": b'{"model_type": "whisper"}', "model.bin": big}
        e = _model_lock(tmp, bodies)
        hub = _Hub(e, bodies)
        seen: list[tuple[int, int]] = []
        stages: list[str] = []
        cancel = threading.Event()
        with _patched(paths, "PORTABLE", False), \
                _patched(paths, "MODELS_DIR", tmp / "models"), \
                _patched(paths, "MODELS_LOCK", tmp / "models.lock"), \
                _patched(net_mod, "_connect", hub), \
                _patched(net_mod, "DOWNLOAD_CHUNK", 64 * 1024):
            # a pause after the first chunk of the big file
            def pause_early(done, total):
                seen.append((done, total))
                if done >= len(bodies["config.json"]) + 64 * 1024:
                    cancel.set()
            try:
                models.download(e, progress=pause_early, cancel=cancel, stage=stages.append)
            except models.DownloadError as err:
                assert err.reason == "cancelled", err
            else:
                raise AssertionError("the pause was not honoured")
            part = e.folder / "model.bin.part"
            assert part.exists() and part.stat().st_size == 64 * 1024, part.stat().st_size
            assert (e.folder / "config.json").exists() and not (e.folder / models.COMPLETE).exists()
            assert models.state(e.repo) == "incomplete"
            assert seen and all(t == e.bytes for _d, t in seen) and seen[0][0] > 0
            # the second attempt: the rest, from where the part left off
            hub.asked.clear()
            seen.clear()
            folder = models.download(e, progress=lambda d, t: seen.append((d, t)), stage=stages.append)
            assert folder == e.folder and not part.exists()
            ranged = [h for u, h in hub.asked if "Range" in h]
            assert ranged and all(h["Range"] == f"bytes={64 * 1024}-" for h in ranged), hub.asked
            assert not any(k.lower() == "authorization" for _u, h in hub.asked for k in h), "a token left"
            assert [u for u, _h in hub.asked] == [e.url("model.bin"),
                                                  "https://us.aws.cdn.hf.co/xet-bridge-us/abc/model.bin?X-Xet-Cas-Uid=public"]
            assert (e.folder / "model.bin").read_bytes() == big
            assert json.loads((e.folder / models.COMPLETE).read_text("utf-8"))["revision"] == e.revision
            assert models.state(e.repo) == "ready" and models.verify(e) == []
            assert seen[-1] == (e.bytes, e.bytes), seen[-1]
            assert stages == ["downloading", "downloading", "verifying"], stages
            rows = [r for r in net_mod.rows() if r.purpose == "model-download"]
            assert {r.host for r in rows} >= {"huggingface.co", "us.aws.cdn.hf.co"}, rows
            assert {r.status for r in rows} >= {302, 307, 200, 206}, rows
            assert any(r.down == 300 * 1024 - 64 * 1024 for r in rows), "the 206 row counts its bytes"
            # a server that ignores the Range starts the file over, and it still completes
            part.write_bytes(big[:1000])
            (e.folder / "model.bin").unlink()
            hub.ignore_range = True
            models.download(e)
            assert (e.folder / "model.bin").read_bytes() == big and models.state(e.repo) == "ready"
            # the file host is off the allowlist: refused before a socket, said as such
            models.remove(e.repo)
            hub.redirect_to = "https://evil.example.com/model.bin"
            try:
                models.download(e)
            except models.DownloadError as err:
                assert err.reason == "refused" and "evil.example.com" in str(err), err
            else:
                raise AssertionError("a redirect off Hugging Face's domains was followed")
            assert net_mod.rows()[-1].status == "refused"
            # no connection: offline, the part untouched, .complete absent
            hub.redirect_to = None
            hub.down = True
            (e.folder).mkdir(parents=True, exist_ok=True)
            part.write_bytes(big[:5000])
            try:
                models.download(e)
            except models.DownloadError as err:
                assert err.reason == "offline" and "huggingface.co" in str(err), err
            assert part.read_bytes() == big[:5000] and models.state(e.repo) == "incomplete"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_models_verify_hashes():
    """A file whose SHA-256 is not the lock's is deleted and NAMED,
    .complete is not written, the good file stays; verify() on a folder
    that is exactly the lock is []."""
    import models
    import net as net_mod

    tmp = Path(tempfile.mkdtemp(prefix="deskit-models-"))
    try:
        bodies = {"config.json": b'{"a": 1}', "model.bin": b"m" * 5000}
        e = _model_lock(tmp, bodies)
        wrong = dict(e.files)
        wrong["config.json"] = (len(bodies["config.json"]), "0" * 64)
        bad_entry = models.Entry(e.repo, e.revision, wrong, e.license)
        hub = _Hub(e, bodies)
        with _patched(paths, "PORTABLE", False), \
                _patched(paths, "MODELS_DIR", tmp / "models"), \
                _patched(paths, "MODELS_LOCK", tmp / "models.lock"), \
                _patched(net_mod, "_connect", hub):
            try:
                models.download(bad_entry)
            except models.DownloadError as err:
                assert err.reason == "verify" and err.files == ("config.json",), err
                assert "config.json" in str(err) and "checksum" in str(err)
            else:
                raise AssertionError("a wrong hash was accepted")
            assert not (e.folder / "config.json").exists() and (e.folder / "model.bin").exists()
            assert not (e.folder / models.COMPLETE).exists() and models.state(e.repo) == "incomplete"
            assert models.verify(bad_entry) == ["config.json"]
            assert models.verify(e) == ["config.json"], "missing counts as bad"
            (e.folder / "config.json").write_bytes(bodies["config.json"])
            assert models.verify(e) == []
            (e.folder / "model.bin").write_bytes(b"m" * 4999)
            assert models.verify(e) == ["model.bin"], "a short file counts as bad"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_models_partial_never_loads():
    """On an installed copy the loader asks models.py first: a folder
    without .complete is ModelMissing and WhisperModel is never built; a
    verified folder is what WhisperModel receives — the path, not the
    name; get_transcriber hands main the stand-in instead of raising, and
    the stand-in's transcribe is the same typed error."""
    import models
    import transcribers
    import transcribers.local_whisper as lw
    from transcribers.base import ModelMissing

    built: list = []

    class _FakeModel:
        def __init__(self, model, device, compute_type, **kw):
            built.append(model)

        def transcribe(self, *a, **k):
            return iter(()), None

    tmp = Path(tempfile.mkdtemp(prefix="deskit-models-"))
    before = dict(os.environ)
    try:
        e = _model_lock(tmp, {"model.bin": b"x" * 10})
        import faster_whisper
        with _patched(faster_whisper, "WhisperModel", _FakeModel), \
                _patched(lw, "_register_cuda_dlls", lambda: None), \
                _patched(paths, "PORTABLE", False), \
                _patched(paths, "MODELS_DIR", tmp / "models"), \
                _patched(paths, "MODELS_LOCK", tmp / "models.lock"), \
                _patched(paths, "CACHE_DIR", tmp / "cache"):
            e.folder.mkdir(parents=True)
            (e.folder / "model.bin").write_bytes(b"x" * 10)
            try:
                lw.LocalWhisperTranscriber(e.repo, "he", english_model="")
            except ModelMissing as err:
                assert err.state == "incomplete", err
            else:
                raise AssertionError("a folder without .complete was loaded")
            assert built == [], "WhisperModel was constructed for a partial model"
            assert os.environ.get("HF_HUB_OFFLINE") == "1", "env() did not run before the import"
            cfg = dataclasses.replace(config_mod.Config(), backend="local")
            cfg = dataclasses.replace(cfg, local=dataclasses.replace(cfg.local, model=e.repo, english_model=""))
            t = transcribers.get_transcriber(cfg)
            assert t.name == "missing" and isinstance(t, transcribers.Transcriber)
            try:
                t.transcribe(RIFF)
            except ModelMissing as err:
                assert err.state == "incomplete" and err.retry_after == float("inf")
            else:
                raise AssertionError("the stand-in transcribed")
            (e.folder / models.COMPLETE).write_text(json.dumps({"revision": e.revision}), "utf-8")
            t = lw.LocalWhisperTranscriber(e.repo, "he", english_model="deepdml/x")
            assert built == [str(e.folder)], built
            assert t._english is None, "an absent detector is Hebrew-only, not a download"
            assert transcribers.get_transcriber(cfg).name == "local"
        # the checkout: the name, as always
        with _patched(faster_whisper, "WhisperModel", _FakeModel), \
                _patched(lw, "_register_cuda_dlls", lambda: None):
            built.clear()
            lw.LocalWhisperTranscriber("ivrit-ai/whisper-large-v3-turbo-ct2", "he", english_model="")
            assert built == ["ivrit-ai/whisper-large-v3-turbo-ct2"], built
    finally:
        os.environ.clear()
        os.environ.update(before)
        shutil.rmtree(tmp, ignore_errors=True)


def test_models_window_offers_downloads_and_closes():
    """The step as a window: the size line before anything is fetched,
    [Download] runs the transfer on a thread while the bar moves, a
    verified download closes the window with `done`; a connection that
    is not there says so in the window and [Close] is `later`; wanted()
    is an installed copy, the local backend, and no model."""
    import models

    tmp = Path(tempfile.mkdtemp(prefix="deskit-models-"))
    try:
        e = _model_lock(tmp, {"model.bin": b"x" * 2_000_000, "config.json": b"{}"})

        def fake_download(entry, *, progress=None, cancel=None, stage=None):
            stage("downloading")
            for done in (500_000, 1_000_000, entry.bytes):
                progress(done, entry.bytes)
                time.sleep(0.05)
            stage("verifying")
            return entry.folder

        def pump(w, until, seconds=8.0):
            deadline = time.monotonic() + seconds
            while not until() and time.monotonic() < deadline:
                try:
                    w.root.update()
                except Exception:                            # noqa: BLE001
                    break
                time.sleep(0.02)

        with _patched(paths, "PORTABLE", False), \
                _patched(paths, "MODELS_DIR", tmp / "models"), \
                _patched(paths, "MODELS_LOCK", tmp / "models.lock"):
            try:
                w = models.Offer(e, downloader=fake_download)
            except Exception as err:                         # noqa: BLE001
                print(f"    (skipped: no Tk window — {err})")
                return
            assert w.outcome == "later" and w.status_text == ""
            w.start()
            pump(w, lambda: w.outcome == "done")
            assert w.outcome == "done", w.status_text
            assert w.status_text == "2 MB — verified", w.status_text

            def offline(entry, **kw):
                raise models.DownloadError("offline", "no connection to huggingface.co: no route")
            w = models.Offer(e, downloader=offline)
            w.start()
            pump(w, lambda: w.status_text == "No connection")
            assert w.status_text == "No connection", w.status_text
            w._not_now()
            assert w.outcome == "later"
            assert models.offer("nobody/nothing") == "later"
            cfg = dataclasses.replace(config_mod.Config(), backend="local")
            cfg = dataclasses.replace(cfg, local=dataclasses.replace(cfg.local, model=e.repo))
            assert models.wanted(cfg)
            assert not models.wanted(dataclasses.replace(cfg, backend="gemini"))
            e.folder.mkdir(parents=True, exist_ok=True)
            (e.folder / models.COMPLETE).write_text(json.dumps({"revision": e.revision}), "utf-8")
            assert not models.wanted(cfg)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_net_admits_the_hub_by_domain():
    """Hugging Face's CDN hostname moves (cdn-lfs.huggingface.co,
    cas-bridge.xethub.hf.co, us.aws.cdn.hf.co on 2026-09-17): the rule
    is the two domains, and a look-alike is not under them."""
    import net as net_mod

    for host in ("huggingface.co", "us.aws.cdn.hf.co", "cdn-lfs-eu-1.hf.co",
                 "cas-bridge.xethub.hf.co", "cdn-lfs.huggingface.co"):
        assert net_mod._host_allowed(host), host
    for host in ("evil-hf.co", "hf.co.evil.com", "huggingface.co.evil.com",
                 "notthehf.co", "example.com"):
        assert not net_mod._host_allowed(host), host
    assert net_mod.ALLOWED_SUFFIXES == (".huggingface.co", ".hf.co")


# ------------------------------------------------------- the packs (PR 16)
#
# DISTRIBUTION_PLAN.md 6.5, D14, D19, D24: packs.lock names the wheels an
# installed copy may download (the GPU pack — NVIDIA's cuBLAS, cuDNN and
# NVRTC at the owner's venv's versions — and the skin pack); the wheels
# come down through net.download() and pip installs them with no network
# at all (--no-index --find-links --require-hashes --no-deps), which is
# how every outbound byte, pip's included, passes the one door. The
# checkout answers `venv` and activates nothing (D4). Every wire and every
# pip below is a fake.

def _pack_lock(tmp: Path, name: str, bodies: dict[str, bytes]) -> "packs.Pack":
    """A lock with one pack whose wheels are `bodies` (filename -> bytes),
    served from files.pythonhosted.org; returns the pack as read back."""
    import hashlib

    import packs

    wheels = tuple(packs.Wheel(fn.split("-")[0].replace("_", "-"), fn.split("-")[1], fn,
                               f"https://files.pythonhosted.org/packages/ab/cd/{fn}",
                               len(body), hashlib.sha256(body).hexdigest())
                   for fn, body in bodies.items())
    packs.write_lock([packs.Pack(name, wheels, tuple(packs.LICENSES.get(name, [])))],
                     tmp / "packs.lock")
    return packs.read_lock(tmp / "packs.lock")[name]


class _PyPI:
    """files.pythonhosted.org as the download meets it: the file, whole
    or from a Range; every request's headers kept."""

    def __init__(self, bodies: dict[str, bytes]):
        self.bodies = bodies
        self.asked: list[tuple[str, dict]] = []

    def __call__(self, method, url, headers, body, timeout_s):
        self.asked.append((url, dict(headers)))
        data = self.bodies[url.rsplit("/", 1)[-1]]
        rng = headers.get("Range")
        if rng:
            start = int(rng.split("=")[1].rstrip("-"))
            return _FakeRaw(data[start:], status=206)
        return _FakeRaw(data, status=200)


class _Pip:
    """subprocess.run as pip: records the command and the flags, lays
    down what a real install would (the nvidia bin folders), or fails
    with a line when told to."""

    def __init__(self, fail: str = ""):
        self.calls: list[tuple[list[str], dict]] = []
        self.fail = fail

    def __call__(self, cmd, **kw):
        import subprocess as _sp
        self.calls.append((list(cmd), dict(kw)))
        if self.fail:
            return _sp.CompletedProcess(cmd, 1, stdout="Collecting...\n", stderr=f"ERROR: {self.fail}\n")
        target = Path(cmd[cmd.index("--target") + 1])
        for sub in ("cublas", "cudnn", "cuda_nvrtc"):
            (target / "nvidia" / sub / "bin").mkdir(parents=True, exist_ok=True)
        return _sp.CompletedProcess(cmd, 0, stdout="Successfully installed\n", stderr="")


def test_packs_lock_is_the_shipped_list():
    """packs.lock names the GPU pack's three NVIDIA wheels at exactly the
    versions this venv holds (D34) and the skin pack's skia wheel for
    cp311 / win_amd64, every wheel from files.pythonhosted.org with a
    size and a SHA-256, the licence links the card shows, and a size
    line of 1.37 GB; requirements_text pins and hashes each one.

    "The versions this venv holds" is a question only the owner's venv
    can answer: the product CI's holds neither pack (requirements.txt
    leaves both out on purpose), so a wheel that is not installed here
    is named and passed over, and the rest of the lock is checked in
    full."""
    from importlib import metadata

    import net as net_mod
    import packs

    lock = packs.read_lock()
    assert set(lock) == set(packs.NAMES) == {"gpu", "skin", "recording"}, list(lock)
    gpu, skin = lock["gpu"], lock["skin"]
    assert [w.name for w in gpu.wheels] == list(packs.PINS["gpu"])
    not_here = []
    for w in gpu.wheels + skin.wheels:
        try:
            held = metadata.version(w.name)
        except metadata.PackageNotFoundError:
            not_here.append(w.name)
        else:
            assert w.version == held, (w.name, w.version, held)
        assert w.filename.endswith("win_amd64.whl") and w.size > 0
        assert re.fullmatch(r"[0-9a-f]{64}", w.sha256), w
        host = w.url.split("/")[2]
        assert host == "files.pythonhosted.org" and host in net_mod.ALLOWED_HOSTS
    assert "-cp311-" in skin.wheels[0].filename
    assert 1_300_000_000 < gpu.bytes < 1_500_000_000 and gpu.versions["nvidia-cudnn-cu12"].startswith("9.")
    assert [x[0] for x in gpu.licenses] == ["NVIDIA CUDA EULA", "cuDNN SLA"]
    assert all(u.startswith("https://docs.nvidia.com/") for _l, u in gpu.licenses)
    assert packs.size_line(gpu).startswith("1.37 GB from files.pythonhosted.org into ")
    text = packs.requirements_text(gpu)
    assert text.splitlines()[0] == f"nvidia-cublas-cu12=={gpu.wheels[0].version} --hash=sha256:{gpu.wheels[0].sha256}"
    assert len(text.splitlines()) == 3
    rec = packs.pack("recording")
    assert rec is not None and [w.name for w in rec.wheels] == ["av"], "PyAV is the Recording pack (13.4)"
    assert any("GPL" in label for label, _u in rec.licenses), rec.licenses
    base = (REPO / "requirements.lock").read_text("utf-8")
    assert "\nav==" not in base and "nvidia-" not in base
    # skia-python is in BOTH since 2026-09-19: the base wheelhouse ships the
    # skin (the owner's desk look on every install); the pack entry stays
    # for a copy that lost it, and its pinned wheel is the base's own
    skin = packs.pack("skin")
    assert skin is not None and f"skia-python=={skin.wheels[0].version}" in base, "one skia, two lists"
    if not_here:
        print(f"        (not installed in this venv, versions not compared: "
              f"{', '.join(not_here)})")


def test_packs_pip_command():
    """pip is handed the wheels already on disk and nothing else: no
    index, the find-links folder, the target, hashes required, no
    dependency walk; and it runs with no console window."""
    import inspect

    import packs

    tmp = Path(tempfile.mkdtemp(prefix="deskit-packs-"))
    try:
        with _patched(paths, "PACKS_DIR", tmp / "packs"):
            p = _pack_lock(tmp, "gpu", {"nvidia_cublas_cu12-1.0-py3-none-win_amd64.whl": b"x"})
            cmd = packs.pip_command(p, tmp / "req.txt")
            assert cmd[:4] == [sys.executable, "-m", "pip", "install"]
            for flag in ("--no-index", "--require-hashes", "--no-deps", "--disable-pip-version-check"):
                assert flag in cmd, flag
            assert cmd[cmd.index("--find-links") + 1] == str(p.wheels_dir)
            assert cmd[cmd.index("--target") + 1] == str(p.site)
            assert cmd[cmd.index("-r") + 1] == str(tmp / "req.txt")
            assert p.site == tmp / "packs" / "gpu" / "site"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    src = inspect.getsource(packs._run_pip)
    assert "creationflags=CREATE_NO_WINDOW" in src and packs.CREATE_NO_WINDOW == 0x08000000


def test_packs_install_downloads_through_net_then_pip_offline():
    """install(): each wheel through net.download() (a row under
    pack-install from files.pythonhosted.org, a Range after a pause,
    the hash checked), then pip with the flags above, then the record
    with the versions, the wheels gone; activate("gpu") puts the pack's
    bin folders first on PATH and calls add_dll_directory for each; a
    pip that fails leaves no record and says its line."""
    import net as net_mod
    import packs

    tmp = Path(tempfile.mkdtemp(prefix="deskit-packs-"))
    before = os.environ.get("PATH", "")
    try:
        bodies = {"nvidia_cublas_cu12-1.0-py3-none-win_amd64.whl": bytes(range(256)) * 600,
                  "nvidia_cudnn_cu12-2.0-py3-none-win_amd64.whl": b"d" * 3000}
        pypi = _PyPI(bodies)
        pip = _Pip()
        added: list[str] = []
        with _patched(paths, "PORTABLE", False), \
                _patched(paths, "PACKS_DIR", tmp / "packs"), \
                _patched(paths, "PACKS_LOCK", tmp / "packs.lock"), \
                _patched(net_mod, "_connect", pypi), \
                _patched(net_mod, "DOWNLOAD_CHUNK", 64 * 1024), \
                _patched(packs.subprocess, "run", pip), \
                _patched(os, "add_dll_directory", lambda d: added.append(d)):
            p = _pack_lock(tmp, "gpu", bodies)
            assert packs.state("gpu") == "missing" and packs.standing("gpu") == "missing"
            assert packs.activate("gpu") is False
            cancel = threading.Event()
            seen: list = []

            def pause(done, total):
                seen.append((done, total))
                if done >= 64 * 1024:
                    cancel.set()
            try:
                packs.install(p, progress=pause, cancel=cancel)
            except packs.DownloadError as err:
                assert err.reason == "cancelled", err
            else:
                raise AssertionError("the pause was not honoured")
            part = p.wheels_dir / (list(bodies)[0] + ".part")
            assert part.exists() and part.stat().st_size == 64 * 1024 and pip.calls == []
            assert seen and all(t == p.bytes for _d, t in seen)
            stages: list[str] = []
            site = packs.install(p, stage=stages.append)
            assert site == p.site and stages == ["downloading", "installing"]
            ranged = [h["Range"] for _u, h in pypi.asked if "Range" in h]
            assert ranged == [f"bytes={64 * 1024}-"], pypi.asked
            assert not any(k.lower() == "authorization" for _u, h in pypi.asked for k in h)
            assert len(pip.calls) == 1
            cmd, kw = pip.calls[0]
            assert "--no-index" in cmd and kw["creationflags"] == packs.CREATE_NO_WINDOW
            req = (p.folder / "requirements.txt")
            assert not req.exists() and not p.wheels_dir.exists(), "the wheels and the list are gone once installed"
            rec = json.loads(p.record.read_text("utf-8"))
            assert rec["versions"] == {"nvidia-cublas-cu12": "1.0", "nvidia-cudnn-cu12": "2.0"}
            assert rec["installed_at"][:4] == time.strftime("%Y")
            assert packs.state("gpu") == "ok" and packs.standing("gpu") == "ok"
            rows = [r for r in net_mod.rows() if r.purpose == "pack-install"]
            assert rows and {r.host for r in rows} == {"files.pythonhosted.org"}, rows
            assert {r.status for r in rows} >= {200, 206}
            # activate: the bin folders first on PATH, each registered
            assert packs.activate("gpu") is True and packs.activate("gpu") is True
            bins = packs.dll_dirs(p)
            assert len(bins) == 3 and all(b.endswith("bin") for b in bins)
            assert os.environ["PATH"].split(os.pathsep)[:3] == bins
            assert added == bins
            # a pip that fails: its line, no record
            packs._active.discard("gpu")
            packs.remove("gpu")
            assert packs.state("gpu") == "missing" and not p.folder.exists()
            pip.fail = "THESE PACKAGES DO NOT MATCH THE HASHES"
            try:
                packs.install(p)
            except packs.InstallError as err:
                assert err.reason == "install" and "HASHES" in str(err), err
            else:
                raise AssertionError("a failed pip was called an install")
            assert not p.record.exists() and packs.state("gpu") == "missing"
    finally:
        os.environ["PATH"] = before
        import packs as _packs
        _packs._active.discard("gpu")
        shutil.rmtree(tmp, ignore_errors=True)


def test_packs_lock_mismatch_is_stale():
    """An installed record whose cudnn version is not the lock's is
    `stale` — offered as an update, never re-downloaded on its own;
    a failure the ladder noted makes the standing `failed:<reason>`,
    activate() refuse and the tier cpu, until the note is cleared or the
    pack removed."""
    import hardware
    import packs

    tmp = Path(tempfile.mkdtemp(prefix="deskit-packs-"))
    d, s, t = _layer_files()
    try:
        with _patched(paths, "PORTABLE", False), \
                _patched(paths, "PACKS_DIR", tmp / "packs"), \
                _patched(paths, "PACKS_LOCK", tmp / "packs.lock"), \
                _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t):
            p = _pack_lock(tmp, "gpu", {"nvidia_cublas_cu12-1.0-py3-none-win_amd64.whl": b"a",
                                        "nvidia_cudnn_cu12-2.0-py3-none-win_amd64.whl": b"b"})
            p.site.mkdir(parents=True)
            p.record.write_text(json.dumps({"versions": {"nvidia-cublas-cu12": "1.0",
                                                          "nvidia-cudnn-cu12": "1.9"}}), "utf-8")
            assert packs.state("gpu") == "stale" and packs.standing("gpu") == "stale"
            assert hardware.tier_for(_facts(gpu_pack="stale")) == "gpu", "a stale pack still runs"
            p.record.write_text(json.dumps({"versions": p.versions}), "utf-8")
            assert packs.state("gpu") == "ok"
            packs.note_failure("gpu", "Library cudnn64_9.dll is not found\nmore")
            assert packs.failure("gpu") == "Library cudnn64_9.dll is not found"
            assert packs.standing("gpu") == "failed:Library cudnn64_9.dll is not found"
            assert packs.activate("gpu") is False
            with _patched(paths, "DEVELOPER", False):
                assert hardware.tier_for(_facts(gpu_pack=packs.standing("gpu"))) == "cpu"
                assert hardware.tier_for(_facts(gpu_pack="ok")) == "gpu"
                assert hardware.tier_for(_facts(gpu_pack="unknown")) == "cpu"
            assert json.loads(t.read_text("utf-8"))["hardware.gpu_pack_failed"].startswith("Library")
            assert "gpu_pack_failed" not in s.read_text("utf-8") if s.exists() else True
            packs.clear_failure("gpu")
            assert packs.standing("gpu") == "ok" and "hardware.gpu_pack_failed" not in json.loads(t.read_text("utf-8"))
            packs.note_failure("gpu", "again")
            assert packs.remove("gpu") and packs.standing("gpu") == "missing" and packs.failure("gpu") == ""
            assert packs.state("nothing") == "unknown"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
        shutil.rmtree(d, ignore_errors=True)


def test_packs_wanted_and_decline():
    """The step is offered on an installed copy with the switch on, an
    NVIDIA card with a driver that clears the floor, and no pack (or a
    stale one); [Not now] writes setup.offer_gpu_pack = false to
    settings.toml and the start stops asking; the checkout answers
    `venv`, activates nothing and is never asked."""
    import packs

    tmp = Path(tempfile.mkdtemp(prefix="deskit-packs-"))
    d, s, t = _layer_files()
    try:
        cfg = config_mod.Config()
        assert cfg.setup.offer_gpu_pack is True and config_mod.defaults_flat()["setup.offer_gpu_pack"] is True
        card = _facts()
        assert packs.state("gpu") == "venv" and packs.activate("gpu") is False
        assert not packs.wanted(cfg, card), "the checkout"
        with _patched(paths, "PORTABLE", False), \
                _patched(paths, "PACKS_DIR", tmp / "packs"), \
                _patched(paths, "PACKS_LOCK", tmp / "packs.lock"), \
                _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t):
            _pack_lock(tmp, "gpu", {"nvidia_cublas_cu12-1.0-py3-none-win_amd64.whl": b"a"})
            assert packs.wanted(cfg, card)
            assert not packs.wanted(cfg, None)
            assert not packs.wanted(cfg, _facts(cuda_devices=0))
            assert not packs.wanted(cfg, _facts(driver_ok=False))
            packs.decline("gpu")
            assert 'offer_gpu_pack = false' in s.read_text("utf-8")
            assert not packs.wanted(config_mod.load_layered(settings=s, state=t), card)
            # the window's own answers reach decline() through offer()
            import steps
            with _patched(steps, "show", lambda step: "declined"):
                config_mod.save({"setup.offer_gpu_pack": True}, settings=s, state=t)
                assert packs.offer("gpu") == "declined"
                assert 'offer_gpu_pack = false' in s.read_text("utf-8")
            with _patched(steps, "show", lambda step: "later"):
                config_mod.save({"setup.offer_gpu_pack": True}, settings=s, state=t)
                assert packs.offer("gpu") == "later"
                assert "offer_gpu_pack" not in s.read_text("utf-8")
            assert packs.offer("nothing") == "later"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
        shutil.rmtree(d, ignore_errors=True)


def test_packs_failed_falls_to_cpu_with_card():
    """On an installed copy the ladder registers the pack instead of
    scanning site-packages, and a cuda attempt that fails with the pack
    present is written down as failed:<first line> — the next probe
    says cpu and the Home card of 6.9 has its reason."""
    import hardware
    import packs
    import transcribers.local_whisper as lw

    class _FakeModel:
        def __init__(self, model, device, compute_type, **kw):
            if device == "cuda":
                raise RuntimeError("Library cublas64_12.dll is not found\nsecond line")

        def transcribe(self, *a, **k):
            return iter(()), None

    tmp = Path(tempfile.mkdtemp(prefix="deskit-packs-"))
    d, s, t = _layer_files()
    activated: list[str] = []
    before = dict(os.environ)
    try:
        import faster_whisper
        with _patched(faster_whisper, "WhisperModel", _FakeModel), \
                _patched(paths, "PORTABLE", False), \
                _patched(paths, "PACKS_DIR", tmp / "packs"), \
                _patched(paths, "PACKS_LOCK", tmp / "packs.lock"), \
                _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t), \
                _patched(paths, "CACHE_DIR", tmp / "cache"), \
                _patched(packs, "activate", lambda name: activated.append(name) or False):
            p = _pack_lock(tmp, "gpu", {"nvidia_cublas_cu12-1.0-py3-none-win_amd64.whl": b"a"})
            p.site.mkdir(parents=True)
            p.record.write_text(json.dumps({"versions": p.versions}), "utf-8")
            assert packs.state("gpu") == "ok"
            lw._register_cuda_dlls()
            assert activated == ["gpu"], "the product registers the pack, not site-packages"
            lw.LocalWhisperTranscriber(str(tmp), "he", english_model="")
            assert packs.standing("gpu") == "failed:Library cublas64_12.dll is not found"
            with _patched(paths, "DEVELOPER", False):
                assert hardware.gpu_pack_state().startswith("failed:")
                assert hardware.tier_for(_facts(gpu_pack=hardware.gpu_pack_state())) == "cpu"
            # a cpu-only attempt notes nothing; a missing pack notes nothing
            packs.clear_failure("gpu")
            lw.LocalWhisperTranscriber(str(tmp), "he", device="cpu", english_model="")
            assert packs.failure("gpu") == ""
            packs.remove("gpu")
            lw.LocalWhisperTranscriber(str(tmp), "he", english_model="")
            assert packs.failure("gpu") == ""
    finally:
        os.environ.clear()
        os.environ.update(before)
        shutil.rmtree(tmp, ignore_errors=True)
        shutil.rmtree(d, ignore_errors=True)


def test_the_step_window_says_declined_before_it_starts():
    """steps.StepWindow: [Not now] before the work starts is `declined`
    (the caller writes it down), after a failure it is `later`; the
    licence links are drawn; a pack's step carries its links and says
    Install."""
    import packs
    import steps

    calls: list = []
    step = steps.Step(title="כותרת", body="גוף", size_line="1 MB from x into y", total=10,
                      work=lambda **kw: calls.append(kw),
                      links=[("NVIDIA CUDA EULA", "https://docs.nvidia.com/cuda/eula/index.html"),
                             ("cuDNN SLA", "https://docs.nvidia.com/x")], button="Install")
    try:
        w = steps.StepWindow(step)
    except Exception as err:                                 # noqa: BLE001
        print(f"    (skipped: no Tk window — {err})")
        return
    labels = [c for c in w.root.winfo_children()[0].winfo_children()
              if c.winfo_class() == "Frame"]
    links = [x.cget("text") for f in labels for x in f.winfo_children() if x.winfo_class() == "Label"]
    assert links == ["NVIDIA CUDA EULA", "cuDNN SLA"], links
    w._not_now()
    assert w.outcome == "declined" and calls == []
    tmp = Path(tempfile.mkdtemp(prefix="deskit-packs-"))
    try:
        with _patched(paths, "PACKS_DIR", tmp / "packs"):
            p = _pack_lock(tmp, "gpu", {"nvidia_cublas_cu12-1.0-py3-none-win_amd64.whl": b"a" * 5})
            st = packs.step(p, installer=lambda pk, **kw: (_ for _ in ()).throw(
                packs.DownloadError("offline", "no connection")))
            assert st.button == "Install" and st.links == list(p.licenses) and st.total == 5
            assert "5 B" in st.body and st.size_line.startswith("5 B from files.pythonhosted.org")
            w = steps.StepWindow(st)
            w.start()
            deadline = time.monotonic() + 8
            while w.status_text != "No connection" and time.monotonic() < deadline:
                w.root.update()
                time.sleep(0.02)
            assert w.status_text == "No connection", w.status_text
            w._not_now()
            assert w.outcome == "later"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


# ------------------------------------- the Speed page and the Home rows (PR 17)
#
# DISTRIBUTION_PLAN.md 6.9 and chapter 9 (screen 10, Settings > Speed):
# what the machine wants goes on the Home pile — the model that is not
# there, the GPU pack that will not run, the tier that changed — each
# with the button that fixes it, and Settings > Speed carries this PC's
# summary, the model's standing, the pack's, and the four knobs the
# probe writes. The stand-in backend picks the model up at the next
# dictation once it lands. Every state below is faked; nothing runs a
# step for real.

def test_the_stand_in_upgrades_itself_when_the_model_lands():
    """transcribers.missing: while the model is not on disk every
    dictation is the typed ModelMissing and the builder is never called;
    once .complete is there the next dictation builds the real backend,
    hands it the language, and everything the real one has is reachable
    through the stand-in — including its name."""
    import models
    from transcribers.base import ModelMissing
    from transcribers.missing import MissingModelTranscriber

    built: list = []

    class _Real:
        name = "local"
        last_words = [("שלום", 0.0, 0.5, 0.9)]

        def transcribe(self, wav_bytes, language=None):
            return f"real:{language}"

        def study_decode(self, *a, **k):
            return "studied"

    def build():
        built.append(1)
        return _Real()

    tmp = Path(tempfile.mkdtemp(prefix="deskit-models-"))
    try:
        e = _model_lock(tmp, {"model.bin": b"x" * 10})
        with _patched(paths, "PORTABLE", False), \
                _patched(paths, "MODELS_DIR", tmp / "models"), \
                _patched(paths, "MODELS_LOCK", tmp / "models.lock"):
            err = ModelMissing(e.repo, "absent", "not yet")
            t = MissingModelTranscriber(err, build)
            assert t.name == "missing" and not hasattr(t, "study_decode")
            for _ in range(2):
                try:
                    t.transcribe(RIFF, "he")
                except ModelMissing as got:
                    assert got.state == "absent" and got.retry_after == float("inf")
                else:
                    raise AssertionError("transcribed without a model")
            assert built == [], "the builder ran before the model was there"
            e.folder.mkdir(parents=True)
            (e.folder / "model.bin").write_bytes(b"x" * 10)
            (e.folder / models.COMPLETE).write_text(json.dumps({"revision": e.revision}), "utf-8")
            assert t.transcribe(RIFF, "he") == "real:he" and built == [1]
            assert t.transcribe(RIFF, "en") == "real:en" and built == [1], "built once"
            assert t.name == "local" and t.last_words[0][0] == "שלום"
            assert hasattr(t, "study_decode") and t.study_decode() == "studied"
            # without a builder it is only ever the error
            assert MissingModelTranscriber(err).name == "missing"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_hardware_change_note_and_summary():
    """A tier that changed since the last start is written down
    (tier_changed, tier_changed_at) for the Home row and cleared by its
    OK; summary() is the one line the Speed page prints for a card, no
    card, an old driver, and a machine never probed."""
    import hardware

    d, s, t = _layer_files()
    try:
        with _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t), \
                _patched(paths, "DEVELOPER", True), \
                _patched(hardware, "probe", lambda: dict(_facts(cuda_devices=0, tier="cpu",
                                                                probed_at="2026-09-17T23:00:00",
                                                                probe_version=1))), \
                _patched(hardware, "probe_slow", lambda: {}), \
                _patched(hardware.threading, "Thread",
                         lambda *a, **k: type("T", (), {"start": lambda self: None})()):
            hardware.record({"tier": "gpu"})
            said: list[str] = []
            hardware.run_at_start(say=said.append)
            rec = hardware.recorded()
            assert rec["tier"] == "cpu" and rec["tier_changed"] == "gpu → cpu", rec
            assert rec["tier_changed_at"] == "2026-09-17T23:00:00" and said == [
                "Your hardware changed: DeskIT now runs as cpu"]
            hardware.run_at_start()
            assert hardware.recorded()["tier_changed"] == "gpu → cpu", "an unchanged start keeps the note"
            hardware.clear_change()
            rec = hardware.recorded()
            assert "tier_changed" not in rec and "tier_changed_at" not in rec and rec["tier"] == "cpu"
    finally:
        shutil.rmtree(d, ignore_errors=True)
    assert hardware.summary({}) == "not probed yet"
    line = hardware.summary(_facts(tier="gpu"))
    assert line == "gpu (on the graphics card) · NVIDIA card, 16 GB, driver 596.49 · 12 cores, 16 GB RAM", line
    assert hardware.summary(_facts(tier="cpu", cuda_devices=0)).startswith("cpu (on the processor) · no NVIDIA card")
    assert "too old for CUDA 12.3" in hardware.summary(_facts(tier="cpu", driver="531.14", driver_ok=False))
    assert hardware.summary(_facts(tier="gpu-small", vram_mb=5000)).startswith(
        "gpu-small (on a small graphics card) · NVIDIA card, 5 GB")


def test_the_speed_page_and_the_home_rows():
    """This PC, on Settings > The app: the summary line, the model's
    standing, the pack's, and the buttons each state earns — none in
    the checkout, where both are the venv's; Home: a missing model, a
    failed pack and a changed tier are rows on the pile with the button
    that fixes each, and Retry / OK act at once. The four [local] knobs
    the probe writes are the file's, not the screen's (2026-09-18), and
    the Speed tab that carried them went with them."""
    import settings as settings_mod

    assert settings_mod.tab_named("Speed") is None
    for path in ("local.device", "local.compute_type", "local.cpu_threads",
                 "local.beam_size", "setup.offer_gpu_pack"):
        assert path not in settings_mod.friendly_paths(), path

    import dashboard as dash

    with _window() as board:
        if board is None:
            return

        def drawn():
            board._show("Settings")
            board._settings_go(settings_mod.APP)
            board._finish_settings()
            board.root.update_idletasks()
            return list(board.parts["speed_lines"]), list(board.parts["speed_buttons"])

        # the checkout: two lines, no buttons
        lines, buttons = drawn()
        assert "checkout" in lines[0] and buttons == [], (lines, buttons)
        assert len(lines) == 2 and "venv" in lines[1]
        assert board._waiting_hardware() == []
        # an installed copy, nothing there yet, a card with a good driver
        words = {"model": "absent", "pack": "missing", "changed": ""}
        facts = _facts(tier="cpu")
        with _patched(paths, "PORTABLE", False), \
                _patched(dash.models_mod, "state", lambda repo: words["model"]), \
                _patched(dash.packs_mod, "standing", lambda name: words["pack"]), \
                _patched(dash.hardware_mod, "recorded", lambda: dict(facts, tier_changed=words["changed"])):
            lines, buttons = drawn()
            assert lines[0].startswith("not downloaded yet (1.62 GB)"), lines
            assert lines[1].startswith("off — NVIDIA's libraries are not installed (1.37 GB)"), lines
            assert buttons == ["Download the model", "Turn on GPU speed (1.37 GB)"], buttons
            rows = board._waiting_hardware()
            assert len(rows) == 1 and rows[0]["kind"] == "hardware", rows
            assert "not on this PC yet (1.62 GB)" in rows[0]["text"]
            assert [b[0] for b in rows[0]["buttons"]] == ["Download"]
            # the model ready, the pack installed but broken, the tier changed
            words.update(model="ready", pack="failed:Library cudnn64_9.dll is not found",
                         changed="gpu → cpu")
            lines, buttons = drawn()
            assert lines[0].startswith("ready — ivrit-ai/") and "could not start (Library cudnn64_9" in lines[1]
            assert buttons == ["Delete and re-download the model", "Delete the model",
                               "Retry GPU speed", "Reinstall the GPU pack", "Remove the GPU pack"], buttons
            rows = board._waiting_hardware()
            assert [r["mark"] for r in rows] == ["alert", "engine"], rows
            assert "GPU speed could not start (Library cudnn64_9.dll is not found)" in rows[0]["text"]
            assert [b[0] for b in rows[0]["buttons"]] == ["Retry", "Reinstall", "Remove the pack"]
            assert "now runs gpu → cpu" in rows[1]["text"] and rows[1]["buttons"][0][0] == "OK"
            # a stale pack and an incomplete model
            words.update(model="incomplete", pack="stale", changed="")
            lines, buttons = drawn()
            assert lines[0].startswith("download did not finish") and lines[1].startswith("installed from an older release")
            assert buttons == ["Continue the download", "Update the GPU pack (1.37 GB)", "Remove the GPU pack"], buttons
            assert [b[0] for b in board._waiting_hardware()[0]["buttons"]] == ["Continue"]
            # no card at all: no pack button, no pack row
            words.update(model="ready", pack="missing")
            facts.update(cuda_devices=0)
            lines, buttons = drawn()
            assert lines[1] == "no NVIDIA card — dictation runs on the processor", lines
            assert buttons == ["Delete and re-download the model", "Delete the model"]
            facts.update(cuda_devices=1, driver_ok=False)
            lines, buttons = drawn()
            assert lines[1].startswith("the NVIDIA driver is too old"), lines
            # the buttons that act here and now
            cleared: list = []
            with _patched(dash.packs_mod, "clear_failure", lambda n: cleared.append(("clear", n))), \
                    _patched(dash.packs_mod, "remove", lambda n: cleared.append(("remove", n)) or True), \
                    _patched(dash.hardware_mod, "clear_change", lambda: cleared.append(("seen",))), \
                    _patched(dash.launch, "run_step", lambda flag, name=None: cleared.append((flag, name)) or True):
                board._hardware_retry()
                board._hardware_remove()
                board._hardware_seen()
                board._hardware_step("--download-model")
                board._hardware_step("--install-pack", "gpu")
            assert cleared == [("clear", "gpu"), ("remove", "gpu"), ("seen",),
                               ("--download-model", None), ("--install-pack", "gpu")], cleared


def test_tts_probe_no_hebrew_voice():
    """6.8: the slow probe that finds no he-IL voice writes
    visual_qa.speak = "off" into the machine layer — only where
    settings.toml is silent, never in the checkout — and takes it out
    the start a voice is found; no_voice() is what the Screen tab reads
    to draw the block with the ms-settings link; the block is there on
    an installed copy without a voice and nowhere else."""
    import hardware

    d, s, t = _layer_files()
    try:
        with _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t):
            with _patched(paths, "DEVELOPER", True):
                assert hardware.apply_voice("") is None
                assert not t.exists() or "visual_qa.speak" not in t.read_text("utf-8")
            with _patched(paths, "DEVELOPER", False), _patched(paths, "PORTABLE", False):
                assert hardware.apply_voice("") == "off"
                assert config_mod.load_layered(settings=s, state=t).visual_qa.speak == "off"
                assert "visual_qa.speak" not in (s.read_text("utf-8") if s.exists() else "")
                hardware.record({"he_voice": ""})
                assert hardware.no_voice()
                assert hardware.apply_voice("Microsoft Asaf") is None
                assert config_mod.load_layered(settings=s, state=t).visual_qa.speak == "button"
                hardware.record({"he_voice": "Microsoft Asaf"})
                assert not hardware.no_voice()
                # the person's own choice is never touched
                config_mod.save({"visual_qa.speak": "auto"}, settings=s, state=t)
                assert hardware.apply_voice("") is None
                assert config_mod.load_layered(settings=s, state=t).visual_qa.speak == "auto"
                hardware.record({"ollama": False})
                assert hardware.ollama_absent()
                hardware.record({"ollama": True, "ollama_models": ["gemma3:4b"]})
                assert not hardware.ollama_absent()
            assert not hardware.no_voice() and not hardware.ollama_absent(), "the checkout"
    finally:
        shutil.rmtree(d, ignore_errors=True)
    assert "Time & Language > Speech" in hardware.NO_VOICE

    import dashboard as dash
    import settings as settings_mod

    with _window() as board:
        if board is None:
            return

        def drawn(tab):
            # the tab first, then the screen: _show fills whichever tab
            # is current, and its first card is built on the spot
            board.parts.pop("voice_block", None)
            board._settings_tab = tab
            board._show("Settings")
            board._finish_settings()
            board.root.update_idletasks()
            return "voice_block" in board.parts

        assert not drawn("Screen"), "the checkout drew the no-voice block"
        with _patched(dash.hardware_mod, "no_voice", lambda: True):
            assert drawn("Screen") and not drawn("Cards")


def test_ollama_absent_hides_local_entries():
    """6.7: with the probe saying no Ollama, an installed copy's provider
    menus carry no "On this computer" entry — unless it is the value the
    file holds, which a menu has to be able to show; the checkout keeps
    every entry; and the ask-the-screen refusal names the three ways
    out with the model the tier suggests."""
    import dashboard as dash
    import settings as settings_mod

    class _Setting:
        def __init__(self, path, value, choices=()):
            self.path, self.value, self.choices = path, value, choices

    # a provider menu the way the tabs used to word one; the provider
    # rows are the file's since 2026-09-18, so the test brings its own
    row = settings_mod.Friendly("lookup.prefer", "Which looks it up first", "",
                                (("ollama", "On this computer"),
                                 ("gemini", "Google's model")))
    with _window() as board:
        if board is None:
            return
        board.parts.setdefault("values", {})
        names = board._menu_for(row, _Setting("lookup.prefer", "groq"))
        assert any(v == "ollama" for v, _n in names), "the checkout hid Ollama"
        with _patched(dash.hardware_mod, "ollama_absent", lambda: True):
            names = board._menu_for(row, _Setting("lookup.prefer", "groq"))
            assert not any(v == "ollama" for v, _n in names), names
            assert len(names) == len(row.names) - 1
            names = board._menu_for(row, _Setting("lookup.prefer", "ollama"))
            assert any(v == "ollama" for v, _n in names), "the held value was hidden"
            plain = board._menu_for(None, _Setting("x", "a", ("a", "b")))
            assert plain == [("a", "a"), ("b", "b")]
    import visual_qa
    src = inspect.getsource(visual_qa)
    assert "install Ollama from ollama.com and pull" in src and "Settings > Privacy" in src


