# ------------------------------------------- the wizard's pages (PR 20)
#
# DISTRIBUTION_PLAN.md 9.2 and docs/distplan/research-onboarding.md: seven
# pages in one window; the Hebrew model, the GPU pack and the English
# detector as a queue the wizard hosts and keeps pumping between pages;
# the extras page's switches through their own writers; `setup.done`
# into state.json. steps.py is split into the run (the work and its
# state), the pane (the face) and the window (the standalone step).

def test_step_run_state_machine():
    """steps.StepRun: idle until start(); progress moves the bytes and
    the status line; the end words — done, paused (cancelled), offline,
    failed — each land once and read as the plan's English; said()
    picks the Hebrew sentence and its colour."""
    import steps

    def work(progress, cancel, stage):
        progress(5, 10)
        stage("verifying")

    def settle(run):
        deadline = time.monotonic() + 5
        landed = []
        while run.state == "running" and time.monotonic() < deadline:
            landed += run.pump()
            time.sleep(0.01)
        return landed

    run = steps.StepRun(steps.Step(title="t", body="b", size_line="s", total=10, work=work))
    assert run.state == "idle" and run.status() == "" and not run.ended
    assert run.start() is True
    settle(run)
    assert run.state == "done" and run.done_bytes == 10 and run.status() == "10 B — verified"
    assert run.said() == (steps.SAID["done"], "green")
    assert run.start() is True, "a finished run may run again"
    settle(run)

    class Stop(Exception):
        def __init__(self, reason, why):
            super().__init__(why)
            self.reason = reason

    def offline(**kw):
        raise Stop("offline", "no route")
    run = steps.StepRun(steps.Step(title="t", body="b", size_line="s", total=10, work=offline))
    run.start()
    settle(run)
    assert run.state == "offline" and run.status() == "No connection"
    assert run.said()[1] == "amber"

    def slow(progress, cancel, stage):
        for i in range(200):
            if cancel.is_set():
                raise Stop("cancelled", "paused")
            progress(i, 200)
            time.sleep(0.01)
    run = steps.StepRun(steps.Step(title="t", body="b", size_line="s", total=200, work=slow))
    run.start()
    time.sleep(0.1)
    run.pause()
    landed = settle(run)
    assert run.state == "paused" and landed == ["paused"] and run.status() == "Paused"
    assert 0 < run.done_bytes < 200

    def broken(**kw):
        raise RuntimeError("disk full")
    run = steps.StepRun(steps.Step(title="t", body="b", size_line="s", total=1, work=broken,
                                   said={"failed": "נכשל: {why}"}))
    run.start()
    settle(run)
    assert run.state == "failed" and run.said() == ("נכשל: disk full", "red")


def test_the_computer_page_is_skipped_when_nothing_is_left_to_download():
    """A copy whose downloads have all landed — or a portable one — never
    sees the computer page (the owner, 2026-09-19 evening: "I do not
    want the installation page"): Next from the microphone lands on the
    sentence page, Back from there on the microphone, and the counter
    counts seven. A copy with one thing to download still gets the page."""
    import firstrun

    cfg = dataclasses.replace(config_mod.load(REPO / "defaults.toml"),
                              setup=config_mod.SetupConfig(done=False))
    d, s, t = _layer_files()
    nothing = {"portable": False, "model": None, "pack": None, "detector": None,
               "recording": None, "tier": "gpu"}
    with _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t):
        try:
            w = firstrun.Wizard(cfg, facts={"tier": "gpu"}, offers=nothing)
        except Exception as err:                             # noqa: BLE001
            print(f"    (skipped: no Tk window — {err})")
            return
        try:
            w.page = firstrun.PAGES.index("mic")
            w._show_page()
            w._next()
            assert w.name == "say", w.name
            w._back()
            assert w.name == "mic", w.name
            w.page = firstrun.PAGES.index("say")
            w._show_page()
            assert [c for c in w.body.winfo_children()], "no page drawn"
            assert "of 7" in _wizard_words(w), "the counter still counts the hidden page"
        finally:
            try:
                w._close()            # the microphone stream too, not only the window
            except Exception:                                # noqa: BLE001
                pass
            # buried before the next Tk: firstrun.run's rule, here by hand
            # (a Recorder collected with its stream open is an access
            # violation on the audio thread — measured here, 2026-09-19)
            w = None
            gc.collect()
        one = dict(nothing, recording=type("T", (), {"name": "recording", "bytes": 5})())
        try:
            w = firstrun.Wizard(cfg, facts={"tier": "gpu"}, offers=one,
                                stepper=lambda kind, thing: __import__("steps").Step(
                                    title="t", body="b", size_line="5 B", total=5,
                                    work=lambda progress, cancel, stage: None, name=kind))
        except Exception as err:                             # noqa: BLE001
            print(f"    (skipped: no Tk window — {err})")
            return
        try:
            w.page = firstrun.PAGES.index("mic")
            w._show_page()
            w._next()
            assert w.name == "computer", "one download, and the page was skipped"
            assert "of 8" in _wizard_words(w)
        finally:
            try:
                w._close()
            except Exception:                                # noqa: BLE001
                pass
        shutil.rmtree(d, ignore_errors=True)


def _wizard_words(w) -> str:
    """Every Label's text on the wizard's body, joined."""
    import tkinter as tk
    out = []

    def walk(widget):
        for child in widget.winfo_children():
            if isinstance(child, tk.Label):
                out.append(str(child.cget("text")))
            walk(child)
    walk(w.body)
    return " | ".join(out)


def test_the_wizard_offers_the_recording_pack_until_it_is_there():
    """The fourth offer on the computer page (the owner, 2026-09-19
    evening: "the software comes with everything; nobody installs things
    in the middle"): the Recording pack, on by default, queued after the
    others — offered while packs.lock names it and it is not installed,
    never on a portable copy, never when the lock does not know it. It
    stays a download rather than a line in the installer: PyAV's wheel
    carries a GPL FFmpeg (D24)."""
    import firstrun
    import models
    import packs

