def test_the_wizard_offers_what_this_copy_lacks():
    """firstrun.downloads_for: nothing on a portable copy; the model
    when the local backend has none ready; the pack when packs.wanted
    says so; the detector only on the gpu tier and only while it is not
    on disk. hardware_line: the three sentences of 9.2."""
    import firstrun
    import models

    cfg = config_mod.load(REPO / "defaults.toml")
    gpu = {"tier": "gpu", "vram_mb": 16311, "cuda_devices": 1, "driver_ok": True}
    with _patched(paths, "PORTABLE", True):
        out = firstrun.downloads_for(cfg, gpu)
        assert out["portable"] and out["model"] is None and out["pack"] is None
    tmp = Path(tempfile.mkdtemp(prefix="deskit-wizard-"))
    try:
        with _patched(paths, "PORTABLE", False), \
                _patched(paths, "MODELS_DIR", tmp / "models"), \
                _patched(paths, "MODELS_LOCK", tmp / "models.lock"), \
                _patched(paths, "PACKS_DIR", tmp / "packs"), \
                _patched(paths, "PACKS_LOCK", tmp / "packs.lock"):
            first = models.Entry(cfg.local.model, "b" * 40, {"model.bin": (5, "0" * 64)})
            second = models.Entry(cfg.local.english_model, "c" * 40, {"model.bin": (7, "0" * 64)})
            models.write_lock([first, second], tmp / "models.lock")
            _pack_lock(tmp, "gpu", {"nvidia_cublas_cu12-1.0-py3-none-win_amd64.whl": b"a" * 5})
            out = firstrun.downloads_for(cfg, gpu)
            assert out["model"] is not None and out["model"].repo == cfg.local.model
            assert out["pack"] is not None and out["pack"].name == "gpu"
            assert out["detector"] is not None and out["detector"].repo == cfg.local.english_model
            small = dict(gpu, tier="gpu-small", vram_mb=4096)
            assert firstrun.downloads_for(cfg, small)["detector"] is None, "no detector on 4 GB"
            # a first start: the pack is not there yet, so the tier says
            # cpu — the detector goes with the card all the same
            first = dict(gpu, tier="cpu", gpu_pack="missing")
            assert firstrun.downloads_for(cfg, first)["detector"] is not None, "the detector went with the tier"
            assert firstrun.hardware_line(first).startswith("NVIDIA card, 16 GB — fast")
            cpu = {"tier": "cpu", "cuda_devices": 0}
            out = firstrun.downloads_for(cfg, cpu)
            assert out["pack"] is None and out["detector"] is None and out["model"] is not None
            cloud = dataclasses.replace(cfg, backend="gemini")
            assert firstrun.downloads_for(cloud, gpu)["model"] is None
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    assert firstrun.hardware_line(gpu).startswith("NVIDIA card, 16 GB — fast")
    assert "smaller mode" in firstrun.hardware_line(
        {"tier": "gpu-small", "vram_mb": 4096, "cuda_devices": 1, "driver_ok": True})
    assert firstrun.hardware_line({"tier": "cpu", "cuda_devices": 0}).startswith("No NVIDIA card")
    assert "too old" in firstrun.hardware_line({"tier": "cpu", "cuda_devices": 1, "driver_ok": False})
    assert firstrun.hardware_line(None) == "This computer has not been probed yet"
    # the detector's own words, and a name on every step for the queue line
    e = models.Entry("x/y", "c" * 40, {"model.bin": (1_600_000_000, "0" * 64)})
    st = models.step(e, downloader=lambda *a, **k: None, words=models.DETECTOR_TEXT)
    assert st.title == models.DETECTOR_TEXT["title"] and "1.60 GB" in st.body
    assert st.name == "English detector"
    assert models.step(e, downloader=lambda *a, **k: None).name == "Hebrew model"
    assert firstrun.microphone_allowed() in (True, False, None)


def test_the_sentence_page_loads_the_model_before_it_records():
    """Two jobs on one button, in order: "Load the speech model" first —
    the status says it is loading and, on landing, how long it took —
    and only then "Record 3 seconds". People do not read the small print
    (the owner's 1.1.1 walkthrough, 2026-09-19): a Record that spent five
    seconds loading read as "transcription is slow"."""
    import dataclasses

    import firstrun
    import transcribers

    cfg = dataclasses.replace(config_mod.load(REPO / "defaults.toml"),
                              setup=config_mod.SetupConfig(done=False))
    _d, s, t = _layer_files()
    loads: list[str] = []

    class Fake:
        timing = {"load_s": 4.2}

        def transcribe(self, wav, language=None):
            time.sleep(0.05)
            return "שלום"

    def build(_cfg):
        loads.append("load")
        time.sleep(0.05)
        return Fake()

    def pump(w, until, seconds=6.0):
        deadline = time.monotonic() + seconds
        while not until() and time.monotonic() < deadline:
            try:
                w.root.update()
            except Exception:                                # noqa: BLE001
                break
            time.sleep(0.02)

    offers = {"portable": True}
    facts = {"tier": "gpu", "vram_mb": 16311, "cuda_devices": 1, "driver_ok": True}
    with _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t), \
            _patched(transcribers, "get_transcriber", build):
        try:
            w = firstrun.Wizard(cfg, facts=facts, offers=offers)
        except Exception as err:                             # noqa: BLE001
            print(f"    (skipped: no Tk window — {err})")
            return
        try:
            w.page = firstrun.PAGES.index("say")
            w._show_page()
            assert w.name == "say" and w.say.itemcget(w.say._label, "text") == firstrun.WORDS["say.load"]
            w.listener.record = lambda seconds: (RIFF, seconds)   # no microphone here
            w._say_action()                                   # job one: the model
            assert loads == ["load"] or w._busy
            pump(w, lambda: w._backend is not None)
            assert loads == ["load"] and w._backend is not None
            assert w.say.itemcget(w.say._label, "text") == firstrun.WORDS["say.button"], w.say.itemcget(w.say._label, "text")
            assert w.status.cget("text").startswith("Model loaded in 4.2 s"), w.status.cget("text")
            w._say_action()                                   # job two: the sentence
            pump(w, lambda: w._sample == "שלום")
            assert loads == ["load"], "the model was loaded once"
            assert w.status.cget("text").startswith("This is what it heard — decoded in"), w.status.cget("text")
        finally:
            w._closing = True
            w.root.destroy()


def test_the_wizard_leaves_no_tk_object_for_another_thread_to_bury():
    """The stranger's copy died 34 s into its first dictation (2026-09-19,
    spawn.log: "Tcl_AsyncDelete: async handler deleted by the wrong
    thread"): the wizard's widgets, their PhotoImages and the consent
    card are reference cycles, and the cyclic collector that finally
    freed them ran on a DECODE thread — a PhotoImage's __del__ then
    talks to a Tk that is gone, from the wrong thread, and the process
    aborts. firstrun.run() now buries the wizard on the main thread
    before it returns: every Tk-bound object the wizard made is gone
    when run() hands back its Result, so no later collection on any
    thread has one to finalize."""
    import firstrun
    import tkinter
    from PIL import ImageTk

    cfg = dataclasses.replace(config_mod.load(REPO / "defaults.toml"),
                              setup=config_mod.SetupConfig(done=False))
    d, s, t = _layer_files()
    kinds = (ImageTk.PhotoImage, tkinter.Image, tkinter.Variable, tkinter.Misc)

    def tk_bound(collect: bool) -> set[int]:
        if collect:
            gc.collect()
        return {id(o) for o in gc.get_objects() if isinstance(o, kinds)}

    before = tk_bound(collect=True)
    made: list[int] = []

    class Walked(firstrun.Wizard):
        """The wizard, walking itself: extras with the consent card up,
        then closed from its own tick — the way a person closes it."""
        def __init__(self, *a, **k):
            super().__init__(*a, **k)
            made.append(id(self))
            self.root.after(150, self._walk)

        def _walk(self):
            try:
                self.page = firstrun.PAGES.index("extras")
                self._show_page()
                self.switches["cloud"].toggle()              # the key field opens
                self.root.after(150, self._close)
            except Exception:                                # noqa: BLE001
                self._close()
                raise

    with _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t),             _patched(paths, "CONSENT_FILE", d / "consent.json"),             _patched(firstrun, "key_probe", lambda: 1),             _patched(firstrun, "Wizard", Walked):
        result = firstrun.run(cfg, facts={"tier": "cpu"},
                              offers={"portable": True, "model": None, "pack": None,
                                      "detector": None, "tier": "cpu"})
    if not made:
        print("    (skipped: no Tk window)")
        return
    assert bool(result) is False, "closing the wizard is not finishing it"
    # Counted WITHOUT collecting: a collection here, on the main thread,
    # would bury them safely and hide the bug (43 survivors measured
    # without run()'s burial, 0 with it).
    left = tk_bound(collect=False) - before
    assert not left, (f"{len(left)} Tk-bound object(s) of the wizard survived run() — "
                      "the next collection on a decode thread aborts the app")


def test_the_wizard_hosts_the_downloads_and_keeps_them_running_between_pages():
    """The seven pages walked with Next: the queue pressed on page 2 runs
    the model, then the pack, then the detector, one after the other,
    while the wizard is on later pages (the pane is rebuilt on the
    sentence page and the record button waits for the model); the pack
    landing re-probes the hardware; the extras page's switches write
    through their own writers; the last page writes setup.done into
    state.json and [Open the desk] is reported to main."""
    import firstrun
    import hardware
    import steps

    cfg = dataclasses.replace(config_mod.load(REPO / "defaults.toml"),
                              setup=config_mod.SetupConfig(done=False))
    d, s, t = _layer_files()
    order: list[str] = []

    class Thing:
        def __init__(self, name, size):
            self.name, self.bytes, self.repo = name, size, name

    def stepper(kind, thing):
        def work(progress, cancel, stage):
            for i in range(4):
                progress((i + 1) * thing.bytes // 4, thing.bytes)
                time.sleep(0.03)
            order.append(kind)
        return steps.Step(title=f"כותרת {kind}", body="גוף",
                          size_line=f"{thing.bytes} B from x into y",
                          total=thing.bytes, work=work, name=kind)

    offers = {"portable": False, "model": Thing("m", 400), "pack": Thing("gpu", 300),
              "detector": Thing("e", 200), "tier": "gpu"}
    facts = {"tier": "gpu", "vram_mb": 16311, "cuda_devices": 1, "driver_ok": True}
    probed = []

    def fake_probe(say=None):
        probed.append(1)
        return dict(facts)

    def pump(w, until, seconds=8.0):
        deadline = time.monotonic() + seconds
        while not until() and time.monotonic() < deadline:
            try:
                w.root.update()
            except Exception:                                # noqa: BLE001
                break
            time.sleep(0.02)

    import notify_hook
    hooked: list[str] = []
    claude_settings = d / "claude-settings.json"
    with _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t), \
            _patched(paths, "PORTABLE", False), _patched(hardware, "run_at_start", fake_probe), \
            _patched(notify_hook, "DEFAULT_SETTINGS", claude_settings), \
            _patched(notify_hook, "install_hook", lambda *a, **k: hooked.append("install")), \
            _patched(notify_hook, "uninstall_hook", lambda *a, **k: hooked.append("uninstall")):
        try:
            w = firstrun.Wizard(cfg, facts=facts, offers=offers, stepper=stepper)
        except Exception as err:                             # noqa: BLE001
            print(f"    (skipped: no Tk window — {err})")
            return
        try:
            assert w.name == "welcome"
            w._next()
            assert w.name == "account"
            w._next()                     # REQUIRED is off in this file
            assert w.name == "mic"
            w._next()
            assert w.name == "computer" and w.pane is not None
            assert w.pane.run is w.runs["model"] and w.active == -1
            assert w.want == {"pack": True, "detector": True, "recording": False}
            w._download()
            assert w.queue == ["model", "pack", "detector"] and w.active == 0
            assert w.runs["model"].running
            w._computer_gate()                               # what the tick does
            assert not w.next_loud._enabled and not w.next_quiet._enabled,                 "Next stayed live under a running bar (the owner's 1.1.1 walkthrough)"
            assert w.note.cget("text") == firstrun.WORDS["computer.wait"]
            w.runs["model"].state = "paused"                 # Pause opens the way on
            w._computer_gate()
            assert w.next._enabled and w.note.cget("text") == ""
            w.runs["model"].state = "running"
            w._next()                                        # programmatically, while it runs
            assert w.name == "say" and w.pane is not None and w.pane.compact
            assert not w.say._enabled, "the record button ran before the model landed"
            pump(w, lambda: w.active == 2 and w.runs["detector"].ended, seconds=12)
            assert order == ["model", "pack", "detector"], order
            assert probed == [1], "the pack landing did not re-probe"
            assert w.result.installed_pack
            pump(w, lambda: w.say._enabled, seconds=3)
            assert w.say._enabled
            w._next()
            assert w.name == "keys"
            w._next()
            assert w.name == "extras"
            assert set(w.switches) == {"cloud", "awake", "updates", "claude", "snip"}, "D33's five"
            assert w.switches["updates"].get() is True, "the shipped default is on (D21)"
            assert w.switches["awake"].get() is True, "the default is what the owner runs (D34)"
            assert w.switches["snip"].get() is True and w.switches["claude"].get() is False
            w.switches["awake"].toggle()
            w.switches["snip"].toggle()
            w.switches["claude"].toggle()
            assert w.extras["awake"] is False and w.extras["snip"] is False and w.extras["claude"]
            w._next()
            assert w.name == "done"
            written = config_mod.read_settings(s)
            assert written.get("awake.hold") is False, written
            assert written.get("capture.capture_hotkey") == "ctrl+f11", written
            assert written.get("notify.enabled") is None, "notify.enabled is the default already"
            assert hooked == ["install"], hooked
            assert set(w.switches) == {"autostart", "phone"}, "the last page's two"
            assert w.switches["phone"].get() is False and w.switches["autostart"].get() is False
            w.switches["phone"].toggle()
            assert "server.enabled" not in config_mod.read_settings(s), "written on Finish, not before"
            assert "setup.autostart" not in config_mod.read_state(t), "an unmoved switch was written"
            assert "setup.done" not in config_mod.read_state(t)
            w._open_desk()
            assert w.result.saved and w.result.open_desk
            assert config_mod.read_state(t).get("setup.done") is True
            assert config_mod.read_settings(s).get("server.enabled") is True
            assert bool(w.result) is True
        finally:
            try:
                w.root.destroy()
            except Exception:                                # noqa: BLE001
                pass
            shutil.rmtree(d, ignore_errors=True)


def test_a_returning_account_skips_the_wizard_and_brings_its_words():
    """The account page of a PC joining an account that already holds
    settings (the owner, 2026-09-20: "if he has a user he signs in,
    everything comes down and DeskIT opens; the rest is for someone
    new"): once the session is there the wizard asks the server ONCE
    whether settings exist; a yes turns Continue into Open DeskIT with
    one plain line; the press records the sync consent with the card's
    text_version, runs the first sync, and — nothing left to download —
    does Start's work at once (the app, the desk, setup.done), the
    microphone, sentence, keys, extras and Ready pages never shown; with
    a download still missing only the computer page stands between the
    account and the desk. A no, or a server that could not be asked, is
    the ordinary wizard. Nothing here names the server to the person."""
    import consent_card as cc
    import firstrun
    import privacy
    import sb

    cfg = dataclasses.replace(config_mod.load(REPO / "defaults.toml"),
                              setup=config_mod.SetupConfig(done=False))
    d, s, t = _layer_files()
    person = {"email": "person@example.com", "id": "x", "is_anonymous": False}
    answer = {"has": True, "asked": 0, "synced": []}

    def has_settings():
        answer["asked"] += 1
        return answer["has"]

    def sync_now(vocab=None, reason=""):
        answer["synced"].append(reason)
        # the wizard hands the pull a live Vocab on the app's file: a
        # None here skipped the words on his installed copy
        assert vocab is not None and vocab.path == paths.VOCAB_FILE, vocab
        return {"settings": "pulled", "vocab": "pulled 17, pushed 0"}

    def settle(w, seconds=1.5, until=None):
        deadline = time.monotonic() + seconds
        while time.monotonic() < deadline:
            w.root.update()
            w._drain()
            if until is not None and until():
                return
            time.sleep(0.02)

    def wizard(offers):
        try:
            return firstrun.Wizard(cfg, facts={"tier": "gpu"}, offers=offers)
        except Exception as err:                             # noqa: BLE001
            print(f"    (skipped: no Tk window — {err})")
            return None

    def bury(w):
        try:
            w._close()
        except Exception:                                    # noqa: BLE001
            pass
        gc.collect()

    nothing = {"portable": True, "model": None, "pack": None, "detector": None,
               "recording": None, "tier": "gpu"}
    with _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t), \
            _patched(paths, "VOCAB_FILE", d / "vocab.json"), \
            _patched(sb, "user", lambda: person), _patched(sb, "configured", lambda: True), \
            _patched(sb, "has_synced_settings", has_settings), _patched(sb, "sync_now", sync_now):
        assert str(_SCRATCH_HOME) in str(paths.CONSENT_FILE), paths.CONSENT_FILE
        for _k in privacy.SYNC_KINDS:
            privacy.withdraw(_k)
        card = cc.card_for("settings_sync")
        try:
            # 1. a returning person, nothing to download: account -> desk
            w = wizard(nothing)
            if w is None:
                return
            w.page = firstrun.PAGES.index("account")
            w._show_page()
            settle(w, until=lambda: w._returning)
            assert w._returning and answer["asked"] == 1, answer
            assert w.next.itemcget(w.next._label, "text") == firstrun.WORDS["account.open"]
            words = _wizard_words(w)
            assert firstrun.WORDS["account.returning"] in words
            assert "Welcome back" in firstrun.WORDS["account.returning"]
            for word in ("Supabase", "server", "sync_now", "settings_sync"):
                assert word not in firstrun.WORDS["account.returning"], word
            assert all(w._hidden(n) for n in ("mic", "say", "keys", "extras", "done"))
            assert privacy.consent("settings_sync") is None, "granted before the press"
            w._next()
            settle(w, until=lambda: w.result.saved)
            assert answer["synced"] == ["wizard"], answer
            row = privacy.consent("settings_sync")
            assert row is not None and row["text_version"] == card["text_version"], row
            assert privacy.allowed("history_sync"), "the returning road left the history sync shut"
            assert w.result.open_desk and w.result.saved
            assert config_mod.read_state(t).get("setup.done") is True
            bury(w)

            # 2. a returning person with a download missing: the computer
            #    page, then the desk — no other page
            for _k in privacy.SYNC_KINDS:
                privacy.withdraw(_k)
            answer.update(has=True, asked=0, synced=[])
            (t).unlink(missing_ok=True)
            w = wizard({**nothing, "portable": False, "recording": type("T", (), {"name": "av", "bytes": 27_556_236, "repo": "av"})()})
            w.page = firstrun.PAGES.index("account")
            w._show_page()
            settle(w, until=lambda: w._returning)
            assert w._returning
            w._next()
            settle(w, until=lambda: w.name == "computer")
            assert w.name == "computer" and not w.result.saved, w.name
            assert not w._hidden("computer") and w._hidden("say")
            shown = [n for n in firstrun.PAGES if not w._hidden(n)]
            assert shown == ["welcome", "account", "computer"], shown
            w._next()                                        # past the downloads
            settle(w, until=lambda: w.result.saved)
            assert w.result.open_desk and w.result.saved, "the desk did not follow the downloads"
            bury(w)

            # 3. a new person, or a server that could not be asked: the
            #    ordinary wizard, Continue, every page
            for _k in privacy.SYNC_KINDS:
                privacy.withdraw(_k)
            answer.update(has=False, asked=0, synced=[])
            w = wizard(nothing)
            w.page = firstrun.PAGES.index("account")
            w._show_page()
            settle(w, 0.6)
            assert answer["asked"] == 1 and not w._returning
            assert not any(w._hidden(n) for n in ("mic", "say", "keys", "extras", "done"))
            assert firstrun.WORDS["account.returning"] not in _wizard_words(w)
            w._next()
            assert w.name == "mic" and answer["synced"] == []
            bury(w)

            # 4. I have an account (the owner: "signs in and is INSIDE the
            #    app — nothing to press"): the choice, the sign-in road,
            #    the sign-in comes back, the server says yes, and the
            #    words are brought and the desk opened with no press
            signed = {"who": None}

            def sign_in_google(**kw):
                signed["who"] = dict(person)
                return dict(person)

            with _patched(sb, "user", lambda: signed["who"]), \
                    _patched(sb, "sign_in_google", sign_in_google), \
                    _patched(firstrun.Wizard, "_came_back", lambda self, who: None):
                for _k in privacy.SYNC_KINDS:
                    privacy.withdraw(_k)
                privacy.withdraw("account")
                answer.update(has=True, asked=0, synced=[])
                t.unlink(missing_ok=True)
                w = wizard(nothing)
                w.page = firstrun.PAGES.index("account")
                w._show_page()
                assert w._account_step == "choice" and set(w.roads) == {"create", "signin"}
                w._account_show("signin")
                assert w.name_box is None and w.signin is not None
                assert firstrun.WORDS["account.signin.line"] in _wizard_words(w)
                assert not w._auto_open
                w._sign_in()
                settle(w, 3, until=lambda: w.result.saved)
                assert answer["asked"] == 1 and w._returning, answer
                assert answer["synced"] == ["wizard"], answer
                assert w.result.open_desk and w.result.saved, "the desk did not open by itself"
                assert not w._auto_open
                row = privacy.consent("settings_sync")
                assert row is not None and row["text_version"] == card["text_version"], row
                bury(w)

                # 5. I have an account, but the account holds nothing yet:
                #    said plainly, Continue, the ordinary wizard
                signed["who"] = None
                for _k in privacy.SYNC_KINDS:
                    privacy.withdraw(_k)
                privacy.withdraw("account")
                answer.update(has=False, asked=0, synced=[])
                t.unlink(missing_ok=True)
                w = wizard(nothing)
                w.page = firstrun.PAGES.index("account")
                w._show_page()
                w._account_show("signin")
                w._sign_in()
                settle(w, 3, until=lambda: w._returning_answer is not None)
                settle(w, 0.3)
                assert answer["asked"] == 1 and not w._returning and not w.result.saved
                assert w.account_note.cget("text") == firstrun.WORDS["account.fresh"]
                assert w.next.itemcget(w.next._label, "text") == firstrun.WORDS["account.continue"]
                w._next()
                assert w.name == "mic" and answer["synced"] == []
                bury(w)

                # 6. Create an account with a Google account that already
                #    holds settings: the truth is welcome back, and the
                #    button — the person chose to look, nothing opens alone
                signed["who"] = None
                for _k in privacy.SYNC_KINDS:
                    privacy.withdraw(_k)
                privacy.withdraw("account")
                answer.update(has=True, asked=0, synced=[])
                t.unlink(missing_ok=True)
                w = wizard(nothing)
                w.page = firstrun.PAGES.index("account")
                w._show_page()
                w._account_show("create")
                assert w.name_box is not None
                w.name_box.entry.insert(0, "Dana")
                w._sign_in()
                settle(w, 3, until=lambda: w._returning)
                settle(w, 0.3)
                assert w._returning and answer["synced"] == [] and not w.result.saved
                assert w.next.itemcget(w.next._label, "text") == firstrun.WORDS["account.open"]
                assert firstrun.WORDS["account.returning"] in _wizard_words(w)
                # Not you? on the welcome-back card: the returning answer
                # is forgotten with the session, every page is back
                signed_out = []
                with _patched(sb, "sign_out", lambda everywhere=True: signed_out.append(everywhere)):
                    w._account_sign_out()
                    settle(w, 0.5, until=lambda: signed_out)
                assert signed_out == [False], signed_out
                assert not w._returning and w._returning_answer is None
                assert w._account_step == "choice"
                assert not any(w._hidden(n) for n in ("mic", "say", "keys", "extras", "done"))
                bury(w)
        finally:
            for _k in privacy.SYNC_KINDS:
                privacy.withdraw(_k)
            privacy.withdraw("account")      # cases 4-6 pressed the sign-in
            shutil.rmtree(d, ignore_errors=True)


def test_the_last_page_keeps_words_and_settings_in_the_account_by_default():
    """The wizard's last page (the owner, 2026-09-20 — two PCs on one
    Google account shared not one learned word, the gate being off in
    both behind a card nobody found: "make it the default, on the last
    screen, with a line that says what they are ticking and how to turn
    it off"): signed in, a third switch — Keep my words, settings and
    what I said in my account — drawn ON above the two, its help line
    naming what follows and the way off; Start records BOTH sync
    consents (privacy.SYNC_KINDS — the owner, 2026-09-20 afternoon:
    "one switch for everything, the history too, on"), each with its
    card's own text_version, and nothing before Start does (the extras
    page's Next writes only its own switches); off, Start writes no
    row; on a later run with both gates open, off withdraws both, and
    with only one open the switch is drawn on and Start grants the
    missing one. Not signed in, the row is not on the page and Start
    records nothing — a consent nobody saw is not one."""
    import consent_card as cc
    import firstrun
    import privacy
    import sb

    cfg = dataclasses.replace(config_mod.load(REPO / "defaults.toml"),
                              setup=config_mod.SetupConfig(done=False))
    d, s, t = _layer_files()
    offers = {"portable": True, "model": None, "pack": None, "detector": None, "tier": "gpu"}
    person = {"email": "person@example.com", "id": "x", "is_anonymous": False}
    who = {"user": person}

    def wizard():
        try:
            return firstrun.Wizard(cfg, facts={"tier": "gpu"}, offers=offers)
        except Exception as err:                             # noqa: BLE001
            print(f"    (skipped: no Tk window — {err})")
            return None

    def bury(w):
        try:
            w._close()
        except Exception:                                    # noqa: BLE001
            pass
        gc.collect()

    with _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t), \
            _patched(sb, "user", lambda: who["user"]), _patched(sb, "configured", lambda: True):
        assert str(_SCRATCH_HOME) in str(paths.CONSENT_FILE), paths.CONSENT_FILE
        assert privacy.SYNC_KINDS == ("settings_sync", "history_sync")
        for kind in privacy.SYNC_KINDS:
            privacy.withdraw(kind)
        cards = {kind: cc.card_for(kind) for kind in privacy.SYNC_KINDS}
        try:
            # 1. drawn on, off by hand, Start writes nothing
            w = wizard()
            if w is None:
                return
            assert w.sync_wanted is True and w._sync_shown is False
            w.page = firstrun.PAGES.index("extras")
            w._show_page()
            w._next()                                        # the extras page's own writer
            assert w.name == "done"
            for kind in privacy.SYNC_KINDS:
                assert privacy.consent(kind) is None, f"{kind} granted before the row was seen"
            assert list(w.switches) == ["sync", "autostart", "phone"], list(w.switches)
            assert w.switches["sync"].get() is True, "the default is on"
            words = _wizard_words(w)
            assert firstrun.WORDS["done.sync"] in words
            assert "what I said" in firstrun.WORDS["done.sync"], "the row does not name the history"
            assert "Settings > Privacy > Withdraw" in words, "no way off named on the row"
            assert "Never your voice" in words, "the row does not say what stays"
            assert "the Said page is the same" in words, "the row does not say what the history sync does"
            w.switches["sync"].toggle()
            assert w.sync_wanted is False
            w._open_desk()
            assert w.result.saved and config_mod.read_state(t).get("setup.done") is True
            for kind in privacy.SYNC_KINDS:
                assert privacy.consent(kind) is None, f"off on Start wrote a {kind} row"
            bury(w)

            # 2. left on, Start records both with each card's version
            w = wizard()
            w.page = firstrun.PAGES.index("done")
            w._show_page()
            assert w.switches["sync"].get() is True
            w._open_desk()
            rows = {}
            for kind in privacy.SYNC_KINDS:
                rows[kind] = privacy.consent(kind)
                assert rows[kind] is not None and rows[kind]["text_version"] == cards[kind]["text_version"], (kind, rows[kind])
                assert privacy.allowed(kind)
            bury(w)

            # 3. a later run, both gates open: drawn on and quiet; off withdraws both
            w = wizard()
            assert w._sync_shown is True and w.sync_wanted is True
            w.page = firstrun.PAGES.index("done")
            w._show_page()
            w._open_desk()
            for kind in privacy.SYNC_KINDS:
                assert privacy.consent(kind) == rows[kind], kind
            bury(w)
            w = wizard()
            w.page = firstrun.PAGES.index("done")
            w._show_page()
            w.switches["sync"].toggle()
            w._open_desk()
            for kind in privacy.SYNC_KINDS:
                assert privacy.consent(kind) is None, f"off did not withdraw {kind}"
                assert not privacy.allowed(kind)
            bury(w)

            # 3b. only the settings sync open (a copy from before the one
            # switch): drawn on, and Start grants the history sync too
            privacy.grant("settings_sync", cards["settings_sync"]["text_version"])
            w = wizard()
            assert w._sync_shown is False and w.sync_wanted is True
            w.page = firstrun.PAGES.index("done")
            w._show_page()
            assert w.switches["sync"].get() is True
            w._open_desk()
            assert privacy.allowed("history_sync"), "the missing sync was not granted"
            assert privacy.allowed("settings_sync")
            bury(w)
            for kind in privacy.SYNC_KINDS:
                privacy.withdraw(kind)

            # 4. not signed in: no row, and Start records nothing
            who["user"] = None
            w = wizard()
            w.page = firstrun.PAGES.index("done")
            w._show_page()
            assert list(w.switches) == ["autostart", "phone"], list(w.switches)
            assert w.sync_wanted is True                    # the default, unseen
            w._open_desk()
            for kind in privacy.SYNC_KINDS:
                assert privacy.consent(kind) is None, f"a {kind} consent nobody saw was written"
            bury(w)
        finally:
            for kind in privacy.SYNC_KINDS:
                privacy.withdraw(kind)
            shutil.rmtree(d, ignore_errors=True)


def test_the_cloud_switch_is_the_consent_and_next_waits_for_a_working_key():
    """The cloud switch on the extras page (the owner, 2026-09-19 evening:
    "whoever turns it on — that is enough; a key must be checked; on with
    no key, it must not let me continue"): flipping it on records the
    consent row with the card's text_version at once and opens the key
    field under the row — a rounded ui.Field, masked, the way to a free
    key; Next is shut with "turn it off or paste a working key" until a
    key passes the `key-test` probe; a refused key is taken out of the
    store and Next stays shut; off again withdraws the consent, folds
    the field away and opens Next."""
    import consent_card as cc
    import firstrun
    import privacy
    import secretstore
    import tkinter as tk
    import ui

    cfg = dataclasses.replace(config_mod.load(REPO / "defaults.toml"),
                              setup=config_mod.SetupConfig(done=False))
    d, s, t = _layer_files()
    offers = {"portable": True, "model": None, "pack": None, "detector": None, "tier": "gpu"}
    store: dict = {}
    probe = {"answer": None}

    def fake_probe():
        if isinstance(probe["answer"], Exception):
            raise probe["answer"]
        return probe["answer"]

    def settle(w, seconds=1.0):
        deadline = time.monotonic() + seconds
        while time.monotonic() < deadline:
            w.root.update()
            w._drain()
            w._extras_gate()
            time.sleep(0.02)

    with _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t),             _patched(firstrun, "key_probe", fake_probe),             _patched(secretstore, "set", lambda name, value: store.__setitem__(name, value)),             _patched(secretstore, "get", lambda name: store.get(name)),             _patched(secretstore, "delete", lambda name: store.pop(name, None) is not None):
        assert str(_SCRATCH_HOME) in str(paths.CONSENT_FILE), paths.CONSENT_FILE
        privacy.withdraw("cloud_text")
        try:
            w = firstrun.Wizard(cfg, facts={"tier": "gpu"}, offers=offers)
        except Exception as err:                             # noqa: BLE001
            print(f"    (skipped: no Tk window — {err})")
            return
        try:
            w.page = firstrun.PAGES.index("extras")
            w._show_page()
            w.root.update()
            card = cc.card_for("cloud_text")
            rows_only = w.extras_card.h
            w._extras_gate()
            assert w.next._enabled, "Next shut with the cloud off"

            w.switches["cloud"].toggle()
            settle(w, 0.2)
            row = privacy.consent("cloud_text")
            assert row is not None and row["text_version"] == card["text_version"], row
            assert w.extras["cloud"] is True and w.switches["cloud"].get() is True
            assert w.key_panel is not None and w.key_panel.master is w.cloud_slot
            assert isinstance(w.key_box, ui.Field) and w.key_field.cget("show") == "•"
            labels = [c.cget("text") for c in w.key_panel.winfo_children() if isinstance(c, tk.Label)]
            assert any("console.groq.com" in t_ for t_ in labels), "no way to a free key"
            assert w.extras_card.h > rows_only
            assert not w.next_loud._enabled and not w.next_quiet._enabled, "Next open with no key"
            assert w.note.cget("text") == firstrun.WORDS["extras.key.wait"]

            w._save_key()                                    # nothing pasted
            assert store == {} and "paste the key first" in w.key_note.cget("text")
            # THE NOTE IS TWO LINES TALL FROM THE START and the card is
            # re-fitted after every message (his walk of the built
            # installer, 2026-09-19 night: a note that wrapped pushed the
            # rows down under a face that was never re-fitted, and the
            # last row was cut off)
            assert int(w.key_note.cget("height")) == 2 and w.key_note.cget("anchor") == "nw"
            w.root.update_idletasks()
            assert w.extras_card.h == w.extras_card.body.winfo_reqheight() + 2 * w.extras_card.pad
            # something that cannot be a key — Hebrew, a sentence — is said
            # so in plain words and never stored (the same walk: Hebrew in
            # the Authorization header came back as a codec error dressed
            # as "could not reach Groq")
            probe["answer"] = 3
            w.key_field.insert(0, "שלום")
            w._save_key()
            settle(w, 0.3)
            assert store == {} and w.key_note.cget("text") == firstrun.WORDS["extras.key.notkey"]
            assert not w.next._enabled and "gsk_" in firstrun.WORDS["extras.key.notkey"]
            for bad in ("a key with spaces", "", "gsk\tkey"):
                assert not firstrun.looks_like_key(bad), bad
            assert firstrun.looks_like_key("gsk_Abc123_xyz")
            probe["answer"] = firstrun.KeyRefused("HTTP 401")
            w.key_field.insert(0, "gsk_wrong_key_xxxxxxxxxxxxxxxxxxxxxx")
            w._save_key()
            settle(w, 1.0)
            assert "groq" not in store, "a refused key stayed in the store"
            assert w.key_note.cget("text") == firstrun.WORDS["extras.key.refused"] and not w.next._enabled
            assert w.key_field.get() == "", "the field is emptied after Save"
            # plain words on the card: no Python error text, the reason
            # goes to the log
            for key in ("extras.key.refused", "extras.key.offline"):
                assert "{detail}" not in firstrun.WORDS[key] and "(" not in firstrun.WORDS[key], key
            probe["answer"] = UnicodeEncodeError("latin-1", "x", 0, 1, "bad")
            w.key_field.insert(0, "gsk_stored_elsewhere")
            w._save_key()
            settle(w, 1.0)
            assert "groq" not in store and w.key_note.cget("text") == firstrun.WORDS["extras.key.refused"]
            w.root.update_idletasks()
            assert w.extras_card.h == w.extras_card.body.winfo_reqheight() + 2 * w.extras_card.pad

            probe["answer"] = 3
            w.key_field.insert(0, "gsk_test_not_a_real_key_1234567890")
            w._save_key()
            settle(w, 1.0)
            assert store == {"groq": "gsk_test_not_a_real_key_1234567890"}, store
            assert w.key_note.cget("text") == firstrun.WORDS["extras.key.works"]
            assert w.next._enabled and w.note.cget("text") == ""

            w.switches["cloud"].toggle()                     # off: the row folds away
            settle(w, 0.2)
            assert w.key_panel is None and w.extras["cloud"] is False
            assert privacy.consent("cloud_text") is None, "off did not withdraw"
            assert w.extras_card.h == rows_only and w.next._enabled
        finally:
            privacy.withdraw("cloud_text")
            try:
                w.root.destroy()
            except Exception:                                # noqa: BLE001
                pass
            shutil.rmtree(d, ignore_errors=True)


def test_the_wizard_shows_one_row_per_microphone():
    """firstrun.one_per_device (2026-09-19, the owner's screen: five rows
    for two microphones): the same name under MME, WASAPI, WDM-KS and
    DirectSound is one row, WASAPI's; an MME name cut at 31 characters
    is its WASAPI row; the device the settings already name is the row
    kept for its group, whatever its API, so it lights up and Next
    writes nothing; DirectSound and the two "default" aliases are not
    rows; two Bluetooth endpoints with different names stay two rows."""
    import firstrun

    def row(name, api, index):
        return (firstrun.device_key(name, api), firstrun.clean_name(name), api, index)

    listing = [
        row("Microphone (HD Webcam eMeet C960)", "Windows WASAPI", 20),
        row("Headset Microphone (Arctis 7 Chat)", "Windows WASAPI", 21),
        row("Microphone (Realtek HD Audio Mic input)", "Windows WDM-KS", 23),
        row("Headset (@System32\\drivers\\bthhfenum.sys,#2;%1 Hands-Free%0\r\n;(Nothing Ear))",
            "Windows WDM-KS", 31),
        row("Headset (@System32\\drivers\\bthhfenum.sys,#2;%1 Hands-Free%0\r\n;(Nothing ear (1)))",
            "Windows WDM-KS", 43),
        row("Headset Microphone (Arctis 7 Chat)", "Windows WDM-KS", 45),
        row("Microphone (HD Webcam eMeet C960)", "Windows WDM-KS", 48),
        row("Microsoft Sound Mapper - Input", "MME", 0),
        row("Headset Microphone (Arctis 7 Ch", "MME", 1),
        row("Microphone (HD Webcam eMeet C96", "MME", 2),
        row("Primary Sound Capture Driver", "Windows DirectSound", 8),
        row("Headset Microphone (Arctis 7 Chat)", "Windows DirectSound", 9),
        row("Microphone (HD Webcam eMeet C960)", "Windows DirectSound", 10),
    ]
    rows = firstrun.one_per_device(listing)
    names = [r[1] for r in rows]
    assert names == ["Microphone (HD Webcam eMeet C960)", "Headset Microphone (Arctis 7 Chat)",
                     "Microphone (Realtek HD Audio Mic input)", "Nothing Ear", "Nothing ear (1"], names
    assert all(r[2] == "Windows WASAPI" for r in rows[:2]), "the microphone's best API is the row"
    assert not any("Sound Mapper" in n or "Primary Sound" in n for n in names)
    # the settings name the MME row: that row is the group's, and lights up
    mme = firstrun.device_key("Headset Microphone (Arctis 7 Ch", "MME")
    kept = firstrun.one_per_device(listing, mme)
    assert [r[0] for r in kept if "Arctis" in r[1]] == [mme], kept
    assert len(kept) == len(rows)
    assert firstrun.order_for(kept, mme)[0][0] == mme
    # the same-device rule is exactly the MME cut, nothing looser
    assert firstrun.same_device(row("Nothing Ear", "Windows WDM-KS", 1), row("Nothing ear (1", "Windows WDM-KS", 2)) is False
    assert firstrun.same_device(row("Headset Microphone (Arctis 7 Ch", "MME", 1), row("Headset Microphone (Arctis 7 Chat)", "Windows WASAPI", 2))
    assert firstrun.same_device(row("Headset Microphone (Arctis 7 Ch", "Windows WDM-KS", 1), row("Headset Microphone (Arctis 7 Chat)", "Windows WASAPI", 2)) is False
    # the Windows default (an MME index) is named by the row shown for it
    assert firstrun.default_device(listing, rows) in ("", firstrun.device_key("Headset Microphone (Arctis 7 Chat)", "Windows WASAPI"),
                                                     *[r[0] for r in rows])
    # every word on every page is English, bar the person's own sentence
    hebrew = [k for k, v in firstrun.WORDS.items()
              if any(0x0590 <= ord(ch) <= 0x05FF for ch in " ".join(v) if isinstance(v, tuple)) or
              (isinstance(v, str) and any(0x0590 <= ord(ch) <= 0x05FF for ch in v))]
    assert hebrew == [], hebrew
    assert firstrun.WORDS["finish"] == "Start" and firstrun.WORDS["account.continue"] == "Continue"


def test_the_wizards_microphone_help_is_on_screen_once():
    """The microphone page's help (Windows may be blocking desktop apps)
    is drawn into one frame and never twice: asked for by the registry
    at page-build, by the quiet timer, and again after another device is
    picked, the page shows one block with one button; a level that moves
    takes it down; and the mic page's Next is the primary while the
    account page's is quiet behind [Sign in with Google]."""
    import firstrun
    import sb
    import ui as ui_mod

    cfg = dataclasses.replace(config_mod.load(REPO / "defaults.toml"),
                              setup=config_mod.SetupConfig(done=False))
    d, s, t = _layer_files()
    offers = {"portable": True, "model": None, "pack": None, "detector": None, "tier": "gpu"}
    with _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t), \
            _patched(sb, "user", lambda: None):
        try:
            w = firstrun.Wizard(cfg, facts={}, offers=offers)
        except Exception as err:                             # noqa: BLE001
            print(f"    (skipped: no Tk window — {err})")
            return
        try:
            w.page = firstrun.PAGES.index("account")
            w._show_page()
            if w.roads:
                w._account_show("create")
                assert w.next is w.next_quiet, "Sign in is the page's action; Next is quiet"
                assert w.signin._primary
                w._account_show("signed", who={"email": "person@example.com"})
                assert w.next is w.next_loud and w.next._enabled
                assert "person@example.com" in w.account_line.cget("text")
            w.page = firstrun.PAGES.index("mic")
            w._show_page()
            w.root.update()
            assert w.next is w.next_loud
            if w.hint is None:
                print("    (no input device on this machine: the help has no page)")
                return
            w._warn_silent()
            w._warn_silent()
            w.root.update()
            assert w.hint_count() == 1, "the help was drawn twice"
            buttons = [c for c in w.hint.winfo_children()[0].body.winfo_children()
                       if isinstance(c, ui_mod.Button)]
            assert len(buttons) == 1, "one [Open Windows settings]"
            # another device picked: the timer starts again, the block does not double
            others = [k for k in w._rows if k != w.device]
            if others:
                w._pick(others[0])
                assert w._warned is False and w.hint_count() == 0
                w._warn_silent()
                w._warn_silent()
                assert w.hint_count() == 1
            # it moved: the help comes down
            w.meter.show(firstrun.SPEECH * 2)
            w._quiet_since = 0
            w.listener.level = lambda: firstrun.SPEECH * 2
            w._closing = False
            w._tick()
            assert w.hint_count() == 0, "the help stayed after the bar moved"
            assert w.meter_note.cget("text") == firstrun.WORDS["mic.heard"]
        finally:
            try:
                w._close()
            except Exception:                                # noqa: BLE001
                pass
            shutil.rmtree(d, ignore_errors=True)


def test_the_wizard_rebinds_a_key_on_its_own_page():
    """The keys page's chips (the owner, 2026-09-19: "let me change the
    keys already on this page"): a click listens, the next key is
    written through config.with_field + check_hotkeys + config.save
    under the dashboard's NESTED_HOTKEYS name — the path Settings > Keys
    takes — and the chip and the wizard's cfg show it; Esc cancels and
    writes nothing; a key another field already means is refused with
    the wizard's sentence and nothing is written; a modifier alone waits
    for its release; a chord on the hold key is refused."""
    import firstrun

    cfg = dataclasses.replace(config_mod.load(REPO / "defaults.toml"),
                              setup=config_mod.SetupConfig(done=False))
    d, s, t = _layer_files()
    offers = {"portable": True, "model": None, "pack": None, "detector": None, "tier": "gpu"}

    class Event:
        def __init__(self, keysym, keycode):
            self.keysym, self.keycode = keysym, keycode

    with _patched(paths, "SETTINGS_FILE", s), _patched(paths, "STATE_FILE", t), \
            _patched(hotkey_mod, "held_modifier_groups", lambda probe=None: frozenset()):
        try:
            w = firstrun.Wizard(cfg, facts={}, offers=offers)
        except Exception as err:                             # noqa: BLE001
            print(f"    (skipped: no Tk window — {err})")
            return
        try:
            w.page = firstrun.PAGES.index("keys")
            w._show_page()
            w.root.update()
            assert set(w.caps) == {"hotkey", "latch_hotkey", "punctuate_hotkey", "visual_qa_hotkey"}
            before = cfg.punctuate_hotkey
            # Esc: nothing written, the chip says what it said
            w._rebind("punctuate_hotkey")
            assert w._capturing == "punctuate_hotkey" and w._key_binds
            assert w.caps["punctuate_hotkey"].itemcget(w.caps["punctuate_hotkey"]._label, "text") == firstrun.WORDS["keys.press"]
            w._key_down(Event("Escape", 27))
            assert w._capturing is None and not w._key_binds
            assert not s.exists() or "punctuate_hotkey" not in s.read_text("utf-8")
            assert w.cfg.punctuate_hotkey == before
            # F7 (free in defaults.toml; F8 is Translate): written, shown, remembered
            w._rebind("punctuate_hotkey")
            w._key_down(Event("F7", 0x76))
            assert w._capturing is None
            assert config_mod.read_settings(s).get("punctuate_hotkey") == "f7", config_mod.read_settings(s)
            assert w.cfg.punctuate_hotkey == "f7"
            assert w.caps["punctuate_hotkey"].itemcget(w.caps["punctuate_hotkey"]._label, "text") == "F7"
            assert "F7" in w.note.cget("text")
            # F8 is Translate's: refused by name, nothing written
            w._rebind("punctuate_hotkey")
            w._key_down(Event("F8", 0x77))
            assert w.note.cget("text") == firstrun.WORDS["keys.taken"].format(key="F8", other="Translate (tap)"), w.note.cget("text")
            assert config_mod.read_settings(s).get("punctuate_hotkey") == "f7"
            # the hold key, pressed for the latch: refused, nothing written
            w._rebind("latch_hotkey")
            w._key_down(Event("Control_R", 0x11))
            assert w._capturing == "latch_hotkey", "a modifier waits for its release"
            w._key_up(Event("Control_R", 0x11))
            assert w._capturing is None
            assert "Hold and talk" in w.note.cget("text") and "Right Ctrl" in w.note.cget("text"), w.note.cget("text")
            assert config_mod.read_settings(s).get("latch_hotkey") is None
            assert w.cfg.latch_hotkey == cfg.latch_hotkey
            # a chord on the held key: refused with the plain sentence
            w._apply_key("hotkey", "ctrl+f6")
            assert w.note.cget("text") == firstrun.WORDS["keys.no_chord"]
            assert config_mod.read_settings(s).get("hotkey") is None
            # the nested one goes under its section's name
            w._rebind("visual_qa_hotkey")
            w._key_down(Event("F5", 0x74))
            assert config_mod.read_settings(s).get("visual_qa.visual_qa_hotkey") == "f5", config_mod.read_settings(s)
            assert w.cfg.visual_qa.hotkey == "f5"
            # leaving the page while listening stops listening
            w._rebind("punctuate_hotkey")
            w._next()
            assert w.name == "extras" and w._capturing is None and not w._key_binds
        finally:
            try:
                w._close()
            except Exception:                                # noqa: BLE001
                pass
            shutil.rmtree(d, ignore_errors=True)


def test_the_claude_code_door_is_installed_and_removed_cleanly():
    """notify_hook.hook_installed / uninstall_hook: a settings.json with
    somebody else's hooks keeps them byte for byte in meaning; ours are
    found, removed, and an empty event key goes with them."""
    import notify_hook

    d = Path(tempfile.mkdtemp(prefix="deskit-hook-"))
    try:
        path = d / "settings.json"
        assert notify_hook.hook_installed(path) is False
        assert notify_hook.uninstall_hook(path) is False
        theirs = {"hooks": {"Stop": [{"matcher": "", "hooks": [{"type": "command", "command": "echo hi"}]}]},
                  "theme": "dark"}
        path.write_text(json.dumps(theirs), "utf-8")
        assert notify_hook.hook_installed(path) is False
        assert notify_hook.install_hook(path, python="C:\\py\\pythonw.exe", script="C:\\app\\notify_hook.py")
        assert notify_hook.hook_installed(path) is True
        data = json.loads(path.read_text("utf-8"))
        assert data["theme"] == "dark" and data["hooks"]["Stop"][0]["hooks"][0]["command"] == "echo hi"
        assert notify_hook.uninstall_hook(path) is True
        assert notify_hook.hook_installed(path) is False
        assert json.loads(path.read_text("utf-8")) == theirs
        assert notify_hook.uninstall_hook(path) is False
    finally:
        shutil.rmtree(d, ignore_errors=True)


