def test_the_desk_is_a_landing_until_a_sign_in():
    """Q1, the owner's rule of 2026-09-18 after the first live sign-out:
    "a page that shows nothing — not Home, Corrections, Problems, Said,
    Keys, Settings — just a landing screen with a sentence about the
    app and a sign-in button, and only that until I sign in."

    With a configured project, REQUIRED on and no session the window
    opens ON the landing: the places are off the bar, the sheet is one
    card with the sentence and [Sign in with Google], and every _show is
    refused. The app's own status saying locked does the same and its
    browser wait shows under the button; a session arriving — in this
    process when the app is not running, in the app's word when it is
    — takes the landing down onto Home with the places back. With
    REQUIRED off (this file's default) none of it happens."""
    import sb
    import dashboard as dash

    with _fixture_project(), _patched(sb, "REQUIRED", True), _consented("account"), \
            _window() as board:
        if board is None:
            return
        # from the first frame, before any poll
        assert board._landing_up and board.screen == "Landing"
        assert not board.nav.winfo_manager(), "the places are still on the bar"
        words = " ".join(_texts(board.sheet))
        assert "Hebrew dictation" in words and "Sign in once" in words, words
        assert "landing_button" in board.parts and "landing_line" in board.parts
        assert board.parts["landing_line"].cget("text") == ""
        for name in ("Home", "Settings", "Network"):
            board._show(name)
            assert board.screen == "Landing", name
        board._refresh(None)
        assert board._landing_up
        # the app answers, locked, waiting on the browser
        board._refresh({"ok": True, "stage": "running", "locked": True,
                        "account": {"configured": True, "signed_in": False,
                                    "busy": "waiting for the browser"}})
        assert board._landing_up and board.screen == "Landing"
        assert board.parts["landing_line"].cget("text").startswith("Waiting for Google")
        board._refresh({"ok": True, "stage": "running", "locked": True,
                        "account": {"configured": True, "signed_in": False,
                                    "busy": "", "last_error": "the browser never came back"}})
        assert "never came back" in board.parts["landing_line"].cget("text")
        # the app's word: signed in — down onto Home, the places back
        board._refresh({"ok": True, "stage": "running", "locked": False,
                        "account": {"configured": True, "signed_in": True}})
        assert not board._landing_up and board.screen == "Home"
        assert board.nav.winfo_manager() == "place"
        assert board.nav.selected == "Home"
        board._show("Settings")
        assert board.screen == "Settings"
        # the app stops answering and there is still no session here: up
        board._refresh(None)
        assert board._landing_up and board.screen == "Landing"
        # a session in THIS process (the window's own sign-in when the
        # app is not running lands one): down
        sb.sign_in_anonymous()
        board._refresh(None)
        assert not board._landing_up and board.screen == "Home"
        # ...and Sign out from Privacy locks the desk again
        sb.sign_out()
        board._refresh(None)
        assert board._landing_up and board.screen == "Landing"
    with _fixture_project(), _window() as board:
        if board is None:
            return
        assert not board._landing_up and board.screen == "Home"
        board._refresh(None)
        assert board.screen == "Home" and board.nav.winfo_manager() == "place"
    assert "Landing" not in dash.SCREENS, "the landing is not a place to walk to"


def test_keepalive_workflow_shape():
    """The weekly knock (8.9): a schedule, one curl GET to
    /rest/v1/profiles with the publishable key as `apikey` from a
    repository VARIABLE, no Authorization header, no secret, nothing
    else; exits green when the variables are not set yet."""
    wf = (REPO / ".github" / "workflows" / "supabase-keepalive.yml").read_text("utf-8")
    assert re.search(r"schedule:\s*\n\s*- cron: \"[^\"]+\"", wf)
    assert "workflow_dispatch" in wf and "permissions: {}" in wf
    assert wf.count("curl") == 1 and "/rest/v1/profiles?select=user_id&limit=1" in wf
    assert '--header "apikey: $SUPABASE_PUBLISHABLE_KEY"' in wf
    assert "Authorization" not in wf and "sb_secret" not in wf and "secrets." not in wf
    assert "vars.SUPABASE_URL" in wf and "vars.SUPABASE_PUBLISHABLE_KEY" in wf
    assert "exit 0" in wf.split("curl")[0], "an unset variable must exit green"
    assert "--request POST" not in wf and "-X" not in wf


def test_account_block_on_the_privacy_tab():
    """Settings > Privacy carries the ACCOUNT card (screen 16): "start
    dictation first" with no app; with a status that says signed out,
    Sign in with Google and Anonymous account; signed in with Google,
    the e-mail and Sign out / Delete my account (no Sync now since
    2026-09-20: the sync is live, the owner's word), and Delete asks
    first — the question grows out of the card with Keep it and Delete,
    and a press sends `account` with the verb over the pipe. A shut sync
    row on the same page carries [Turn on], which sends `account`
    `sync` with its kind; a shut cloud row carries nothing (its card
    opens on first use)."""
    import settings as settings_mod

    d = Path(tempfile.mkdtemp(prefix="deskit-acct-card-"))
    try:
        with _patched(paths, "SETTINGS_FILE", d / "s.toml"), _patched(paths, "STATE_FILE", d / "t.json"), \
                _window() as board:
            if board is None:
                return
            board._show("Settings")
            board._settings_go("Privacy")
            board._finish_settings()
            board.root.update_idletasks()
            line = board.parts["account_line"]
            assert "start dictation first" in line.cget("text")
            labels = lambda: [w.itemcget(w._label, "text")  # noqa: E731
                              for w in board.parts["account_strip"].winfo_children()
                              if hasattr(w, "_label")]
            assert labels() == []
            board.running = True
            board.status = {"stage": "running", "account": {
                "configured": True, "signed_in": False, "user_id": "", "anonymous": True,
                "email": "", "device_name": "PC", "busy": "", "last_error": "",
                "last_sync": "", "waiting": 0, "region": "Frankfurt (Supabase)"}}
            board._paint_account()
            assert line.cget("text").startswith("none — sign in")
            # the buttons sit inside the card: strip bottom under the body
            board.root.update_idletasks()
            strip = board.parts["account_strip"]
            body = strip.master
            bottom, room = strip.winfo_y() + strip.winfo_reqheight(), body.winfo_height()
            assert bottom <= room, (bottom, room)
            assert labels() == ["Sign in with Google", "Anonymous account"], labels()
            board.status["account"].update(signed_in=True, anonymous=False,
                                           email="person@example.com", waiting=2,
                                           last_sync="2026-09-18T12:03:00+00:00")
            board._paint_account()
            assert "person@example.com" in line.cget("text")
            assert "2 reports waiting" in board.parts["account_sub"].cget("text")
            assert labels() == ["Sign out", "Delete my account"], labels()
            sent: list = []
            board._ask = lambda command, then=None, **args: sent.append((command, args))
            board.parts["account_strip"].winfo_children()[1]._command()
            assert board._account_asking and labels() == ["Keep it", "Delete"], labels()
            assert "Delete your account" in line.cget("text") and sent == []
            board.parts["account_strip"].winfo_children()[0]._command()
            assert not board._account_asking and labels()[0] == "Sign out"
            board.status["account"].update(anonymous=True, email="")
            board._paint_account()
            assert labels() == ["Sign in with Google", "Sign out", "Delete my account"]
            # the shut sync rows: [Turn on] asks the app for that one card
            import privacy
            for kind in privacy.SYNC_KINDS + ("cloud_text",):
                privacy.withdraw(kind)
            board._draw_settings()
            board.root.update_idletasks()
            cards = {widget[0] for rows in board.parts["rows"].values()
                     for kind_, widget in rows if kind_ == "consent"}
            turn_on = [w for canvas in cards for w in canvas.winfo_children()
                       if hasattr(w, "_label") and w.itemcget(w._label, "text") == "Turn on"]
            assert len(turn_on) == 2, f"{len(turn_on)} Turn on button(s): the two syncs, no more"
            for w in turn_on:
                w._command()
            assert sorted(a.get("kind") for _c, a in sent) == ["history_sync", "settings_sync"], sent
            assert all(c == "account" and a["do"] == "sync" for c, a in sent), sent
    finally:
        shutil.rmtree(d, ignore_errors=True)


def test_account_command_over_the_pipe():
    """main.App._account_command: `status` answers sb.status(); a sign-in
    with the account gate shut opens the card and says so, with the gate
    open it starts a thread and answers at once (nothing on the control
    thread waits on a browser); `sync` nudges the worker; `delete` with
    no account is refused; an unknown verb is an error."""
    import sb
    import privacy

    app = __import__('main').App.__new__(__import__('main').App)
    app._say = lambda text: None
    asked: list[str] = []
    with _fixture_project() as fake, _patched(privacy, "_asker", lambda kind: asked.append(kind)):
        reply = app._account_command("status")
        assert reply["ok"] and reply["account"]["configured"] and not reply["account"]["signed_in"]
        reply = app._account_command("google")
        assert not reply["ok"] and "card" in reply["error"] and asked == ["account"], reply
        assert fake.calls == []
        assert not app._account_command("delete")["ok"]
        assert not app._account_command("bogus")["ok"]
        with _consented("account"):
            reply = app._account_command("anonymous")
            assert reply["ok"], reply
            for _ in range(50):
                if sb.signed_in():
                    break
                time.sleep(0.05)
            assert sb.signed_in(), "the sign-in thread did not finish"
            assert app._account_command("sync")["ok"]
            assert sb._wake.is_set()
            sb._wake.clear()
            reply = app._account_command("signout")
            assert reply["ok"]
            for _ in range(50):
                if not sb.signed_in():
                    break
                time.sleep(0.05)
            assert not sb.signed_in()
        with _patched(sb, "PROJECT_REF", ""):
            assert "not configured" in app._account_command("google")["error"]


